('eee5bbb7fea8d332fa26ab550ba2d0cd', 1, 'ร้านขายของชำแห่งหนึ่งในหมู่บ้านต้องการวางจำหน่ายยาสามัญประจำบ้านที่เป็นยาบรรจุเสร็จและมีฉลากครบถ้วน ข้อใดถูกต้องตามพระราชบัญญัติยา พ.ศ. 2510', '[{"label": "A", "text": "ต้องขอใบอนุญาตขายยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายฯ (ขย.2) ก่อนจึงจะขายได้"}, {"label": "B", "text": "ขายได้เฉพาะเมื่อมีเภสัชกรอยู่ประจำร้านตลอดเวลาที่เปิดทำการ"}, {"label": "C", "text": "ขายได้โดยไม่ต้องขอใบอนุญาตขายยา และไม่ต้องมีเภสัชกรประจำร้าน"}, {"label": "D", "text": "ขายได้เฉพาะในพื้นที่ที่ไม่มีร้านขายยาแผนปัจจุบันตั้งอยู่เท่านั้น"}, {"label": "E", "text": "ต้องจดแจ้งการขายต่อสำนักงานสาธารณสุขจังหวัดเป็นรายปีก่อนจำหน่าย"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ขายได้โดยไม่ต้องขอใบอนุญาตขายยา และไม่ต้องมีเภสัชกรประจำร้าน — การขายยาสามัญประจำบ้านได้รับยกเว้นจากการขอใบอนุญาตขายยาตาม พ.ร.บ.ยา", "reason": "พ.ร.บ.ยา พ.ศ. 2510 กำหนดให้ผู้ที่จะขายยาต้องได้รับใบอนุญาต แต่มีข้อยกเว้นหลายกรณี หนึ่งในนั้นคือการขายยาสามัญประจำบ้าน ซึ่งเป็นยาบรรจุเสร็จที่รัฐมนตรีประกาศว่ามีความปลอดภัยพอให้ประชาชนซื้อหาใช้เองได้ ร้านค้าทั่วไปจึงขายได้โดยไม่ต้องมีใบอนุญาตและไม่ต้องมีผู้มีหน้าที่ปฏิบัติการ\n\nอย่างไรก็ตาม ข้อยกเว้นนี้ครอบคลุมเฉพาะยาสามัญประจำบ้าน หากร้านนำยาอันตรายหรือยาบรรจุเสร็จอื่นที่ไม่ใช่ยาสามัญประจำบ้านมาขาย จะเป็นการขายยาโดยไม่ได้รับอนุญาต และร้านยังต้องไม่ขายยาปลอม ยาผิดมาตรฐาน หรือยาเสื่อมคุณภาพ", "choices": [{"label": "A", "text": "ต้องขอใบอนุญาตขายยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายฯ (ขย.2) ก่อนจึงจะขายได้", "is_correct": false, "explanation": "ผิด การขายยาสามัญประจำบ้านได้รับยกเว้นไม่ต้องขอใบอนุญาตใด ๆ ใบอนุญาต ขย.2 จำเป็นเมื่อจะขายยาบรรจุเสร็จอื่นที่ไม่ใช่ยาสามัญประจำบ้าน"}, {"label": "B", "text": "ขายได้เฉพาะเมื่อมีเภสัชกรอยู่ประจำร้านตลอดเวลาที่เปิดทำการ", "is_correct": false, "explanation": "ผิด การมีเภสัชกรอยู่ประจำเป็นหน้าที่ของผู้รับอนุญาตขายยาแผนปัจจุบัน (ขย.1) ไม่ใช่เงื่อนไขของการขายยาสามัญประจำบ้าน"}, {"label": "C", "text": "ขายได้โดยไม่ต้องขอใบอนุญาตขายยา และไม่ต้องมีเภสัชกรประจำร้าน", "is_correct": true, "explanation": "ถูกต้อง พ.ร.บ.ยา ยกเว้นการขายยาสามัญประจำบ้านไว้ไม่ต้องขอใบอนุญาตขายยา จึงไม่มีข้อกำหนดให้ต้องมีผู้มีหน้าที่ปฏิบัติการ"}, {"label": "D", "text": "ขายได้เฉพาะในพื้นที่ที่ไม่มีร้านขายยาแผนปัจจุบันตั้งอยู่เท่านั้น", "is_correct": false, "explanation": "ผิด กฎหมายไม่ได้จำกัดพื้นที่การขายยาสามัญประจำบ้านโดยพิจารณาจากการมีหรือไม่มีร้านขายยา"}, {"label": "E", "text": "ต้องจดแจ้งการขายต่อสำนักงานสาธารณสุขจังหวัดเป็นรายปีก่อนจำหน่าย", "is_correct": false, "explanation": "ผิด ไม่มีข้อกำหนดให้ร้านค้าทั่วไปต้องจดแจ้งก่อนขายยาสามัญประจำบ้าน"}], "key_takeaway": "ยาสามัญประจำบ้านเป็นยาประเภทเดียวที่ร้านค้าทั่วไปขายได้โดยไม่ต้องมีใบอนุญาตขายยา"}'::jsonb, 'easy', 'law-day1 • ยาสามัญประจำบ้าน'),
('e0bfad6e5e716a21fd18bfb14fa7cf1a', 2, 'ตามพระราชบัญญัติยา พ.ศ. 2510 คำว่า “ยาบรรจุเสร็จ” หมายถึงข้อใด', '[{"label": "A", "text": "ยาที่ผลิตขึ้นและบรรจุในภาชนะหรือหีบห่อที่ปิดหรือผนึกไว้ โดยมีฉลากครบถ้วนตามกฎหมาย"}, {"label": "B", "text": "ยาที่เภสัชกรแบ่งจากภาชนะใหญ่ใส่ซองพร้อมฉลาก เพื่อส่งมอบแก่ผู้ป่วยเฉพาะราย"}, {"label": "C", "text": "ยาที่ขึ้นทะเบียนตำรับแล้ว ไม่ว่าจะบรรจุอยู่ในภาชนะรูปแบบใดก็ตาม"}, {"label": "D", "text": "ยาที่รัฐมนตรีประกาศให้เป็นยาสามัญประจำบ้านเท่านั้น"}, {"label": "E", "text": "ยาที่นำเข้าจากต่างประเทศโดยยังอยู่ในบรรจุภัณฑ์เดิมของผู้ผลิตต่างประเทศ"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ยาที่ผลิตและบรรจุในภาชนะที่ปิดหรือผนึก มีฉลากครบถ้วนตามกฎหมาย — นิยามยาบรรจุเสร็จเน้นที่การบรรจุในภาชนะที่ปิดหรือผนึกพร้อมฉลากครบถ้วน", "reason": "พ.ร.บ.ยา ให้นิยาม “ยาบรรจุเสร็จ” ว่าเป็นยาแผนปัจจุบันหรือยาแผนโบราณที่ผลิตขึ้น และบรรจุในภาชนะหรือหีบห่อที่ปิดหรือผนึกไว้ โดยมีฉลากครบถ้วนตามที่กฎหมายกำหนด\n\nนิยามนี้สำคัญต่อการแบ่งประเภทใบอนุญาต เช่น ใบอนุญาต ขย.2 และ ขย.บ. ที่ขายได้เฉพาะยาบรรจุเสร็จ ผู้รับอนุญาตประเภทนี้จึงไม่มีสิทธิแบ่งบรรจุหรือแบ่งขายยาจากภาชนะใหญ่", "choices": [{"label": "A", "text": "ยาที่ผลิตขึ้นและบรรจุในภาชนะหรือหีบห่อที่ปิดหรือผนึกไว้ โดยมีฉลากครบถ้วนตามกฎหมาย", "is_correct": true, "explanation": "ถูกต้อง ตรงกับนิยามยาบรรจุเสร็จใน พ.ร.บ.ยา คือยาที่ผลิตขึ้น บรรจุในภาชนะหรือหีบห่อที่ปิดหรือผนึก และมีฉลากครบถ้วนตามที่กฎหมายกำหนด"}, {"label": "B", "text": "ยาที่เภสัชกรแบ่งจากภาชนะใหญ่ใส่ซองพร้อมฉลาก เพื่อส่งมอบแก่ผู้ป่วยเฉพาะราย", "is_correct": false, "explanation": "ผิด ยาที่แบ่งจ่ายให้ผู้ป่วยเฉพาะรายเป็นการส่งมอบยาในร้าน ไม่ใช่ยาที่ผลิตและปิดผนึกพร้อมฉลากครบถ้วนแบบยาบรรจุเสร็จ"}, {"label": "C", "text": "ยาที่ขึ้นทะเบียนตำรับแล้ว ไม่ว่าจะบรรจุอยู่ในภาชนะรูปแบบใดก็ตาม", "is_correct": false, "explanation": "ผิด การขึ้นทะเบียนตำรับไม่ได้ทำให้ยาเป็นยาบรรจุเสร็จ นิยามเน้นที่การบรรจุในภาชนะที่ปิดหรือผนึกและมีฉลากครบถ้วน"}, {"label": "D", "text": "ยาที่รัฐมนตรีประกาศให้เป็นยาสามัญประจำบ้านเท่านั้น", "is_correct": false, "explanation": "ผิด ยาสามัญประจำบ้านเป็นยาบรรจุเสร็จกลุ่มหนึ่ง แต่ยาบรรจุเสร็จยังรวมยาอื่น เช่น ยาอันตรายที่บรรจุเสร็จด้วย"}, {"label": "E", "text": "ยาที่นำเข้าจากต่างประเทศโดยยังอยู่ในบรรจุภัณฑ์เดิมของผู้ผลิตต่างประเทศ", "is_correct": false, "explanation": "ผิด แหล่งที่มาของยาไม่ใช่องค์ประกอบของนิยาม ยาที่ผลิตในประเทศก็เป็นยาบรรจุเสร็จได้"}], "key_takeaway": "ยาบรรจุเสร็จคือยาที่ผลิตแล้วบรรจุในภาชนะปิดหรือผนึกพร้อมฉลากครบถ้วน ไม่ใช่ยาที่ร้านแบ่งบรรจุเอง"}'::jsonb, 'easy', 'law-day1 • นิยามยาบรรจุเสร็จ'),
('3fa49987d31e9a89ae604b3014db146e', 3, 'ผู้รับอนุญาตขายยาแผนปัจจุบันเฉพาะยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายหรือยาควบคุมพิเศษ (ขย.2) มีสิทธิขายยาในข้อใด', '[{"label": "A", "text": "ยาบรรจุเสร็จทุกประเภท รวมถึงยาอันตราย หากผู้มีหน้าที่ปฏิบัติการอยู่ในร้าน"}, {"label": "B", "text": "ยาอันตรายที่เป็นยาบรรจุเสร็จได้ แต่ห้ามขายยาควบคุมพิเศษ"}, {"label": "C", "text": "ยาควบคุมพิเศษได้ เมื่อผู้ซื้อนำใบสั่งยาของแพทย์มาแสดง"}, {"label": "D", "text": "ยาทุกประเภทที่แบ่งขายจากภาชนะใหญ่ ยกเว้นยาควบคุมพิเศษ"}, {"label": "E", "text": "ยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายหรือยาควบคุมพิเศษ เช่น ยาสามัญประจำบ้าน"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายหรือยาควบคุมพิเศษ — ขอบเขตการขายของ ขย.2 จำกัดตามชื่อใบอนุญาต", "reason": "ใบอนุญาตขายยาแผนปัจจุบันเฉพาะยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายหรือยาควบคุมพิเศษ (ขย.2) ให้สิทธิขายได้เฉพาะยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายหรือยาควบคุมพิเศษ เช่น ยาสามัญประจำบ้าน และยาบรรจุเสร็จอื่นที่ไม่ได้จัดเป็นยาอันตรายหรือยาควบคุมพิเศษ\n\nการขายยาอันตรายหรือยาควบคุมพิเศษต้องทำในร้านที่ได้รับใบอนุญาตขายยาแผนปัจจุบัน (ขย.1) ซึ่งมีเภสัชกรชั้นหนึ่งเป็นผู้มีหน้าที่ปฏิบัติการ หาก ขย.2 นำยาอันตรายมาขายจะเป็นการขายยานอกขอบเขตที่ได้รับอนุญาต", "choices": [{"label": "A", "text": "ยาบรรจุเสร็จทุกประเภท รวมถึงยาอันตราย หากผู้มีหน้าที่ปฏิบัติการอยู่ในร้าน", "is_correct": false, "explanation": "ผิด ขย.2 ขายยาอันตรายไม่ได้ ไม่ว่าผู้มีหน้าที่ปฏิบัติการจะอยู่ในร้านหรือไม่"}, {"label": "B", "text": "ยาอันตรายที่เป็นยาบรรจุเสร็จได้ แต่ห้ามขายยาควบคุมพิเศษ", "is_correct": false, "explanation": "ผิด ใบอนุญาต ขย.2 ไม่ครอบคลุมยาอันตราย แม้จะเป็นยาบรรจุเสร็จ"}, {"label": "C", "text": "ยาควบคุมพิเศษได้ เมื่อผู้ซื้อนำใบสั่งยาของแพทย์มาแสดง", "is_correct": false, "explanation": "ผิด ขย.2 ขายยาควบคุมพิเศษไม่ได้ทุกกรณี การขายยาควบคุมพิเศษตามใบสั่งยาเป็นสิทธิของ ขย.1"}, {"label": "D", "text": "ยาทุกประเภทที่แบ่งขายจากภาชนะใหญ่ ยกเว้นยาควบคุมพิเศษ", "is_correct": false, "explanation": "ผิด ขย.2 ขายได้เฉพาะยาบรรจุเสร็จ จึงแบ่งขายยาจากภาชนะใหญ่ไม่ได้"}, {"label": "E", "text": "ยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายหรือยาควบคุมพิเศษ เช่น ยาสามัญประจำบ้าน", "is_correct": true, "explanation": "ถูกต้อง ขอบเขตของ ขย.2 เป็นไปตามชื่อใบอนุญาต คือขายได้เฉพาะยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายหรือยาควบคุมพิเศษ"}], "key_takeaway": "ขย.2 ขายยาอันตรายหรือยาควบคุมพิเศษไม่ได้ทุกกรณี และขายได้เฉพาะยาบรรจุเสร็จ"}'::jsonb, 'easy', 'law-day1 • ใบอนุญาต ขย.2'),
('aeaca4f6dd84b7d86433b7cdaac8e530', 4, 'ข้อใดถูกต้องเกี่ยวกับข้อความที่ต้องแสดงบนฉลากของยาแผนปัจจุบันที่จัดเป็นยาอันตราย', '[{"label": "A", "text": "ต้องมีคำว่า “ยาอันตราย” ด้วยอักษรสีเขียวภายในกรอบสี่เหลี่ยม"}, {"label": "B", "text": "ต้องมีคำว่า “ยาอันตราย” ด้วยอักษรสีแดงที่เห็นได้ชัดเจน"}, {"label": "C", "text": "ต้องมีรูปหัวกะโหลกไขว้และคำว่า “ยาพิษ” ด้วยอักษรสีดำ"}, {"label": "D", "text": "ไม่ต้องแสดงคำใด เพราะเภสัชกรเป็นผู้ส่งมอบยาให้ผู้ป่วยอยู่แล้ว"}, {"label": "E", "text": "แสดงคำว่า “ยาอันตราย” ในเอกสารกำกับยาก็เพียงพอ ไม่ต้องแสดงบนฉลาก"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ต้องมีคำว่า “ยาอันตราย” ด้วยอักษรสีแดงที่เห็นได้ชัดเจน — เป็นข้อกำหนดเรื่องฉลากยาอันตรายตาม พ.ร.บ.ยา", "reason": "พ.ร.บ.ยา กำหนดหน้าที่ผู้รับอนุญาตผลิตและผู้รับอนุญาตนำยาเข้าให้จัดให้มีฉลากตามที่ขึ้นทะเบียนไว้ โดยยาบางประเภทต้องแสดงข้อความเฉพาะ ได้แก่ ยาอันตรายต้องมีคำว่า “ยาอันตราย” และยาควบคุมพิเศษต้องมีคำว่า “ยาควบคุมพิเศษ” ด้วยอักษรสีแดงเห็นได้ชัด เช่นเดียวกับข้อความ “ยาใช้ภายนอก” หรือ “ยาใช้เฉพาะที่” ตามแต่กรณี\n\nจุดประสงค์คือให้ผู้ใช้และผู้ขายรับรู้ระดับการควบคุมของยาได้ทันที", "choices": [{"label": "A", "text": "ต้องมีคำว่า “ยาอันตราย” ด้วยอักษรสีเขียวภายในกรอบสี่เหลี่ยม", "is_correct": false, "explanation": "ผิด กฎหมายกำหนดให้ใช้อักษรสีแดง ไม่ใช่สีเขียว"}, {"label": "B", "text": "ต้องมีคำว่า “ยาอันตราย” ด้วยอักษรสีแดงที่เห็นได้ชัดเจน", "is_correct": true, "explanation": "ถูกต้อง พ.ร.บ.ยา กำหนดให้ฉลากยาอันตรายมีคำว่า “ยาอันตราย” ด้วยอักษรสีแดงเห็นได้ชัด"}, {"label": "C", "text": "ต้องมีรูปหัวกะโหลกไขว้และคำว่า “ยาพิษ” ด้วยอักษรสีดำ", "is_correct": false, "explanation": "ผิด พ.ร.บ.ยา ไม่ได้กำหนดสัญลักษณ์หรือข้อความดังกล่าวสำหรับยาอันตราย"}, {"label": "D", "text": "ไม่ต้องแสดงคำใด เพราะเภสัชกรเป็นผู้ส่งมอบยาให้ผู้ป่วยอยู่แล้ว", "is_correct": false, "explanation": "ผิด การที่เภสัชกรเป็นผู้ส่งมอบไม่ได้ยกเว้นหน้าที่ของผู้ผลิตหรือผู้นำเข้าในการแสดงข้อความบนฉลาก"}, {"label": "E", "text": "แสดงคำว่า “ยาอันตราย” ในเอกสารกำกับยาก็เพียงพอ ไม่ต้องแสดงบนฉลาก", "is_correct": false, "explanation": "ผิด ข้อความนี้ต้องปรากฏบนฉลาก การแสดงเฉพาะในเอกสารกำกับยาไม่เพียงพอ"}], "key_takeaway": "ฉลากยาอันตรายต้องมีคำว่า “ยาอันตราย” เป็นอักษรสีแดงเห็นได้ชัด"}'::jsonb, 'easy', 'law-day1 • ฉลากยา'),
('b258483b22662b9ce5a21ce75479ce0b', 5, 'นาย ก. ไม่ได้เป็นเภสัชกร แต่ต้องการลงทุนเปิดร้านขายยาแผนปัจจุบัน (ขย.1) ข้อใดถูกต้อง', '[{"label": "A", "text": "นาย ก. ขอรับอนุญาตไม่ได้ เพราะผู้รับอนุญาต ขย.1 ต้องเป็นเภสัชกรชั้นหนึ่งเท่านั้น"}, {"label": "B", "text": "นาย ก. เป็นผู้รับอนุญาตได้ และเป็นผู้มีหน้าที่ปฏิบัติการเองได้หากผ่านการอบรมของ อย."}, {"label": "C", "text": "นาย ก. ขอได้เฉพาะใบอนุญาต ขย.2 เพราะไม่ใช่เภสัชกร"}, {"label": "D", "text": "นาย ก. เป็นผู้รับอนุญาตได้ โดยต้องจัดให้มีเภสัชกรชั้นหนึ่งเป็นผู้มีหน้าที่ปฏิบัติการ"}, {"label": "E", "text": "นาย ก. เป็นผู้รับอนุญาตได้ โดยให้พยาบาลวิชาชีพเป็นผู้มีหน้าที่ปฏิบัติการแทน"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. นาย ก. เป็นผู้รับอนุญาตได้ โดยต้องจัดให้มีเภสัชกรชั้นหนึ่งเป็นผู้มีหน้าที่ปฏิบัติการ — กฎหมายแยกบทบาทผู้รับอนุญาตออกจากผู้มีหน้าที่ปฏิบัติการ", "reason": "พ.ร.บ.ยา แยกบทบาทสองส่วน คือ “ผู้รับอนุญาต” ซึ่งเป็นเจ้าของกิจการที่ได้รับใบอนุญาตและต้องมีคุณสมบัติและไม่มีลักษณะต้องห้ามตามกฎหมาย แต่ไม่จำเป็นต้องเป็นเภสัชกร กับ “ผู้มีหน้าที่ปฏิบัติการ” ซึ่งสำหรับร้านขายยาแผนปัจจุบัน (ขย.1) ต้องเป็นผู้ประกอบวิชาชีพเภสัชกรรมชั้นหนึ่ง\n\nผู้รับอนุญาตมีหน้าที่จัดให้มีผู้มีหน้าที่ปฏิบัติการอยู่ประจำตลอดเวลาทำการ และทั้งสองฝ่ายมีหน้าที่และความรับผิดตามกฎหมายของตนเอง", "choices": [{"label": "A", "text": "นาย ก. ขอรับอนุญาตไม่ได้ เพราะผู้รับอนุญาต ขย.1 ต้องเป็นเภสัชกรชั้นหนึ่งเท่านั้น", "is_correct": false, "explanation": "ผิด ผู้รับอนุญาตเป็นบุคคลทั่วไปหรือนิติบุคคลได้ คนที่ต้องเป็นเภสัชกรชั้นหนึ่งคือผู้มีหน้าที่ปฏิบัติการ"}, {"label": "B", "text": "นาย ก. เป็นผู้รับอนุญาตได้ และเป็นผู้มีหน้าที่ปฏิบัติการเองได้หากผ่านการอบรมของ อย.", "is_correct": false, "explanation": "ผิด ผู้มีหน้าที่ปฏิบัติการของ ขย.1 ต้องเป็นเภสัชกรชั้นหนึ่ง การอบรมไม่สามารถใช้แทนได้"}, {"label": "C", "text": "นาย ก. ขอได้เฉพาะใบอนุญาต ขย.2 เพราะไม่ใช่เภสัชกร", "is_correct": false, "explanation": "ผิด การเป็นหรือไม่เป็นเภสัชกรของผู้รับอนุญาตไม่ได้จำกัดประเภทใบอนุญาตที่ขอได้"}, {"label": "D", "text": "นาย ก. เป็นผู้รับอนุญาตได้ โดยต้องจัดให้มีเภสัชกรชั้นหนึ่งเป็นผู้มีหน้าที่ปฏิบัติการ", "is_correct": true, "explanation": "ถูกต้อง กฎหมายแยกผู้รับอนุญาตออกจากผู้มีหน้าที่ปฏิบัติการ ผู้รับอนุญาตไม่จำเป็นต้องเป็นเภสัชกร แต่ต้องจัดให้มีเภสัชกรชั้นหนึ่งปฏิบัติการ"}, {"label": "E", "text": "นาย ก. เป็นผู้รับอนุญาตได้ โดยให้พยาบาลวิชาชีพเป็นผู้มีหน้าที่ปฏิบัติการแทน", "is_correct": false, "explanation": "ผิด พยาบาลวิชาชีพไม่มีคุณสมบัติเป็นผู้มีหน้าที่ปฏิบัติการของร้านขายยาแผนปัจจุบัน"}], "key_takeaway": "เจ้าของร้าน ขย.1 ไม่ต้องเป็นเภสัชกร แต่ผู้มีหน้าที่ปฏิบัติการต้องเป็นเภสัชกรชั้นหนึ่ง"}'::jsonb, 'easy', 'law-day1 • ผู้รับอนุญาตและผู้มีหน้าที่ปฏิบัติการ'),
('413e110a2e05838794c7d6ca56396057', 6, 'บริษัทแห่งหนึ่งซื้อยาเม็ดบรรจุขวดใหญ่มาแบ่งใส่ซองเล็ก พิมพ์ฉลากยี่ห้อของบริษัทเอง แล้วส่งขายต่อให้ร้านขายยา การ “แบ่งบรรจุ” ดังกล่าวมีสถานะใดตามพระราชบัญญัติยา', '[{"label": "A", "text": "เป็นการผลิตยา จึงต้องได้รับใบอนุญาตผลิตยา"}, {"label": "B", "text": "เป็นการขายส่งยา จึงใช้เพียงใบอนุญาตขายส่งยาก็เพียงพอ"}, {"label": "C", "text": "ไม่ถือเป็นการผลิต เพราะไม่ได้เปลี่ยนแปลงตัวยาสำคัญ"}, {"label": "D", "text": "เป็นการขายปลีกยา ซึ่งใช้ใบอนุญาตขายยาแผนปัจจุบัน (ขย.1) ได้"}, {"label": "E", "text": "ทำได้โดยไม่ต้องขออนุญาต หากยาต้นทางขึ้นทะเบียนตำรับไว้แล้ว"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. เป็นการผลิตยา จึงต้องได้รับใบอนุญาตผลิตยา — พ.ร.บ.ยา นิยามคำว่า “ผลิต” ให้รวมถึงการแบ่งบรรจุ", "reason": "พ.ร.บ.ยา นิยามคำว่า “ผลิต” ไว้กว้าง ครอบคลุมการทำ ผสม ปรุง แปรสภาพ เปลี่ยนรูป และแบ่งบรรจุ ไม่ว่าจะใช้เครื่องหมายการค้าหรือไม่ ดังนั้นการนำยาจากภาชนะใหญ่มาแบ่งใส่บรรจุภัณฑ์ใหม่เพื่อจำหน่ายเป็นการผลิตยา ผู้กระทำต้องได้รับใบอนุญาตผลิตยา และยาที่ได้ต้องขึ้นทะเบียนตำรับยาด้วย\n\nกรณีนี้ต่างจากการที่เภสัชกรจัดยาส่งมอบให้ผู้ป่วยเฉพาะรายในร้านขายยาที่ได้รับอนุญาต ซึ่งเป็นการขายตามปกติของวิชาชีพ", "choices": [{"label": "A", "text": "เป็นการผลิตยา จึงต้องได้รับใบอนุญาตผลิตยา", "is_correct": true, "explanation": "ถูกต้อง นิยามคำว่า “ผลิต” ใน พ.ร.บ.ยา รวมถึงการแบ่งบรรจุ ผู้แบ่งบรรจุเพื่อขายจึงต้องได้รับใบอนุญาตผลิตยา"}, {"label": "B", "text": "เป็นการขายส่งยา จึงใช้เพียงใบอนุญาตขายส่งยาก็เพียงพอ", "is_correct": false, "explanation": "ผิด ใบอนุญาตขายส่งให้สิทธิขายเท่านั้น ไม่ครอบคลุมการแบ่งบรรจุซึ่งกฎหมายถือว่าเป็นการผลิต"}, {"label": "C", "text": "ไม่ถือเป็นการผลิต เพราะไม่ได้เปลี่ยนแปลงตัวยาสำคัญ", "is_correct": false, "explanation": "ผิด นิยามการผลิตไม่ได้จำกัดเฉพาะการเปลี่ยนแปลงตัวยา การแบ่งบรรจุถือเป็นการผลิตแล้ว"}, {"label": "D", "text": "เป็นการขายปลีกยา ซึ่งใช้ใบอนุญาตขายยาแผนปัจจุบัน (ขย.1) ได้", "is_correct": false, "explanation": "ผิด การแบ่งบรรจุพร้อมติดฉลากยี่ห้อตนเองเพื่อขายต่อไม่ใช่การขายปลีกให้ผู้ป่วย และไม่อยู่ในขอบเขตของ ขย.1"}, {"label": "E", "text": "ทำได้โดยไม่ต้องขออนุญาต หากยาต้นทางขึ้นทะเบียนตำรับไว้แล้ว", "is_correct": false, "explanation": "ผิด ทะเบียนตำรับของยาต้นทางเป็นของผู้ผลิตเดิม ไม่ได้ให้สิทธิผู้อื่นแบ่งบรรจุโดยไม่มีใบอนุญาตผลิต"}], "key_takeaway": "การแบ่งบรรจุยาเพื่อจำหน่ายต่อถือเป็นการผลิตยาและต้องมีใบอนุญาตผลิต"}'::jsonb, 'easy', 'law-day1 • นิยามการผลิตยา (แบ่งบรรจุ)'),
('37fe84a27ba52fe9924ed034507eab3b', 7, 'บริษัทยาต้องการโฆษณาขายยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายทางโทรทัศน์ ข้อใดถูกต้องตามพระราชบัญญัติยา', '[{"label": "A", "text": "โฆษณาได้ทันทีเพราะไม่ใช่ยาอันตราย เพียงแจ้งให้ อย. ทราบภายหลัง"}, {"label": "B", "text": "ต้องได้รับอนุมัติจากสภาเภสัชกรรมแทนสำนักงานคณะกรรมการอาหารและยา"}, {"label": "C", "text": "ต้องได้รับอนุมัติข้อความ เสียง หรือภาพที่ใช้ในการโฆษณาจากผู้อนุญาตก่อน"}, {"label": "D", "text": "ไม่ต้องขออนุมัติ หากใช้ข้อความตรงกับฉลากที่ขึ้นทะเบียนไว้ทุกคำ"}, {"label": "E", "text": "ต้องขออนุมัติเฉพาะโฆษณาทางสื่อสิ่งพิมพ์ ส่วนสื่อโทรทัศน์ไม่ต้องขอ"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ต้องได้รับอนุมัติข้อความ เสียง หรือภาพที่ใช้ในการโฆษณาจากผู้อนุญาตก่อน — การโฆษณาขายยาทุกสื่อต้องได้รับอนุมัติล่วงหน้า", "reason": "พ.ร.บ.ยา กำหนดว่าการโฆษณาขายยาจะทำได้ต่อเมื่อได้รับอนุมัติข้อความ เสียง หรือภาพที่ใช้ในการโฆษณาจากผู้อนุญาต และต้องปฏิบัติตามเงื่อนไขที่ผู้อนุญาตกำหนด หลักนี้ใช้กับทุกสื่อและทุกประเภทยา\n\nนอกจากต้องได้รับอนุมัติแล้ว เนื้อหาโฆษณายังต้องไม่ขัดข้อห้าม เช่น ไม่โอ้อวดว่ารักษาได้หายขาด และไม่แสดงสรรพคุณยาอันตรายหรือยาควบคุมพิเศษต่อประชาชนทั่วไป", "choices": [{"label": "A", "text": "โฆษณาได้ทันทีเพราะไม่ใช่ยาอันตราย เพียงแจ้งให้ อย. ทราบภายหลัง", "is_correct": false, "explanation": "ผิด การโฆษณาขายยาทุกประเภทต้องได้รับอนุมัติก่อนเผยแพร่ ไม่ใช่การแจ้งภายหลัง"}, {"label": "B", "text": "ต้องได้รับอนุมัติจากสภาเภสัชกรรมแทนสำนักงานคณะกรรมการอาหารและยา", "is_correct": false, "explanation": "ผิด สภาเภสัชกรรมไม่ใช่ผู้อนุญาตโฆษณาขายยาตาม พ.ร.บ.ยา"}, {"label": "C", "text": "ต้องได้รับอนุมัติข้อความ เสียง หรือภาพที่ใช้ในการโฆษณาจากผู้อนุญาตก่อน", "is_correct": true, "explanation": "ถูกต้อง การโฆษณาขายยาต้องได้รับอนุมัติข้อความ เสียง หรือภาพจากผู้อนุญาตก่อน และต้องปฏิบัติตามเงื่อนไขที่กำหนด"}, {"label": "D", "text": "ไม่ต้องขออนุมัติ หากใช้ข้อความตรงกับฉลากที่ขึ้นทะเบียนไว้ทุกคำ", "is_correct": false, "explanation": "ผิด แม้ข้อความตรงกับฉลาก การโฆษณาก็ยังต้องได้รับอนุมัติก่อน"}, {"label": "E", "text": "ต้องขออนุมัติเฉพาะโฆษณาทางสื่อสิ่งพิมพ์ ส่วนสื่อโทรทัศน์ไม่ต้องขอ", "is_correct": false, "explanation": "ผิด หลักการขออนุมัติใช้กับการโฆษณาทุกสื่อ"}], "key_takeaway": "โฆษณาขายยาทุกชนิดในทุกสื่อต้องได้รับอนุมัติจากผู้อนุญาตก่อนเผยแพร่"}'::jsonb, 'easy', 'law-day1 • การโฆษณายา (การขออนุมัติ)'),
('a5943fe7f0a7a05d6f6c7baf5017fbfc', 8, 'ใบอนุญาตขายยาแผนปัจจุบันเฉพาะยาบรรจุเสร็จสำหรับสัตว์ (ขย.บ.) ให้สิทธิผู้รับอนุญาตขายยาในข้อใด', '[{"label": "A", "text": "ยาสำหรับสัตว์ทุกรูปแบบ รวมทั้งการแบ่งบรรจุจากภาชนะใหญ่"}, {"label": "B", "text": "ยาบรรจุเสร็จทั้งสำหรับคนและสัตว์ ยกเว้นยาควบคุมพิเศษ"}, {"label": "C", "text": "ยาบรรจุเสร็จสำหรับสัตว์ และวัตถุดิบยาสำหรับแบ่งผสมอาหารสัตว์"}, {"label": "D", "text": "ยาสำหรับสัตว์ และยาอันตรายสำหรับคนเมื่อมีใบสั่งของสัตวแพทย์"}, {"label": "E", "text": "ยาแผนปัจจุบันที่เป็นยาบรรจุเสร็จสำหรับสัตว์เท่านั้น"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ยาแผนปัจจุบันที่เป็นยาบรรจุเสร็จสำหรับสัตว์เท่านั้น — ขอบเขตของ ขย.บ. จำกัดเฉพาะยาบรรจุเสร็จสำหรับสัตว์", "reason": "พ.ร.บ.ยา แบ่งใบอนุญาตขายยาแผนปัจจุบันตามขอบเขตของยาที่ขายได้ ใบอนุญาตขายยาแผนปัจจุบันเฉพาะยาบรรจุเสร็จสำหรับสัตว์ (ขย.บ.) ขายได้เฉพาะยาบรรจุเสร็จสำหรับสัตว์ ห้ามแบ่งบรรจุ และไม่ครอบคลุมยาสำหรับคน\n\nยาสำหรับสัตว์ต้องมีข้อความ “ยาสำหรับสัตว์” บนฉลาก ซึ่งช่วยให้แยกจากยาสำหรับคนได้", "choices": [{"label": "A", "text": "ยาสำหรับสัตว์ทุกรูปแบบ รวมทั้งการแบ่งบรรจุจากภาชนะใหญ่", "is_correct": false, "explanation": "ผิด ขย.บ. ขายได้เฉพาะยาบรรจุเสร็จ แบ่งบรรจุหรือแบ่งขายจากภาชนะใหญ่ไม่ได้"}, {"label": "B", "text": "ยาบรรจุเสร็จทั้งสำหรับคนและสัตว์ ยกเว้นยาควบคุมพิเศษ", "is_correct": false, "explanation": "ผิด ใบอนุญาตนี้ไม่ครอบคลุมยาสำหรับคน"}, {"label": "C", "text": "ยาบรรจุเสร็จสำหรับสัตว์ และวัตถุดิบยาสำหรับแบ่งผสมอาหารสัตว์", "is_correct": false, "explanation": "ผิด ขย.บ. ขายได้เฉพาะยาบรรจุเสร็จ วัตถุดิบยาที่นำไปแบ่งผสมไม่ใช่ยาบรรจุเสร็จ จึงไม่อยู่ในขอบเขตใบอนุญาต"}, {"label": "D", "text": "ยาสำหรับสัตว์ และยาอันตรายสำหรับคนเมื่อมีใบสั่งของสัตวแพทย์", "is_correct": false, "explanation": "ผิด ขย.บ. ขายยาสำหรับคนไม่ได้ ไม่ว่าจะมีใบสั่งใดก็ตาม"}, {"label": "E", "text": "ยาแผนปัจจุบันที่เป็นยาบรรจุเสร็จสำหรับสัตว์เท่านั้น", "is_correct": true, "explanation": "ถูกต้อง ขอบเขตของ ขย.บ. จำกัดเฉพาะยาบรรจุเสร็จสำหรับสัตว์ตามชื่อใบอนุญาต"}], "key_takeaway": "ขย.บ. ขายได้เฉพาะยาบรรจุเสร็จสำหรับสัตว์ ห้ามขายยาสำหรับคนและห้ามแบ่งบรรจุ"}'::jsonb, 'easy', 'law-day1 • ใบอนุญาต ขย.บ. (ยาสำหรับสัตว์)'),
('caeb8b81999e7d6b5e33a2a02a3aaeb0', 9, 'บริษัทจำกัดแห่งหนึ่งต้องการนำยาแผนปัจจุบันชนิดใหม่จากต่างประเทศเข้ามาจำหน่ายในประเทศไทยเป็นครั้งแรก ข้อใดถูกต้อง', '[{"label": "A", "text": "ต้องมีเพียงใบอนุญาตนำเข้า เพราะการขึ้นทะเบียนตำรับเป็นหน้าที่ของผู้ผลิตต่างประเทศ"}, {"label": "B", "text": "ต้องขึ้นทะเบียนตำรับยาเท่านั้น ไม่ต้องมีใบอนุญาตนำเข้าหากมีใบอนุญาตขายส่งอยู่แล้ว"}, {"label": "C", "text": "นำเข้าได้โดยไม่ต้องขึ้นทะเบียน หากยาได้รับอนุมัติจาก US FDA หรือ EMA แล้ว"}, {"label": "D", "text": "ต้องมีใบอนุญาตนำหรือสั่งยาเข้ามาในราชอาณาจักร และยานั้นต้องขึ้นทะเบียนตำรับยาก่อนจำหน่าย"}, {"label": "E", "text": "นำเข้าและจำหน่ายได้ก่อน แล้วจึงยื่นขึ้นทะเบียนตำรับยาภายหลัง"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ต้องมีใบอนุญาตนำหรือสั่งยาเข้าฯ และยาต้องขึ้นทะเบียนตำรับยาก่อนจำหน่าย — การนำเข้าเพื่อจำหน่ายต้องมีทั้งใบอนุญาตของสถานประกอบการและทะเบียนของตัวผลิตภัณฑ์", "reason": "พ.ร.บ.ยา ควบคุมสองชั้น ชั้นแรกคือสถานประกอบการ ผู้ที่จะนำหรือสั่งยาเข้ามาในราชอาณาจักรต้องได้รับใบอนุญาต ชั้นที่สองคือตัวผลิตภัณฑ์ ยาที่จะผลิตหรือนำเข้าเพื่อจำหน่ายต้องขึ้นทะเบียนตำรับยาก่อน โดยผู้รับอนุญาตนำเข้าเป็นผู้ยื่นขึ้นทะเบียน\n\nการได้รับอนุมัติจากหน่วยงานต่างประเทศอาจใช้เป็นข้อมูลประกอบการพิจารณาได้ แต่ไม่ทดแทนการขึ้นทะเบียนในประเทศไทย", "choices": [{"label": "A", "text": "ต้องมีเพียงใบอนุญาตนำเข้า เพราะการขึ้นทะเบียนตำรับเป็นหน้าที่ของผู้ผลิตต่างประเทศ", "is_correct": false, "explanation": "ผิด ผู้รับอนุญาตนำเข้าในประเทศไทยต้องเป็นผู้ยื่นขึ้นทะเบียนตำรับยา ผู้ผลิตต่างประเทศขึ้นทะเบียนเองไม่ได้"}, {"label": "B", "text": "ต้องขึ้นทะเบียนตำรับยาเท่านั้น ไม่ต้องมีใบอนุญาตนำเข้าหากมีใบอนุญาตขายส่งอยู่แล้ว", "is_correct": false, "explanation": "ผิด ใบอนุญาตขายส่งไม่ครอบคลุมการนำยาเข้ามาในราชอาณาจักร"}, {"label": "C", "text": "นำเข้าได้โดยไม่ต้องขึ้นทะเบียน หากยาได้รับอนุมัติจาก US FDA หรือ EMA แล้ว", "is_correct": false, "explanation": "ผิด การอนุมัติของต่างประเทศไม่ทดแทนการขึ้นทะเบียนตำรับยาในประเทศไทย"}, {"label": "D", "text": "ต้องมีใบอนุญาตนำหรือสั่งยาเข้ามาในราชอาณาจักร และยานั้นต้องขึ้นทะเบียนตำรับยาก่อนจำหน่าย", "is_correct": true, "explanation": "ถูกต้อง การนำเข้าเพื่อจำหน่ายต้องมีทั้งใบอนุญาตนำหรือสั่งยาเข้าฯ และทะเบียนตำรับยาในประเทศไทย"}, {"label": "E", "text": "นำเข้าและจำหน่ายได้ก่อน แล้วจึงยื่นขึ้นทะเบียนตำรับยาภายหลัง", "is_correct": false, "explanation": "ผิด ยาต้องขึ้นทะเบียนตำรับก่อนจึงจะนำเข้าเพื่อจำหน่ายได้ การจำหน่ายยาที่ไม่ได้ขึ้นทะเบียนเป็นความผิด"}], "key_takeaway": "นำเข้ายาเพื่อจำหน่ายต้องมีทั้งใบอนุญาตนำเข้าและทะเบียนตำรับยาของไทย"}'::jsonb, 'easy', 'law-day1 • การนำเข้ายาและทะเบียนตำรับยา'),
('6317bcf78cb3838883eb02a09fe3d6f3', 10, 'ร้านขายยาแผนปัจจุบัน (ขย.1) แห่งหนึ่งแจ้งเวลาปฏิบัติการของเภสัชกรไว้ 08.00–20.00 น. เวลา 12.30 น. เภสัชกรออกไปทำธุระนอกร้าน ผู้ช่วยซึ่งไม่ใช่เภสัชกรยังเปิดร้านอยู่ มีลูกค้ามาขอซื้อ amoxicillin capsule ซึ่งเป็นยาอันตราย ผู้ช่วยควรทำอย่างไรจึงถูกต้องตามกฎหมาย', '[{"label": "A", "text": "ขายได้ หากลูกค้าเคยซื้อยานี้ที่ร้านและมีประวัติในระบบคอมพิวเตอร์"}, {"label": "B", "text": "ไม่ขาย amoxicillin และแจ้งให้ลูกค้ารอหรือกลับมาเมื่อเภสัชกรอยู่ปฏิบัติหน้าที่"}, {"label": "C", "text": "ขายได้ หากโทรศัพท์ปรึกษาเภสัชกรและเภสัชกรอนุญาตทางโทรศัพท์"}, {"label": "D", "text": "ขายได้ หากลูกค้ามีใบสั่งยาจากคลินิก เพราะใบสั่งยาใช้แทนการมีเภสัชกรได้"}, {"label": "E", "text": "ขายได้ไม่เกินหนึ่งแผง เพื่อไม่ให้ผู้ป่วยขาดยา"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ไม่ขาย amoxicillin และแจ้งให้ลูกค้ารอหรือกลับมาเมื่อเภสัชกรอยู่ — การขายยาอันตรายใน ขย.1 ต้องทำโดยเภสัชกรผู้มีหน้าที่ปฏิบัติการ", "reason": "พ.ร.บ.ยา กำหนดให้ผู้รับอนุญาตขายยาแผนปัจจุบันจัดให้มีเภสัชกรผู้มีหน้าที่ปฏิบัติการอยู่ประจำตลอดเวลาที่เปิดทำการ และการขายยาอันตรายหรือยาควบคุมพิเศษต้องทำโดยเภสัชกร เมื่อเภสัชกรไม่อยู่ ผู้ช่วยจึงขายยาอันตรายแทนไม่ได้ แม้จะได้รับอนุญาตทางโทรศัพท์หรือลูกค้ามีใบสั่งยา\n\nการที่เภสัชกรไม่อยู่ในช่วงเวลาที่แจ้งไว้ยังเป็นการละเลยหน้าที่ของผู้รับอนุญาตและผู้มีหน้าที่ปฏิบัติการด้วย ทางปฏิบัติที่ถูกต้องคือไม่ขายยาอันตรายหรือยาควบคุมพิเศษในขณะนั้น และจัดให้เภสัชกรอยู่ปฏิบัติหน้าที่ตามเวลาที่แจ้ง", "choices": [{"label": "A", "text": "ขายได้ หากลูกค้าเคยซื้อยานี้ที่ร้านและมีประวัติในระบบคอมพิวเตอร์", "is_correct": false, "explanation": "ผิด ประวัติการซื้อไม่ได้ทำให้ผู้ที่ไม่ใช่เภสัชกรมีสิทธิขายยาอันตราย"}, {"label": "B", "text": "ไม่ขาย amoxicillin และแจ้งให้ลูกค้ารอหรือกลับมาเมื่อเภสัชกรอยู่ปฏิบัติหน้าที่", "is_correct": true, "explanation": "ถูกต้อง ยาอันตรายต้องขายโดยเภสัชกรผู้มีหน้าที่ปฏิบัติการ ผู้ช่วยขายแทนไม่ได้"}, {"label": "C", "text": "ขายได้ หากโทรศัพท์ปรึกษาเภสัชกรและเภสัชกรอนุญาตทางโทรศัพท์", "is_correct": false, "explanation": "ผิด การอนุญาตทางโทรศัพท์ไม่ใช่การที่เภสัชกรอยู่ประจำและควบคุมการขาย ณ สถานที่ขายยา"}, {"label": "D", "text": "ขายได้ หากลูกค้ามีใบสั่งยาจากคลินิก เพราะใบสั่งยาใช้แทนการมีเภสัชกรได้", "is_correct": false, "explanation": "ผิด ใบสั่งยาไม่ทดแทนหน้าที่ของเภสัชกรในการตรวจสอบและส่งมอบยา"}, {"label": "E", "text": "ขายได้ไม่เกินหนึ่งแผง เพื่อไม่ให้ผู้ป่วยขาดยา", "is_correct": false, "explanation": "ผิด กฎหมายไม่มีข้อยกเว้นเรื่องจำนวนที่ให้ผู้ที่ไม่ใช่เภสัชกรขายยาอันตรายได้"}], "key_takeaway": "ผู้ช่วยที่ไม่ใช่เภสัชกรขายยาอันตรายแทนเภสัชกรไม่ได้ทุกกรณี"}'::jsonb, 'medium', 'law-day1 • หน้าที่ผู้มีหน้าที่ปฏิบัติการ (อยู่ประจำ)'),
('fe8dc0b8ed1965ddd47c866c8ed5c834', 11, 'แพทย์เปิดคลินิกเวชกรรมและจ่ายยาให้ผู้ป่วยที่ตนตรวจรักษา วันหนึ่งมีบุคคลทั่วไปเดินเข้ามาขอซื้อยาลดความดันโลหิตโดยไม่ได้ให้แพทย์ตรวจ พนักงานคลินิกจึงขายยาให้ตามที่ขอ ข้อใดถูกต้อง', '[{"label": "A", "text": "ทำได้ เพราะคลินิกที่มีใบอนุญาตสถานพยาบาลถือว่าได้รับอนุญาตขายยาไปด้วย"}, {"label": "B", "text": "ทำได้ หากแพทย์อยู่ในคลินิกขณะที่พนักงานขายยา"}, {"label": "C", "text": "ทำได้ เพราะยาลดความดันโลหิตไม่ใช่ยาควบคุมพิเศษ"}, {"label": "D", "text": "ผิดเฉพาะกฎหมายว่าด้วยสถานพยาบาล แต่ไม่ผิดพระราชบัญญัติยา"}, {"label": "E", "text": "การขายให้ผู้ที่ไม่ใช่คนไข้ของแพทย์ไม่อยู่ในข้อยกเว้น จึงเป็นการขายยาโดยไม่ได้รับอนุญาต"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. การขายให้ผู้ที่ไม่ใช่คนไข้ของแพทย์ไม่อยู่ในข้อยกเว้น จึงเป็นการขายยาโดยไม่ได้รับอนุญาต — ข้อยกเว้นของแพทย์ใช้กับการขายยาให้คนไข้ของตนเท่านั้น", "reason": "พ.ร.บ.ยา ยกเว้นให้ผู้ประกอบวิชาชีพเวชกรรมขายยาเฉพาะสำหรับคนไข้ของตนได้โดยไม่ต้องขอใบอนุญาตขายยา (ทำนองเดียวกันกับผู้ประกอบวิชาชีพทันตกรรมและผู้ประกอบการบำบัดโรคสัตว์) ข้อยกเว้นนี้มีไว้รองรับการรักษาที่แพทย์ตรวจวินิจฉัยแล้ว\n\nเมื่อคลินิกขายยาให้บุคคลที่ไม่ได้รับการตรวจรักษา ผู้ซื้อไม่ใช่คนไข้ของแพทย์ การขายครั้งนั้นจึงไม่อยู่ในข้อยกเว้นและเป็นการขายยาโดยไม่ได้รับอนุญาต", "choices": [{"label": "A", "text": "ทำได้ เพราะคลินิกที่มีใบอนุญาตสถานพยาบาลถือว่าได้รับอนุญาตขายยาไปด้วย", "is_correct": false, "explanation": "ผิด ใบอนุญาตสถานพยาบาลเป็นคนละฉบับกับใบอนุญาตขายยาตาม พ.ร.บ.ยา"}, {"label": "B", "text": "ทำได้ หากแพทย์อยู่ในคลินิกขณะที่พนักงานขายยา", "is_correct": false, "explanation": "ผิด การที่แพทย์อยู่ในคลินิกไม่ทำให้ผู้ซื้อกลายเป็นคนไข้ที่แพทย์ตรวจรักษา"}, {"label": "C", "text": "ทำได้ เพราะยาลดความดันโลหิตไม่ใช่ยาควบคุมพิเศษ", "is_correct": false, "explanation": "ผิด ประเด็นคือสิทธิในการขาย ไม่ใช่ประเภทของยา คลินิกไม่มีสิทธิขายยาให้ผู้ที่ไม่ใช่คนไข้"}, {"label": "D", "text": "ผิดเฉพาะกฎหมายว่าด้วยสถานพยาบาล แต่ไม่ผิดพระราชบัญญัติยา", "is_correct": false, "explanation": "ผิด การขายยาโดยไม่ได้รับอนุญาตเป็นความผิดตาม พ.ร.บ.ยาโดยตรง"}, {"label": "E", "text": "การขายให้ผู้ที่ไม่ใช่คนไข้ของแพทย์ไม่อยู่ในข้อยกเว้น จึงเป็นการขายยาโดยไม่ได้รับอนุญาต", "is_correct": true, "explanation": "ถูกต้อง ข้อยกเว้นใช้กับการขายยาเฉพาะคนไข้ของแพทย์เอง การขายให้บุคคลทั่วไปจึงต้องมีใบอนุญาตขายยา"}], "key_takeaway": "แพทย์ขายยาได้โดยไม่ต้องมีใบอนุญาตเฉพาะสำหรับคนไข้ของตนเท่านั้น"}'::jsonb, 'medium', 'law-day1 • ข้อยกเว้นผู้ประกอบวิชาชีพเวชกรรม'),
('fb42bc2d03638e5209add9683927b829', 12, 'ระหว่างตรวจสต็อก เภสัชกรพบยาเม็ดเคลือบล็อตหนึ่งที่ยังไม่ถึงวันสิ้นอายุตามฉลาก แต่เม็ดยาเปลี่ยนสี บวม และเยิ้ม ผลวิเคราะห์พบว่าปริมาณตัวยาสำคัญลดลงจนไม่ได้มาตรฐาน คาดว่าเกิดจากการเก็บในที่ร้อนชื้นหลังออกจากโรงงาน โดยล็อตนี้ผ่านการตรวจคุณภาพตอนผลิต ยาล็อตนี้จัดเป็นยาประเภทใดตามพระราชบัญญัติยา', '[{"label": "A", "text": "ยาปลอม เพราะคุณภาพของยาไม่ตรงกับที่แสดงไว้บนฉลาก"}, {"label": "B", "text": "ยาผิดมาตรฐาน เพราะเป็นความบกพร่องในขั้นตอนการผลิต"}, {"label": "C", "text": "ยาเสื่อมคุณภาพ เพราะแปรสภาพจนมีลักษณะเช่นเดียวกับยาผิดมาตรฐาน"}, {"label": "D", "text": "ยังไม่จัดเป็นยาที่ห้ามขาย เพราะยังไม่ถึงวันสิ้นอายุตามฉลาก"}, {"label": "E", "text": "ยาที่ไม่ได้ขึ้นทะเบียน เพราะคุณสมบัติไม่ตรงกับตำรับที่ขึ้นทะเบียนไว้"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ยาเสื่อมคุณภาพ เพราะแปรสภาพจนมีลักษณะเช่นเดียวกับยาผิดมาตรฐาน — ยาที่แปรสภาพหลังการผลิตจัดเป็นยาเสื่อมคุณภาพแม้ยังไม่สิ้นอายุ", "reason": "พ.ร.บ.ยา กำหนดลักษณะของ “ยาเสื่อมคุณภาพ” ไว้สองกรณี คือ (1) ยาที่สิ้นอายุตามที่แสดงไว้ในฉลาก และ (2) ยาที่แปรสภาพจนมีลักษณะเช่นเดียวกับยาผิดมาตรฐาน กรณีนี้เป็นกรณีที่สอง เพราะยาผ่านมาตรฐานตอนผลิตแต่เสื่อมจากการเก็บรักษาไม่เหมาะสม\n\nส่วน “ยาผิดมาตรฐาน” หมายถึงยาที่ผลิตขึ้นไม่ได้มาตรฐานตามตำรับที่ขึ้นทะเบียน กฎหมายห้ามขายยาทั้งสามกลุ่ม ได้แก่ ยาปลอม ยาผิดมาตรฐาน และยาเสื่อมคุณภาพ ร้านยาจึงต้องเก็บรักษายาให้เหมาะสมและแยกยาที่เสื่อมคุณภาพออกจากชั้นขาย", "choices": [{"label": "A", "text": "ยาปลอม เพราะคุณภาพของยาไม่ตรงกับที่แสดงไว้บนฉลาก", "is_correct": false, "explanation": "ผิด ยาปลอมเกี่ยวกับการทำเทียมหรือการแสดงข้อมูลอันเป็นเท็จ เช่น ผู้ผลิตหรือวันสิ้นอายุ หรือการผลิตที่ตัวยาขาดหรือเกินมาก กรณีนี้ยาเสื่อมจากการเก็บรักษา"}, {"label": "B", "text": "ยาผิดมาตรฐาน เพราะเป็นความบกพร่องในขั้นตอนการผลิต", "is_correct": false, "explanation": "ผิด ยาผิดมาตรฐานเป็นยาที่ผลิตขึ้นไม่ได้มาตรฐาน แต่ล็อตนี้ผ่านมาตรฐานตอนผลิตแล้วจึงเสื่อมภายหลัง"}, {"label": "C", "text": "ยาเสื่อมคุณภาพ เพราะแปรสภาพจนมีลักษณะเช่นเดียวกับยาผิดมาตรฐาน", "is_correct": true, "explanation": "ถูกต้อง ยาที่แปรสภาพจนมีลักษณะเช่นเดียวกับยาผิดมาตรฐานถือเป็นยาเสื่อมคุณภาพ แม้ยังไม่สิ้นอายุ"}, {"label": "D", "text": "ยังไม่จัดเป็นยาที่ห้ามขาย เพราะยังไม่ถึงวันสิ้นอายุตามฉลาก", "is_correct": false, "explanation": "ผิด ยาเสื่อมคุณภาพมีทั้งยาที่สิ้นอายุและยาที่แปรสภาพ วันสิ้นอายุบนฉลากจึงไม่ใช่เกณฑ์เดียว"}, {"label": "E", "text": "ยาที่ไม่ได้ขึ้นทะเบียน เพราะคุณสมบัติไม่ตรงกับตำรับที่ขึ้นทะเบียนไว้", "is_correct": false, "explanation": "ผิด ยาล็อตนี้ขึ้นทะเบียนแล้ว การที่คุณภาพเสื่อมลงไม่ได้ทำให้กลายเป็นยาที่ไม่ได้ขึ้นทะเบียน"}], "key_takeaway": "ยาที่เสื่อมจากการเก็บรักษาเป็นยาเสื่อมคุณภาพได้แม้ยังไม่ถึงวันสิ้นอายุ"}'::jsonb, 'medium', 'law-day1 • ยาเสื่อมคุณภาพ'),
('91ebc1857236cf4d5b03ed762a985443', 13, 'พนักงานร้านขายยาแห่งหนึ่งพิมพ์สติกเกอร์วันสิ้นอายุใหม่ซึ่งช้ากว่าวันเดิม 1 ปี แล้วนำไปปิดทับวันสิ้นอายุเดิมบนกล่องยาที่ใกล้หมดอายุ เพื่อจะได้ขายได้นานขึ้น ยาดังกล่าวมีสถานะใดตามพระราชบัญญัติยา', '[{"label": "A", "text": "ยาปลอม เพราะแสดงวันเดือนปีที่ยาสิ้นอายุเกินความจริง"}, {"label": "B", "text": "ยาเสื่อมคุณภาพ เพราะเป็นยาที่ใกล้ถึงวันสิ้นอายุ"}, {"label": "C", "text": "ยาผิดมาตรฐาน เพราะฉลากไม่ตรงกับที่ขึ้นทะเบียนไว้"}, {"label": "D", "text": "ยังเป็นยาปกติ หากตรวจวิเคราะห์แล้วตัวยาสำคัญยังอยู่ในเกณฑ์"}, {"label": "E", "text": "เป็นเพียงความผิดเรื่องฉลาก ไม่ได้จัดเป็นยาประเภทที่ห้ามขาย"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ยาปลอม เพราะแสดงวันเดือนปีที่ยาสิ้นอายุเกินความจริง — การแสดงวันสิ้นอายุเกินความจริงเข้านิยามยาปลอม", "reason": "นิยาม “ยาปลอม” ใน พ.ร.บ.ยา ไม่ได้จำกัดเฉพาะยาที่ทำเทียมทั้งเม็ด แต่ครอบคลุมยาที่แสดงข้อมูลอันเป็นเท็จในสาระสำคัญด้วย เช่น แสดงชื่อว่าเป็นยาอื่น แสดงวันเดือนปีที่ยาสิ้นอายุเกินความจริง แสดงชื่อผู้ผลิตหรือที่ตั้งสถานที่ผลิตที่ไม่เป็นความจริง หรือแสดงว่าเป็นยาตามตำรับที่ขึ้นทะเบียนซึ่งไม่เป็นความจริง\n\nการปิดสติกเกอร์ขยายวันสิ้นอายุจึงทำให้ยานั้นเป็นยาปลอมทันที แม้ตัวยาจะยังมีคุณภาพดี และการขายยาปลอมเป็นความผิดที่มีโทษสูงกว่าการขายยาผิดมาตรฐานหรือยาเสื่อมคุณภาพ", "choices": [{"label": "A", "text": "ยาปลอม เพราะแสดงวันเดือนปีที่ยาสิ้นอายุเกินความจริง", "is_correct": true, "explanation": "ถูกต้อง พ.ร.บ.ยา กำหนดให้ยาที่แสดงวันเดือนปีที่ยาสิ้นอายุเกินความจริงเป็นยาปลอม"}, {"label": "B", "text": "ยาเสื่อมคุณภาพ เพราะเป็นยาที่ใกล้ถึงวันสิ้นอายุ", "is_correct": false, "explanation": "ผิด ยาที่ใกล้สิ้นอายุแต่ยังไม่สิ้นอายุไม่ได้เป็นยาเสื่อมคุณภาพด้วยเหตุนั้น ประเด็นของข้อนี้คือการแสดงวันสิ้นอายุเท็จ"}, {"label": "C", "text": "ยาผิดมาตรฐาน เพราะฉลากไม่ตรงกับที่ขึ้นทะเบียนไว้", "is_correct": false, "explanation": "ผิด ยาผิดมาตรฐานเกี่ยวกับคุณภาพของยาที่ผลิต ไม่ใช่การปลอมแปลงวันสิ้นอายุ"}, {"label": "D", "text": "ยังเป็นยาปกติ หากตรวจวิเคราะห์แล้วตัวยาสำคัญยังอยู่ในเกณฑ์", "is_correct": false, "explanation": "ผิด การแสดงวันสิ้นอายุเกินความจริงทำให้เป็นยาปลอมตามกฎหมาย โดยไม่ต้องพิจารณาผลวิเคราะห์"}, {"label": "E", "text": "เป็นเพียงความผิดเรื่องฉลาก ไม่ได้จัดเป็นยาประเภทที่ห้ามขาย", "is_correct": false, "explanation": "ผิด กฎหมายจัดให้การแสดงวันสิ้นอายุเกินจริงเป็นยาปลอม ซึ่งห้ามผลิต นำเข้า และขาย"}], "key_takeaway": "แก้หรือปิดทับวันสิ้นอายุให้ช้ากว่าความจริงเท่ากับทำให้ยานั้นเป็นยาปลอม"}'::jsonb, 'medium', 'law-day1 • ยาปลอม (วันสิ้นอายุเกินจริง)'),
('5a02b596207085e0ebd7b1e783d2d435', 14, 'บุคคลหนึ่งเปิดเพจเฟซบุ๊กขายยาปฏิชีวนะและยาเม็ดคุมกำเนิดซึ่งเป็นยาอันตราย โดยรับคำสั่งซื้อทางข้อความแล้วส่งพัสดุถึงบ้านผู้ซื้อ บุคคลนี้ไม่มีใบอนุญาตขายยาและไม่มีสถานที่ขายยาที่ได้รับอนุญาต ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ไม่ผิด หากยาทุกรายการที่ขายเป็นยาที่ขึ้นทะเบียนตำรับถูกต้อง"}, {"label": "B", "text": "ไม่ผิด หากผู้ขายเป็นเภสัชกรที่มีใบอนุญาตประกอบวิชาชีพ"}, {"label": "C", "text": "ผิดเฉพาะกฎหมายว่าด้วยการพาณิชย์อิเล็กทรอนิกส์ แต่ไม่ผิดพระราชบัญญัติยา"}, {"label": "D", "text": "ผิดพระราชบัญญัติยา เพราะขายยาโดยไม่ได้รับอนุญาตและไม่ได้ขายในสถานที่ที่ได้รับอนุญาต"}, {"label": "E", "text": "ไม่ผิด หากผู้ซื้อส่งรูปใบสั่งยาของแพทย์มาก่อนสั่งซื้อ"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ผิด พ.ร.บ.ยา เพราะขายยาโดยไม่ได้รับอนุญาตและไม่ได้ขายในสถานที่ที่ได้รับอนุญาต — การขายยาแผนปัจจุบันต้องมีใบอนุญาตและขายในสถานที่ที่ได้รับอนุญาตเท่านั้น", "reason": "พ.ร.บ.ยา กำหนดให้ผู้ขายยาแผนปัจจุบันต้องได้รับใบอนุญาต และขายยาได้เฉพาะ ณ สถานที่ที่ระบุไว้ในใบอนุญาต การรับคำสั่งซื้อผ่านสื่อสังคมออนไลน์แล้วส่งพัสดุโดยไม่มีร้านขายยาที่ได้รับอนุญาตและไม่มีเภสัชกรควบคุมการส่งมอบ จึงเป็นการขายยาโดยไม่ได้รับอนุญาต\n\nนอกจากนี้ การโพสต์แสดงสรรพคุณยาอันตรายต่อประชาชนทั่วไปอาจเป็นความผิดฐานโฆษณาขายยาที่ฝ่าฝืนกฎหมายอีกด้วย ทะเบียนตำรับ ใบอนุญาตประกอบวิชาชีพ หรือใบสั่งยา ไม่สามารถใช้แทนใบอนุญาตขายยาได้", "choices": [{"label": "A", "text": "ไม่ผิด หากยาทุกรายการที่ขายเป็นยาที่ขึ้นทะเบียนตำรับถูกต้อง", "is_correct": false, "explanation": "ผิด ทะเบียนตำรับเป็นการควบคุมตัวผลิตภัณฑ์ ไม่ได้ให้สิทธิบุคคลใดขายยาโดยไม่มีใบอนุญาต"}, {"label": "B", "text": "ไม่ผิด หากผู้ขายเป็นเภสัชกรที่มีใบอนุญาตประกอบวิชาชีพ", "is_correct": false, "explanation": "ผิด ใบอนุญาตประกอบวิชาชีพเภสัชกรรมไม่ใช่ใบอนุญาตขายยา และไม่ทำให้ขายยานอกสถานที่ที่ได้รับอนุญาตได้"}, {"label": "C", "text": "ผิดเฉพาะกฎหมายว่าด้วยการพาณิชย์อิเล็กทรอนิกส์ แต่ไม่ผิดพระราชบัญญัติยา", "is_correct": false, "explanation": "ผิด การขายยาโดยไม่ได้รับอนุญาตเป็นความผิดตาม พ.ร.บ.ยาโดยตรง ไม่ว่าจะขายผ่านช่องทางใด"}, {"label": "D", "text": "ผิดพระราชบัญญัติยา เพราะขายยาโดยไม่ได้รับอนุญาตและไม่ได้ขายในสถานที่ที่ได้รับอนุญาต", "is_correct": true, "explanation": "ถูกต้อง การขายยาแผนปัจจุบันต้องมีใบอนุญาตและขายในสถานที่ที่ระบุในใบอนุญาต การขายผ่านเพจโดยไม่มีทั้งสองอย่างจึงผิดกฎหมาย"}, {"label": "E", "text": "ไม่ผิด หากผู้ซื้อส่งรูปใบสั่งยาของแพทย์มาก่อนสั่งซื้อ", "is_correct": false, "explanation": "ผิด ใบสั่งยาไม่ได้ทำให้ผู้ที่ไม่มีใบอนุญาตมีสิทธิขายยา"}], "key_takeaway": "ขายยาออนไลน์โดยไม่มีร้านขายยาที่ได้รับอนุญาตเป็นการขายยาโดยไม่ได้รับอนุญาต"}'::jsonb, 'medium', 'law-day1 • การขายยาออนไลน์/นอกสถานที่ที่ได้รับอนุญาต'),
('bd2b9475a9fd999c3b29a014ce8dd478', 15, 'ร้านขายของชำแห่งหนึ่งนำยาเม็ดหลายชนิด ได้แก่ prednisolone ยาแก้ปวด และยาต้านฮิสตามีน มาจัดรวมใส่ซองพลาสติกซองละ 4–5 เม็ด เขียนหน้าซองว่า “ยาแก้ปวดเมื่อย” แล้วขายให้ชาวบ้าน ข้อใดอธิบายสถานะทางกฎหมายได้ถูกต้องที่สุด', '[{"label": "A", "text": "ไม่ผิด เพราะยาแต่ละชนิดในซองเป็นยาที่ขึ้นทะเบียนตำรับแล้ว"}, {"label": "B", "text": "เป็นการขายยาชุดที่ผิดกฎหมายหลายประการ เช่น ขายยาโดยไม่ได้รับอนุญาต และขายยาอันตรายโดยไม่มีเภสัชกร"}, {"label": "C", "text": "ผิดเฉพาะเมื่อมีผู้ป่วยได้รับอันตรายจากการใช้ยาชุดนั้น"}, {"label": "D", "text": "ไม่ผิด หากเจ้าของร้านมีใบอนุญาตขายยาสามัญประจำบ้าน"}, {"label": "E", "text": "ผิดเพียงเรื่องฉลากไม่ครบ หากแก้ไขฉลากให้ครบถ้วนก็ขายต่อได้"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. เป็นการขายยาชุดที่ผิดกฎหมายหลายประการ เช่น ขายยาโดยไม่ได้รับอนุญาต และขายยาอันตรายโดยไม่มีเภสัชกร — ยาชุดมักประกอบด้วยยาอันตรายที่แบ่งบรรจุและขายโดยผู้ไม่มีใบอนุญาต", "reason": "“ยาชุด” คือการนำยาหลายชนิด ซึ่งมักมียาอันตรายอย่าง corticosteroid หรือ NSAIDs ปนอยู่ มาจัดรวมกันเพื่อขายให้ประชาชนโดยไม่ผ่านการวินิจฉัย การกระทำนี้ผิด พ.ร.บ.ยา หลายประเด็น ได้แก่ ขายยาแผนปัจจุบันโดยไม่ได้รับอนุญาต ขายยาอันตรายโดยไม่มีเภสัชกรควบคุม และการแบ่งบรรจุเพื่อขายยังเข้านิยามการผลิตโดยไม่ได้รับอนุญาตด้วย\n\nข้อยกเว้นการขายยาสามัญประจำบ้านใช้กับยาสามัญประจำบ้านที่บรรจุเสร็จเท่านั้น ไม่ครอบคลุมการนำยาอันตรายมาแบ่งขาย", "choices": [{"label": "A", "text": "ไม่ผิด เพราะยาแต่ละชนิดในซองเป็นยาที่ขึ้นทะเบียนตำรับแล้ว", "is_correct": false, "explanation": "ผิด การขึ้นทะเบียนตำรับของยาแต่ละชนิดไม่ได้ทำให้ร้านมีสิทธิแบ่งบรรจุและขายยาอันตรายโดยไม่มีใบอนุญาต"}, {"label": "B", "text": "เป็นการขายยาชุดที่ผิดกฎหมายหลายประการ เช่น ขายยาโดยไม่ได้รับอนุญาต และขายยาอันตรายโดยไม่มีเภสัชกร", "is_correct": true, "explanation": "ถูกต้อง ร้านไม่มีใบอนุญาตขายยา นำยาอันตรายมาแบ่งบรรจุรวมกันและขายโดยไม่มีเภสัชกร จึงผิดกฎหมายหลายประเด็น"}, {"label": "C", "text": "ผิดเฉพาะเมื่อมีผู้ป่วยได้รับอันตรายจากการใช้ยาชุดนั้น", "is_correct": false, "explanation": "ผิด ความผิดเกิดขึ้นตั้งแต่ขายหรือมีไว้เพื่อขาย โดยไม่ต้องรอให้เกิดความเสียหาย"}, {"label": "D", "text": "ไม่ผิด หากเจ้าของร้านมีใบอนุญาตขายยาสามัญประจำบ้าน", "is_correct": false, "explanation": "ผิด กฎหมายไม่มีใบอนุญาตขายยาสามัญประจำบ้าน เพราะการขายยาสามัญประจำบ้านได้รับยกเว้นอยู่แล้ว และข้อยกเว้นนี้ไม่ครอบคลุมยาอันตรายอย่าง prednisolone"}, {"label": "E", "text": "ผิดเพียงเรื่องฉลากไม่ครบ หากแก้ไขฉลากให้ครบถ้วนก็ขายต่อได้", "is_correct": false, "explanation": "ผิด แม้แก้ฉลากแล้ว ร้านก็ยังไม่มีใบอนุญาตและไม่มีเภสัชกรควบคุมการขายยาอันตราย"}], "key_takeaway": "การจัดยาชุดขายในร้านค้าทั่วไปผิดกฎหมายหลายประเด็นและเสี่ยงอันตรายจากสเตียรอยด์แฝง"}'::jsonb, 'medium', 'law-day1 • ยาชุด'),
('d90d94f24a7d56460cf3cc97b3aed48b', 16, 'ภก. ข. เป็นผู้มีหน้าที่ปฏิบัติการของร้าน ขย.1 ร้านที่ 1 เวลา 09.00–17.00 น. ต่อมาร้านที่ 2 ซึ่งอยู่ห่างออกไป 5 กิโลเมตร ต้องการแจ้งชื่อ ภก. ข. เป็นผู้มีหน้าที่ปฏิบัติการเวลา 13.00–21.00 น. โดยให้ ภก. ข. ขับรถสลับไปมาระหว่างสองร้าน ข้อใดถูกต้อง', '[{"label": "A", "text": "ทำได้ เพราะทั้งสองร้านตั้งอยู่ในจังหวัดเดียวกัน"}, {"label": "B", "text": "ทำไม่ได้ เพราะผู้มีหน้าที่ปฏิบัติการต้องอยู่ประจำสถานที่ขายยาตลอดเวลาที่แจ้งไว้ ซึ่งเวลาทั้งสองร้านทับซ้อนกัน"}, {"label": "C", "text": "ทำได้ หากติดกล้องวงจรปิดให้เภสัชกรเฝ้าดูอีกร้านได้ตลอดเวลา"}, {"label": "D", "text": "ทำได้ หากผู้รับอนุญาตของทั้งสองร้านเป็นบุคคลเดียวกัน"}, {"label": "E", "text": "ทำได้ หากช่วงเวลาที่ทับซ้อนรวมกันไม่เกินวันละ 4 ชั่วโมง"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ทำไม่ได้ เพราะผู้มีหน้าที่ปฏิบัติการต้องอยู่ประจำตลอดเวลาที่แจ้ง และเวลาทั้งสองร้านทับซ้อนกัน — หน้าที่อยู่ประจำตลอดเวลาทำการทำให้แจ้งเวลาปฏิบัติการทับซ้อนสองแห่งไม่ได้", "reason": "พ.ร.บ.ยา กำหนดให้ผู้มีหน้าที่ปฏิบัติการของร้านขายยาแผนปัจจุบันอยู่ประจำ ณ สถานที่ขายยาตลอดเวลาที่เปิดทำการตามที่แจ้งไว้ เพื่อควบคุมการขายยาอันตรายและยาควบคุมพิเศษด้วยตนเอง หากแจ้งเวลาปฏิบัติการในสองร้านทับซ้อนกัน เภสัชกรย่อมปฏิบัติหน้าที่ได้ครบเพียงร้านเดียว อีกร้านจึงไม่มีผู้มีหน้าที่ปฏิบัติการตามที่กฎหมายกำหนด\n\nเภสัชกรปฏิบัติงานในหลายสถานที่ได้ถ้าช่วงเวลาไม่ทับซ้อนกันและได้แจ้งต่อผู้อนุญาตอย่างถูกต้อง", "choices": [{"label": "A", "text": "ทำได้ เพราะทั้งสองร้านตั้งอยู่ในจังหวัดเดียวกัน", "is_correct": false, "explanation": "ผิด ระยะทางหรือการอยู่จังหวัดเดียวกันไม่ทำให้เภสัชกรอยู่ประจำสองร้านพร้อมกันได้"}, {"label": "B", "text": "ทำไม่ได้ เพราะผู้มีหน้าที่ปฏิบัติการต้องอยู่ประจำสถานที่ขายยาตลอดเวลาที่แจ้งไว้ ซึ่งเวลาทั้งสองร้านทับซ้อนกัน", "is_correct": true, "explanation": "ถูกต้อง เภสัชกรอยู่สองสถานที่ในเวลาเดียวกันไม่ได้ การแจ้งเวลาทับซ้อนจึงขัดหน้าที่อยู่ประจำตลอดเวลาทำการ"}, {"label": "C", "text": "ทำได้ หากติดกล้องวงจรปิดให้เภสัชกรเฝ้าดูอีกร้านได้ตลอดเวลา", "is_correct": false, "explanation": "ผิด การดูผ่านกล้องไม่ใช่การอยู่ประจำและควบคุมการขายยา ณ สถานที่ขายยา"}, {"label": "D", "text": "ทำได้ หากผู้รับอนุญาตของทั้งสองร้านเป็นบุคคลเดียวกัน", "is_correct": false, "explanation": "ผิด หน้าที่อยู่ประจำผูกกับสถานที่ขายยาแต่ละแห่ง ไม่ได้ขึ้นกับว่าเจ้าของเป็นใคร"}, {"label": "E", "text": "ทำได้ หากช่วงเวลาที่ทับซ้อนรวมกันไม่เกินวันละ 4 ชั่วโมง", "is_correct": false, "explanation": "ผิด กฎหมายไม่มีข้อยกเว้นให้แจ้งเวลาทับซ้อนได้ตามจำนวนชั่วโมง"}], "key_takeaway": "เภสัชกรคนเดียวจะเป็นผู้มีหน้าที่ปฏิบัติการสองร้านในช่วงเวลาที่ทับซ้อนกันไม่ได้"}'::jsonb, 'medium', 'law-day1 • ผู้มีหน้าที่ปฏิบัติการหลายแห่ง'),
('ea516a3b522f21ff931508463f6e64ac', 17, 'ร้านขายยาแห่งหนึ่งติดป้ายหน้าร้านโฆษณายาทาภายนอกชนิดบรรจุเสร็จที่ไม่ใช่ยาอันตราย ข้อความว่า “ทาแล้วหายขาด ไม่กลับมาเป็นซ้ำ ดาราชื่อดังใช้แล้วยืนยันผล” ข้อใดถูกต้อง', '[{"label": "A", "text": "ไม่ขัดกฎหมาย เพราะไม่ใช่ยาอันตรายจึงโฆษณาได้โดยอิสระ"}, {"label": "B", "text": "ไม่ขัดกฎหมาย เพราะป้ายในบริเวณร้านไม่ถือเป็นการโฆษณา"}, {"label": "C", "text": "ขัดกฎหมายเฉพาะส่วนที่อ้างดารา ส่วนคำว่า “หายขาด” ใช้ได้หากมีงานวิจัยรองรับ"}, {"label": "D", "text": "ไม่ขัดกฎหมาย หากผู้ผลิตยินยอมให้ร้านใช้ข้อความดังกล่าว"}, {"label": "E", "text": "ขัดกฎหมาย เพราะโอ้อวดว่ารักษาได้หายขาด และใช้บุคคลอื่นรับรองหรือยกย่องสรรพคุณยา"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ขัดกฎหมาย เพราะโอ้อวดว่ารักษาได้หายขาดและใช้บุคคลอื่นรับรองสรรพคุณยา — ข้อความโฆษณานี้ขัดข้อห้ามด้านเนื้อหาของการโฆษณาขายยาตาม พ.ร.บ.ยา", "reason": "พ.ร.บ.ยา กำหนดว่าการโฆษณาขายยาต้องไม่โอ้อวดสรรพคุณว่าบำบัด บรรเทา รักษา หรือป้องกันโรคได้อย่างศักดิ์สิทธิ์หรือหายขาด ต้องไม่ใช้ข้อความที่บุคคลอื่นรับรองหรือยกย่องสรรพคุณยา และต้องไม่แสดงสรรพคุณยาเกินความจริง ข้อห้ามเหล่านี้ใช้กับยาทุกประเภท ไม่ใช่เฉพาะยาอันตราย\n\nป้ายหน้าร้านที่แสดงสรรพคุณยาเพื่อจูงใจให้ซื้อถือเป็นการโฆษณา จึงต้องได้รับอนุมัติก่อนและต้องไม่มีข้อความต้องห้าม", "choices": [{"label": "A", "text": "ไม่ขัดกฎหมาย เพราะไม่ใช่ยาอันตรายจึงโฆษณาได้โดยอิสระ", "is_correct": false, "explanation": "ผิด ข้อห้ามด้านเนื้อหาโฆษณาใช้กับยาทุกประเภท และการโฆษณาต้องได้รับอนุมัติก่อนด้วย"}, {"label": "B", "text": "ไม่ขัดกฎหมาย เพราะป้ายในบริเวณร้านไม่ถือเป็นการโฆษณา", "is_correct": false, "explanation": "ผิด ป้ายที่แสดงสรรพคุณยาต่อสาธารณะเพื่อจูงใจให้ซื้อถือเป็นการโฆษณา"}, {"label": "C", "text": "ขัดกฎหมายเฉพาะส่วนที่อ้างดารา ส่วนคำว่า “หายขาด” ใช้ได้หากมีงานวิจัยรองรับ", "is_correct": false, "explanation": "ผิด ข้อความโอ้อวดว่ารักษาหายขาดเป็นข้อห้ามโดยตรง งานวิจัยไม่ทำให้ใช้ได้"}, {"label": "D", "text": "ไม่ขัดกฎหมาย หากผู้ผลิตยินยอมให้ร้านใช้ข้อความดังกล่าว", "is_correct": false, "explanation": "ผิด ความยินยอมของผู้ผลิตไม่ทดแทนการอนุมัติของผู้อนุญาต และไม่ทำให้ข้อความต้องห้ามใช้ได้"}, {"label": "E", "text": "ขัดกฎหมาย เพราะโอ้อวดว่ารักษาได้หายขาด และใช้บุคคลอื่นรับรองหรือยกย่องสรรพคุณยา", "is_correct": true, "explanation": "ถูกต้อง ข้อความนี้ขัดข้อห้ามการโฆษณาขายยาสองข้อ คือโอ้อวดว่ารักษาหายขาด และใช้บุคคลอื่นรับรองสรรพคุณ"}], "key_takeaway": "โฆษณายาห้ามอ้างว่ารักษาหายขาดและห้ามใช้บุคคลอื่นรับรองสรรพคุณ ไม่ว่าจะเป็นยาประเภทใด"}'::jsonb, 'medium', 'law-day1 • การโฆษณายา (ข้อห้ามเนื้อหา)'),
('86e4b652e73543a7e48ccc07735c36d0', 18, 'ร้านขายยา ขย.1 ได้รับหนังสือแจ้งจากผู้รับอนุญาตผลิตยาว่ายาน้ำเชื่อมล็อตหนึ่งถูกเรียกคืนเพราะพบการปนเปื้อน ร้านยังมียาล็อตนี้เหลือ 12 ขวด เภสัชกรควรทำอย่างไรจึงเหมาะสมที่สุดตามหลักวิธีปฏิบัติทางเภสัชกรรมชุมชน (GPP)', '[{"label": "A", "text": "หยุดขายทันที แยกเก็บในพื้นที่เฉพาะพร้อมป้ายชี้บ่ง แล้วส่งคืนตามระบบเรียกคืนและบันทึกหลักฐาน"}, {"label": "B", "text": "ขายยาที่เหลือต่อจนหมด เพราะเป็นยาที่ขึ้นทะเบียนแล้ว แล้วจึงงดสั่งซื้อล็อตนี้"}, {"label": "C", "text": "ทิ้งยาทั้งหมดในถังขยะทั่วไปทันทีโดยไม่ต้องบันทึก"}, {"label": "D", "text": "วางไว้บนชั้นขายตามเดิม แต่ติดป้ายลดราคาเพื่อระบายสต็อก"}, {"label": "E", "text": "รอให้เจ้าหน้าที่ อย. มาตรวจร้านก่อน จึงจะดำเนินการกับยาล็อตนี้"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. หยุดขายทันที แยกเก็บพร้อมป้ายชี้บ่ง ส่งคืนตามระบบเรียกคืนและบันทึกหลักฐาน — GPP กำหนดให้ร้านมีระบบจัดการยาเรียกคืนและแยกยาที่ไม่พร้อมจำหน่ายออกจากยาที่ขาย", "reason": "มาตรฐานร้านขายยาตามกฎกระทรวงว่าด้วยการขออนุญาตและการออกใบอนุญาตขายยาแผนปัจจุบัน พ.ศ. 2556 (GPP) กำหนดให้ร้านมีระบบควบคุมคุณภาพยา รวมถึงการจัดการยาที่ถูกเรียกคืน ยาหมดอายุ หรือยาเสื่อมคุณภาพ โดยต้องแยกเก็บในพื้นที่เฉพาะที่มีป้ายชัดเจน ไม่ปะปนกับยาที่จำหน่าย และส่งคืนหรือทำลายอย่างมีบันทึกตรวจสอบได้\n\nในภาพรวม ผู้รับอนุญาตผลิตหรือนำเข้ามีหน้าที่เรียกเก็บยาคืนเมื่อพบปัญหาคุณภาพหรือความปลอดภัย และร้านขายยาซึ่งเป็นปลายทางต้องร่วมดำเนินการ การขายยาที่ถูกเรียกคืนเพราะคุณภาพไม่ได้มาตรฐานยังอาจเป็นความผิดฐานขายยาผิดมาตรฐานด้วย", "choices": [{"label": "A", "text": "หยุดขายทันที แยกเก็บในพื้นที่เฉพาะพร้อมป้ายชี้บ่ง แล้วส่งคืนตามระบบเรียกคืนและบันทึกหลักฐาน", "is_correct": true, "explanation": "ถูกต้อง เป็นขั้นตอนตามระบบเรียกคืนยาและการจัดการยาที่ไม่พร้อมจำหน่ายตามหลัก GPP"}, {"label": "B", "text": "ขายยาที่เหลือต่อจนหมด เพราะเป็นยาที่ขึ้นทะเบียนแล้ว แล้วจึงงดสั่งซื้อล็อตนี้", "is_correct": false, "explanation": "ผิด ยาที่ถูกเรียกคืนเพราะปัญหาคุณภาพต้องหยุดขายทันที ทะเบียนตำรับไม่ได้รับรองคุณภาพของล็อตที่มีปัญหา"}, {"label": "C", "text": "ทิ้งยาทั้งหมดในถังขยะทั่วไปทันทีโดยไม่ต้องบันทึก", "is_correct": false, "explanation": "ผิด ต้องส่งคืนหรือทำลายตามระบบที่กำหนดพร้อมบันทึกหลักฐาน และการทิ้งยาในขยะทั่วไปไม่เหมาะสม"}, {"label": "D", "text": "วางไว้บนชั้นขายตามเดิม แต่ติดป้ายลดราคาเพื่อระบายสต็อก", "is_correct": false, "explanation": "ผิด การวางขายยาที่ถูกเรียกคืนยังถือเป็นการมีไว้เพื่อขาย และเสี่ยงต่อผู้ป่วย"}, {"label": "E", "text": "รอให้เจ้าหน้าที่ อย. มาตรวจร้านก่อน จึงจะดำเนินการกับยาล็อตนี้", "is_correct": false, "explanation": "ผิด ร้านต้องดำเนินการทันทีที่ได้รับแจ้ง ไม่ต้องรอการตรวจ"}], "key_takeaway": "เมื่อได้รับแจ้งเรียกคืนยา ให้หยุดขาย แยกเก็บพร้อมป้าย ส่งคืน และบันทึกหลักฐานทันที"}'::jsonb, 'medium', 'law-day1 • การเรียกคืนยา'),
('69f330d15a2d7f32b92cbe64ecd7f6c6', 19, 'ผู้ป่วยนำใบสั่งยาจากแพทย์ประจำคลินิกเวชกรรมเอกชนมาที่ร้าน ขย.1 เพื่อซื้อยาซึ่งจัดเป็นยาควบคุมพิเศษ ข้อใดเป็นการปฏิบัติที่ถูกต้อง', '[{"label": "A", "text": "ร้านขายยาไม่มีสิทธิขายยาควบคุมพิเศษ ผู้ป่วยต้องรับยาจากโรงพยาบาลเท่านั้น"}, {"label": "B", "text": "ขายได้โดยไม่ต้องมีใบสั่งยา หากเภสัชกรซักประวัติแล้วเห็นว่าจำเป็น"}, {"label": "C", "text": "เภสัชกรขายได้ตามใบสั่งยาที่ถูกต้อง บันทึกการขายยาควบคุมพิเศษ และเก็บหลักฐานใบสั่งยาตามที่กฎหมายกำหนด"}, {"label": "D", "text": "ผู้ช่วยเภสัชกรขายได้ หากผู้ป่วยมีใบสั่งยาที่ครบถ้วน"}, {"label": "E", "text": "ขายได้ แต่ต้องคืนใบสั่งยาให้ผู้ป่วยไว้ใช้ซื้อซ้ำในครั้งต่อไป"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. เภสัชกรขายได้ตามใบสั่งยาที่ถูกต้อง พร้อมบันทึกการขายและเก็บหลักฐานใบสั่งยา — ยาควบคุมพิเศษขายได้ใน ขย.1 โดยเภสัชกร เมื่อมีใบสั่งยาที่ถูกต้อง", "reason": "พ.ร.บ.ยา กำหนดให้ผู้รับอนุญาตขายยาแผนปัจจุบันขายยาควบคุมพิเศษได้เฉพาะตามใบสั่งยาของผู้ประกอบวิชาชีพเวชกรรม ทันตกรรม หรือผู้ประกอบการบำบัดโรคสัตว์ และการขายต้องทำโดยเภสัชกรผู้มีหน้าที่ปฏิบัติการ\n\nร้านต้องจัดทำบัญชีหรือบันทึกการขายยาควบคุมพิเศษตามแบบที่กฎหมายกำหนด และเก็บหลักฐานใบสั่งยาไว้ให้ตรวจสอบได้ ซึ่งเป็นส่วนหนึ่งของการควบคุมการขายยาตามมาตรฐาน GPP", "choices": [{"label": "A", "text": "ร้านขายยาไม่มีสิทธิขายยาควบคุมพิเศษ ผู้ป่วยต้องรับยาจากโรงพยาบาลเท่านั้น", "is_correct": false, "explanation": "ผิด ร้าน ขย.1 ขายยาควบคุมพิเศษได้ตามใบสั่งยา"}, {"label": "B", "text": "ขายได้โดยไม่ต้องมีใบสั่งยา หากเภสัชกรซักประวัติแล้วเห็นว่าจำเป็น", "is_correct": false, "explanation": "ผิด ลักษณะสำคัญของยาควบคุมพิเศษคือต้องขายตามใบสั่งยา ดุลยพินิจของเภสัชกรใช้แทนใบสั่งยาไม่ได้"}, {"label": "C", "text": "เภสัชกรขายได้ตามใบสั่งยาที่ถูกต้อง บันทึกการขายยาควบคุมพิเศษ และเก็บหลักฐานใบสั่งยาตามที่กฎหมายกำหนด", "is_correct": true, "explanation": "ถูกต้อง ขย.1 ขายยาควบคุมพิเศษได้เมื่อมีใบสั่งยาของผู้ประกอบวิชาชีพที่กฎหมายกำหนด และต้องบันทึกการขายพร้อมเก็บหลักฐาน"}, {"label": "D", "text": "ผู้ช่วยเภสัชกรขายได้ หากผู้ป่วยมีใบสั่งยาที่ครบถ้วน", "is_correct": false, "explanation": "ผิด การขายยาควบคุมพิเศษต้องทำโดยเภสัชกรผู้มีหน้าที่ปฏิบัติการ ใบสั่งยาไม่ทำให้ผู้ช่วยขายได้"}, {"label": "E", "text": "ขายได้ แต่ต้องคืนใบสั่งยาให้ผู้ป่วยไว้ใช้ซื้อซ้ำในครั้งต่อไป", "is_correct": false, "explanation": "ผิด ร้านต้องเก็บหลักฐานการขายตามใบสั่งยาไว้ การคืนใบสั่งยาเพื่อใช้ซื้อซ้ำเสี่ยงต่อการใช้ซ้ำโดยไม่มีการควบคุม"}], "key_takeaway": "ยาควบคุมพิเศษขายใน ขย.1 ได้เฉพาะตามใบสั่งยา โดยเภสัชกร พร้อมบันทึกและเก็บหลักฐาน"}'::jsonb, 'medium', 'law-day1 • ยาควบคุมพิเศษ'),
('a16b35f66238685af94c3f9845890fda', 20, 'ร้านขายยาแห่งหนึ่งเตรียมรับการตรวจประเมินตามมาตรฐานร้านขายยา (GPP) พบว่าเภสัชกรใช้ถาดนับเม็ดยาใบเดียวกับยาทุกชนิด รวมทั้ง amoxicillin และ co-trimoxazole ข้อใดเป็นการแก้ไขที่ถูกต้องตามหลักเกณฑ์', '[{"label": "A", "text": "ใช้ถาดเดิมได้ แต่ต้องเช็ดด้วยกระดาษทิชชูแห้งหลังนับยาทุกครั้ง"}, {"label": "B", "text": "เลิกใช้ถาด แล้วนับยาด้วยมือเปล่าแทน"}, {"label": "C", "text": "ไม่ต้องแก้ไข เพราะ GPP กำหนดเฉพาะเรื่องตู้เย็นและเทอร์โมมิเตอร์"}, {"label": "D", "text": "จัดถาดนับเม็ดยาแยกไว้เฉพาะยากลุ่มที่แพ้ได้บ่อย เช่น กลุ่ม penicillin และ sulfonamide"}, {"label": "E", "text": "ใช้ถาดเดิมได้ หากยาทุกรายการเป็นยาเม็ดเคลือบฟิล์ม"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. จัดถาดนับเม็ดยาแยกไว้เฉพาะยากลุ่มที่แพ้ได้บ่อย เช่น penicillin และ sulfonamide — ป้องกันการปนเปื้อนข้ามของยาที่ก่อการแพ้ได้บ่อยไปยังยาอื่น", "reason": "มาตรฐานร้านขายยาตามกฎกระทรวงฯ พ.ศ. 2556 กำหนดอุปกรณ์ที่ร้านต้องมีเพื่อให้การส่งมอบยามีคุณภาพ หนึ่งในนั้นคือถาดนับเม็ดยาที่แยกไว้ใช้เฉพาะกับยากลุ่มที่ก่อการแพ้ได้บ่อย อย่างกลุ่ม penicillin และ sulfonamide เพราะผงยาที่ตกค้างอาจปนไปกับยาอื่นและทำให้ผู้ป่วยที่แพ้ยาได้รับยาโดยไม่รู้ตัว\n\nอุปกรณ์อื่นที่ GPP กำหนด เช่น ตู้เย็นสำหรับเก็บยาพร้อมเครื่องวัดอุณหภูมิ และอุปกรณ์ตรวจคัดกรองพื้นฐาน", "choices": [{"label": "A", "text": "ใช้ถาดเดิมได้ แต่ต้องเช็ดด้วยกระดาษทิชชูแห้งหลังนับยาทุกครั้ง", "is_correct": false, "explanation": "ผิด การเช็ดด้วยทิชชูแห้งป้องกันผงยาตกค้างไม่ได้แน่นอน หลักเกณฑ์จึงกำหนดให้แยกถาด"}, {"label": "B", "text": "เลิกใช้ถาด แล้วนับยาด้วยมือเปล่าแทน", "is_correct": false, "explanation": "ผิด การนับยาด้วยมือเปล่าไม่ถูกสุขลักษณะ และยังทำให้ยาปนเปื้อนข้ามได้"}, {"label": "C", "text": "ไม่ต้องแก้ไข เพราะ GPP กำหนดเฉพาะเรื่องตู้เย็นและเทอร์โมมิเตอร์", "is_correct": false, "explanation": "ผิด GPP ครอบคลุมอุปกรณ์การส่งมอบยาด้วย ไม่ได้มีเฉพาะอุปกรณ์ควบคุมอุณหภูมิ"}, {"label": "D", "text": "จัดถาดนับเม็ดยาแยกไว้เฉพาะยากลุ่มที่แพ้ได้บ่อย เช่น กลุ่ม penicillin และ sulfonamide", "is_correct": true, "explanation": "ถูกต้อง GPP กำหนดให้แยกถาดนับเม็ดยาสำหรับยากลุ่มที่ก่อการแพ้ได้บ่อย เพื่อป้องกันการปนเปื้อนข้ามไปยังยาอื่น"}, {"label": "E", "text": "ใช้ถาดเดิมได้ หากยาทุกรายการเป็นยาเม็ดเคลือบฟิล์ม", "is_correct": false, "explanation": "ผิด ยาเคลือบฟิล์มก็มีผงยาหลุดหรือแตกได้ ไม่ใช่ข้อยกเว้นตามหลักเกณฑ์"}], "key_takeaway": "ร้านขายยาต้องมีถาดนับยาแยกสำหรับยากลุ่มแพ้ง่าย เช่น penicillin และ sulfonamide"}'::jsonb, 'medium', 'law-day1 • GPP: อุปกรณ์และการป้องกันการปนเปื้อน'),
('21d8da3bb0f3ef4450c4834aebfa7f33', 21, 'เภสัชกรร้าน ขย.1 แบ่งจ่ายยาเม็ด ibuprofen 20 เม็ดใส่ซองให้ผู้ป่วย ตามมาตรฐานร้านขายยา (GPP) ฉลากยาที่ส่งมอบควรมีข้อมูลชุดใดจึงครบถ้วนและเหมาะสมที่สุด', '[{"label": "A", "text": "ชื่อการค้าของยาและราคาขายเท่านั้น เพราะผู้ป่วยได้รับคำแนะนำด้วยวาจาแล้ว"}, {"label": "B", "text": "เลขทะเบียนตำรับยาและเลขที่ผลิต โดยไม่จำเป็นต้องระบุวิธีใช้"}, {"label": "C", "text": "ชื่อเภสัชกรผู้จ่ายยาและเลขที่ใบอนุญาตประกอบวิชาชีพเท่านั้น"}, {"label": "D", "text": "ชื่อและที่อยู่ร้าน ชื่อผู้ป่วย ชื่อยา ความแรง จำนวน ข้อบ่งใช้ วิธีใช้ คำเตือน และวันที่จ่ายยา"}, {"label": "E", "text": "วิธีใช้อย่างเดียว เพราะชื่อยาถือเป็นข้อมูลภายในของร้าน"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ชื่อและที่อยู่ร้าน ชื่อผู้ป่วย ชื่อยา ความแรง จำนวน ข้อบ่งใช้ วิธีใช้ คำเตือน และวันที่จ่าย — GPP กำหนดให้ฉลากยาที่ส่งมอบมีข้อมูลเพียงพอให้ใช้ยาได้ถูกต้องและสืบย้อนได้", "reason": "มาตรฐานร้านขายยาตามกฎกระทรวงฯ พ.ศ. 2556 กำหนดให้ยาที่ส่งมอบแก่ผู้ป่วยโดยไม่ได้อยู่ในภาชนะบรรจุเดิมของผู้ผลิต ต้องมีฉลากที่มีข้อมูลจำเป็น ได้แก่ ชื่อและที่อยู่ของร้าน ชื่อผู้ป่วย ชื่อยา ความแรง จำนวน ข้อบ่งใช้ วิธีใช้ คำเตือนที่จำเป็น และวันที่จ่ายยา\n\nฉลากที่ครบถ้วนช่วยลดความคลาดเคลื่อนทางยาและช่วยให้บุคลากรสุขภาพคนอื่นรู้ว่าผู้ป่วยได้รับยาอะไร", "choices": [{"label": "A", "text": "ชื่อการค้าของยาและราคาขายเท่านั้น เพราะผู้ป่วยได้รับคำแนะนำด้วยวาจาแล้ว", "is_correct": false, "explanation": "ผิด คำแนะนำด้วยวาจาไม่ทดแทนข้อมูลบนฉลาก ผู้ป่วยอาจจำวิธีใช้ไม่ได้"}, {"label": "B", "text": "เลขทะเบียนตำรับยาและเลขที่ผลิต โดยไม่จำเป็นต้องระบุวิธีใช้", "is_correct": false, "explanation": "ผิด วิธีใช้เป็นข้อมูลสำคัญที่สุดสำหรับผู้ป่วยและขาดไม่ได้"}, {"label": "C", "text": "ชื่อเภสัชกรผู้จ่ายยาและเลขที่ใบอนุญาตประกอบวิชาชีพเท่านั้น", "is_correct": false, "explanation": "ผิด ข้อมูลนี้ไม่พอให้ผู้ป่วยรู้ว่ายาคืออะไรและใช้อย่างไร"}, {"label": "D", "text": "ชื่อและที่อยู่ร้าน ชื่อผู้ป่วย ชื่อยา ความแรง จำนวน ข้อบ่งใช้ วิธีใช้ คำเตือน และวันที่จ่ายยา", "is_correct": true, "explanation": "ถูกต้อง เป็นข้อมูลที่ช่วยให้ผู้ป่วยใช้ยาได้ถูกต้องและสืบย้อนแหล่งที่จ่ายยาได้ตามหลัก GPP"}, {"label": "E", "text": "วิธีใช้อย่างเดียว เพราะชื่อยาถือเป็นข้อมูลภายในของร้าน", "is_correct": false, "explanation": "ผิด ผู้ป่วยมีสิทธิทราบชื่อยาที่ได้รับ และชื่อยาจำเป็นต่อการป้องกันการแพ้ยาและยาซ้ำซ้อน"}], "key_takeaway": "ฉลากยาที่ร้านยาแบ่งจ่ายต้องระบุอย่างน้อยร้าน ผู้ป่วย ชื่อยา ความแรง จำนวน ข้อบ่งใช้ วิธีใช้ คำเตือน และวันที่จ่าย"}'::jsonb, 'medium', 'law-day1 • GPP: ฉลากยาที่ส่งมอบ'),
('c9c53b6102041eab3be5d58ce98bdf91', 22, 'นักท่องเที่ยวชาวต่างชาติซึ่งเป็นโรคเบาหวานนำยาแผนปัจจุบันที่ใช้ประจำติดตัวเข้ามาในประเทศไทย เพื่อใช้รักษาตนเองระหว่างพักอยู่ ยานี้ไม่ได้ขึ้นทะเบียนตำรับในประเทศไทย ข้อใดถูกต้อง', '[{"label": "A", "text": "นำเข้าได้โดยไม่ต้องขอใบอนุญาต หากเป็นยาใช้เฉพาะตัวในปริมาณไม่เกินที่จำเป็นตามที่กฎหมายกำหนด"}, {"label": "B", "text": "นำเข้าไม่ได้ทุกกรณี เพราะยาไม่ได้ขึ้นทะเบียนตำรับในประเทศไทย"}, {"label": "C", "text": "ต้องยื่นขอใบอนุญาตนำหรือสั่งยาเข้ามาในราชอาณาจักรก่อนเดินทาง"}, {"label": "D", "text": "นำเข้าได้โดยไม่จำกัดปริมาณ เพราะเป็นยาสำหรับใช้ส่วนตัว"}, {"label": "E", "text": "นำเข้าได้ และขายยาส่วนที่เหลือให้ผู้อื่นก่อนเดินทางกลับได้"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. นำเข้าได้โดยไม่ต้องขอใบอนุญาต หากเป็นยาใช้เฉพาะตัวในปริมาณไม่เกินที่จำเป็นตามที่กฎหมายกำหนด — พ.ร.บ.ยา ยกเว้นการนำยาติดตัวเข้ามาเพื่อใช้เฉพาะตัวในปริมาณจำกัด", "reason": "หลักทั่วไปคือการนำหรือสั่งยาเข้ามาในราชอาณาจักรต้องได้รับใบอนุญาต และยาต้องขึ้นทะเบียนตำรับ แต่ พ.ร.บ.ยา มีข้อยกเว้นสำหรับการนำยาติดตัวเข้ามาเพื่อใช้เฉพาะตัวในปริมาณที่ไม่เกินความจำเป็นตามที่กฎหมายกำหนด เพื่อให้ผู้เดินทางใช้ยาประจำต่อได้\n\nข้อยกเว้นนี้ใช้เพื่อการใช้เองเท่านั้น หากนำไปขายหรือแบ่งให้ผู้อื่นจะกลายเป็นการขายยาโดยไม่ได้รับอนุญาต (ข้อนี้ไม่รวมยาที่อยู่ภายใต้ประมวลกฎหมายยาเสพติด ซึ่งมีหลักเกณฑ์เฉพาะ)", "choices": [{"label": "A", "text": "นำเข้าได้โดยไม่ต้องขอใบอนุญาต หากเป็นยาใช้เฉพาะตัวในปริมาณไม่เกินที่จำเป็นตามที่กฎหมายกำหนด", "is_correct": true, "explanation": "ถูกต้อง พ.ร.บ.ยา ยกเว้นการนำยาติดตัวเข้ามาเพื่อใช้เฉพาะตัวในปริมาณที่ไม่เกินความจำเป็นตามที่กฎหมายกำหนด"}, {"label": "B", "text": "นำเข้าไม่ได้ทุกกรณี เพราะยาไม่ได้ขึ้นทะเบียนตำรับในประเทศไทย", "is_correct": false, "explanation": "ผิด ข้อยกเว้นการนำยาติดตัวเพื่อใช้เฉพาะตัวไม่ได้กำหนดให้ยาต้องขึ้นทะเบียนในไทย"}, {"label": "C", "text": "ต้องยื่นขอใบอนุญาตนำหรือสั่งยาเข้ามาในราชอาณาจักรก่อนเดินทาง", "is_correct": false, "explanation": "ผิด ใบอนุญาตนำเข้าใช้กับการนำเข้าเพื่อประกอบธุรกิจ ไม่ใช่การนำยาติดตัวเพื่อใช้เอง"}, {"label": "D", "text": "นำเข้าได้โดยไม่จำกัดปริมาณ เพราะเป็นยาสำหรับใช้ส่วนตัว", "is_correct": false, "explanation": "ผิด ข้อยกเว้นจำกัดปริมาณไว้ไม่เกินความจำเป็นตามที่กฎหมายกำหนด"}, {"label": "E", "text": "นำเข้าได้ และขายยาส่วนที่เหลือให้ผู้อื่นก่อนเดินทางกลับได้", "is_correct": false, "explanation": "ผิด ข้อยกเว้นใช้กับการใช้เฉพาะตัว การขายให้ผู้อื่นเป็นการขายยาโดยไม่ได้รับอนุญาตและขายยาที่ไม่ได้ขึ้นทะเบียน"}], "key_takeaway": "นำยาติดตัวเพื่อใช้เองได้โดยไม่ต้องมีใบอนุญาต แต่ต้องไม่เกินปริมาณที่จำเป็นและห้ามนำไปขาย"}'::jsonb, 'medium', 'law-day1 • ข้อยกเว้นการนำยาติดตัว'),
('906cfd44a05cfc65e75b767f5a48e666', 23, 'เภสัชกรผู้มีหน้าที่ปฏิบัติการของร้านขายยา ขย.1 แห่งหนึ่งลาออก ผู้รับอนุญาตจ้าง ภก. ค. มาทำงานแทนในวันถัดไป ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ไม่ต้องดำเนินการใด เพราะใบอนุญาตออกในนามผู้รับอนุญาต ไม่ได้ออกในนามเภสัชกร"}, {"label": "B", "text": "แจ้งสภาเภสัชกรรมเพียงหน่วยงานเดียวก็เพียงพอ"}, {"label": "C", "text": "ต้องปิดร้านและยื่นขอใบอนุญาตขายยาฉบับใหม่ทั้งหมด"}, {"label": "D", "text": "เปลี่ยนชื่อได้ในรอบต่ออายุใบอนุญาตครั้งถัดไป"}, {"label": "E", "text": "ผู้รับอนุญาตต้องขอเปลี่ยนผู้มีหน้าที่ปฏิบัติการต่อผู้อนุญาตตามขั้นตอน ภก. ค. จึงจะเป็นผู้มีหน้าที่ปฏิบัติการโดยชอบได้"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ต้องขอเปลี่ยนผู้มีหน้าที่ปฏิบัติการต่อผู้อนุญาต ภก. ค. จึงจะเป็นผู้มีหน้าที่ปฏิบัติการโดยชอบ — ผู้มีหน้าที่ปฏิบัติการเป็นรายการที่ผูกกับใบอนุญาตและต้องเปลี่ยนผ่านผู้อนุญาต", "reason": "ตาม พ.ร.บ.ยา ผู้ขอรับใบอนุญาตขายยาแผนปัจจุบันต้องระบุผู้มีหน้าที่ปฏิบัติการและเวลาปฏิบัติการ เมื่อจะเปลี่ยนตัวผู้มีหน้าที่ปฏิบัติการ ผู้รับอนุญาตต้องยื่นขอเปลี่ยนแปลงต่อผู้อนุญาต (เช่น สำนักงานสาธารณสุขจังหวัดหรือ อย. ตามพื้นที่) ตามแบบและขั้นตอนที่กำหนด\n\nระหว่างที่ยังไม่มีผู้มีหน้าที่ปฏิบัติการที่ถูกต้อง ร้านต้องไม่ขายยาอันตรายหรือยาควบคุมพิเศษ เพื่อไม่ให้ผิดหน้าที่ตามกฎหมาย", "choices": [{"label": "A", "text": "ไม่ต้องดำเนินการใด เพราะใบอนุญาตออกในนามผู้รับอนุญาต ไม่ได้ออกในนามเภสัชกร", "is_correct": false, "explanation": "ผิด แม้ใบอนุญาตจะออกในนามผู้รับอนุญาต แต่ผู้มีหน้าที่ปฏิบัติการเป็นรายการที่ต้องแจ้งและได้รับความเห็นชอบจากผู้อนุญาต"}, {"label": "B", "text": "แจ้งสภาเภสัชกรรมเพียงหน่วยงานเดียวก็เพียงพอ", "is_correct": false, "explanation": "ผิด หน่วยงานที่รับเรื่องเปลี่ยนผู้มีหน้าที่ปฏิบัติการคือผู้อนุญาตตาม พ.ร.บ.ยา ไม่ใช่สภาเภสัชกรรม"}, {"label": "C", "text": "ต้องปิดร้านและยื่นขอใบอนุญาตขายยาฉบับใหม่ทั้งหมด", "is_correct": false, "explanation": "ผิด การเปลี่ยนผู้มีหน้าที่ปฏิบัติการทำได้ด้วยการขอเปลี่ยนแปลง ไม่ต้องขอใบอนุญาตใหม่"}, {"label": "D", "text": "เปลี่ยนชื่อได้ในรอบต่ออายุใบอนุญาตครั้งถัดไป", "is_correct": false, "explanation": "ผิด ต้องดำเนินการเมื่อมีการเปลี่ยนตัว ไม่ใช่รอรอบต่ออายุ เพราะระหว่างนั้นร้านจะไม่มีผู้มีหน้าที่ปฏิบัติการที่ชอบด้วยกฎหมาย"}, {"label": "E", "text": "ผู้รับอนุญาตต้องขอเปลี่ยนผู้มีหน้าที่ปฏิบัติการต่อผู้อนุญาตตามขั้นตอน ภก. ค. จึงจะเป็นผู้มีหน้าที่ปฏิบัติการโดยชอบได้", "is_correct": true, "explanation": "ถูกต้อง ชื่อผู้มีหน้าที่ปฏิบัติการผูกกับใบอนุญาต การเปลี่ยนตัวต้องดำเนินการต่อผู้อนุญาตตามขั้นตอนของกฎหมาย"}], "key_takeaway": "เปลี่ยนเภสัชกรผู้มีหน้าที่ปฏิบัติการต้องยื่นขอเปลี่ยนต่อผู้อนุญาต ไม่ใช่จ้างคนใหม่มาทำงานได้ทันที"}'::jsonb, 'medium', 'law-day1 • การเปลี่ยนผู้มีหน้าที่ปฏิบัติการ'),
('526bf245d988d4eb39e96e119f6abf29', 24, 'บริษัทที่ได้รับใบอนุญาตขายส่งยาแผนปัจจุบันเปิดหน้าร้านที่โกดัง และขายยาอันตรายแบบปลีกให้ประชาชนที่เดินเข้ามาซื้อครั้งละ 1–2 แผง โดยมีเภสัชกรผู้มีหน้าที่ปฏิบัติการของบริษัทอยู่ ข้อใดถูกต้อง', '[{"label": "A", "text": "ถูกต้อง เพราะใบอนุญาตขายส่งครอบคลุมการขายยาทุกระดับ"}, {"label": "B", "text": "ถูกต้อง เพราะมีเภสัชกรผู้มีหน้าที่ปฏิบัติการอยู่ในสถานที่"}, {"label": "C", "text": "ไม่ถูกต้อง เพราะใบอนุญาตขายส่งไม่ครอบคลุมการขายปลีกแก่ประชาชน ต้องมีใบอนุญาต ขย.1 แยกต่างหาก"}, {"label": "D", "text": "ถูกต้อง หากขายในราคาส่งเท่ากับที่ขายให้ร้านขายยา"}, {"label": "E", "text": "ถูกต้อง หากบริษัทออกใบกำกับภาษีให้ผู้ซื้อทุกราย"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ไม่ถูกต้อง เพราะใบอนุญาตขายส่งไม่ครอบคลุมการขายปลีกแก่ประชาชน — ใบอนุญาตแต่ละประเภทมีขอบเขตเฉพาะ การขายปลีกต้องใช้ใบอนุญาตขายปลีก", "reason": "พ.ร.บ.ยา แยกใบอนุญาตตามลักษณะกิจการ การ “ขายส่ง” หมายถึงการขายตรงให้ผู้รับอนุญาตขายยา ผู้รับอนุญาตผลิตหรือนำเข้า ผู้ประกอบวิชาชีพ หรือสถานพยาบาลตามที่กฎหมายกำหนด ไม่รวมการขายให้ประชาชนทั่วไปเพื่อนำไปใช้เอง\n\nการขายปลีกยาอันตรายแก่ประชาชนต้องทำในร้านที่ได้รับใบอนุญาตขายยาแผนปัจจุบัน (ขย.1) ซึ่งมีมาตรฐานสถานที่และการส่งมอบยาตาม GPP การมีเภสัชกรหรือการขายในราคาส่งไม่ได้ทำให้การขายปลีกนั้นอยู่ในขอบเขตใบอนุญาตขายส่ง", "choices": [{"label": "A", "text": "ถูกต้อง เพราะใบอนุญาตขายส่งครอบคลุมการขายยาทุกระดับ", "is_correct": false, "explanation": "ผิด ใบอนุญาตขายส่งมีขอบเขตเฉพาะการขายส่ง ไม่ครอบคลุมการขายปลีกแก่ประชาชน"}, {"label": "B", "text": "ถูกต้อง เพราะมีเภสัชกรผู้มีหน้าที่ปฏิบัติการอยู่ในสถานที่", "is_correct": false, "explanation": "ผิด การมีเภสัชกรอยู่ไม่ได้ขยายขอบเขตของใบอนุญาต"}, {"label": "C", "text": "ไม่ถูกต้อง เพราะใบอนุญาตขายส่งไม่ครอบคลุมการขายปลีกแก่ประชาชน ต้องมีใบอนุญาต ขย.1 แยกต่างหาก", "is_correct": true, "explanation": "ถูกต้อง สิทธิตามใบอนุญาตขายส่งคือขายให้ผู้รับอนุญาตและสถานพยาบาลตามที่กฎหมายกำหนด การขายปลีกแก่ประชาชนต้องมีใบอนุญาตขายปลีก"}, {"label": "D", "text": "ถูกต้อง หากขายในราคาส่งเท่ากับที่ขายให้ร้านขายยา", "is_correct": false, "explanation": "ผิด สิ่งที่บอกว่าเป็นการขายส่งหรือขายปลีกคือผู้ซื้อ ไม่ใช่ราคา"}, {"label": "E", "text": "ถูกต้อง หากบริษัทออกใบกำกับภาษีให้ผู้ซื้อทุกราย", "is_correct": false, "explanation": "ผิด เอกสารทางภาษีไม่เกี่ยวกับขอบเขตของใบอนุญาตตาม พ.ร.บ.ยา"}], "key_takeaway": "ผู้รับอนุญาตขายส่งยาขายปลีกให้ประชาชนไม่ได้ ถ้าจะขายปลีกต้องมีใบอนุญาต ขย.1"}'::jsonb, 'medium', 'law-day1 • ใบอนุญาตขายส่งยา'),
('f9042b5e0ff8868e0133c45ff9ac0bcc', 25, 'บริษัทผู้รับอนุญาตผลิตยาแห่งหนึ่งมียาเม็ด X ความแรง 500 mg ที่ขึ้นทะเบียนตำรับไว้แล้ว ต่อมาบริษัทต้องการ (1) ผลิตความแรง 1,000 mg ออกจำหน่าย และ (2) เปลี่ยนสารช่วยในตำรับ 500 mg เพื่อลดต้นทุน บริษัทเริ่มผลิตและจำหน่ายทั้งสองกรณีทันที โดยอ้างว่าเป็นยาตัวเดิมที่ขึ้นทะเบียนไว้แล้ว ข้อใดถูกต้อง', '[{"label": "A", "text": "กรณี (1) ทำได้ทันทีเพราะตัวยาสำคัญเดิม ส่วนกรณี (2) ต้องขออนุญาตก่อน"}, {"label": "B", "text": "ทั้งสองกรณีต้องได้รับอนุญาตก่อน ความแรงใหม่ต้องขึ้นทะเบียนตำรับ และการเปลี่ยนสูตรต้องได้รับอนุญาตแก้ไขทะเบียน"}, {"label": "C", "text": "กรณี (2) ทำได้ทันทีเพราะไม่ได้เปลี่ยนตัวยาสำคัญ ส่วนกรณี (1) ต้องขึ้นทะเบียนใหม่"}, {"label": "D", "text": "ทั้งสองกรณีทำได้ทันที แล้วแจ้ง อย. ภายหลังการจำหน่าย"}, {"label": "E", "text": "ทั้งสองกรณีทำได้ทันที หากผ่านการควบคุมคุณภาพของโรงงานตามหลัก GMP แล้ว"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ทั้งสองกรณีต้องได้รับอนุญาตก่อน ความแรงใหม่ต้องขึ้นทะเบียน และการเปลี่ยนสูตรต้องได้รับอนุญาตแก้ไขทะเบียน — ทะเบียนตำรับผูกกับสูตรและความแรงที่ได้รับอนุมัติ การเปลี่ยนแปลงต้องได้รับอนุญาตก่อน", "reason": "พ.ร.บ.ยา กำหนดให้ยาที่จะผลิตหรือนำเข้าเพื่อจำหน่ายต้องขึ้นทะเบียนตำรับยา ทะเบียนตำรับครอบคลุมรายละเอียดที่ได้รับอนุมัติ เช่น ชื่อและปริมาณตัวยาสำคัญ ความแรง รูปแบบ และส่วนประกอบของตำรับ ยาความแรงใหม่จึงเป็นตำรับที่ต้องขึ้นทะเบียนแยก ส่วนการเปลี่ยนแปลงรายการในทะเบียนตำรับเดิม เช่น สารช่วย ต้องได้รับอนุญาตแก้ไขทะเบียนก่อน\n\nการผลิตตามสูตรที่ต่างจากที่ขึ้นทะเบียนไว้ทำให้ผลิตภัณฑ์ไม่ตรงตามทะเบียน ผู้รับอนุญาตอาจมีความผิดฐานผลิตยาที่ไม่ได้ขึ้นทะเบียนหรือไม่เป็นไปตามทะเบียน การผ่าน GMP เป็นมาตรฐานของกระบวนการผลิต และไม่ทดแทนการควบคุมด้านทะเบียน", "choices": [{"label": "A", "text": "กรณี (1) ทำได้ทันทีเพราะตัวยาสำคัญเดิม ส่วนกรณี (2) ต้องขออนุญาตก่อน", "is_correct": false, "explanation": "ผิด ความแรงที่ต่างไปทำให้เป็นตำรับใหม่ที่ต้องขึ้นทะเบียน แม้ตัวยาสำคัญจะเหมือนเดิม"}, {"label": "B", "text": "ทั้งสองกรณีต้องได้รับอนุญาตก่อน ความแรงใหม่ต้องขึ้นทะเบียนตำรับ และการเปลี่ยนสูตรต้องได้รับอนุญาตแก้ไขทะเบียน", "is_correct": true, "explanation": "ถูกต้อง ตำรับยาที่ต่างกันในสาระสำคัญต้องขึ้นทะเบียนแยก และการแก้ไขรายการในทะเบียนตำรับต้องได้รับอนุญาตก่อนผลิต"}, {"label": "C", "text": "กรณี (2) ทำได้ทันทีเพราะไม่ได้เปลี่ยนตัวยาสำคัญ ส่วนกรณี (1) ต้องขึ้นทะเบียนใหม่", "is_correct": false, "explanation": "ผิด สารช่วยเป็นส่วนหนึ่งของสูตรตำรับที่ขึ้นทะเบียนไว้ และอาจมีผลต่อคุณภาพยา การเปลี่ยนจึงต้องได้รับอนุญาตก่อน"}, {"label": "D", "text": "ทั้งสองกรณีทำได้ทันที แล้วแจ้ง อย. ภายหลังการจำหน่าย", "is_correct": false, "explanation": "ผิด ทั้งสองกรณีต้องได้รับอนุญาตก่อนผลิตหรือจำหน่าย ไม่ใช่แจ้งภายหลัง"}, {"label": "E", "text": "ทั้งสองกรณีทำได้ทันที หากผ่านการควบคุมคุณภาพของโรงงานตามหลัก GMP แล้ว", "is_correct": false, "explanation": "ผิด GMP เป็นมาตรฐานการผลิต ไม่ได้ทดแทนการขึ้นทะเบียนหรือการขอแก้ไขทะเบียนตำรับยา"}], "key_takeaway": "ความแรงใหม่ต้องขึ้นทะเบียนตำรับ และการเปลี่ยนสูตรตำรับเดิมต้องได้รับอนุญาตแก้ไขทะเบียนก่อนผลิต"}'::jsonb, 'hard', 'law-day1 • ทะเบียนตำรับยา (การแก้ไข/ความแรงใหม่)'),
('01927eef63c27b965f53b67d0c41ebfe', 26, 'เจ้าหน้าที่ตรวจร้านขายยาแผนปัจจุบันเฉพาะยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายหรือยาควบคุมพิเศษ (ขย.2) พบว่า (1) มี diclofenac ชนิดเม็ดในแผงบรรจุเสร็จ ซึ่งจัดเป็นยาอันตราย วางขายอยู่ (2) มียาบรรจุเสร็จที่สิ้นอายุแล้วปะปนอยู่บนชั้นขาย แต่ยังไม่มีผู้ซื้อ (3) ผู้มีหน้าที่ปฏิบัติการอยู่ประจำร้านตามเวลาที่แจ้งไว้ ข้อใดสรุปได้ถูกต้องที่สุด', '[{"label": "A", "text": "ผิดเฉพาะข้อ (2) เพราะ diclofenac อยู่ในแผงบรรจุเสร็จจึงขายใน ขย.2 ได้"}, {"label": "B", "text": "ผิดเฉพาะข้อ (1) เพราะยาที่สิ้นอายุแต่ยังไม่มีผู้ซื้อยังไม่ถือว่าขาย"}, {"label": "C", "text": "ไม่มีความผิด เพราะผู้มีหน้าที่ปฏิบัติการอยู่ประจำร้านตลอดเวลาที่แจ้ง"}, {"label": "D", "text": "ผิดเฉพาะข้อ (1) และจะผิดก็ต่อเมื่อผู้มีหน้าที่ปฏิบัติการไม่ใช่เภสัชกรชั้นหนึ่ง"}, {"label": "E", "text": "ข้อ (1) และ (2) เป็นความผิด แม้ผู้มีหน้าที่ปฏิบัติการจะอยู่ประจำร้านตามเวลาที่แจ้งไว้"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ข้อ (1) และ (2) เป็นความผิด แม้ผู้มีหน้าที่ปฏิบัติการจะอยู่ประจำร้าน — ขย.2 ขายยาอันตรายไม่ได้ และการมียาสิ้นอายุไว้เพื่อขายเป็นการขายยาเสื่อมคุณภาพ", "reason": "ข้อ (1): ขย.2 ขายได้เฉพาะยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายหรือยาควบคุมพิเศษ การมี diclofenac ซึ่งเป็นยาอันตรายวางขายจึงเป็นการขายยานอกขอบเขตใบอนุญาต ไม่ว่าจะเป็นยาบรรจุเสร็จหรือไม่ก็ตาม\n\nข้อ (2): ยาที่สิ้นอายุตามฉลากเป็นยาเสื่อมคุณภาพ และ พ.ร.บ.ยา นิยามคำว่า “ขาย” ให้รวมถึงการมีไว้เพื่อขาย การวางยาสิ้นอายุบนชั้นขายจึงเป็นความผิดแล้วแม้ยังไม่มีผู้ซื้อ\n\nข้อ (3): การที่ผู้มีหน้าที่ปฏิบัติการอยู่ประจำเป็นการปฏิบัติตามหน้าที่ข้อหนึ่ง แต่ไม่ได้ลบล้างความผิดอื่น ผู้มีหน้าที่ปฏิบัติการยังอาจต้องรับผิดร่วมด้วย เพราะมีหน้าที่ควบคุมการขายยาให้เป็นไปตามกฎหมาย", "choices": [{"label": "A", "text": "ผิดเฉพาะข้อ (2) เพราะ diclofenac อยู่ในแผงบรรจุเสร็จจึงขายใน ขย.2 ได้", "is_correct": false, "explanation": "ผิด ขย.2 ขายยาอันตรายไม่ได้ แม้จะเป็นยาบรรจุเสร็จ"}, {"label": "B", "text": "ผิดเฉพาะข้อ (1) เพราะยาที่สิ้นอายุแต่ยังไม่มีผู้ซื้อยังไม่ถือว่าขาย", "is_correct": false, "explanation": "ผิด นิยาม “ขาย” ใน พ.ร.บ.ยา รวมถึงการมีไว้เพื่อขาย การวางยาสิ้นอายุบนชั้นขายจึงเป็นความผิดแล้ว"}, {"label": "C", "text": "ไม่มีความผิด เพราะผู้มีหน้าที่ปฏิบัติการอยู่ประจำร้านตลอดเวลาที่แจ้ง", "is_correct": false, "explanation": "ผิด การอยู่ประจำเป็นหน้าที่ข้อหนึ่ง แต่ไม่ได้ทำให้การขายยานอกขอบเขตหรือการขายยาเสื่อมคุณภาพชอบด้วยกฎหมาย"}, {"label": "D", "text": "ผิดเฉพาะข้อ (1) และจะผิดก็ต่อเมื่อผู้มีหน้าที่ปฏิบัติการไม่ใช่เภสัชกรชั้นหนึ่ง", "is_correct": false, "explanation": "ผิด ขอบเขตของ ขย.2 ห้ามขายยาอันตรายไม่ว่าผู้มีหน้าที่ปฏิบัติการจะมีคุณวุฒิใด และข้อ (2) ก็เป็นความผิดด้วย"}, {"label": "E", "text": "ข้อ (1) และ (2) เป็นความผิด แม้ผู้มีหน้าที่ปฏิบัติการจะอยู่ประจำร้านตามเวลาที่แจ้งไว้", "is_correct": true, "explanation": "ถูกต้อง ข้อ (1) ขายยานอกขอบเขตใบอนุญาต ข้อ (2) มียาเสื่อมคุณภาพไว้เพื่อขาย การที่ผู้มีหน้าที่ปฏิบัติการอยู่ประจำไม่ได้ทำให้พ้นผิด"}], "key_takeaway": "การวางยาไว้บนชั้นขายถือเป็นการขายแล้ว และ ขย.2 ห้ามมียาอันตรายไว้ขายในทุกกรณี"}'::jsonb, 'hard', 'law-day1 • ขอบเขต ขย.2 และยาเสื่อมคุณภาพ (หลายประเด็น)'),
('2f650b42607db8b8c817cec0eaf6f21b', 27, 'พิจารณาสองกรณี (ก) ห้องยาของโรงพยาบาลรัฐสังกัดกระทรวงสาธารณสุขที่จ่ายยาให้ผู้ป่วยตามหน้าที่บำบัดโรค และ (ข) แพทย์ในคลินิกเวชกรรมเอกชนที่จ่ายยาให้คนไข้ที่ตนตรวจรักษา ในแง่การขอใบอนุญาตขายยาและข้อห้ามด้านคุณภาพยาตามพระราชบัญญัติยา ข้อใดถูกต้อง', '[{"label": "A", "text": "(ก) ได้รับยกเว้น แต่ (ข) ต้องขอใบอนุญาต ขย.1 ทุกกรณี"}, {"label": "B", "text": "ทั้ง (ก) และ (ข) ได้รับยกเว้นไม่ต้องขอใบอนุญาตขายยา แต่ยังห้ามขายยาปลอม ยาผิดมาตรฐาน และยาเสื่อมคุณภาพ"}, {"label": "C", "text": "(ข) ได้รับยกเว้น แต่ (ก) ต้องขอใบอนุญาต ขย.1 เพราะจ่ายยาปริมาณมาก"}, {"label": "D", "text": "ทั้งสองแห่งได้รับยกเว้นทั้งการขอใบอนุญาตและข้อห้ามด้านคุณภาพยาทั้งหมด"}, {"label": "E", "text": "ทั้งสองแห่งต้องขอใบอนุญาต ขย.1 และต้องมีเภสัชกรอยู่ประจำตลอดเวลา"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ทั้ง (ก) และ (ข) ได้รับยกเว้นการขอใบอนุญาตขายยา แต่ยังห้ามขายยาปลอม ยาผิดมาตรฐาน และยาเสื่อมคุณภาพ — ข้อยกเว้นตาม พ.ร.บ.ยา ยกเว้นเฉพาะการขอใบอนุญาต ไม่ยกเว้นข้อห้ามด้านคุณภาพยา", "reason": "พ.ร.บ.ยา ยกเว้นไม่ให้ต้องขอใบอนุญาตผลิต ขาย หรือนำเข้ายาในบางกรณี เช่น กระทรวง ทบวง กรมที่มีหน้าที่ป้องกันหรือบำบัดโรค สภากาชาดไทย องค์การเภสัชกรรม และผู้ประกอบวิชาชีพเวชกรรม ทันตกรรม หรือการบำบัดโรคสัตว์ที่ขายยาเฉพาะสำหรับคนไข้หรือสัตว์ที่ตนบำบัด\n\nข้อยกเว้นนี้เป็นการยกเว้นเรื่องใบอนุญาตเท่านั้น ข้อห้ามที่เขียนว่า “ห้ามมิให้ผู้ใด” ผลิต ขาย หรือนำเข้ายาปลอม ยาผิดมาตรฐาน ยาเสื่อมคุณภาพ หรือยาที่ไม่ได้ขึ้นทะเบียน ยังใช้บังคับกับหน่วยงานรัฐและแพทย์ด้วย นอกจากนี้หน่วยงานเหล่านี้ยังต้องปฏิบัติตามกฎหมายวิชาชีพและกฎหมายสถานพยาบาลที่เกี่ยวข้อง", "choices": [{"label": "A", "text": "(ก) ได้รับยกเว้น แต่ (ข) ต้องขอใบอนุญาต ขย.1 ทุกกรณี", "is_correct": false, "explanation": "ผิด แพทย์ที่ขายยาเฉพาะสำหรับคนไข้ของตนได้รับยกเว้นไม่ต้องขอใบอนุญาตขายยา"}, {"label": "B", "text": "ทั้ง (ก) และ (ข) ได้รับยกเว้นไม่ต้องขอใบอนุญาตขายยา แต่ยังห้ามขายยาปลอม ยาผิดมาตรฐาน และยาเสื่อมคุณภาพ", "is_correct": true, "explanation": "ถูกต้อง ข้อยกเว้นเป็นการยกเว้นเฉพาะเรื่องการขอใบอนุญาต ส่วนข้อห้ามด้านคุณภาพยาใช้บังคับกับทุกคน"}, {"label": "C", "text": "(ข) ได้รับยกเว้น แต่ (ก) ต้องขอใบอนุญาต ขย.1 เพราะจ่ายยาปริมาณมาก", "is_correct": false, "explanation": "ผิด กระทรวง ทบวง กรมที่ทำหน้าที่ป้องกันหรือบำบัดโรคได้รับยกเว้น ปริมาณยาที่จ่ายไม่ใช่เกณฑ์"}, {"label": "D", "text": "ทั้งสองแห่งได้รับยกเว้นทั้งการขอใบอนุญาตและข้อห้ามด้านคุณภาพยาทั้งหมด", "is_correct": false, "explanation": "ผิด ข้อยกเว้นไม่ครอบคลุมข้อห้ามขายยาปลอม ยาผิดมาตรฐาน หรือยาเสื่อมคุณภาพ"}, {"label": "E", "text": "ทั้งสองแห่งต้องขอใบอนุญาต ขย.1 และต้องมีเภสัชกรอยู่ประจำตลอดเวลา", "is_correct": false, "explanation": "ผิด ทั้งสองกรณีอยู่ในข้อยกเว้นการขอใบอนุญาตขายยาตาม พ.ร.บ.ยา"}], "key_takeaway": "ได้รับยกเว้นเรื่องใบอนุญาตไม่ได้แปลว่าได้รับยกเว้นข้อห้ามขายยาปลอม ยาผิดมาตรฐาน หรือยาเสื่อมคุณภาพ"}'::jsonb, 'hard', 'law-day1 • ข้อยกเว้นการขออนุญาต (หน่วยงานรัฐ/แพทย์)'),
('c1ed36d0f4acb894facc1de623b152af', 28, 'บริษัทยาได้รับอนุมัติข้อความโฆษณายา Y ซึ่งเป็นยาอันตราย เพื่อลงในวารสารวิชาการที่แจกเฉพาะแพทย์และเภสัชกร (โฆษณา ก.) ต่อมาร้านขายยาแห่งหนึ่งนำข้อความเดียวกันไปโพสต์บนเพจเฟซบุ๊กสาธารณะของร้าน และเพิ่มข้อความว่า “ซื้อ 2 กล่อง แถมฟรี 1 กล่อง” (โฆษณา ข.) ข้อใดถูกต้อง', '[{"label": "A", "text": "ทั้ง ก. และ ข. ทำได้ เพราะข้อความโฆษณาได้รับอนุมัติแล้ว"}, {"label": "B", "text": "ทั้ง ก. และ ข. ขัดกฎหมาย เพราะห้ามโฆษณายาอันตรายในทุกช่องทาง"}, {"label": "C", "text": "โฆษณา ข. ผิดเฉพาะเรื่องแถมพก ถ้าตัดข้อความแถมออกก็โพสต์ได้"}, {"label": "D", "text": "โฆษณา ก. ทำได้เพราะโฆษณาโดยตรงต่อผู้ประกอบวิชาชีพ ส่วนโฆษณา ข. ขัดกฎหมายทั้งเรื่องแสดงสรรพคุณยาอันตรายต่อประชาชนและการแถมพก"}, {"label": "E", "text": "โฆษณา ข. ทำได้ เพราะร้านขายยามีเภสัชกรประจำ จึงเท่ากับสื่อสารต่อผู้ประกอบวิชาชีพ"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. โฆษณา ก. ทำได้ แต่โฆษณา ข. ขัดกฎหมายทั้งการแสดงสรรพคุณยาอันตรายต่อประชาชนและการแถมพก — ข้อห้ามโฆษณาสรรพคุณยาอันตรายยกเว้นการโฆษณาต่อผู้ประกอบวิชาชีพ แต่ห้ามโฆษณาขายยาด้วยการแถมพก", "reason": "พ.ร.บ.ยา ห้ามโฆษณาขายยาที่แสดงสรรพคุณยาอันตรายหรือยาควบคุมพิเศษ แต่ยกเว้นการโฆษณาที่ทำโดยตรงต่อผู้ประกอบวิชาชีพด้านสุขภาพที่กฎหมายกำหนด โฆษณา ก. ในวารสารที่แจกเฉพาะแพทย์และเภสัชกร ซึ่งได้รับอนุมัติแล้ว จึงทำได้\n\nโฆษณา ข. เผยแพร่ต่อประชาชนผ่านเพจสาธารณะ จึงเป็นการแสดงสรรพคุณยาอันตรายต่อประชาชน และยังไม่ได้รับอนุมัติสำหรับสื่อนั้น นอกจากนี้ พ.ร.บ.ยา ยังห้ามโฆษณาขายยาโดยวิธีแถมพกหรือออกสลากรางวัล ข้อความ “ซื้อ 2 แถม 1” จึงเป็นความผิดอีกประเด็นหนึ่ง", "choices": [{"label": "A", "text": "ทั้ง ก. และ ข. ทำได้ เพราะข้อความโฆษณาได้รับอนุมัติแล้ว", "is_correct": false, "explanation": "ผิด การอนุมัติให้ใช้กับกลุ่มเป้าหมายและสื่อที่ขออนุมัติไว้ การนำไปเผยแพร่ต่อประชาชนและเพิ่มข้อความแถมพกไม่อยู่ในการอนุมัตินั้น"}, {"label": "B", "text": "ทั้ง ก. และ ข. ขัดกฎหมาย เพราะห้ามโฆษณายาอันตรายในทุกช่องทาง", "is_correct": false, "explanation": "ผิด กฎหมายยกเว้นให้โฆษณาที่ทำโดยตรงต่อผู้ประกอบวิชาชีพ"}, {"label": "C", "text": "โฆษณา ข. ผิดเฉพาะเรื่องแถมพก ถ้าตัดข้อความแถมออกก็โพสต์ได้", "is_correct": false, "explanation": "ผิด แม้ตัดข้อความแถมออก การแสดงสรรพคุณยาอันตรายต่อประชาชนก็ยังเป็นข้อห้าม"}, {"label": "D", "text": "โฆษณา ก. ทำได้เพราะโฆษณาโดยตรงต่อผู้ประกอบวิชาชีพ ส่วนโฆษณา ข. ขัดกฎหมายทั้งเรื่องแสดงสรรพคุณยาอันตรายต่อประชาชนและการแถมพก", "is_correct": true, "explanation": "ถูกต้อง ข้อห้ามแสดงสรรพคุณยาอันตรายไม่ใช้กับการโฆษณาโดยตรงต่อผู้ประกอบวิชาชีพ แต่โฆษณา ข. มุ่งสู่ประชาชนและใช้วิธีแถมพกซึ่งเป็นข้อห้าม"}, {"label": "E", "text": "โฆษณา ข. ทำได้ เพราะร้านขายยามีเภสัชกรประจำ จึงเท่ากับสื่อสารต่อผู้ประกอบวิชาชีพ", "is_correct": false, "explanation": "ผิด กลุ่มผู้รับโฆษณา ข. คือประชาชนที่เข้าถึงเพจสาธารณะ ไม่ใช่ผู้ประกอบวิชาชีพ"}], "key_takeaway": "โฆษณายาอันตรายทำได้เฉพาะต่อผู้ประกอบวิชาชีพ และห้ามโฆษณาขายยาด้วยการแถมพกหรือชิงรางวัล"}'::jsonb, 'hard', 'law-day1 • การโฆษณายาอันตราย (ผู้ประกอบวิชาชีพ vs ประชาชน)'),
('700b36349ba749439d52f79123a599dc', 29, 'ยาเม็ด Z ขึ้นทะเบียนตำรับไว้ที่ความแรง 100 mg ต่อเม็ด โดยกำหนดเกณฑ์ปริมาณตัวยาสำคัญไว้ 95–105% ผลวิเคราะห์พบว่า ล็อต 1 มีตัวยาสำคัญ 74 mg ต่อเม็ด ล็อต 2 มีตัวยาสำคัญ 91 mg ต่อเม็ด ทั้งสองล็อตยังไม่สิ้นอายุ และสาเหตุมาจากความบกพร่องในกระบวนการผลิต ข้อใดจัดประเภทยาได้ถูกต้องตามพระราชบัญญัติยา', '[{"label": "A", "text": "ล็อต 1 เป็นยาปลอม ส่วนล็อต 2 เป็นยาผิดมาตรฐาน"}, {"label": "B", "text": "ล็อต 1 และล็อต 2 เป็นยาผิดมาตรฐานทั้งคู่"}, {"label": "C", "text": "ล็อต 1 เป็นยาผิดมาตรฐาน ส่วนล็อต 2 เป็นยาเสื่อมคุณภาพ"}, {"label": "D", "text": "ล็อต 1 และล็อต 2 เป็นยาปลอมทั้งคู่"}, {"label": "E", "text": "ล็อต 1 เป็นยาเสื่อมคุณภาพ ส่วนล็อต 2 ยังเป็นยาที่ขายได้"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ล็อต 1 เป็นยาปลอม ส่วนล็อต 2 เป็นยาผิดมาตรฐาน — ระดับที่ตัวยาสำคัญขาดจากเกณฑ์ในตำรับเป็นตัวแบ่งระหว่างยาปลอมกับยาผิดมาตรฐาน", "reason": "พ.ร.บ.ยา กำหนดให้ยาที่ผลิตขึ้นไม่ถูกต้องตามมาตรฐานของตำรับที่ขึ้นทะเบียน จนสารออกฤทธิ์ขาดหรือเกินกว่าร้อยละยี่สิบจากเกณฑ์ที่กำหนดในตำรับ เป็น “ยาปลอม” ส่วนยาที่ผลิตขึ้นโดยสารออกฤทธิ์ขาดหรือเกินจากเกณฑ์แต่ไม่ถึงระดับดังกล่าว หรือมีความบริสุทธิ์หรือลักษณะสำคัญอื่นผิดไปจากเกณฑ์ เป็น “ยาผิดมาตรฐาน”\n\nล็อต 1 (74 mg) ต่ำกว่าเกณฑ์ขั้นต่ำ 95 mg มากกว่าร้อยละยี่สิบ จึงเป็นยาปลอม ล็อต 2 (91 mg) ต่ำกว่าเกณฑ์แต่ไม่ถึงระดับนั้น จึงเป็นยาผิดมาตรฐาน ทั้งสองล็อตไม่ใช่ยาเสื่อมคุณภาพ เพราะยังไม่สิ้นอายุและไม่ได้แปรสภาพหลังการผลิต กฎหมายห้ามผลิต นำเข้า และขายยาทั้งสองประเภท โดยความผิดเกี่ยวกับยาปลอมมีโทษหนักกว่า", "choices": [{"label": "A", "text": "ล็อต 1 เป็นยาปลอม ส่วนล็อต 2 เป็นยาผิดมาตรฐาน", "is_correct": true, "explanation": "ถูกต้อง ล็อต 1 มีตัวยาขาดเกินกว่าร้อยละยี่สิบจากเกณฑ์ในตำรับจึงเป็นยาปลอม ล็อต 2 ต่ำกว่าเกณฑ์แต่ไม่ถึงระดับนั้นจึงเป็นยาผิดมาตรฐาน"}, {"label": "B", "text": "ล็อต 1 และล็อต 2 เป็นยาผิดมาตรฐานทั้งคู่", "is_correct": false, "explanation": "ผิด ล็อต 1 มีตัวยาขาดมากถึงระดับที่กฎหมายกำหนดให้เป็นยาปลอม"}, {"label": "C", "text": "ล็อต 1 เป็นยาผิดมาตรฐาน ส่วนล็อต 2 เป็นยาเสื่อมคุณภาพ", "is_correct": false, "explanation": "ผิด ทั้งสองล็อตยังไม่สิ้นอายุ และปัญหาเกิดจากการผลิต จึงไม่ใช่ยาเสื่อมคุณภาพ"}, {"label": "D", "text": "ล็อต 1 และล็อต 2 เป็นยาปลอมทั้งคู่", "is_correct": false, "explanation": "ผิด ล็อต 2 ขาดจากเกณฑ์ไม่ถึงระดับที่กฎหมายกำหนดให้เป็นยาปลอม"}, {"label": "E", "text": "ล็อต 1 เป็นยาเสื่อมคุณภาพ ส่วนล็อต 2 ยังเป็นยาที่ขายได้", "is_correct": false, "explanation": "ผิด ล็อต 1 ไม่ได้เสื่อมจากการเก็บรักษาหรือสิ้นอายุ และล็อต 2 ต่ำกว่าเกณฑ์มาตรฐานจึงขายไม่ได้"}], "key_takeaway": "ตัวยาขาดหรือเกินกว่าร้อยละยี่สิบจากเกณฑ์ในตำรับเป็นยาปลอม ถ้าน้อยกว่านั้นเป็นยาผิดมาตรฐาน"}'::jsonb, 'hard', 'law-day1 • ยาปลอม vs ยาผิดมาตรฐาน'),
('f5ac75456cddd1c4cfc5719b6c30cb13', 30, 'ร้านขายยา ขย.1 แห่งหนึ่งรับซื้อยาลดน้ำหนักจากผู้ที่หิ้วมาจากต่างประเทศ ยานี้ไม่มีเลขทะเบียนตำรับยาของไทย พนักงานร้านเป็นผู้วางขายและขายให้ลูกค้า ส่วนเภสัชกรผู้มีหน้าที่ปฏิบัติการอยู่ในร้านแต่ไม่ได้ตรวจสอบยาที่รับเข้ามา ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ผิดเฉพาะพนักงานผู้ขาย เพราะเภสัชกรไม่ได้เป็นผู้ส่งมอบยาเอง"}, {"label": "B", "text": "ไม่ผิด หากยานั้นขึ้นทะเบียนถูกต้องในประเทศต้นทาง"}, {"label": "C", "text": "เป็นการขายยาที่ไม่ได้ขึ้นทะเบียนตำรับ ผู้รับอนุญาตต้องรับผิด และเภสัชกรอาจต้องรับผิดทั้งตามกฎหมายและจรรยาบรรณ เพราะมีหน้าที่ควบคุมการขายยา"}, {"label": "D", "text": "ผิดเฉพาะผู้หิ้วยาเข้ามา ส่วนร้านที่รับซื้อต่อโดยสุจริตไม่มีความผิด"}, {"label": "E", "text": "ไม่ผิด หากร้านขายให้เฉพาะลูกค้าที่ร้องขอและไม่ได้โฆษณา"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. เป็นการขายยาที่ไม่ได้ขึ้นทะเบียน ผู้รับอนุญาตต้องรับผิด และเภสัชกรอาจต้องรับผิดด้วย — ห้ามขายยาที่ไม่ได้ขึ้นทะเบียนตำรับ และผู้มีหน้าที่ปฏิบัติการมีหน้าที่ควบคุมการขายยาในร้าน", "reason": "พ.ร.บ.ยา ห้ามขายยาที่ไม่ได้ขึ้นทะเบียนตำรับยาในประเทศไทย ยาที่หิ้วจากต่างประเทศโดยไม่ผ่านการนำเข้าที่ถูกต้องย่อมไม่มีทะเบียนตำรับและไม่มีหลักประกันด้านคุณภาพ ร้านขายยาที่รับซื้อมาขายจึงมีความผิดฐานขายยาที่ไม่ได้ขึ้นทะเบียน โดยผู้รับอนุญาตต้องรับผิดในการประกอบกิจการของตน\n\nผู้มีหน้าที่ปฏิบัติการมีหน้าที่ตามกฎหมายในการควบคุมการขายยาในร้านให้เป็นไปตาม พ.ร.บ.ยา และตามมาตรฐาน GPP ร้านต้องจัดซื้อยาจากแหล่งที่ได้รับอนุญาตเท่านั้น การปล่อยให้มียาไม่ขึ้นทะเบียนวางขายจึงอาจทำให้เภสัชกรต้องรับผิดตาม พ.ร.บ.ยา และถูกดำเนินการทางจรรยาบรรณโดยสภาเภสัชกรรมด้วย", "choices": [{"label": "A", "text": "ผิดเฉพาะพนักงานผู้ขาย เพราะเภสัชกรไม่ได้เป็นผู้ส่งมอบยาเอง", "is_correct": false, "explanation": "ผิด ผู้รับอนุญาตและผู้มีหน้าที่ปฏิบัติการมีหน้าที่ควบคุมการขายยาในร้าน ไม่ได้พ้นความรับผิดเพราะพนักงานเป็นคนขาย"}, {"label": "B", "text": "ไม่ผิด หากยานั้นขึ้นทะเบียนถูกต้องในประเทศต้นทาง", "is_correct": false, "explanation": "ผิด ทะเบียนของต่างประเทศไม่มีผลในไทย ยาที่ขายในไทยต้องขึ้นทะเบียนตำรับกับไทย"}, {"label": "C", "text": "เป็นการขายยาที่ไม่ได้ขึ้นทะเบียนตำรับ ผู้รับอนุญาตต้องรับผิด และเภสัชกรอาจต้องรับผิดทั้งตามกฎหมายและจรรยาบรรณ เพราะมีหน้าที่ควบคุมการขายยา", "is_correct": true, "explanation": "ถูกต้อง ร้านขายยาที่ไม่ได้ขึ้นทะเบียน ผู้รับอนุญาตต้องรับผิด และผู้มีหน้าที่ปฏิบัติการซึ่งมีหน้าที่ควบคุมการขายยาอาจต้องรับผิดด้วย"}, {"label": "D", "text": "ผิดเฉพาะผู้หิ้วยาเข้ามา ส่วนร้านที่รับซื้อต่อโดยสุจริตไม่มีความผิด", "is_correct": false, "explanation": "ผิด การขายยาที่ไม่ได้ขึ้นทะเบียนเป็นความผิดของผู้ขายด้วย ร้านขายยาที่ได้รับอนุญาตต้องตรวจสอบแหล่งที่มาของยา"}, {"label": "E", "text": "ไม่ผิด หากร้านขายให้เฉพาะลูกค้าที่ร้องขอและไม่ได้โฆษณา", "is_correct": false, "explanation": "ผิด การขายยาที่ไม่ได้ขึ้นทะเบียนเป็นความผิดในตัวเอง ไม่ว่าจะโฆษณาหรือไม่"}], "key_takeaway": "ร้านยาต้องซื้อยาจากแหล่งที่ได้รับอนุญาตและขายเฉพาะยาที่ขึ้นทะเบียนในไทย ทั้งผู้รับอนุญาตและเภสัชกรมีส่วนรับผิด"}'::jsonb, 'hard', 'law-day1 • ยาที่ไม่ได้ขึ้นทะเบียนและความรับผิด'),
('5675f93a29acde08465ebbf7f0d85bbd', 31, 'ปัจจุบัน (พ.ศ. 2568) การควบคุมวัตถุออกฤทธิ์ต่อจิตและประสาท เช่น diazepam ในประเทศไทย อยู่ภายใต้กฎหมายฉบับใดเป็นหลัก', '[{"label": "A", "text": "พระราชบัญญัติวัตถุที่ออกฤทธิ์ต่อจิตและประสาท พ.ศ. 2559"}, {"label": "B", "text": "พระราชบัญญัติยาเสพติดให้โทษ พ.ศ. 2522"}, {"label": "C", "text": "ประมวลกฎหมายยาเสพติด พ.ศ. 2564"}, {"label": "D", "text": "พระราชบัญญัติยา พ.ศ. 2510 ในหมวดยาควบคุมพิเศษ"}, {"label": "E", "text": "พระราชบัญญัติสถานพยาบาล พ.ศ. 2541"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ประมวลกฎหมายยาเสพติด พ.ศ. 2564 — ประมวลกฎหมายยาเสพติดได้รวมและยกเลิกกฎหมายยาเสพติดฉบับเดิม", "reason": "ประมวลกฎหมายยาเสพติด พ.ศ. 2564 รวมบทบัญญัติเกี่ยวกับยาเสพติดหลายฉบับเข้าไว้ด้วยกัน และยกเลิก พ.ร.บ.ยาเสพติดให้โทษ พ.ศ. 2522 กับ พ.ร.บ.วัตถุที่ออกฤทธิ์ต่อจิตและประสาท พ.ศ. 2559 ดังนั้นการผลิต นำเข้า จำหน่าย ครอบครอง ทั้งยาเสพติดให้โทษและวัตถุออกฤทธิ์ จึงอยู่ภายใต้ประมวลกฎหมายยาเสพติดเป็นหลัก\n\nในประมวลกฎหมายนี้ ยาเสพติดให้โทษยังแบ่งเป็นประเภท 1–5 และวัตถุออกฤทธิ์ยังแบ่งเป็นประเภท 1–4 เช่นเดิม แต่หลักเกณฑ์การอนุญาต การทำบัญชี และบทกำหนดโทษ อยู่ในฉบับเดียวกัน", "choices": [{"label": "A", "text": "พระราชบัญญัติวัตถุที่ออกฤทธิ์ต่อจิตและประสาท พ.ศ. 2559", "is_correct": false, "explanation": "พ.ร.บ.วัตถุออกฤทธิ์ฯ 2559 ถูกยกเลิกโดยประมวลกฎหมายยาเสพติดแล้ว"}, {"label": "B", "text": "พระราชบัญญัติยาเสพติดให้โทษ พ.ศ. 2522", "is_correct": false, "explanation": "พ.ร.บ.ยาเสพติดให้โทษ 2522 ถูกยกเลิกแล้ว และเดิมก็ไม่ได้ควบคุมวัตถุออกฤทธิ์"}, {"label": "C", "text": "ประมวลกฎหมายยาเสพติด พ.ศ. 2564", "is_correct": true, "explanation": "ถูกต้อง ประมวลกฎหมายยาเสพติดเป็นกฎหมายหลักที่ควบคุมทั้งยาเสพติดให้โทษและวัตถุออกฤทธิ์"}, {"label": "D", "text": "พระราชบัญญัติยา พ.ศ. 2510 ในหมวดยาควบคุมพิเศษ", "is_correct": false, "explanation": "ยาควบคุมพิเศษตาม พ.ร.บ.ยา เป็นคนละระบบ diazepam ถูกควบคุมในฐานะวัตถุออกฤทธิ์"}, {"label": "E", "text": "พระราชบัญญัติสถานพยาบาล พ.ศ. 2541", "is_correct": false, "explanation": "พ.ร.บ.สถานพยาบาลควบคุมการตั้งและดำเนินการสถานพยาบาล ไม่ได้ควบคุมตัววัตถุออกฤทธิ์"}], "key_takeaway": "ยาเสพติดให้โทษและวัตถุออกฤทธิ์ทั้งหมดอยู่ภายใต้ประมวลกฎหมายยาเสพติด พ.ศ. 2564 ซึ่งยกเลิกกฎหมายฉบับเดิม"}'::jsonb, 'easy', 'law-day1 • ประมวลกฎหมายยาเสพติด: ภาพรวม'),
('f847cb340d028c10c5e13293c67d3bc7', 32, 'ข้อใดจัดเป็นยาเสพติดให้โทษประเภท 1 ตามประมวลกฎหมายยาเสพติด', '[{"label": "A", "text": "Methamphetamine"}, {"label": "B", "text": "Morphine sulfate"}, {"label": "C", "text": "ยาน้ำแก้ไอที่มี codeine ผสม"}, {"label": "D", "text": "Diazepam"}, {"label": "E", "text": "Acetic anhydride"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. Methamphetamine — Methamphetamine เป็นยาเสพติดให้โทษชนิดร้ายแรงที่ไม่มีการใช้ทางการแพทย์ที่ได้รับอนุญาต", "reason": "ยาเสพติดให้โทษประเภท 1 คือยาเสพติดให้โทษชนิดร้ายแรง ไม่มีประโยชน์ทางการแพทย์ที่ยอมรับให้ใช้ทั่วไป เช่น heroin, methamphetamine, MDMA\n\nตัวเลือกอื่นอยู่ในประเภทต่างกัน: morphine เป็นประเภท 2 (ยาเสพติดให้โทษทั่วไปที่ใช้ทางการแพทย์ได้), ตำรับยาที่มี codeine ผสมเป็นประเภท 3, acetic anhydride เป็นประเภท 4 (สารที่ใช้ผลิตยาเสพติดประเภท 1) ส่วน diazepam เป็นวัตถุออกฤทธิ์ ไม่ใช่ยาเสพติดให้โทษ", "choices": [{"label": "A", "text": "Methamphetamine", "is_correct": true, "explanation": "ถูกต้อง methamphetamine เป็นยาเสพติดให้โทษประเภท 1"}, {"label": "B", "text": "Morphine sulfate", "is_correct": false, "explanation": "Morphine เป็นยาเสพติดให้โทษประเภท 2 ซึ่งใช้ทางการแพทย์ได้"}, {"label": "C", "text": "ยาน้ำแก้ไอที่มี codeine ผสม", "is_correct": false, "explanation": "ตำรับยาที่มี codeine ผสมจัดเป็นยาเสพติดให้โทษประเภท 3"}, {"label": "D", "text": "Diazepam", "is_correct": false, "explanation": "Diazepam เป็นวัตถุออกฤทธิ์ต่อจิตและประสาท ไม่ใช่ยาเสพติดให้โทษ"}, {"label": "E", "text": "Acetic anhydride", "is_correct": false, "explanation": "Acetic anhydride เป็นยาเสพติดให้โทษประเภท 4 (สารตั้งต้น)"}], "key_takeaway": "ประเภท 1 = ยาเสพติดร้ายแรงที่ไม่ใช้ทางการแพทย์ เช่น heroin, methamphetamine, MDMA"}'::jsonb, 'easy', 'law-day1 • การจัดประเภทยาเสพติดให้โทษ'),
('8d956c9cece5e74a6ac8b5e090be51b6', 33, 'ยาน้ำแก้ไอที่เป็นตำรับยา มี codeine ผสมอยู่ร่วมกับตัวยาอื่นตามสูตรที่ขึ้นทะเบียนไว้ จัดเป็นยาเสพติดประเภทใดตามประมวลกฎหมายยาเสพติด', '[{"label": "A", "text": "ยาเสพติดให้โทษประเภท 1"}, {"label": "B", "text": "ยาเสพติดให้โทษประเภท 2"}, {"label": "C", "text": "วัตถุออกฤทธิ์ประเภท 4"}, {"label": "D", "text": "ยาเสพติดให้โทษประเภท 5"}, {"label": "E", "text": "ยาเสพติดให้โทษประเภท 3"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ยาเสพติดให้โทษประเภท 3 — ตำรับยาที่มียาเสพติดให้โทษประเภท 2 ผสมอยู่ตามที่กำหนดจัดเป็นประเภท 3", "reason": "ยาเสพติดให้โทษประเภท 3 คือยาเสพติดให้โทษที่มีลักษณะเป็นตำรับยา และมียาเสพติดให้โทษประเภท 2 ผสมอยู่ตามที่กำหนด ตัวอย่างคือยาแก้ไอที่มี codeine ผสม\n\nต้องแยกให้ออกว่า codeine ในรูปสารเดี่ยว (ตัวสาร) เป็นยาเสพติดให้โทษประเภท 2 แต่เมื่อผสมเป็นตำรับยาตามที่กำหนดจะเป็นประเภท 3 ซึ่งยังคงต้องได้รับอนุญาตและถูกควบคุม เพียงแต่การควบคุมแตกต่างจากประเภท 2", "choices": [{"label": "A", "text": "ยาเสพติดให้โทษประเภท 1", "is_correct": false, "explanation": "ประเภท 1 เป็นยาเสพติดร้ายแรงที่ไม่ใช้ทางการแพทย์"}, {"label": "B", "text": "ยาเสพติดให้โทษประเภท 2", "is_correct": false, "explanation": "Codeine สารเดี่ยวเป็นประเภท 2 แต่ตำรับยาที่มี codeine ผสมเป็นประเภท 3"}, {"label": "C", "text": "วัตถุออกฤทธิ์ประเภท 4", "is_correct": false, "explanation": "Codeine เป็นยาเสพติดให้โทษ ไม่ใช่วัตถุออกฤทธิ์"}, {"label": "D", "text": "ยาเสพติดให้โทษประเภท 5", "is_correct": false, "explanation": "ประเภท 5 เป็นกลุ่มที่ไม่เข้าประเภท 1–4 เช่น พืชบางชนิด ไม่ใช่ตำรับยาที่มี codeine"}, {"label": "E", "text": "ยาเสพติดให้โทษประเภท 3", "is_correct": true, "explanation": "ถูกต้อง ตำรับยาที่มียาเสพติดประเภท 2 ผสมอยู่ตามที่กำหนดจัดเป็นประเภท 3"}], "key_takeaway": "Codeine สารเดี่ยว = ประเภท 2 แต่ตำรับยาที่มี codeine ผสม = ประเภท 3"}'::jsonb, 'easy', 'law-day1 • การจัดประเภทยาเสพติดให้โทษ'),
('f7ff6e87fae61d5842ecb671bc7ec6a1', 34, 'ในการตรวจโรงงานแห่งหนึ่ง เจ้าหน้าที่พบสาร acetic anhydride จำนวนมากเก็บไว้โดยไม่มีใบอนุญาต สารนี้ถูกควบคุมเพราะใช้ในกระบวนการผลิต heroin สารดังกล่าวจัดเป็นยาเสพติดประเภทใด', '[{"label": "A", "text": "ยาเสพติดให้โทษประเภท 1 เพราะเกี่ยวข้องกับ heroin"}, {"label": "B", "text": "ยาเสพติดให้โทษประเภท 4 ซึ่งเป็นสารที่ใช้ผลิตยาเสพติดประเภท 1"}, {"label": "C", "text": "วัตถุออกฤทธิ์ประเภท 1 ซึ่งไม่มีประโยชน์ทางการแพทย์"}, {"label": "D", "text": "ยาเสพติดให้โทษประเภท 5 ซึ่งไม่เข้าประเภทอื่น"}, {"label": "E", "text": "ไม่เป็นยาเสพติด ควบคุมเฉพาะในฐานะวัตถุอันตราย"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ยาเสพติดให้โทษประเภท 4 ซึ่งเป็นสารที่ใช้ผลิตยาเสพติดประเภท 1 — ยาเสพติดให้โทษประเภท 4 คือสารเคมีที่ใช้ผลิตยาเสพติดให้โทษประเภท 1 หรือ 2 เช่น acetic anhydride", "reason": "ประมวลกฎหมายยาเสพติดกำหนดให้ยาเสพติดให้โทษประเภท 4 คือสารเคมีที่ใช้ในการผลิตยาเสพติดให้โทษประเภท 1 หรือประเภท 2 ตัวอย่างที่รู้จักกันดีคือ acetic anhydride และ acetyl chloride ซึ่งใช้ผลิต heroin\n\nแม้สารนี้จะไม่ใช่ตัวยาเสพติดที่นำมาเสพ แต่กฎหมายควบคุมในฐานะยาเสพติดให้โทษเพื่อตัดวงจรการผลิต ผู้ที่มีไว้ในครอบครองโดยไม่ได้รับอนุญาตจึงมีความผิดตามประมวลกฎหมายยาเสพติด", "choices": [{"label": "A", "text": "ยาเสพติดให้โทษประเภท 1 เพราะเกี่ยวข้องกับ heroin", "is_correct": false, "explanation": "สารตั้งต้นถูกแยกไว้ในประเภท 4 ไม่ได้รวมอยู่ในประเภท 1 ร่วมกับ heroin"}, {"label": "B", "text": "ยาเสพติดให้โทษประเภท 4 ซึ่งเป็นสารที่ใช้ผลิตยาเสพติดประเภท 1", "is_correct": true, "explanation": "ถูกต้อง สารเคมีที่ใช้ผลิตยาเสพติดประเภท 1 หรือ 2 จัดเป็นประเภท 4"}, {"label": "C", "text": "วัตถุออกฤทธิ์ประเภท 1 ซึ่งไม่มีประโยชน์ทางการแพทย์", "is_correct": false, "explanation": "Acetic anhydride ไม่ใช่วัตถุออกฤทธิ์ต่อจิตและประสาท"}, {"label": "D", "text": "ยาเสพติดให้โทษประเภท 5 ซึ่งไม่เข้าประเภทอื่น", "is_correct": false, "explanation": "ประเภท 5 ใช้กับยาเสพติดที่ไม่เข้าประเภท 1–4 แต่สารนี้เข้าประเภท 4 อยู่แล้ว"}, {"label": "E", "text": "ไม่เป็นยาเสพติด ควบคุมเฉพาะในฐานะวัตถุอันตราย", "is_correct": false, "explanation": "สารนี้ถูกควบคุมเป็นยาเสพติดให้โทษตามประมวลกฎหมายยาเสพติด"}], "key_takeaway": "สารเคมีที่ใช้ผลิตยาเสพติดประเภท 1 หรือ 2 (เช่น acetic anhydride) จัดเป็นยาเสพติดให้โทษประเภท 4"}'::jsonb, 'medium', 'law-day1 • การจัดประเภทยาเสพติดให้โทษ: สารตั้งต้น'),
('92b4dc4715b9e283489cbc83eb2e85b5', 35, 'ผู้ป่วยมะเร็งระยะสุดท้ายในโรงพยาบาลชุมชนมีอาการปวดรุนแรง ต้องได้รับ morphine ชนิดรับประทาน บุคลากรในข้อใดมีอำนาจตามกฎหมายในการสั่งจ่ายยานี้ให้แก่ผู้ป่วย', '[{"label": "A", "text": "พยาบาลวิชาชีพที่ผ่านการอบรมการดูแลแบบประคับประคอง"}, {"label": "B", "text": "เภสัชกรผู้รับผิดชอบคลังยาเสพติดของโรงพยาบาล"}, {"label": "C", "text": "นักเทคนิคการแพทย์ที่ตรวจระดับยาในเลือดของผู้ป่วย"}, {"label": "D", "text": "ผู้ประกอบวิชาชีพเวชกรรมที่ดูแลรักษาผู้ป่วยรายนี้"}, {"label": "E", "text": "ผู้อำนวยการโรงพยาบาลซึ่งเป็นผู้รับอนุญาตครอบครอง"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ผู้ประกอบวิชาชีพเวชกรรมที่ดูแลรักษาผู้ป่วยรายนี้ — การสั่งจ่ายยาเสพติดให้โทษประเภท 2 แก่ผู้ป่วยต้องเป็นผู้ประกอบวิชาชีพที่กฎหมายกำหนด เช่น แพทย์", "reason": "ยาเสพติดให้โทษประเภท 2 เช่น morphine จะจ่ายให้ผู้ป่วยได้ตามใบสั่งยาของผู้ประกอบวิชาชีพที่กฎหมายรับรอง ได้แก่ ผู้ประกอบวิชาชีพเวชกรรม ผู้ประกอบวิชาชีพทันตกรรม (ภายในขอบเขตวิชาชีพ) และผู้ประกอบวิชาชีพการสัตวแพทย์สำหรับสัตว์\n\nเภสัชกรมีหน้าที่ตรวจสอบใบสั่งยา จ่ายยา ควบคุมการเก็บรักษาและทำบัญชี แต่ไม่มีอำนาจสั่งจ่ายยาเสพติดให้โทษเอง ส่วนการเป็นผู้รับอนุญาตครอบครองในนามสถานพยาบาลก็ไม่ได้ให้สิทธิ์สั่งจ่ายยาแก่ผู้ป่วย", "choices": [{"label": "A", "text": "พยาบาลวิชาชีพที่ผ่านการอบรมการดูแลแบบประคับประคอง", "is_correct": false, "explanation": "พยาบาลวิชาชีพไม่มีอำนาจสั่งจ่ายยาเสพติดให้โทษ แม้ผ่านการอบรมเฉพาะทาง"}, {"label": "B", "text": "เภสัชกรผู้รับผิดชอบคลังยาเสพติดของโรงพยาบาล", "is_correct": false, "explanation": "เภสัชกรจ่ายยาตามใบสั่งได้ แต่ไม่มีอำนาจสั่งจ่ายยาเสพติดให้โทษเอง"}, {"label": "C", "text": "นักเทคนิคการแพทย์ที่ตรวจระดับยาในเลือดของผู้ป่วย", "is_correct": false, "explanation": "นักเทคนิคการแพทย์ไม่ใช่ผู้มีอำนาจสั่งจ่ายยา"}, {"label": "D", "text": "ผู้ประกอบวิชาชีพเวชกรรมที่ดูแลรักษาผู้ป่วยรายนี้", "is_correct": true, "explanation": "ถูกต้อง ผู้ประกอบวิชาชีพเวชกรรมสั่งจ่ายยาเสพติดให้โทษประเภท 2 เพื่อรักษาผู้ป่วยได้"}, {"label": "E", "text": "ผู้อำนวยการโรงพยาบาลซึ่งเป็นผู้รับอนุญาตครอบครอง", "is_correct": false, "explanation": "ฐานะผู้รับอนุญาตเป็นเรื่องการครอบครองของสถานพยาบาล ไม่ใช่สิทธิ์สั่งจ่ายยาแก่ผู้ป่วย หากไม่ได้เป็นผู้ประกอบวิชาชีพที่ดูแลผู้ป่วย"}], "key_takeaway": "ผู้สั่งจ่ายยาเสพติดให้โทษแก่ผู้ป่วยได้คือผู้ประกอบวิชาชีพเวชกรรม ทันตกรรม (ภายในขอบเขต) และสัตวแพทย์ (สำหรับสัตว์) ส่วนเภสัชกรเป็นผู้จ่ายยาและควบคุมยา"}'::jsonb, 'medium', 'law-day1 • ผู้มีสิทธิ์สั่งจ่ายยาเสพติดให้โทษ'),
('d8f6aaab4f1a6abc4a4e8dd2d11918b9', 36, 'หอผู้ป่วยอายุรกรรมมี morphine injection และ pethidine injection สำรองไว้ใช้ในหอผู้ป่วย หัวหน้าพยาบาลปรึกษาเภสัชกรเรื่องการเก็บรักษายาดังกล่าว ข้อใดเป็นแนวปฏิบัติที่สอดคล้องกับหลักกฎหมาย', '[{"label": "A", "text": "เก็บแยกจากยาอื่นในตู้หรือที่เก็บที่มั่นคงและใส่กุญแจ มีผู้รับผิดชอบกุญแจ และตรวจนับให้ตรงกับบันทึก"}, {"label": "B", "text": "เก็บรวมกับยาฉีดอื่นในรถเข็นยาฉุกเฉินเพื่อให้หยิบใช้ได้เร็วที่สุด"}, {"label": "C", "text": "เก็บในตู้เย็นของหอผู้ป่วยร่วมกับยาอื่น เพราะความเย็นทำให้ยาคงตัวดีกว่า"}, {"label": "D", "text": "ให้พยาบาลแต่ละคนพกติดตัวไว้ระหว่างเวร แล้วคืนเมื่อสิ้นเวรโดยไม่ต้องบันทึก"}, {"label": "E", "text": "เก็บไว้ที่ห้องยาเท่านั้น หอผู้ป่วยไม่สามารถมียาเสพติดสำรองได้ในทุกกรณี"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. เก็บแยกจากยาอื่นในตู้หรือที่เก็บที่มั่นคงและใส่กุญแจ มีผู้รับผิดชอบกุญแจ และตรวจนับให้ตรงกับบันทึก — ยาเสพติดให้โทษต้องเก็บแยกในที่มั่นคงปลอดภัยมีกุญแจ มีผู้รับผิดชอบ และตรวจนับให้ตรงบัญชี", "reason": "หลักการเก็บรักษายาเสพติดให้โทษและวัตถุออกฤทธิ์ คือแยกเก็บเป็นสัดส่วนจากยาอื่นในที่ที่มั่นคงแข็งแรงและปิดล็อกได้ มีผู้รับผิดชอบควบคุมกุญแจ และมีระบบบันทึกรับ-จ่ายที่ตรวจนับได้ เพื่อป้องกันการสูญหายและการนำไปใช้ในทางที่ผิด\n\nสถานพยาบาลสามารถจัดให้มียาเสพติดสำรองในหน่วยบริการได้ภายใต้ระบบควบคุมของสถานพยาบาลที่เป็นผู้รับอนุญาต โดยต้องมีบันทึกการเบิก ใช้ และคืน ที่ตรวจสอบย้อนกลับได้", "choices": [{"label": "A", "text": "เก็บแยกจากยาอื่นในตู้หรือที่เก็บที่มั่นคงและใส่กุญแจ มีผู้รับผิดชอบกุญแจ และตรวจนับให้ตรงกับบันทึก", "is_correct": true, "explanation": "ถูกต้อง เก็บแยกในที่มั่นคงมีกุญแจ มีผู้รับผิดชอบ และตรวจนับให้ตรงกับบันทึก"}, {"label": "B", "text": "เก็บรวมกับยาฉีดอื่นในรถเข็นยาฉุกเฉินเพื่อให้หยิบใช้ได้เร็วที่สุด", "is_correct": false, "explanation": "การเก็บรวมกับยาอื่นในที่ที่เข้าถึงได้ง่ายขัดกับหลักการเก็บแยกในที่มั่นคงปลอดภัย"}, {"label": "C", "text": "เก็บในตู้เย็นของหอผู้ป่วยร่วมกับยาอื่น เพราะความเย็นทำให้ยาคงตัวดีกว่า", "is_correct": false, "explanation": "การเก็บรวมกับยาอื่นในตู้เย็นที่ไม่ได้ปิดล็อกไม่เป็นไปตามหลักการเก็บแยกและมั่นคง"}, {"label": "D", "text": "ให้พยาบาลแต่ละคนพกติดตัวไว้ระหว่างเวร แล้วคืนเมื่อสิ้นเวรโดยไม่ต้องบันทึก", "is_correct": false, "explanation": "การพกติดตัวโดยไม่มีบันทึกทำให้ตรวจสอบไม่ได้และเสี่ยงต่อการสูญหาย"}, {"label": "E", "text": "เก็บไว้ที่ห้องยาเท่านั้น หอผู้ป่วยไม่สามารถมียาเสพติดสำรองได้ในทุกกรณี", "is_correct": false, "explanation": "สถานพยาบาลจัดให้มียาสำรองในหอผู้ป่วยได้ภายใต้ระบบควบคุมของสถานพยาบาล"}], "key_takeaway": "ยาเสพติดต้องเก็บแยกในที่มั่นคงปิดล็อกได้ มีผู้รับผิดชอบ และตรวจนับให้ตรงกับบัญชีเสมอ"}'::jsonb, 'medium', 'law-day1 • การจัดเก็บยาเสพติดให้โทษ'),
('590ba945565e379033a9cd69eeded70f', 37, 'งานคลังยาโรงพยาบาลพบ fentanyl injection หมดอายุจำนวนหนึ่ง เภสัชกรผู้รับผิดชอบต้องการกำจัดยาดังกล่าว ข้อใดเป็นแนวทางที่ถูกต้องตามกฎหมาย', '[{"label": "A", "text": "เภสัชกรหักแอมพูลแล้วเทยาทิ้งในอ่างล้างมือเองได้ทันที แล้วตัดยอดออกจากบัญชี"}, {"label": "B", "text": "ทิ้งรวมกับขยะติดเชื้อของโรงพยาบาลโดยไม่ต้องแจ้งหน่วยงานใด"}, {"label": "C", "text": "ส่งคืนบริษัทผู้แทนจำหน่ายโดยไม่ต้องบันทึก เพราะเป็นยาที่หมดอายุแล้ว"}, {"label": "D", "text": "โอนให้โรงพยาบาลอื่นใช้ต่อ เพราะยาหมดอายุไม่นานยังมีฤทธิ์อยู่"}, {"label": "E", "text": "ขออนุญาตทำลายตามหลักเกณฑ์ที่กฎหมายกำหนด ทำลายภายใต้การควบคุมของพนักงานเจ้าหน้าที่ และบันทึกในบัญชี"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ขออนุญาตทำลายตามหลักเกณฑ์ที่กฎหมายกำหนด ทำลายภายใต้การควบคุมของพนักงานเจ้าหน้าที่ และบันทึกในบัญชี — การทำลายยาเสพติดให้โทษต้องดำเนินการตามหลักเกณฑ์ของกฎหมาย มีพนักงานเจ้าหน้าที่ควบคุม และบันทึกหลักฐาน", "reason": "ยาเสพติดให้โทษที่เสื่อมคุณภาพหรือหมดอายุยังคงเป็นยาเสพติดตามกฎหมาย ผู้รับอนุญาตจะทำลายเองตามอำเภอใจไม่ได้ ต้องดำเนินการตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่ผู้อนุญาตกำหนด โดยการทำลายต้องอยู่ภายใต้การควบคุมของพนักงานเจ้าหน้าที่ และต้องบันทึกตัดยอดในบัญชีรับ-จ่ายพร้อมหลักฐาน\n\nหลักการนี้มีไว้เพื่อให้ยอดยาเสพติดตรวจสอบได้ตลอดเส้นทาง และป้องกันการอ้างว่าทำลายแล้วแต่นำยาออกไปใช้ในทางที่ผิด", "choices": [{"label": "A", "text": "เภสัชกรหักแอมพูลแล้วเทยาทิ้งในอ่างล้างมือเองได้ทันที แล้วตัดยอดออกจากบัญชี", "is_correct": false, "explanation": "การทำลายโดยเภสัชกรคนเดียวโดยไม่มีพนักงานเจ้าหน้าที่ควบคุมไม่เป็นไปตามหลักเกณฑ์ของกฎหมาย"}, {"label": "B", "text": "ทิ้งรวมกับขยะติดเชื้อของโรงพยาบาลโดยไม่ต้องแจ้งหน่วยงานใด", "is_correct": false, "explanation": "ยาเสพติดหมดอายุยังเป็นยาเสพติด ทิ้งรวมกับขยะทั่วไปไม่ได้"}, {"label": "C", "text": "ส่งคืนบริษัทผู้แทนจำหน่ายโดยไม่ต้องบันทึก เพราะเป็นยาที่หมดอายุแล้ว", "is_correct": false, "explanation": "การส่งมอบยาเสพติดทุกครั้งต้องมีบันทึกและเป็นไปตามที่ได้รับอนุญาต"}, {"label": "D", "text": "โอนให้โรงพยาบาลอื่นใช้ต่อ เพราะยาหมดอายุไม่นานยังมีฤทธิ์อยู่", "is_correct": false, "explanation": "ยาหมดอายุนำไปใช้ต่อไม่ได้ และการโอนให้สถานพยาบาลอื่นต้องเป็นไปตามที่ได้รับอนุญาต"}, {"label": "E", "text": "ขออนุญาตทำลายตามหลักเกณฑ์ที่กฎหมายกำหนด ทำลายภายใต้การควบคุมของพนักงานเจ้าหน้าที่ และบันทึกในบัญชี", "is_correct": true, "explanation": "ถูกต้อง ต้องทำลายตามหลักเกณฑ์ที่กำหนด ภายใต้การควบคุมของพนักงานเจ้าหน้าที่ และบันทึกในบัญชี"}], "key_takeaway": "ยาเสพติดหมดอายุยังเป็นยาเสพติด ต้องทำลายตามหลักเกณฑ์ที่กำหนด มีพนักงานเจ้าหน้าที่ควบคุม และบันทึกตัดยอด"}'::jsonb, 'medium', 'law-day1 • การทำลายยาเสพติดให้โทษ'),
('de1414d5c8bd3e441c3e6753458dc4b2', 38, 'โรงพยาบาลเอกชนแห่งหนึ่งได้รับใบอนุญาตจำหน่ายและมีไว้ในครอบครองเพื่อจำหน่ายซึ่งยาเสพติดให้โทษประเภท 2 ข้อใดเป็นหน้าที่ของผู้รับอนุญาตเกี่ยวกับเอกสารหลักฐาน', '[{"label": "A", "text": "ไม่ต้องทำบัญชี เพราะใบสั่งยาของแพทย์ถือเป็นหลักฐานเพียงพอ"}, {"label": "B", "text": "ทำบัญชีเฉพาะเมื่อพนักงานเจ้าหน้าที่ร้องขอให้ตรวจสอบ"}, {"label": "C", "text": "จัดทำบัญชีรับ-จ่ายยาเสพติดให้โทษ และรายงานต่อผู้อนุญาตตามแบบและระยะเวลาที่กำหนด"}, {"label": "D", "text": "ทำบัญชีเฉพาะยาที่รับเข้า ส่วนการจ่ายให้ผู้ป่วยบันทึกในเวชระเบียนแทนได้"}, {"label": "E", "text": "รายงานเฉพาะเมื่อยาหมดอายุหรือสูญหาย ไม่ต้องรายงานตามรอบเวลา"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. จัดทำบัญชีรับ-จ่ายยาเสพติดให้โทษ และรายงานต่อผู้อนุญาตตามแบบและระยะเวลาที่กำหนด — ผู้รับอนุญาตต้องทำบัญชีรับ-จ่ายและรายงานต่อผู้อนุญาตตามแบบและระยะเวลาที่กฎหมายกำหนด", "reason": "ผู้รับอนุญาตเกี่ยวกับยาเสพติดให้โทษมีหน้าที่จัดทำบัญชีรับ-จ่ายยาเสพติดให้โทษทุกรายการทั้งการรับเข้าและการจ่ายออก และต้องรายงานต่อผู้อนุญาต (เลขาธิการคณะกรรมการอาหารและยา) ตามแบบและภายในระยะเวลาที่กำหนด รวมทั้งเก็บบัญชีและหลักฐานไว้ให้พนักงานเจ้าหน้าที่ตรวจสอบได้\n\nใบสั่งยาและเวชระเบียนเป็นหลักฐานประกอบ แต่ไม่ทดแทนบัญชีและรายงานที่กฎหมายกำหนด", "choices": [{"label": "A", "text": "ไม่ต้องทำบัญชี เพราะใบสั่งยาของแพทย์ถือเป็นหลักฐานเพียงพอ", "is_correct": false, "explanation": "ใบสั่งยาเป็นเพียงหลักฐานประกอบ ไม่ทดแทนบัญชีรับ-จ่าย"}, {"label": "B", "text": "ทำบัญชีเฉพาะเมื่อพนักงานเจ้าหน้าที่ร้องขอให้ตรวจสอบ", "is_correct": false, "explanation": "บัญชีต้องจัดทำเป็นประจำ ไม่ใช่ทำเมื่อถูกตรวจ"}, {"label": "C", "text": "จัดทำบัญชีรับ-จ่ายยาเสพติดให้โทษ และรายงานต่อผู้อนุญาตตามแบบและระยะเวลาที่กำหนด", "is_correct": true, "explanation": "ถูกต้อง ต้องทำบัญชีรับ-จ่ายและรายงานตามแบบและระยะเวลาที่กำหนด"}, {"label": "D", "text": "ทำบัญชีเฉพาะยาที่รับเข้า ส่วนการจ่ายให้ผู้ป่วยบันทึกในเวชระเบียนแทนได้", "is_correct": false, "explanation": "ต้องบันทึกทั้งการรับและการจ่ายในบัญชี เวชระเบียนไม่ทดแทนบัญชี"}, {"label": "E", "text": "รายงานเฉพาะเมื่อยาหมดอายุหรือสูญหาย ไม่ต้องรายงานตามรอบเวลา", "is_correct": false, "explanation": "การรายงานตามรอบเวลาเป็นหน้าที่ปกติ ไม่ใช่เฉพาะเหตุพิเศษ"}], "key_takeaway": "ผู้รับอนุญาตต้องทำบัญชีรับ-จ่ายยาเสพติดทุกรายการและรายงานต่อผู้อนุญาตตามรอบที่กำหนด"}'::jsonb, 'medium', 'law-day1 • บัญชีรับ-จ่ายและการรายงาน'),
('3be3db9b98aa7aab56f06caaf7613809', 39, 'ร้านขายยาแผนปัจจุบันแห่งหนึ่งได้รับใบอนุญาตจำหน่ายวัตถุออกฤทธิ์ประเภท 4 ถูกต้องแล้ว ผู้ป่วยนำใบสั่งยาจากแพทย์คลินิกมาขอรับ diazepam 5 mg ระหว่างนั้นเภสัชกรผู้มีหน้าที่ปฏิบัติการออกไปธุระนอกร้าน ข้อใดเป็นการปฏิบัติที่ถูกต้อง', '[{"label": "A", "text": "ให้พนักงานขายจ่ายยาตามใบสั่งได้ เพราะมีใบสั่งยาของแพทย์แล้ว"}, {"label": "B", "text": "ให้ผู้ป่วยรอหรือกลับมาใหม่ เพื่อให้เภสัชกรเป็นผู้ตรวจสอบใบสั่งและจ่ายยา พร้อมบันทึกตามที่กฎหมายกำหนด"}, {"label": "C", "text": "จ่ายยาไปก่อน แล้วให้เภสัชกรมาลงบันทึกย้อนหลังเมื่อกลับมาถึงร้าน"}, {"label": "D", "text": "จ่ายยาได้แต่ไม่ต้องเก็บใบสั่งยาไว้ เพราะเป็นเอกสารของผู้ป่วย"}, {"label": "E", "text": "ให้พนักงานจ่ายยาครึ่งหนึ่งของที่สั่ง เพื่อลดความเสี่ยงเมื่อไม่มีเภสัชกร"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ให้ผู้ป่วยรอหรือกลับมาใหม่ เพื่อให้เภสัชกรเป็นผู้ตรวจสอบใบสั่งและจ่ายยา พร้อมบันทึกตามที่กฎหมายกำหนด — การจ่ายวัตถุออกฤทธิ์ในร้านขายยาต้องทำโดยเภสัชกรตามใบสั่งยา และบันทึกตามที่กำหนด", "reason": "ร้านขายยาที่ได้รับอนุญาตจำหน่ายวัตถุออกฤทธิ์ประเภท 3 หรือ 4 จ่ายได้ตามใบสั่งยาของผู้ประกอบวิชาชีพที่กฎหมายกำหนด และการจ่ายต้องกระทำหรืออยู่ในการควบคุมของเภสัชกรผู้มีหน้าที่ปฏิบัติการ ไม่ใช่พนักงานทั่วไป\n\nนอกจากนี้ร้านต้องเก็บใบสั่งยาไว้เป็นหลักฐานและจัดทำบัญชีรับ-จ่ายวัตถุออกฤทธิ์ตามที่กำหนด การบันทึกย้อนหลังโดยผู้ที่ไม่ได้จ่ายยาจริงทำให้บันทึกไม่ตรงกับข้อเท็จจริง", "choices": [{"label": "A", "text": "ให้พนักงานขายจ่ายยาตามใบสั่งได้ เพราะมีใบสั่งยาของแพทย์แล้ว", "is_correct": false, "explanation": "แม้มีใบสั่งยา การจ่ายวัตถุออกฤทธิ์ในร้านขายยาต้องทำโดยเภสัชกร ไม่ใช่พนักงานขาย"}, {"label": "B", "text": "ให้ผู้ป่วยรอหรือกลับมาใหม่ เพื่อให้เภสัชกรเป็นผู้ตรวจสอบใบสั่งและจ่ายยา พร้อมบันทึกตามที่กฎหมายกำหนด", "is_correct": true, "explanation": "ถูกต้อง เภสัชกรต้องเป็นผู้ตรวจสอบใบสั่งและจ่ายยา พร้อมบันทึกตามกฎหมาย"}, {"label": "C", "text": "จ่ายยาไปก่อน แล้วให้เภสัชกรมาลงบันทึกย้อนหลังเมื่อกลับมาถึงร้าน", "is_correct": false, "explanation": "การจ่ายโดยไม่มีเภสัชกรแล้วลงบันทึกย้อนหลังไม่ถูกต้องทั้งเรื่องผู้จ่ายและความถูกต้องของบันทึก"}, {"label": "D", "text": "จ่ายยาได้แต่ไม่ต้องเก็บใบสั่งยาไว้ เพราะเป็นเอกสารของผู้ป่วย", "is_correct": false, "explanation": "ร้านต้องเก็บใบสั่งยาไว้เป็นหลักฐานประกอบบัญชีตามที่กำหนด"}, {"label": "E", "text": "ให้พนักงานจ่ายยาครึ่งหนึ่งของที่สั่ง เพื่อลดความเสี่ยงเมื่อไม่มีเภสัชกร", "is_correct": false, "explanation": "การลดจำนวนยาไม่แก้ปัญหาที่ผู้จ่ายไม่ใช่เภสัชกร"}], "key_takeaway": "วัตถุออกฤทธิ์ในร้านขายยาต้องจ่ายตามใบสั่งยาโดยเภสัชกร เก็บใบสั่งและบันทึกบัญชีทุกครั้ง"}'::jsonb, 'medium', 'law-day1 • การจำหน่ายวัตถุออกฤทธิ์ในร้านขายยา'),
('35040afb2df6acb7f74e0f22ca5f26ba', 40, 'หลักการสำคัญของประมวลกฎหมายยาเสพติด พ.ศ. 2564 ในการปฏิบัติต่อผู้ใช้ยาเสพติดคือข้อใด', '[{"label": "A", "text": "ผู้เสพทุกรายต้องได้รับโทษจำคุกก่อนจึงจะเข้ารับการบำบัดได้"}, {"label": "B", "text": "ผู้เสพเป็นอาชญากรที่ต้องดำเนินคดีเช่นเดียวกับผู้ค้าทุกกรณี"}, {"label": "C", "text": "การบำบัดรักษาทำได้เฉพาะผู้ที่ถูกจับกุมและศาลสั่งเท่านั้น"}, {"label": "D", "text": "ผู้เสพถือเป็นผู้ป่วยที่ควรได้รับการบำบัดรักษาและฟื้นฟูสมรรถภาพ"}, {"label": "E", "text": "ผู้เสพต้องถูกส่งตัวเข้าค่ายทหารเพื่อปรับพฤติกรรมทุกราย"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ผู้เสพถือเป็นผู้ป่วยที่ควรได้รับการบำบัดรักษาและฟื้นฟูสมรรถภาพ — ประมวลกฎหมายยาเสพติดมองผู้เสพเป็นผู้ป่วยที่ควรได้รับการบำบัดรักษามากกว่าการลงโทษ", "reason": "ประมวลกฎหมายยาเสพติดปรับแนวคิดให้ผู้เสพยาเสพติดเป็นผู้ป่วยที่ควรได้รับการบำบัดรักษาและฟื้นฟูสมรรถภาพ โดยเปิดช่องให้สมัครใจเข้ารับการบำบัด และใช้มาตรการทางสาธารณสุขและสังคมแทนการลงโทษทางอาญาเพียงอย่างเดียว\n\nในขณะเดียวกัน กฎหมายยังคงมุ่งลงโทษผู้ผลิต ผู้ค้า และเครือข่ายอย่างเข้มงวด จึงแยกการปฏิบัติต่อผู้เสพออกจากผู้ค้าอย่างชัดเจน", "choices": [{"label": "A", "text": "ผู้เสพทุกรายต้องได้รับโทษจำคุกก่อนจึงจะเข้ารับการบำบัดได้", "is_correct": false, "explanation": "กฎหมายไม่ได้บังคับให้ต้องรับโทษก่อนบำบัด และเปิดให้สมัครใจเข้าบำบัดได้"}, {"label": "B", "text": "ผู้เสพเป็นอาชญากรที่ต้องดำเนินคดีเช่นเดียวกับผู้ค้าทุกกรณี", "is_correct": false, "explanation": "กฎหมายแยกผู้เสพออกจากผู้ค้า และมองผู้เสพเป็นผู้ป่วย"}, {"label": "C", "text": "การบำบัดรักษาทำได้เฉพาะผู้ที่ถูกจับกุมและศาลสั่งเท่านั้น", "is_correct": false, "explanation": "ผู้เสพสามารถสมัครใจเข้าบำบัดได้โดยไม่ต้องรอให้ถูกจับกุม"}, {"label": "D", "text": "ผู้เสพถือเป็นผู้ป่วยที่ควรได้รับการบำบัดรักษาและฟื้นฟูสมรรถภาพ", "is_correct": true, "explanation": "ถูกต้อง หลักการสำคัญคือผู้เสพคือผู้ป่วยที่ควรได้รับการบำบัดรักษา"}, {"label": "E", "text": "ผู้เสพต้องถูกส่งตัวเข้าค่ายทหารเพื่อปรับพฤติกรรมทุกราย", "is_correct": false, "explanation": "กฎหมายไม่ได้กำหนดให้ผู้เสพทุกรายเข้าค่ายทหาร การบำบัดมีหลายรูปแบบตามความเหมาะสม"}], "key_takeaway": "ประมวลกฎหมายยาเสพติดถือว่าผู้เสพคือผู้ป่วย และแยกการปฏิบัติต่อผู้เสพออกจากผู้ค้า"}'::jsonb, 'easy', 'law-day1 • หลักการบำบัดรักษา: ผู้เสพคือผู้ป่วย'),
('d818298e5f6a0f6faeee7e1b12ec74de', 41, 'ชายอายุ 24 ปี เสพ methamphetamine มาประมาณ 1 ปี ยังไม่เคยถูกจับกุมหรือดำเนินคดี เขามาปรึกษาเภสัชกรที่ร้านยาว่าต้องการเลิกยา แต่กลัวว่าถ้าไปโรงพยาบาลจะถูกแจ้งตำรวจจับ เภสัชกรควรให้ข้อมูลตามหลักกฎหมายอย่างไร', '[{"label": "A", "text": "ต้องไปมอบตัวกับตำรวจก่อน จึงจะเข้ารับการบำบัดได้"}, {"label": "B", "text": "การบำบัดทำได้เฉพาะเมื่อศาลมีคำสั่งเท่านั้น ควรรอให้ถูกจับก่อน"}, {"label": "C", "text": "สถานพยาบาลมีหน้าที่ต้องแจ้งตำรวจทุกครั้งที่พบผู้เสพมาขอบำบัด"}, {"label": "D", "text": "ให้ซื้อยานอนหลับไปใช้เองที่บ้านเพื่อถอนยา ไม่ต้องไปสถานพยาบาล"}, {"label": "E", "text": "สมัครใจเข้ารับการบำบัดได้ที่สถานพยาบาลที่กำหนด และหากปฏิบัติตามจนผ่านเกณฑ์ จะไม่ต้องรับโทษฐานเสพ"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. สมัครใจเข้ารับการบำบัดได้ที่สถานพยาบาลที่กำหนด และหากปฏิบัติตามจนผ่านเกณฑ์ จะไม่ต้องรับโทษฐานเสพ — ผู้เสพสมัครใจเข้ารับการบำบัดได้ และเมื่อผ่านการบำบัดตามเกณฑ์จะไม่ต้องรับโทษฐานเสพ", "reason": "ประมวลกฎหมายยาเสพติดเปิดให้ผู้เสพที่ยังไม่ถูกดำเนินคดีสามารถสมัครใจเข้ารับการบำบัดรักษาในสถานพยาบาลหรือสถานที่ที่กฎหมายกำหนด และเมื่อปฏิบัติตามแผนการบำบัดจนผ่านเกณฑ์ที่กำหนด ผู้นั้นจะไม่ต้องรับโทษในความผิดฐานเสพ เป็นการจูงใจให้ผู้ใช้ยาเข้าสู่ระบบสาธารณสุข\n\nเภสัชกรมีบทบาทให้ข้อมูลที่ถูกต้อง ลดความกลัวและการตีตรา และส่งต่อผู้ใช้ยาเข้าสู่ระบบบำบัด ไม่ควรแนะนำให้ถอนยาด้วยตนเองโดยใช้ยากล่อมประสาท", "choices": [{"label": "A", "text": "ต้องไปมอบตัวกับตำรวจก่อน จึงจะเข้ารับการบำบัดได้", "is_correct": false, "explanation": "ไม่จำเป็นต้องมอบตัวก่อน กฎหมายเปิดให้สมัครใจเข้าบำบัดได้"}, {"label": "B", "text": "การบำบัดทำได้เฉพาะเมื่อศาลมีคำสั่งเท่านั้น ควรรอให้ถูกจับก่อน", "is_correct": false, "explanation": "ไม่ต้องรอคำสั่งศาล การสมัครใจเข้าบำบัดทำได้ก่อนถูกดำเนินคดี"}, {"label": "C", "text": "สถานพยาบาลมีหน้าที่ต้องแจ้งตำรวจทุกครั้งที่พบผู้เสพมาขอบำบัด", "is_correct": false, "explanation": "ระบบบำบัดแบบสมัครใจมุ่งให้ผู้เสพเข้าถึงการรักษา ไม่ใช่การนำตัวไปดำเนินคดี"}, {"label": "D", "text": "ให้ซื้อยานอนหลับไปใช้เองที่บ้านเพื่อถอนยา ไม่ต้องไปสถานพยาบาล", "is_correct": false, "explanation": "การถอนยาเองด้วยยานอนหลับไม่ปลอดภัยและไม่ใช่การบำบัดตามระบบที่กฎหมายกำหนด"}, {"label": "E", "text": "สมัครใจเข้ารับการบำบัดได้ที่สถานพยาบาลที่กำหนด และหากปฏิบัติตามจนผ่านเกณฑ์ จะไม่ต้องรับโทษฐานเสพ", "is_correct": true, "explanation": "ถูกต้อง สมัครใจเข้าบำบัดได้ และเมื่อผ่านเกณฑ์จะไม่ต้องรับโทษฐานเสพ"}], "key_takeaway": "ผู้เสพที่สมัครใจเข้าบำบัดก่อนถูกดำเนินคดีและผ่านการบำบัดตามเกณฑ์ ไม่ต้องรับโทษฐานเสพ"}'::jsonb, 'medium', 'law-day1 • การสมัครใจเข้ารับการบำบัด'),
('feadf891ff4260e35c1285763a626413', 42, 'นักท่องเที่ยวชาวต่างชาติจะเดินทางเข้าประเทศไทยเป็นเวลา 2 สัปดาห์ และต้องรับประทาน diazepam (วัตถุออกฤทธิ์ประเภท 4) ตามที่แพทย์ในประเทศของตนสั่งเป็นประจำ ข้อใดถูกต้องตามหลักการผ่อนผันสำหรับผู้เดินทาง', '[{"label": "A", "text": "นำติดตัวได้ในปริมาณสำหรับรักษาเฉพาะตัวไม่เกิน 30 วัน โดยมีเอกสารทางการแพทย์รับรอง"}, {"label": "B", "text": "นำติดตัวได้ไม่จำกัดปริมาณ เพราะเป็นยาที่แพทย์สั่งจริง"}, {"label": "C", "text": "ห้ามนำวัตถุออกฤทธิ์ทุกประเภทเข้าประเทศไทยโดยเด็ดขาด"}, {"label": "D", "text": "นำเข้าได้เฉพาะเมื่อขอใบอนุญาตนำเข้าเพื่อการค้าแบบเดียวกับบริษัทยา"}, {"label": "E", "text": "นำติดตัวได้ไม่จำกัดปริมาณ หากเก็บไว้ในบรรจุภัณฑ์เดิมของผู้ผลิต"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. นำติดตัวได้ในปริมาณสำหรับรักษาเฉพาะตัวไม่เกิน 30 วัน โดยมีเอกสารทางการแพทย์รับรอง — ผู้เดินทางนำยาที่ควบคุมติดตัวเพื่อรักษาตนเองได้ในปริมาณจำกัดไม่เกิน 30 วัน พร้อมเอกสารทางการแพทย์", "reason": "ประมวลกฎหมายยาเสพติดมีข้อยกเว้นให้ผู้เดินทางเข้าหรือออกราชอาณาจักรนำยาเสพติดให้โทษหรือวัตถุออกฤทธิ์บางประเภทที่ใช้ทางการแพทย์ติดตัวไปได้ เพื่อการรักษาเฉพาะตัว ในปริมาณที่ใช้ไม่เกิน 30 วัน และต้องมีหลักฐานทางการแพทย์ เช่น ใบรับรองแพทย์หรือใบสั่งยา\n\nหลักการนี้ไม่ใช่การนำเข้าเพื่อการค้าจึงไม่ต้องขอใบอนุญาตแบบผู้ประกอบการ แต่ต้องอยู่ในเงื่อนไขของปริมาณและหลักฐาน สำหรับยาเสพติดให้โทษบางรายการอาจมีขั้นตอนเพิ่มเติม ควรตรวจสอบกับสำนักงานคณะกรรมการอาหารและยาก่อนเดินทาง", "choices": [{"label": "A", "text": "นำติดตัวได้ในปริมาณสำหรับรักษาเฉพาะตัวไม่เกิน 30 วัน โดยมีเอกสารทางการแพทย์รับรอง", "is_correct": true, "explanation": "ถูกต้อง นำติดตัวเพื่อรักษาตนเองได้ไม่เกิน 30 วัน พร้อมเอกสารทางการแพทย์"}, {"label": "B", "text": "นำติดตัวได้ไม่จำกัดปริมาณ เพราะเป็นยาที่แพทย์สั่งจริง", "is_correct": false, "explanation": "แม้แพทย์สั่งจริง ปริมาณยังต้องจำกัดตามระยะเวลาการรักษาที่กฎหมายกำหนด"}, {"label": "C", "text": "ห้ามนำวัตถุออกฤทธิ์ทุกประเภทเข้าประเทศไทยโดยเด็ดขาด", "is_correct": false, "explanation": "กฎหมายมีข้อยกเว้นให้ผู้เดินทางนำยาติดตัวเพื่อรักษาตนเองได้"}, {"label": "D", "text": "นำเข้าได้เฉพาะเมื่อขอใบอนุญาตนำเข้าเพื่อการค้าแบบเดียวกับบริษัทยา", "is_correct": false, "explanation": "การนำติดตัวเพื่อรักษาเฉพาะตัวไม่ใช่การนำเข้าเพื่อการค้า"}, {"label": "E", "text": "นำติดตัวได้ไม่จำกัดปริมาณ หากเก็บไว้ในบรรจุภัณฑ์เดิมของผู้ผลิต", "is_correct": false, "explanation": "บรรจุภัณฑ์เดิมช่วยยืนยันตัวยา แต่ไม่ทำให้ไม่มีข้อจำกัดด้านปริมาณ"}], "key_takeaway": "ผู้เดินทางนำยาควบคุมติดตัวเพื่อรักษาตนเองได้ไม่เกิน 30 วัน และต้องมีเอกสารทางการแพทย์"}'::jsonb, 'medium', 'law-day1 • การครอบครองเพื่อใช้ส่วนตัวของผู้เดินทาง'),
('5bb67641c21fd13b7b585fd781474270', 43, 'หลังการปลดพืชกัญชาและกัญชงออกจากบัญชียาเสพติดให้โทษประเภท 5 เมื่อ พ.ศ. 2565 ข้อใดยังคงถูกควบคุมเป็นยาเสพติดให้โทษประเภท 5', '[{"label": "A", "text": "ใบกัญชาสดที่ใช้ประกอบอาหาร"}, {"label": "B", "text": "เมล็ดกัญชงที่ใช้ทำน้ำมันพืช"}, {"label": "C", "text": "สารสกัดจากกัญชาที่มี THC เกินร้อยละ 0.2 โดยน้ำหนัก"}, {"label": "D", "text": "รากและลำต้นของต้นกัญชา"}, {"label": "E", "text": "เปลือกและเส้นใยกัญชงที่ใช้ทอผ้า"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. สารสกัดจากกัญชาที่มี THC เกินร้อยละ 0.2 โดยน้ำหนัก — สารสกัดที่มี THC เกินร้อยละ 0.2 โดยน้ำหนักยังคงเป็นยาเสพติดให้โทษประเภท 5", "reason": "ประกาศกระทรวงสาธารณสุขเรื่องการระบุชื่อยาเสพติดให้โทษประเภท 5 ที่มีผลใน พ.ศ. 2565 ไม่ได้ระบุพืชกัญชาและกัญชงเป็นยาเสพติดอีกต่อไป แต่ยังคงกำหนดให้สารสกัดที่มี tetrahydrocannabinol (THC) เกินร้อยละ 0.2 โดยน้ำหนักเป็นยาเสพติดให้โทษประเภท 5\n\nดังนั้นการผลิต นำเข้า จำหน่าย หรือครอบครองสารสกัดดังกล่าวยังต้องได้รับอนุญาตตามประมวลกฎหมายยาเสพติด และการใช้ต้องเป็นไปเพื่อการแพทย์หรือการศึกษาวิจัยตามที่ได้รับอนุญาต ส่วนต่างๆ ของพืชที่ไม่ใช่สารสกัดดังกล่าวถูกควบคุมด้วยกฎหมายอื่น เช่น กฎหมายสมุนไพรควบคุม หรือกฎหมายอาหาร", "choices": [{"label": "A", "text": "ใบกัญชาสดที่ใช้ประกอบอาหาร", "is_correct": false, "explanation": "ใบกัญชาไม่ใช่ยาเสพติดให้โทษแล้ว แต่ยังถูกควบคุมตามกฎหมายอื่นที่เกี่ยวข้อง"}, {"label": "B", "text": "เมล็ดกัญชงที่ใช้ทำน้ำมันพืช", "is_correct": false, "explanation": "เมล็ดกัญชงไม่ใช่ยาเสพติดให้โทษ"}, {"label": "C", "text": "สารสกัดจากกัญชาที่มี THC เกินร้อยละ 0.2 โดยน้ำหนัก", "is_correct": true, "explanation": "ถูกต้อง สารสกัดที่มี THC เกินร้อยละ 0.2 โดยน้ำหนักยังเป็นยาเสพติดให้โทษประเภท 5"}, {"label": "D", "text": "รากและลำต้นของต้นกัญชา", "is_correct": false, "explanation": "รากและลำต้นไม่ใช่ยาเสพติดให้โทษ"}, {"label": "E", "text": "เปลือกและเส้นใยกัญชงที่ใช้ทอผ้า", "is_correct": false, "explanation": "เปลือกและเส้นใยกัญชงไม่ใช่ยาเสพติดให้โทษ"}], "key_takeaway": "แม้พืชกัญชา-กัญชงไม่เป็นยาเสพติดแล้ว แต่สารสกัดที่มี THC เกินร้อยละ 0.2 โดยน้ำหนักยังเป็นยาเสพติดให้โทษประเภท 5"}'::jsonb, 'medium', 'law-day1 • กัญชา-กัญชง: สถานะทางกฎหมาย'),
('6048af3f66e046e8080383173f281cb6', 44, 'ชาวบ้านในตำบลหนึ่งปลูกพืชกระท่อมและขายใบสดในตลาดชุมชน ตาม พ.ร.บ.พืชกระท่อม พ.ศ. 2565 ห้ามขายใบกระท่อมให้แก่บุคคลกลุ่มใด', '[{"label": "A", "text": "ผู้สูงอายุที่มีอายุ 60 ปีขึ้นไป และผู้ป่วยโรคเรื้อรัง"}, {"label": "B", "text": "ผู้ที่ไม่มีบัตรประจำตัวประชาชนไทยทุกคน"}, {"label": "C", "text": "บุคคลอายุต่ำกว่า 25 ปี และผู้ที่ประกอบอาชีพขับขี่ยานพาหนะ"}, {"label": "D", "text": "บุคคลอายุต่ำกว่า 18 ปี หญิงมีครรภ์ และหญิงให้นมบุตร"}, {"label": "E", "text": "บุคคลทั่วไปทุกคน เพราะการขายต้องทำผ่านร้านขายยาเท่านั้น"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. บุคคลอายุต่ำกว่า 18 ปี หญิงมีครรภ์ และหญิงให้นมบุตร — พ.ร.บ.พืชกระท่อมห้ามขายแก่ผู้มีอายุต่ำกว่า 18 ปี หญิงมีครรภ์ และหญิงให้นมบุตร", "reason": "พ.ร.บ.พืชกระท่อม พ.ศ. 2565 ยอมให้ประชาชนปลูกและขายใบกระท่อมภายในประเทศได้ แต่มีมาตรการคุ้มครองกลุ่มเปราะบาง โดยห้ามขายพืชกระท่อมแก่บุคคลอายุต่ำกว่า 18 ปี หญิงมีครรภ์ และหญิงให้นมบุตร รวมทั้งกำหนดสถานที่ที่ห้ามขาย เช่น ในสถานศึกษา\n\nกฎหมายนี้ไม่ได้กำหนดให้ต้องขายผ่านร้านขายยา และไม่ได้กำหนดห้ามขายตามอาชีพหรือสัญชาติของผู้ซื้อ", "choices": [{"label": "A", "text": "ผู้สูงอายุที่มีอายุ 60 ปีขึ้นไป และผู้ป่วยโรคเรื้อรัง", "is_correct": false, "explanation": "กฎหมายไม่ได้ห้ามขายแก่ผู้สูงอายุหรือผู้ป่วยโรคเรื้อรังโดยเฉพาะ"}, {"label": "B", "text": "ผู้ที่ไม่มีบัตรประจำตัวประชาชนไทยทุกคน", "is_correct": false, "explanation": "กฎหมายไม่ได้กำหนดเงื่อนไขเรื่องบัตรประชาชนไทยของผู้ซื้อ"}, {"label": "C", "text": "บุคคลอายุต่ำกว่า 25 ปี และผู้ที่ประกอบอาชีพขับขี่ยานพาหนะ", "is_correct": false, "explanation": "เกณฑ์อายุคือต่ำกว่า 18 ปี และไม่มีข้อห้ามตามอาชีพ"}, {"label": "D", "text": "บุคคลอายุต่ำกว่า 18 ปี หญิงมีครรภ์ และหญิงให้นมบุตร", "is_correct": true, "explanation": "ถูกต้อง ห้ามขายแก่บุคคลอายุต่ำกว่า 18 ปี หญิงมีครรภ์ และหญิงให้นมบุตร"}, {"label": "E", "text": "บุคคลทั่วไปทุกคน เพราะการขายต้องทำผ่านร้านขายยาเท่านั้น", "is_correct": false, "explanation": "กฎหมายไม่ได้กำหนดให้การขายใบกระท่อมต้องทำผ่านร้านขายยา"}], "key_takeaway": "ห้ามขายพืชกระท่อมแก่ผู้มีอายุต่ำกว่า 18 ปี หญิงมีครรภ์ และหญิงให้นมบุตร"}'::jsonb, 'medium', 'law-day1 • พืชกระท่อม: ข้อห้ามการขาย'),
('4d8a5b9aa339d50adb8b647d52f009be', 45, 'เภสัชกรประจำคลังยาเสพติดของโรงพยาบาลรัฐทราบว่ามารดาที่บ้านปวดเข่ารุนแรงและนอนไม่หลับ จึงนำ morphine tablet จากคลังของโรงพยาบาลกลับบ้านไปให้มารดาใช้ โดยตั้งใจจะนำเงินมาชดใช้ค่ายาภายหลัง ข้อใดวิเคราะห์การกระทำนี้ได้ถูกต้องที่สุด', '[{"label": "A", "text": "ทำได้ เพราะเภสัชกรมีใบประกอบวิชาชีพ จึงครอบครองยาเสพติดได้โดยไม่ต้องขออนุญาต"}, {"label": "B", "text": "เป็นความผิดตามกฎหมายยาเสพติด เพราะใบอนุญาตเป็นของสถานพยาบาล และไม่มีใบสั่งยาจากผู้มีอำนาจสั่งจ่าย"}, {"label": "C", "text": "ทำได้ หากบันทึกในบัญชีรับ-จ่ายของโรงพยาบาลครบถ้วน"}, {"label": "D", "text": "ทำได้ หากชดใช้ค่ายาครบภายใน 30 วัน"}, {"label": "E", "text": "เป็นเพียงความผิดทางวินัยข้าราชการ ไม่เกี่ยวกับกฎหมายยาเสพติด"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. เป็นความผิดตามกฎหมายยาเสพติด เพราะใบอนุญาตเป็นของสถานพยาบาล และไม่มีใบสั่งยาจากผู้มีอำนาจสั่งจ่าย — การนำยาเสพติดออกจากคลังไปใช้เองโดยไม่มีใบสั่งยาและนอกขอบเขตใบอนุญาตเป็นความผิดตามกฎหมายยาเสพติด", "reason": "ใบอนุญาตครอบครองและจำหน่ายยาเสพติดให้โทษเป็นของสถานพยาบาลและผูกกับสถานที่ ไม่ใช่สิทธิ์ส่วนตัวของเภสัชกร การที่เภสัชกรนำยาออกจากคลังไปครอบครองหรือส่งมอบให้ผู้อื่นนอกระบบ โดยไม่มีใบสั่งยาจากผู้ประกอบวิชาชีพที่มีอำนาจสั่งจ่าย จึงเป็นการครอบครองและจำหน่ายยาเสพติดให้โทษโดยไม่ได้รับอนุญาต การชดใช้ค่ายาไม่ทำให้การกระทำชอบด้วยกฎหมาย\n\nนอกจากความผิดตามประมวลกฎหมายยาเสพติดแล้ว ยังอาจเป็นความผิดทางวินัยและผิดจรรยาบรรณวิชาชีพเภสัชกรรมด้วย ความผิดหลายด้านอาจเกิดพร้อมกันได้ ทางที่ถูกคือให้มารดาพบแพทย์เพื่อประเมินและรับยาตามระบบ", "choices": [{"label": "A", "text": "ทำได้ เพราะเภสัชกรมีใบประกอบวิชาชีพ จึงครอบครองยาเสพติดได้โดยไม่ต้องขออนุญาต", "is_correct": false, "explanation": "ใบประกอบวิชาชีพไม่ใช่ใบอนุญาตครอบครองยาเสพติดเป็นการส่วนตัว"}, {"label": "B", "text": "เป็นความผิดตามกฎหมายยาเสพติด เพราะใบอนุญาตเป็นของสถานพยาบาล และไม่มีใบสั่งยาจากผู้มีอำนาจสั่งจ่าย", "is_correct": true, "explanation": "ถูกต้อง เป็นการครอบครองและจำหน่ายนอกขอบเขตใบอนุญาตและไม่มีใบสั่งยา จึงผิดกฎหมายยาเสพติด"}, {"label": "C", "text": "ทำได้ หากบันทึกในบัญชีรับ-จ่ายของโรงพยาบาลครบถ้วน", "is_correct": false, "explanation": "การบันทึกบัญชีไม่ทำให้การจ่ายยาที่ไม่มีใบสั่งและออกนอกระบบชอบด้วยกฎหมาย"}, {"label": "D", "text": "ทำได้ หากชดใช้ค่ายาครบภายใน 30 วัน", "is_correct": false, "explanation": "การชดใช้ค่ายาไม่ลบล้างความผิดฐานครอบครองหรือจำหน่ายโดยไม่ได้รับอนุญาต"}, {"label": "E", "text": "เป็นเพียงความผิดทางวินัยข้าราชการ ไม่เกี่ยวกับกฎหมายยาเสพติด", "is_correct": false, "explanation": "นอกจากวินัย ยังเป็นความผิดตามกฎหมายยาเสพติดและผิดจรรยาบรรณวิชาชีพด้วย"}], "key_takeaway": "ใบอนุญาตยาเสพติดเป็นของสถานพยาบาล เภสัชกรนำยาออกไปใช้นอกระบบไม่ได้แม้จะชดใช้ค่ายา"}'::jsonb, 'hard', 'law-day1 • การครอบครองโดยไม่ได้รับอนุญาต / จรรยาบรรณ'),
('393ce0e9365388ad2151240c0be7c8ac', 46, 'ลูกค้าเข้ามาที่ร้านขายยาแผนปัจจุบัน ขอซื้อยาแก้หวัดคัดจมูกสูตรผสมที่มี pseudoephedrine แบบที่เคยซื้อได้เมื่อหลายปีก่อน เภสัชกรควรตอบอย่างไรจึงถูกต้องตามกฎหมาย', '[{"label": "A", "text": "ขายได้ หากลูกค้าแสดงบัตรประชาชนและซื้อไม่เกิน 1 แผง"}, {"label": "B", "text": "ร้านขายยาจำหน่ายไม่ได้ เพราะยาที่มี pseudoephedrine ถูกควบคุมเข้มงวดตามกฎหมายยาเสพติดและจำกัดให้ใช้ในสถานพยาบาล"}, {"label": "C", "text": "ขายได้ตามปกติ เพราะ pseudoephedrine เป็นยาสามัญประจำบ้าน"}, {"label": "D", "text": "ขายได้ หากเภสัชกรบันทึกชื่อผู้ซื้อในสมุดบันทึกการขายยาอันตราย"}, {"label": "E", "text": "ขายได้เฉพาะชนิดน้ำเชื่อมสำหรับเด็ก เพราะไม่สามารถนำไปสกัดได้"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ร้านขายยาจำหน่ายไม่ได้ เพราะยาที่มี pseudoephedrine ถูกควบคุมเข้มงวดตามกฎหมายยาเสพติดและจำกัดให้ใช้ในสถานพยาบาล — ยาที่มี pseudoephedrine ถูกควบคุมตามกฎหมายยาเสพติดเพราะใช้เป็นสารตั้งต้นผลิต methamphetamine ร้านขายยาจึงขายไม่ได้", "reason": "Pseudoephedrine ถูกนำไปสกัดเป็นสารตั้งต้นในการผลิต methamphetamine ประเทศไทยจึงยกระดับการควบคุมยาที่มี pseudoephedrine ให้อยู่ภายใต้กฎหมายยาเสพติด จำกัดการใช้ไว้ในสถานพยาบาล และยาแก้หวัดสูตรผสมที่เคยมีขายทั่วไปถูกยกเลิกหรือเปลี่ยนสูตร ร้านขายยาแผนปัจจุบันจึงไม่สามารถจำหน่ายยาที่มี pseudoephedrine ได้\n\nเภสัชกรควรอธิบายเหตุผลแก่ลูกค้า และเลือกยาบรรเทาอาการคัดจมูกอื่นที่จำหน่ายได้ถูกกฎหมาย หรือแนะนำให้พบแพทย์ตามความเหมาะสม", "choices": [{"label": "A", "text": "ขายได้ หากลูกค้าแสดงบัตรประชาชนและซื้อไม่เกิน 1 แผง", "is_correct": false, "explanation": "การแสดงบัตรหรือจำกัดจำนวนไม่ทำให้ร้านขายยามีสิทธิ์จำหน่ายยาที่ถูกจำกัดไว้ในสถานพยาบาล"}, {"label": "B", "text": "ร้านขายยาจำหน่ายไม่ได้ เพราะยาที่มี pseudoephedrine ถูกควบคุมเข้มงวดตามกฎหมายยาเสพติดและจำกัดให้ใช้ในสถานพยาบาล", "is_correct": true, "explanation": "ถูกต้อง ยาที่มี pseudoephedrine ถูกควบคุมเข้มงวดตามกฎหมายยาเสพติด ร้านขายยาจำหน่ายไม่ได้"}, {"label": "C", "text": "ขายได้ตามปกติ เพราะ pseudoephedrine เป็นยาสามัญประจำบ้าน", "is_correct": false, "explanation": "Pseudoephedrine ไม่ใช่ยาสามัญประจำบ้าน และถูกควบคุมเข้มงวดเพราะเป็นสารตั้งต้น"}, {"label": "D", "text": "ขายได้ หากเภสัชกรบันทึกชื่อผู้ซื้อในสมุดบันทึกการขายยาอันตราย", "is_correct": false, "explanation": "การบันทึกแบบยาอันตรายไม่เพียงพอ เพราะยานี้ถูกควบคุมตามกฎหมายยาเสพติด"}, {"label": "E", "text": "ขายได้เฉพาะชนิดน้ำเชื่อมสำหรับเด็ก เพราะไม่สามารถนำไปสกัดได้", "is_correct": false, "explanation": "รูปแบบยาน้ำไม่ได้รับการยกเว้น การควบคุมครอบคลุมยาที่มี pseudoephedrine ทุกรูปแบบ"}], "key_takeaway": "Pseudoephedrine ถูกควบคุมตามกฎหมายยาเสพติดเพราะเป็นสารตั้งต้นของ methamphetamine ร้านขายยาจำหน่ายไม่ได้"}'::jsonb, 'medium', 'law-day1 • สารตั้งต้น: pseudoephedrine'),
('f87191bcac1b596de9f36f36944feabe', 47, 'Tramadol ถูกควบคุมในประเทศไทยในลักษณะใด', '[{"label": "A", "text": "เป็นยาเสพติดให้โทษประเภท 2 ตามประมวลกฎหมายยาเสพติด"}, {"label": "B", "text": "เป็นวัตถุออกฤทธิ์ประเภท 4 ตามประมวลกฎหมายยาเสพติด"}, {"label": "C", "text": "เป็นยาสามัญประจำบ้านที่ขายได้ในร้านค้าทั่วไป"}, {"label": "D", "text": "เป็นยาอันตรายที่ไม่มีมาตรการควบคุมการขายเป็นพิเศษ"}, {"label": "E", "text": "เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา พ.ศ. 2510 พร้อมมาตรการควบคุมการขายและการรายงาน"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา พ.ศ. 2510 พร้อมมาตรการควบคุมการขายและการรายงาน — Tramadol เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา มีมาตรการควบคุมการขายเพื่อป้องกันการใช้ในทางที่ผิด", "reason": "Tramadol ถูกนำไปใช้ในทางที่ผิดในกลุ่มวัยรุ่น (เช่น ผสมเครื่องดื่ม) กระทรวงสาธารณสุขจึงประกาศให้ยาที่มี tramadol เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา พ.ศ. 2510 และสำนักงานคณะกรรมการอาหารและยามีมาตรการควบคุมการกระจายยา เช่น จำกัดปริมาณการซื้อของร้านขายยา และกำหนดให้จัดทำบัญชีและรายงานการซื้อขาย\n\nTramadol ไม่ได้ถูกควบคุมเป็นยาเสพติดให้โทษหรือวัตถุออกฤทธิ์ตามประมวลกฎหมายยาเสพติด แต่การควบคุมตาม พ.ร.บ.ยา ในฐานะยาควบคุมพิเศษเข้มงวดกว่ายาอันตรายทั่วไป", "choices": [{"label": "A", "text": "เป็นยาเสพติดให้โทษประเภท 2 ตามประมวลกฎหมายยาเสพติด", "is_correct": false, "explanation": "Tramadol ไม่ได้จัดเป็นยาเสพติดให้โทษประเภท 2"}, {"label": "B", "text": "เป็นวัตถุออกฤทธิ์ประเภท 4 ตามประมวลกฎหมายยาเสพติด", "is_correct": false, "explanation": "Tramadol ไม่ได้จัดเป็นวัตถุออกฤทธิ์"}, {"label": "C", "text": "เป็นยาสามัญประจำบ้านที่ขายได้ในร้านค้าทั่วไป", "is_correct": false, "explanation": "Tramadol ไม่ใช่ยาสามัญประจำบ้าน"}, {"label": "D", "text": "เป็นยาอันตรายที่ไม่มีมาตรการควบคุมการขายเป็นพิเศษ", "is_correct": false, "explanation": "Tramadol ถูกยกระดับเป็นยาควบคุมพิเศษและมีมาตรการควบคุมการขายเพิ่มเติม"}, {"label": "E", "text": "เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา พ.ศ. 2510 พร้อมมาตรการควบคุมการขายและการรายงาน", "is_correct": true, "explanation": "ถูกต้อง tramadol เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา มีมาตรการควบคุมการขายและการรายงาน"}], "key_takeaway": "Tramadol = ยาควบคุมพิเศษตาม พ.ร.บ.ยา ไม่ใช่ยาเสพติดตามประมวลกฎหมายยาเสพติด แต่มีมาตรการควบคุมการขายเข้มงวด"}'::jsonb, 'easy', 'law-day1 • Tramadol: สถานะทางกฎหมาย'),
('87bb553ebc68c7581d4cde2b8071fd5b', 48, 'เภสัชกรร้านยาสังเกตว่ามีวัยรุ่นกลุ่มเดิมมาขอซื้อยาน้ำแก้ไอที่มี dextromethorphan ครั้งละหลายขวดเกือบทุกวัน โดยไม่มีอาการไอ และบอกว่า "ซื้อไปฝากเพื่อน" ข้อใดเป็นการปฏิบัติที่เหมาะสมที่สุดตามหลักวิชาชีพและกฎหมาย', '[{"label": "A", "text": "ขายตามที่ขอ เพราะ dextromethorphan ไม่ใช่ยาเสพติด เภสัชกรจึงปฏิเสธการขายไม่ได้"}, {"label": "B", "text": "ขายได้ไม่จำกัด หากผู้ซื้อยืนยันว่ามีอายุเกิน 18 ปี"}, {"label": "C", "text": "ขายให้ครั้งละหลายขวดเพื่อลดจำนวนครั้งที่ต้องมาร้าน"}, {"label": "D", "text": "ใช้วิจารณญาณทางวิชาชีพปฏิเสธการขายเมื่อสงสัยการใช้ผิดวัตถุประสงค์ ให้คำแนะนำ และบันทึกการขายตามที่กำหนด"}, {"label": "E", "text": "แจ้งตำรวจจับกุมวัยรุ่นทันที เพราะการซื้อยาแก้ไอปริมาณมากเป็นความผิดฐานเสพยาเสพติด"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ใช้วิจารณญาณทางวิชาชีพปฏิเสธการขายเมื่อสงสัยการใช้ผิดวัตถุประสงค์ ให้คำแนะนำ และบันทึกการขายตามที่กำหนด — เภสัชกรต้องใช้วิจารณญาณปฏิเสธการขายยาที่สงสัยว่าจะถูกนำไปใช้ในทางที่ผิด ให้คำแนะนำ และบันทึกตามที่กำหนด", "reason": "Dextromethorphan เป็นยาที่มีรายงานการนำไปใช้ในทางที่ผิดในกลุ่มวัยรุ่น สำนักงานคณะกรรมการอาหารและยาจึงจัดเป็นยาที่ต้องเฝ้าระวัง มีมาตรการควบคุมการกระจายและการขายของร้านขายยา แม้จะไม่ใช่ยาเสพติดตามประมวลกฎหมายยาเสพติด\n\nตามหลักวิชาชีพ เภสัชกรผู้มีหน้าที่ปฏิบัติการมีหน้าที่ประเมินความเหมาะสมก่อนส่งมอบยาทุกครั้ง และมีสิทธิ์ปฏิเสธการขายเมื่อพบพฤติกรรมที่บ่งชี้การใช้ผิดวัตถุประสงค์ พร้อมให้ความรู้เรื่องอันตราย และแนะนำแหล่งช่วยเหลือ การกล่าวหาว่าผู้ซื้อกระทำความผิดฐานเสพยาเสพติดไม่ถูกต้องตามข้อเท็จจริง", "choices": [{"label": "A", "text": "ขายตามที่ขอ เพราะ dextromethorphan ไม่ใช่ยาเสพติด เภสัชกรจึงปฏิเสธการขายไม่ได้", "is_correct": false, "explanation": "เภสัชกรมีหน้าที่ประเมินความเหมาะสมและปฏิเสธการขายได้ แม้ยาจะไม่ใช่ยาเสพติด"}, {"label": "B", "text": "ขายได้ไม่จำกัด หากผู้ซื้อยืนยันว่ามีอายุเกิน 18 ปี", "is_correct": false, "explanation": "อายุของผู้ซื้อไม่ใช่เหตุผลให้ขายได้ไม่จำกัด เมื่อมีพฤติกรรมบ่งชี้การใช้ผิดวัตถุประสงค์"}, {"label": "C", "text": "ขายให้ครั้งละหลายขวดเพื่อลดจำนวนครั้งที่ต้องมาร้าน", "is_correct": false, "explanation": "การขายครั้งละมากๆ เพิ่มความเสี่ยงของการใช้ในทางที่ผิดและขัดกับมาตรการควบคุม"}, {"label": "D", "text": "ใช้วิจารณญาณทางวิชาชีพปฏิเสธการขายเมื่อสงสัยการใช้ผิดวัตถุประสงค์ ให้คำแนะนำ และบันทึกการขายตามที่กำหนด", "is_correct": true, "explanation": "ถูกต้อง ใช้วิจารณญาณปฏิเสธการขาย ให้คำแนะนำ และบันทึกตามที่กำหนด"}, {"label": "E", "text": "แจ้งตำรวจจับกุมวัยรุ่นทันที เพราะการซื้อยาแก้ไอปริมาณมากเป็นความผิดฐานเสพยาเสพติด", "is_correct": false, "explanation": "Dextromethorphan ไม่ใช่ยาเสพติดตามประมวลกฎหมายยาเสพติด การซื้อยาแก้ไอไม่ใช่ความผิดฐานเสพยาเสพติด"}], "key_takeaway": "เภสัชกรมีหน้าที่คัดกรองและปฏิเสธการขายยาที่สงสัยว่าจะถูกนำไปใช้ในทางที่ผิด แม้ยานั้นจะไม่ใช่ยาเสพติด"}'::jsonb, 'medium', 'law-day1 • บทบาทเภสัชกรในการป้องกันการใช้ในทางที่ผิด'),
('a63201d75a9eea4cae3d0a47880e6ce9', 49, 'บริษัทยาที่เป็นผู้รับอนุญาตต้องการโฆษณายา morphine ชนิดออกฤทธิ์นาน ข้อใดถูกต้องตามหลักการควบคุมการโฆษณายาเสพติดให้โทษ', '[{"label": "A", "text": "โฆษณาได้เฉพาะในลักษณะทางวิชาการที่ส่งถึงผู้ประกอบวิชาชีพด้านสุขภาพ ห้ามโฆษณาต่อประชาชนทั่วไป"}, {"label": "B", "text": "โฆษณาทางโทรทัศน์ได้ หากระบุคำเตือนเรื่องการติดยา"}, {"label": "C", "text": "โฆษณาผ่านสื่อสังคมออนไลน์ได้ หากระบุว่าต้องใช้ตามแพทย์สั่ง"}, {"label": "D", "text": "โฆษณาในร้านขายยาได้ เพราะเป็นสถานที่ที่มีเภสัชกรประจำ"}, {"label": "E", "text": "ห้ามเผยแพร่ข้อมูลยาทุกรูปแบบ แม้แต่ข้อมูลทางวิชาการแก่แพทย์"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. โฆษณาได้เฉพาะในลักษณะทางวิชาการที่ส่งถึงผู้ประกอบวิชาชีพด้านสุขภาพ ห้ามโฆษณาต่อประชาชนทั่วไป — การโฆษณายาเสพติดให้โทษทำได้เฉพาะทางวิชาการต่อผู้ประกอบวิชาชีพ ห้ามโฆษณาต่อประชาชน", "reason": "กฎหมายยาเสพติดห้ามโฆษณายาเสพติดให้โทษและวัตถุออกฤทธิ์ เว้นแต่เป็นการโฆษณาทางวิชาการที่กระทำต่อผู้ประกอบวิชาชีพที่เกี่ยวข้อง เช่น แพทย์ ทันตแพทย์ เภสัชกร ทั้งนี้เพื่อป้องกันไม่ให้ประชาชนเกิดความต้องการใช้ยาโดยไม่มีข้อบ่งใช้\n\nการใส่คำเตือนหรือข้อความให้ใช้ตามแพทย์สั่งไม่ทำให้การโฆษณาต่อสาธารณชนชอบด้วยกฎหมาย", "choices": [{"label": "A", "text": "โฆษณาได้เฉพาะในลักษณะทางวิชาการที่ส่งถึงผู้ประกอบวิชาชีพด้านสุขภาพ ห้ามโฆษณาต่อประชาชนทั่วไป", "is_correct": true, "explanation": "ถูกต้อง โฆษณาได้เฉพาะทางวิชาการต่อผู้ประกอบวิชาชีพ"}, {"label": "B", "text": "โฆษณาทางโทรทัศน์ได้ หากระบุคำเตือนเรื่องการติดยา", "is_correct": false, "explanation": "การโฆษณาทางโทรทัศน์เป็นการโฆษณาต่อประชาชน ซึ่งห้ามแม้มีคำเตือน"}, {"label": "C", "text": "โฆษณาผ่านสื่อสังคมออนไลน์ได้ หากระบุว่าต้องใช้ตามแพทย์สั่ง", "is_correct": false, "explanation": "สื่อสังคมออนไลน์เข้าถึงประชาชนทั่วไป จึงห้ามโฆษณา"}, {"label": "D", "text": "โฆษณาในร้านขายยาได้ เพราะเป็นสถานที่ที่มีเภสัชกรประจำ", "is_correct": false, "explanation": "การโฆษณาในร้านขายยาเป็นการโฆษณาต่อผู้บริโภค ซึ่งไม่อนุญาต"}, {"label": "E", "text": "ห้ามเผยแพร่ข้อมูลยาทุกรูปแบบ แม้แต่ข้อมูลทางวิชาการแก่แพทย์", "is_correct": false, "explanation": "กฎหมายยกเว้นให้เผยแพร่ข้อมูลทางวิชาการแก่ผู้ประกอบวิชาชีพได้"}], "key_takeaway": "ยาเสพติดให้โทษโฆษณาได้เฉพาะทางวิชาการต่อผู้ประกอบวิชาชีพ ห้ามโฆษณาต่อประชาชนทุกช่องทาง"}'::jsonb, 'easy', 'law-day1 • การโฆษณายาเสพติดให้โทษ'),
('f2c4ec3439338796e88514d2425dad30', 50, 'คืนหนึ่งมีคนร้ายงัดตู้เก็บยาเสพติดของโรงพยาบาลเอกชน และขโมย fentanyl transdermal patch กับ morphine injection ไปจำนวนหนึ่ง เช้าวันรุ่งขึ้นเภสัชกรตรวจพบ ข้อใดเป็นการดำเนินการที่ถูกต้องที่สุด', '[{"label": "A", "text": "ปรับยอดในบัญชีให้ตรงกับยาที่เหลือ แล้วสั่งซื้อยาเพิ่มเพื่อไม่ให้กระทบผู้ป่วย"}, {"label": "B", "text": "รอจนถึงรอบรายงานประจำปี แล้วจึงรายงานยอดที่หายไปพร้อมกัน"}, {"label": "C", "text": "แจ้งความต่อพนักงานสอบสวน และแจ้งการสูญหายต่อผู้อนุญาตหรือพนักงานเจ้าหน้าที่ตามที่กฎหมายกำหนด พร้อมบันทึกหลักฐาน"}, {"label": "D", "text": "แจ้งเฉพาะผู้บริหารโรงพยาบาล เพราะเป็นทรัพย์สินของโรงพยาบาล ไม่จำเป็นต้องแจ้งหน่วยงานรัฐ"}, {"label": "E", "text": "บันทึกว่ายาแตกเสียหายระหว่างใช้ เพื่อหลีกเลี่ยงการตรวจสอบ"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. แจ้งความต่อพนักงานสอบสวน และแจ้งการสูญหายต่อผู้อนุญาตหรือพนักงานเจ้าหน้าที่ตามที่กฎหมายกำหนด พร้อมบันทึกหลักฐาน — เมื่อยาเสพติดสูญหายหรือถูกลักขโมย ผู้รับอนุญาตต้องแจ้งความและแจ้งการสูญหายต่อผู้อนุญาตตามที่กฎหมายกำหนด", "reason": "ผู้รับอนุญาตมีหน้าที่ควบคุมยาเสพติดให้โทษไม่ให้รั่วไหลออกนอกระบบ เมื่อเกิดการสูญหายหรือถูกลักขโมย ต้องแจ้งการสูญหายต่อผู้อนุญาตหรือพนักงานเจ้าหน้าที่ภายในเวลาที่กฎหมายกำหนด และการลักทรัพย์เป็นความผิดอาญาที่ควรแจ้งความต่อพนักงานสอบสวนเพื่อเป็นหลักฐาน ทั้งยังต้องบันทึกรายละเอียดในบัญชีให้ตรงกับข้อเท็จจริง\n\nการปรับยอดโดยไม่รายงาน หรือการบันทึกสาเหตุอันเป็นเท็จ ทำให้บัญชีไม่ตรงความจริงและอาจเป็นความผิดเพิ่มเติม", "choices": [{"label": "A", "text": "ปรับยอดในบัญชีให้ตรงกับยาที่เหลือ แล้วสั่งซื้อยาเพิ่มเพื่อไม่ให้กระทบผู้ป่วย", "is_correct": false, "explanation": "การปรับยอดเงียบๆ โดยไม่แจ้งการสูญหาย เป็นการไม่ปฏิบัติตามหน้าที่ของผู้รับอนุญาต"}, {"label": "B", "text": "รอจนถึงรอบรายงานประจำปี แล้วจึงรายงานยอดที่หายไปพร้อมกัน", "is_correct": false, "explanation": "การสูญหายต้องแจ้งภายในเวลาที่กำหนด ไม่ใช่รอรอบรายงานประจำปี"}, {"label": "C", "text": "แจ้งความต่อพนักงานสอบสวน และแจ้งการสูญหายต่อผู้อนุญาตหรือพนักงานเจ้าหน้าที่ตามที่กฎหมายกำหนด พร้อมบันทึกหลักฐาน", "is_correct": true, "explanation": "ถูกต้อง แจ้งความ แจ้งการสูญหายต่อผู้อนุญาตหรือพนักงานเจ้าหน้าที่ และบันทึกหลักฐาน"}, {"label": "D", "text": "แจ้งเฉพาะผู้บริหารโรงพยาบาล เพราะเป็นทรัพย์สินของโรงพยาบาล ไม่จำเป็นต้องแจ้งหน่วยงานรัฐ", "is_correct": false, "explanation": "ยาเสพติดเป็นสิ่งที่รัฐควบคุม การสูญหายต้องแจ้งหน่วยงานตามกฎหมาย ไม่ใช่แจ้งภายในองค์กรเท่านั้น"}, {"label": "E", "text": "บันทึกว่ายาแตกเสียหายระหว่างใช้ เพื่อหลีกเลี่ยงการตรวจสอบ", "is_correct": false, "explanation": "การบันทึกสาเหตุเท็จทำให้บัญชีไม่ตรงความจริงและเป็นการกระทำที่ผิด"}], "key_takeaway": "ยาเสพติดสูญหายหรือถูกขโมยต้องแจ้งความและแจ้งผู้อนุญาตตามกำหนด ห้ามปรับยอดเงียบหรือบันทึกเท็จ"}'::jsonb, 'medium', 'law-day1 • การสูญหายของยาเสพติด'),
('777cc7cd84b7a52c77497fddb310e98e', 51, 'ผู้ป่วยมะเร็งเสียชีวิตที่บ้าน บุตรสาวนำ fentanyl transdermal patch ที่ยังไม่ได้ใช้ 6 แผ่น และ morphine tablet ที่เหลือ มาคืนที่ห้องยาโรงพยาบาลซึ่งเป็นผู้จ่ายยา พร้อมบอกว่า "ถ้าทิ้งที่บ้านกลัวหลานไปหยิบเล่น" ข้อใดเป็นการดำเนินการที่เหมาะสมที่สุด', '[{"label": "A", "text": "ปฏิเสธการรับคืน และแนะนำให้ทิ้งในถังขยะที่บ้าน"}, {"label": "B", "text": "รับคืนแล้วนำเข้าสต็อกเพื่อจ่ายให้ผู้ป่วยรายอื่นต่อ เพราะยายังไม่หมดอายุ"}, {"label": "C", "text": "รับคืนและมอบให้บุตรสาวนำไปใช้ต่อ หากมีอาการปวดในอนาคต"}, {"label": "D", "text": "รับคืนพร้อมบันทึกรายละเอียด แยกเก็บอย่างมั่นคง และนำเข้าสู่กระบวนการทำลายตามหลักเกณฑ์ ไม่นำไปจ่ายซ้ำ"}, {"label": "E", "text": "รับคืนแล้วทำลายทันทีโดยเภสัชกรคนเดียว โดยไม่ต้องบันทึก เพราะเป็นยาที่จ่ายออกไปแล้ว"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. รับคืนพร้อมบันทึกรายละเอียด แยกเก็บอย่างมั่นคง และนำเข้าสู่กระบวนการทำลายตามหลักเกณฑ์ ไม่นำไปจ่ายซ้ำ — ยาเสพติดที่ผู้ป่วยนำมาคืนต้องบันทึก แยกเก็บอย่างมั่นคง และนำเข้าสู่การทำลายตามหลักเกณฑ์ ห้ามนำไปจ่ายซ้ำ", "reason": "ยาเสพติดให้โทษที่เหลือหลังผู้ป่วยเสียชีวิตเสี่ยงต่อการรั่วไหลและอุบัติเหตุ (เช่น เด็กสัมผัสแผ่น fentanyl) การรับคืนจึงเป็นการคุ้มครองความปลอดภัยของชุมชน แต่เมื่อรับคืนแล้ว ยาต้องอยู่ในระบบควบคุมของผู้รับอนุญาต คือบันทึกรายละเอียด (ชนิด จำนวน ผู้นำส่ง) แยกเก็บในที่มั่นคง และรวบรวมเข้าสู่กระบวนการทำลายตามหลักเกณฑ์ที่กำหนด\n\nยาที่ผ่านมือผู้ป่วยแล้วไม่สามารถรับประกันคุณภาพและความถูกต้องได้ จึงไม่ควรนำกลับไปจ่ายให้ผู้ป่วยรายอื่น และการมอบยาให้ญาติไปใช้ต่อโดยไม่มีใบสั่งยาเป็นการส่งมอบยาเสพติดโดยไม่ชอบด้วยกฎหมาย", "choices": [{"label": "A", "text": "ปฏิเสธการรับคืน และแนะนำให้ทิ้งในถังขยะที่บ้าน", "is_correct": false, "explanation": "การทิ้งในขยะบ้านเสี่ยงต่อการรั่วไหลและอุบัติเหตุ ไม่ใช่วิธีกำจัดยาเสพติดที่เหมาะสม"}, {"label": "B", "text": "รับคืนแล้วนำเข้าสต็อกเพื่อจ่ายให้ผู้ป่วยรายอื่นต่อ เพราะยายังไม่หมดอายุ", "is_correct": false, "explanation": "ยาที่คืนจากผู้ป่วยไม่สามารถรับประกันคุณภาพ ไม่ควรนำไปจ่ายซ้ำ"}, {"label": "C", "text": "รับคืนและมอบให้บุตรสาวนำไปใช้ต่อ หากมีอาการปวดในอนาคต", "is_correct": false, "explanation": "การให้ญาติใช้ยาเสพติดโดยไม่มีใบสั่งยาเป็นการส่งมอบที่ไม่ชอบด้วยกฎหมาย"}, {"label": "D", "text": "รับคืนพร้อมบันทึกรายละเอียด แยกเก็บอย่างมั่นคง และนำเข้าสู่กระบวนการทำลายตามหลักเกณฑ์ ไม่นำไปจ่ายซ้ำ", "is_correct": true, "explanation": "ถูกต้อง รับคืน บันทึก แยกเก็บอย่างมั่นคง และเข้าสู่กระบวนการทำลายตามหลักเกณฑ์"}, {"label": "E", "text": "รับคืนแล้วทำลายทันทีโดยเภสัชกรคนเดียว โดยไม่ต้องบันทึก เพราะเป็นยาที่จ่ายออกไปแล้ว", "is_correct": false, "explanation": "การทำลายต้องเป็นไปตามหลักเกณฑ์ที่กำหนดและมีบันทึก จะทำลายเองโดยไม่บันทึกไม่ได้"}], "key_takeaway": "ยาเสพติดที่รับคืนจากผู้ป่วยต้องบันทึก แยกเก็บอย่างมั่นคง และเข้าสู่กระบวนการทำลาย ห้ามนำไปจ่ายซ้ำหรือคืนให้ญาติใช้"}'::jsonb, 'hard', 'law-day1 • การรับคืนและทำลายยาเสพติดจากผู้ป่วย'),
('2b9ba1e51264f3e12aa6fdb35fa2c3eb', 52, 'เภสัชกรผู้มีหน้าที่ปฏิบัติการของร้านขายยาแผนปัจจุบัน (ขย.1) ต้องการสั่งซื้อ morphine tablet มาเก็บไว้ที่ร้าน เพื่อจำหน่ายให้ผู้ป่วยมะเร็งในชุมชนที่มีใบสั่งยาจากแพทย์โรงพยาบาล โดยเห็นว่าร้านมีใบอนุญาตขายยาแผนปัจจุบันและมีเภสัชกรประจำอยู่แล้ว ข้อใดถูกต้อง', '[{"label": "A", "text": "ทำได้ทันที เพราะใบอนุญาตขายยาแผนปัจจุบันครอบคลุมยาทุกประเภทรวมถึงยาเสพติด"}, {"label": "B", "text": "ทำได้ หากผู้ป่วยทุกรายมีใบสั่งยาและร้านเก็บสำเนาใบสั่งยาไว้"}, {"label": "C", "text": "ทำไม่ได้ เว้นแต่ได้รับใบอนุญาตเกี่ยวกับยาเสพติดให้โทษประเภท 2 ตามประมวลกฎหมายยาเสพติด ใบอนุญาตตาม พ.ร.บ.ยา ไม่ครอบคลุม"}, {"label": "D", "text": "ทำได้ หากซื้อจากโรงพยาบาลที่ได้รับอนุญาต เพราะถือว่าใช้ใบอนุญาตของโรงพยาบาลแทน"}, {"label": "E", "text": "ทำได้ หากจำกัดปริมาณการเก็บไม่เกิน 100 เม็ด"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ทำไม่ได้ เว้นแต่ได้รับใบอนุญาตเกี่ยวกับยาเสพติดให้โทษประเภท 2 ตามประมวลกฎหมายยาเสพติด ใบอนุญาตตาม พ.ร.บ.ยา ไม่ครอบคลุม — การจำหน่ายหรือครอบครองยาเสพติดให้โทษประเภท 2 ต้องได้รับใบอนุญาตตามประมวลกฎหมายยาเสพติด ซึ่งแยกจากใบอนุญาตตาม พ.ร.บ.ยา", "reason": "การควบคุมยาเสพติดให้โทษเป็นระบบใบอนุญาตตามประมวลกฎหมายยาเสพติด ซึ่งแยกต่างหากจากใบอนุญาตขายยาตาม พ.ร.บ.ยา ใบอนุญาตขายยาแผนปัจจุบัน (ขย.1) ให้สิทธิ์ขายยาตาม พ.ร.บ.ยา เท่านั้น ไม่รวมถึงการจำหน่ายหรือมีไว้ในครอบครองเพื่อจำหน่ายซึ่งยาเสพติดให้โทษประเภท 2\n\nการมีใบสั่งยา การเก็บสำเนา หรือการจำกัดปริมาณ ไม่ทดแทนใบอนุญาต และใบอนุญาตของสถานพยาบาลอื่นก็ใช้แทนกันไม่ได้ เพราะใบอนุญาตผูกกับผู้รับอนุญาตและสถานที่ ในทางปฏิบัติผู้ป่วยมักรับยาเสพติดให้โทษประเภท 2 จากสถานพยาบาลที่ได้รับอนุญาต", "choices": [{"label": "A", "text": "ทำได้ทันที เพราะใบอนุญาตขายยาแผนปัจจุบันครอบคลุมยาทุกประเภทรวมถึงยาเสพติด", "is_correct": false, "explanation": "ใบอนุญาตตาม พ.ร.บ.ยา ไม่ครอบคลุมยาเสพติดให้โทษ ซึ่งต้องได้รับอนุญาตตามประมวลกฎหมายยาเสพติด"}, {"label": "B", "text": "ทำได้ หากผู้ป่วยทุกรายมีใบสั่งยาและร้านเก็บสำเนาใบสั่งยาไว้", "is_correct": false, "explanation": "ใบสั่งยาเป็นเงื่อนไขการจ่ายแก่ผู้ป่วย แต่ไม่ทดแทนใบอนุญาตจำหน่ายหรือครอบครองยาเสพติด"}, {"label": "C", "text": "ทำไม่ได้ เว้นแต่ได้รับใบอนุญาตเกี่ยวกับยาเสพติดให้โทษประเภท 2 ตามประมวลกฎหมายยาเสพติด ใบอนุญาตตาม พ.ร.บ.ยา ไม่ครอบคลุม", "is_correct": true, "explanation": "ถูกต้อง ต้องได้รับใบอนุญาตตามประมวลกฎหมายยาเสพติด ใบอนุญาตตาม พ.ร.บ.ยา ไม่ครอบคลุม"}, {"label": "D", "text": "ทำได้ หากซื้อจากโรงพยาบาลที่ได้รับอนุญาต เพราะถือว่าใช้ใบอนุญาตของโรงพยาบาลแทน", "is_correct": false, "explanation": "ใบอนุญาตผูกกับผู้รับอนุญาตและสถานที่ จะใช้ใบอนุญาตของผู้อื่นแทนไม่ได้"}, {"label": "E", "text": "ทำได้ หากจำกัดปริมาณการเก็บไม่เกิน 100 เม็ด", "is_correct": false, "explanation": "การจำกัดปริมาณไม่ใช่ข้อยกเว้นการขออนุญาต"}], "key_takeaway": "ใบอนุญาตขายยาตาม พ.ร.บ.ยา ไม่ครอบคลุมยาเสพติดให้โทษ ต้องได้รับใบอนุญาตตามประมวลกฎหมายยาเสพติดแยกต่างหาก"}'::jsonb, 'hard', 'law-day1 • การขออนุญาตจำหน่าย/ครอบครองยาเสพติด'),
('03c83c17ef61b15cedf86e9431dad522', 53, 'หลักการควบคุมยาเสพติดให้โทษประเภท 1 เช่น heroin ตามประมวลกฎหมายยาเสพติด คือข้อใด', '[{"label": "A", "text": "ห้ามผลิต นำเข้า ส่งออก จำหน่าย หรือมีไว้ในครอบครอง เว้นแต่ได้รับอนุญาตเฉพาะกรณีจำเป็นเพื่อประโยชน์ของทางราชการ"}, {"label": "B", "text": "โรงพยาบาลรัฐทุกแห่งสามารถมีไว้ในครอบครองเพื่อใช้รักษาผู้ป่วยได้โดยไม่ต้องขออนุญาต"}, {"label": "C", "text": "แพทย์สั่งจ่ายให้ผู้ป่วยได้ หากเขียนใบสั่งยาตามแบบที่กำหนด"}, {"label": "D", "text": "ร้านขายยาที่มีใบอนุญาตจำหน่ายยาเสพติดประเภท 2 สามารถจำหน่ายได้ด้วย"}, {"label": "E", "text": "บุคคลทั่วไปครอบครองได้ไม่เกินปริมาณที่กำหนดโดยไม่ต้องขออนุญาต"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ห้ามผลิต นำเข้า ส่งออก จำหน่าย หรือมีไว้ในครอบครอง เว้นแต่ได้รับอนุญาตเฉพาะกรณีจำเป็นเพื่อประโยชน์ของทางราชการ — ยาเสพติดให้โทษประเภท 1 ห้ามเด็ดขาด เว้นแต่ได้รับอนุญาตเฉพาะกรณีจำเป็นเพื่อประโยชน์ของทางราชการ", "reason": "ยาเสพติดให้โทษประเภท 1 เป็นยาเสพติดร้ายแรงที่ไม่มีการใช้ทางการแพทย์ตามปกติ กฎหมายจึงห้ามการผลิต นำเข้า ส่งออก จำหน่าย และมีไว้ในครอบครอง โดยจะอนุญาตได้เฉพาะกรณีจำเป็นเพื่อประโยชน์ของทางราชการ เช่น การศึกษาวิจัยหรือการตรวจวิเคราะห์ของหน่วยงานรัฐ\n\nดังนั้นจึงไม่มีการสั่งจ่ายให้ผู้ป่วยในเวชปฏิบัติทั่วไป และใบอนุญาตสำหรับยาเสพติดประเภทอื่นไม่ครอบคลุมประเภท 1", "choices": [{"label": "A", "text": "ห้ามผลิต นำเข้า ส่งออก จำหน่าย หรือมีไว้ในครอบครอง เว้นแต่ได้รับอนุญาตเฉพาะกรณีจำเป็นเพื่อประโยชน์ของทางราชการ", "is_correct": true, "explanation": "ถูกต้อง ห้ามทุกกิจกรรม เว้นแต่ได้รับอนุญาตเฉพาะกรณีจำเป็นเพื่อประโยชน์ของทางราชการ"}, {"label": "B", "text": "โรงพยาบาลรัฐทุกแห่งสามารถมีไว้ในครอบครองเพื่อใช้รักษาผู้ป่วยได้โดยไม่ต้องขออนุญาต", "is_correct": false, "explanation": "โรงพยาบาลไม่สามารถครอบครองยาเสพติดประเภท 1 เพื่อรักษาผู้ป่วยได้"}, {"label": "C", "text": "แพทย์สั่งจ่ายให้ผู้ป่วยได้ หากเขียนใบสั่งยาตามแบบที่กำหนด", "is_correct": false, "explanation": "ยาเสพติดประเภท 1 ไม่มีการสั่งจ่ายเพื่อรักษาผู้ป่วยในเวชปฏิบัติ"}, {"label": "D", "text": "ร้านขายยาที่มีใบอนุญาตจำหน่ายยาเสพติดประเภท 2 สามารถจำหน่ายได้ด้วย", "is_correct": false, "explanation": "ใบอนุญาตประเภท 2 ไม่ครอบคลุมประเภท 1"}, {"label": "E", "text": "บุคคลทั่วไปครอบครองได้ไม่เกินปริมาณที่กำหนดโดยไม่ต้องขออนุญาต", "is_correct": false, "explanation": "การครอบครองยาเสพติดประเภท 1 โดยไม่ได้รับอนุญาตเป็นความผิดเสมอ"}], "key_takeaway": "ยาเสพติดให้โทษประเภท 1 ห้ามเด็ดขาด อนุญาตได้เฉพาะกรณีจำเป็นเพื่อประโยชน์ของทางราชการ"}'::jsonb, 'easy', 'law-day1 • การควบคุมยาเสพติดให้โทษประเภท 1'),
('a3151e31ce132ba361a1b3592adcf118', 54, 'ผู้ป่วยมะเร็งได้รับ morphine sulfate tablet จากโรงพยาบาลตามใบสั่งของแพทย์ เพื่อนำไปรับประทานที่บ้านเป็นเวลา 2 สัปดาห์ ผู้ป่วยถามเภสัชกรว่าต้องขออนุญาตครอบครองยานี้หรือไม่ ข้อใดถูกต้อง', '[{"label": "A", "text": "ต้องยื่นขอใบอนุญาตครอบครองยาเสพติดที่สำนักงานคณะกรรมการอาหารและยาก่อนรับยา"}, {"label": "B", "text": "ต้องแจ้งสถานีตำรวจในพื้นที่ว่ามียาเสพติดไว้ในบ้าน"}, {"label": "C", "text": "ครอบครองได้เฉพาะเมื่อเก็บไว้ในโรงพยาบาล ห้ามนำกลับบ้าน"}, {"label": "D", "text": "ต้องให้แพทย์เป็นผู้เก็บยาไว้และนำมาให้ทุกวัน"}, {"label": "E", "text": "ไม่ต้องขออนุญาต เพราะเป็นการครอบครองในปริมาณที่ได้รับตามใบสั่งยาเพื่อรักษาตนเอง"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ไม่ต้องขออนุญาต เพราะเป็นการครอบครองในปริมาณที่ได้รับตามใบสั่งยาเพื่อรักษาตนเอง — ผู้ป่วยที่ครอบครองยาเสพติดตามใบสั่งยาเพื่อรักษาตนเองไม่ต้องขออนุญาต", "reason": "ประมวลกฎหมายยาเสพติดกำหนดข้อยกเว้นให้ผู้ป่วยที่มีไว้ในครอบครองซึ่งยาเสพติดให้โทษหรือวัตถุออกฤทธิ์ ในปริมาณที่ได้รับตามใบสั่งยาของผู้ประกอบวิชาชีพเพื่อการรักษาโรคของตนเอง ไม่ต้องขออนุญาตครอบครอง\n\nเภสัชกรควรแนะนำผู้ป่วยให้เก็บยาในที่ปลอดภัยพ้นมือเด็ก ไม่แบ่งยาให้ผู้อื่น และนำยาที่เหลือกลับมาคืนสถานพยาบาลเพื่อกำจัดอย่างถูกต้อง", "choices": [{"label": "A", "text": "ต้องยื่นขอใบอนุญาตครอบครองยาเสพติดที่สำนักงานคณะกรรมการอาหารและยาก่อนรับยา", "is_correct": false, "explanation": "ผู้ป่วยที่มีใบสั่งยาได้รับการยกเว้น ไม่ต้องขอใบอนุญาตครอบครอง"}, {"label": "B", "text": "ต้องแจ้งสถานีตำรวจในพื้นที่ว่ามียาเสพติดไว้ในบ้าน", "is_correct": false, "explanation": "กฎหมายไม่ได้กำหนดให้ผู้ป่วยต้องแจ้งตำรวจ"}, {"label": "C", "text": "ครอบครองได้เฉพาะเมื่อเก็บไว้ในโรงพยาบาล ห้ามนำกลับบ้าน", "is_correct": false, "explanation": "ผู้ป่วยนำยากลับไปใช้ที่บ้านได้ตามใบสั่งยา"}, {"label": "D", "text": "ต้องให้แพทย์เป็นผู้เก็บยาไว้และนำมาให้ทุกวัน", "is_correct": false, "explanation": "กฎหมายไม่ได้กำหนดให้แพทย์ต้องเก็บยาแทนผู้ป่วย"}, {"label": "E", "text": "ไม่ต้องขออนุญาต เพราะเป็นการครอบครองในปริมาณที่ได้รับตามใบสั่งยาเพื่อรักษาตนเอง", "is_correct": true, "explanation": "ถูกต้อง การครอบครองตามใบสั่งยาเพื่อรักษาตนเองได้รับการยกเว้นไม่ต้องขออนุญาต"}], "key_takeaway": "ผู้ป่วยครอบครองยาเสพติดตามปริมาณในใบสั่งยาเพื่อรักษาตนเองได้โดยไม่ต้องขออนุญาต"}'::jsonb, 'easy', 'law-day1 • การครอบครองของผู้ป่วยตามใบสั่งยา'),
('01e88976af97613e700a86728a133fcd', 55, 'หญิงอายุ 32 ปี นำใบสั่งยาจากคลินิกเวชกรรมความงามที่สั่ง phentermine (วัตถุออกฤทธิ์ประเภท 2) 30 เม็ด มาที่ร้านขายยาแผนปัจจุบันซึ่งได้รับใบอนุญาตจำหน่ายวัตถุออกฤทธิ์ประเภท 3 และ 4 โดยบอกว่าคลินิกยาหมด เภสัชกรควรดำเนินการอย่างไร', '[{"label": "A", "text": "จ่ายยาได้ เพราะร้านมีใบอนุญาตวัตถุออกฤทธิ์ และผู้ป่วยมีใบสั่งยาจากแพทย์"}, {"label": "B", "text": "ไม่จ่ายยา เพราะใบอนุญาตของร้านไม่ครอบคลุมวัตถุออกฤทธิ์ประเภท 2 และแนะนำให้รับยาที่สถานพยาบาลผู้สั่งจ่าย"}, {"label": "C", "text": "จ่ายยาได้ครึ่งหนึ่งของที่สั่ง แล้วให้ผู้ป่วยไปรับส่วนที่เหลือที่คลินิก"}, {"label": "D", "text": "จ่ายยาได้ หากผู้ป่วยลงนามรับรองว่าจะใช้ตามแพทย์สั่ง"}, {"label": "E", "text": "จ่ายยาชนิดอื่นในกลุ่มลดความอยากอาหารทดแทนตามดุลยพินิจของเภสัชกร"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ไม่จ่ายยา เพราะใบอนุญาตของร้านไม่ครอบคลุมวัตถุออกฤทธิ์ประเภท 2 และแนะนำให้รับยาที่สถานพยาบาลผู้สั่งจ่าย — ใบอนุญาตวัตถุออกฤทธิ์ประเภท 3 และ 4 ของร้านขายยาไม่ครอบคลุมประเภท 2 แม้มีใบสั่งยาก็จ่ายไม่ได้", "reason": "ใบอนุญาตเกี่ยวกับวัตถุออกฤทธิ์ออกให้ตามประเภทของวัตถุออกฤทธิ์ ใบอนุญาตจำหน่ายวัตถุออกฤทธิ์ประเภท 3 และ 4 จึงไม่ครอบคลุมวัตถุออกฤทธิ์ประเภท 2 ซึ่งถูกควบคุมเข้มงวดกว่า และโดยหลักจะจ่ายให้ผู้ป่วยในสถานพยาบาลที่ได้รับอนุญาตเท่านั้น ร้านขายยาจึงจ่าย phentermine ไม่ได้แม้ผู้ป่วยจะมีใบสั่งยา\n\nประเด็นที่ต้องแยกคือ ใบสั่งยาเป็นเงื่อนไขของการจ่าย แต่สิทธิ์ในการจำหน่ายมาจากใบอนุญาต เมื่อไม่มีใบอนุญาตครอบคลุมประเภทนั้น การจ่ายเพียงบางส่วนหรือการให้ผู้ป่วยลงนามรับรองก็ไม่ทำให้ชอบด้วยกฎหมาย และการเปลี่ยนยาเองโดยไม่ปรึกษาผู้สั่งจ่ายก็ไม่เหมาะสม", "choices": [{"label": "A", "text": "จ่ายยาได้ เพราะร้านมีใบอนุญาตวัตถุออกฤทธิ์ และผู้ป่วยมีใบสั่งยาจากแพทย์", "is_correct": false, "explanation": "ใบอนุญาตออกตามประเภท ใบอนุญาตประเภท 3 และ 4 ไม่ครอบคลุมประเภท 2"}, {"label": "B", "text": "ไม่จ่ายยา เพราะใบอนุญาตของร้านไม่ครอบคลุมวัตถุออกฤทธิ์ประเภท 2 และแนะนำให้รับยาที่สถานพยาบาลผู้สั่งจ่าย", "is_correct": true, "explanation": "ถูกต้อง ร้านไม่มีสิทธิ์จำหน่ายวัตถุออกฤทธิ์ประเภท 2 ควรแนะนำให้รับยาที่สถานพยาบาลผู้สั่งจ่าย"}, {"label": "C", "text": "จ่ายยาได้ครึ่งหนึ่งของที่สั่ง แล้วให้ผู้ป่วยไปรับส่วนที่เหลือที่คลินิก", "is_correct": false, "explanation": "การจ่ายบางส่วนยังเป็นการจำหน่ายโดยไม่ได้รับอนุญาต"}, {"label": "D", "text": "จ่ายยาได้ หากผู้ป่วยลงนามรับรองว่าจะใช้ตามแพทย์สั่ง", "is_correct": false, "explanation": "การลงนามของผู้ป่วยไม่ทดแทนใบอนุญาตตามกฎหมาย"}, {"label": "E", "text": "จ่ายยาชนิดอื่นในกลุ่มลดความอยากอาหารทดแทนตามดุลยพินิจของเภสัชกร", "is_correct": false, "explanation": "การเปลี่ยนยาเองโดยไม่ปรึกษาผู้สั่งจ่ายไม่เหมาะสม และไม่ได้แก้ปัญหาเรื่องการจ่ายตามใบสั่ง"}], "key_takeaway": "ใบอนุญาตวัตถุออกฤทธิ์ออกตามประเภท ร้านที่มีใบอนุญาตประเภท 3 และ 4 จ่ายวัตถุออกฤทธิ์ประเภท 2 ไม่ได้แม้มีใบสั่งยา"}'::jsonb, 'hard', 'law-day1 • การจำหน่ายวัตถุออกฤทธิ์ประเภท 2'),
('aa878b4dc540ed2b46ab3beb8d3b1999', 56, 'ผู้ประกอบการรายหนึ่งต้องการเปิดร้านจำหน่ายช่อดอกกัญชาแห้ง และสอบถามเภสัชกรเกี่ยวกับสถานะทางกฎหมายในภาพรวม ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ช่อดอกกัญชาเป็นยาเสพติดให้โทษประเภท 1 จำหน่ายไม่ได้ในทุกกรณี"}, {"label": "B", "text": "ช่อดอกกัญชาเป็นวัตถุออกฤทธิ์ประเภท 2 ต้องจำหน่ายในโรงพยาบาลเท่านั้น"}, {"label": "C", "text": "ช่อดอกกัญชาเป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา ต้องขายในร้านขายยาแผนปัจจุบัน"}, {"label": "D", "text": "ช่อดอกกัญชาไม่มีกฎหมายใดควบคุม จำหน่ายแก่ใครก็ได้อย่างอิสระ"}, {"label": "E", "text": "ช่อดอกกัญชาเป็นสมุนไพรควบคุม การจำหน่ายต้องได้รับอนุญาตและอยู่ภายใต้ข้อจำกัดที่กฎหมายกำหนด"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ช่อดอกกัญชาเป็นสมุนไพรควบคุม การจำหน่ายต้องได้รับอนุญาตและอยู่ภายใต้ข้อจำกัดที่กฎหมายกำหนด — ช่อดอกกัญชาถูกควบคุมในฐานะสมุนไพรควบคุม ผู้จำหน่ายต้องได้รับอนุญาตและปฏิบัติตามข้อจำกัด", "reason": "หลังกัญชาไม่เป็นยาเสพติดให้โทษแล้ว (ยกเว้นสารสกัดที่มี THC เกินร้อยละ 0.2 โดยน้ำหนัก) กระทรวงสาธารณสุขได้ประกาศให้กัญชา โดยเฉพาะส่วนช่อดอก เป็นสมุนไพรควบคุมตาม พ.ร.บ.คุ้มครองและส่งเสริมภูมิปัญญาการแพทย์แผนไทย พ.ศ. 2542 ผู้ที่จะจำหน่ายต้องได้รับใบอนุญาต และต้องปฏิบัติตามข้อจำกัด เช่น ห้ามจำหน่ายแก่บุคคลอายุต่ำกว่า 20 ปี สตรีมีครรภ์ และสตรีให้นมบุตร และตั้งแต่ปี 2568 มีการปรับหลักเกณฑ์ให้การจำหน่ายช่อดอกมุ่งเน้นเพื่อการแพทย์ เช่น ต้องมีใบสั่งจากผู้ประกอบวิชาชีพที่กฎหมายกำหนด\n\nเนื่องจากรายละเอียดของมาตรการเกี่ยวกับกัญชามีการปรับปรุงบ่อย เภสัชกรควรตรวจสอบประกาศฉบับล่าสุดเสมอ แต่หลักการคือกัญชายังเป็นสิ่งที่รัฐควบคุม ไม่ได้เปิดเสรีโดยไม่มีเงื่อนไข", "choices": [{"label": "A", "text": "ช่อดอกกัญชาเป็นยาเสพติดให้โทษประเภท 1 จำหน่ายไม่ได้ในทุกกรณี", "is_correct": false, "explanation": "ช่อดอกกัญชาไม่ได้เป็นยาเสพติดให้โทษประเภท 1"}, {"label": "B", "text": "ช่อดอกกัญชาเป็นวัตถุออกฤทธิ์ประเภท 2 ต้องจำหน่ายในโรงพยาบาลเท่านั้น", "is_correct": false, "explanation": "กัญชาไม่ได้จัดเป็นวัตถุออกฤทธิ์"}, {"label": "C", "text": "ช่อดอกกัญชาเป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา ต้องขายในร้านขายยาแผนปัจจุบัน", "is_correct": false, "explanation": "ช่อดอกกัญชาไม่ได้ควบคุมในฐานะยาควบคุมพิเศษตาม พ.ร.บ.ยา"}, {"label": "D", "text": "ช่อดอกกัญชาไม่มีกฎหมายใดควบคุม จำหน่ายแก่ใครก็ได้อย่างอิสระ", "is_correct": false, "explanation": "ช่อดอกกัญชายังถูกควบคุม การจำหน่ายต้องได้รับอนุญาตและมีข้อห้ามจำหน่ายแก่บางกลุ่ม"}, {"label": "E", "text": "ช่อดอกกัญชาเป็นสมุนไพรควบคุม การจำหน่ายต้องได้รับอนุญาตและอยู่ภายใต้ข้อจำกัดที่กฎหมายกำหนด", "is_correct": true, "explanation": "ถูกต้อง ช่อดอกกัญชาเป็นสมุนไพรควบคุม ต้องได้รับอนุญาตและปฏิบัติตามข้อจำกัด"}], "key_takeaway": "ช่อดอกกัญชาเป็นสมุนไพรควบคุม ไม่ใช่สินค้าเสรี การจำหน่ายต้องได้รับอนุญาตและมีข้อจำกัด โดยเน้นการใช้ทางการแพทย์"}'::jsonb, 'medium', 'law-day1 • กัญชา: สมุนไพรควบคุม'),
('e7dd6dfb062b26e9e8536e2932b715e2', 57, 'เภสัชกรห้องยาผู้ป่วยนอกได้รับใบสั่งยา morphine sulfate tablet ที่ตัวเลขจำนวนเม็ดมีร่องรอยการแก้ไขจาก "20" เป็น "120" โดยไม่มีลายมือชื่อกำกับการแก้ไข แพทย์ผู้สั่งยังปฏิบัติงานอยู่ในโรงพยาบาล ผู้ป่วยเร่งให้จ่ายยาเพราะต้องรีบกลับบ้าน ข้อใดเป็นการปฏิบัติที่ถูกต้องที่สุด', '[{"label": "A", "text": "ระงับการจ่ายไว้ก่อน ติดต่อแพทย์ผู้สั่งเพื่อยืนยันและให้แก้ไขพร้อมลงนามกำกับ แล้วจึงจ่ายตามที่ยืนยัน"}, {"label": "B", "text": "จ่าย 120 เม็ดตามที่ปรากฏ เพราะใบสั่งมีลายมือชื่อแพทย์อยู่แล้ว"}, {"label": "C", "text": "จ่าย 20 เม็ดตามที่เภสัชกรเดาว่าถูกต้อง โดยไม่ต้องสอบถามแพทย์"}, {"label": "D", "text": "ปฏิเสธการจ่ายยาและแจ้งตำรวจจับกุมผู้ป่วยทันที"}, {"label": "E", "text": "ให้ผู้ป่วยลงลายมือชื่อรับรองการแก้ไขแทนแพทย์ แล้วจ่ายยา"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ระงับการจ่ายไว้ก่อน ติดต่อแพทย์ผู้สั่งเพื่อยืนยันและให้แก้ไขพร้อมลงนามกำกับ แล้วจึงจ่ายตามที่ยืนยัน — ใบสั่งยาเสพติดที่มีการแก้ไขโดยไม่มีการลงนามกำกับต้องได้รับการยืนยันจากผู้สั่งก่อนจ่าย", "reason": "เภสัชกรมีหน้าที่ตรวจสอบความถูกต้องและความสมบูรณ์ของใบสั่งยาก่อนจ่าย โดยเฉพาะยาเสพติดให้โทษซึ่งเสี่ยงต่อการปลอมแปลงใบสั่งยาเพื่อนำยาไปใช้ในทางที่ผิด การแก้ไขสาระสำคัญเช่นจำนวนยาโดยไม่มีลายมือชื่อผู้สั่งกำกับ ทำให้ใบสั่งไม่สมบูรณ์ เภสัชกรจึงต้องระงับการจ่ายและยืนยันกับผู้สั่งยาโดยตรง ให้ผู้สั่งแก้ไขและลงนามกำกับก่อน\n\nการเดาจำนวนเองหรือให้ผู้ป่วยรับรองแทนไม่ถูกต้อง ส่วนการแจ้งตำรวจทันทีโดยยังไม่ได้ข้อเท็จจริงก็ไม่เหมาะสม เพราะการแก้ไขอาจเกิดจากความผิดพลาดของผู้สั่งเอง หากยืนยันได้ว่ามีการปลอมแปลงจึงดำเนินการตามระเบียบของสถานพยาบาลและกฎหมายต่อไป", "choices": [{"label": "A", "text": "ระงับการจ่ายไว้ก่อน ติดต่อแพทย์ผู้สั่งเพื่อยืนยันและให้แก้ไขพร้อมลงนามกำกับ แล้วจึงจ่ายตามที่ยืนยัน", "is_correct": true, "explanation": "ถูกต้อง ระงับการจ่าย ยืนยันกับแพทย์ผู้สั่ง ให้แก้ไขและลงนามกำกับก่อนจ่าย"}, {"label": "B", "text": "จ่าย 120 เม็ดตามที่ปรากฏ เพราะใบสั่งมีลายมือชื่อแพทย์อยู่แล้ว", "is_correct": false, "explanation": "ลายมือชื่อเดิมไม่ได้รับรองการแก้ไขที่เกิดภายหลัง การจ่ายตามตัวเลขที่ถูกแก้จึงเสี่ยงต่อการจ่ายจากใบสั่งที่ปลอมแปลง"}, {"label": "C", "text": "จ่าย 20 เม็ดตามที่เภสัชกรเดาว่าถูกต้อง โดยไม่ต้องสอบถามแพทย์", "is_correct": false, "explanation": "เภสัชกรไม่ควรเดาเจตนาของผู้สั่ง ต้องยืนยันกับแพทย์โดยตรง"}, {"label": "D", "text": "ปฏิเสธการจ่ายยาและแจ้งตำรวจจับกุมผู้ป่วยทันที", "is_correct": false, "explanation": "ควรตรวจสอบข้อเท็จจริงกับผู้สั่งก่อน การแจ้งจับทันทีเป็นการด่วนสรุป"}, {"label": "E", "text": "ให้ผู้ป่วยลงลายมือชื่อรับรองการแก้ไขแทนแพทย์ แล้วจ่ายยา", "is_correct": false, "explanation": "ผู้ป่วยไม่มีอำนาจรับรองการแก้ไขใบสั่งยาแทนผู้สั่งจ่าย"}], "key_takeaway": "ใบสั่งยาเสพติดที่ถูกแก้ไขโดยไม่มีการลงนามกำกับ ต้องระงับการจ่ายและยืนยันกับผู้สั่งก่อนเสมอ"}'::jsonb, 'hard', 'law-day1 • ใบสั่งยาเสพติดให้โทษ: การตรวจสอบความถูกต้อง'),
('fe8512fce90290991f1545cd5906bfdf', 58, 'ผู้ป่วยในโปรแกรมบำบัดด้วย methadone ของโรงพยาบาล (methadone maintenance treatment) ซึ่งรับยาแบบดื่มต่อหน้าเจ้าหน้าที่ทุกวัน ขอให้เภสัชกรจ่าย methadone ให้นำกลับบ้าน 14 วัน เพราะจะไปทำงานต่างจังหวัด โดยแพทย์ยังไม่ได้ประเมินหรือสั่ง ข้อใดเป็นการปฏิบัติที่ถูกต้อง', '[{"label": "A", "text": "จ่ายได้ 14 วัน เพราะ methadone เป็นยาที่ผู้ป่วยได้รับอยู่แล้ว"}, {"label": "B", "text": "จ่ายได้ 7 วันตามดุลยพินิจของเภสัชกร เพื่อลดความเสี่ยงลงครึ่งหนึ่ง"}, {"label": "C", "text": "แนะนำให้ผู้ป่วยไปซื้อ methadone จากร้านขายยาในต่างจังหวัด"}, {"label": "D", "text": "ไม่จ่ายตามคำขอ ประสานให้แพทย์ประเมินและสั่งตามแนวทางของโปรแกรม หรือส่งต่อสถานบำบัดในพื้นที่ปลายทาง"}, {"label": "E", "text": "จ่ายได้ หากผู้ป่วยวางเงินมัดจำและลงนามรับผิดชอบเอง"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ไม่จ่ายตามคำขอ ประสานให้แพทย์ประเมินและสั่งตามแนวทางของโปรแกรม หรือส่งต่อสถานบำบัดในพื้นที่ปลายทาง — การจ่าย methadone ในโปรแกรมบำบัดต้องเป็นไปตามคำสั่งแพทย์และแนวทางของโปรแกรม เภสัชกรจ่ายเองตามคำขอไม่ได้", "reason": "Methadone เป็นยาเสพติดให้โทษประเภท 2 การใช้ในโปรแกรมบำบัดผู้ติดสารกลุ่ม opioid ต้องจ่ายตามคำสั่งของผู้ประกอบวิชาชีพเวชกรรม ภายใต้สถานพยาบาลที่ได้รับอนุญาตและตามแนวทางของโปรแกรม ซึ่งโดยทั่วไปเน้นการดื่มยาต่อหน้าเจ้าหน้าที่ การให้ยากลับบ้าน (take-home dose) ต้องผ่านการประเมินของแพทย์และเป็นไปตามเกณฑ์ เพื่อป้องกันการรั่วไหลและการใช้เกินขนาด\n\nเภสัชกรไม่มีอำนาจสั่งจ่ายหรือเปลี่ยนแผนการจ่ายยาเสพติดเอง ทางที่เหมาะสมคือประสานแพทย์ให้ประเมิน หรือส่งต่อผู้ป่วยไปรับยาต่อที่สถานบำบัดในพื้นที่ปลายทางเพื่อให้การรักษาต่อเนื่อง และร้านขายยาไม่สามารถจำหน่าย methadone ได้", "choices": [{"label": "A", "text": "จ่ายได้ 14 วัน เพราะ methadone เป็นยาที่ผู้ป่วยได้รับอยู่แล้ว", "is_correct": false, "explanation": "การที่ผู้ป่วยเคยได้รับยาไม่ทำให้เภสัชกรจ่ายยานอกเหนือคำสั่งแพทย์ได้"}, {"label": "B", "text": "จ่ายได้ 7 วันตามดุลยพินิจของเภสัชกร เพื่อลดความเสี่ยงลงครึ่งหนึ่ง", "is_correct": false, "explanation": "เภสัชกรไม่มีอำนาจกำหนดปริมาณยาเสพติดที่จ่ายเองแม้จะลดจำนวนลง"}, {"label": "C", "text": "แนะนำให้ผู้ป่วยไปซื้อ methadone จากร้านขายยาในต่างจังหวัด", "is_correct": false, "explanation": "ร้านขายยาไม่สามารถจำหน่าย methadone ซึ่งเป็นยาเสพติดให้โทษประเภท 2"}, {"label": "D", "text": "ไม่จ่ายตามคำขอ ประสานให้แพทย์ประเมินและสั่งตามแนวทางของโปรแกรม หรือส่งต่อสถานบำบัดในพื้นที่ปลายทาง", "is_correct": true, "explanation": "ถูกต้อง ไม่จ่ายตามคำขอ ประสานแพทย์ประเมินตามแนวทาง หรือส่งต่อสถานบำบัดปลายทาง"}, {"label": "E", "text": "จ่ายได้ หากผู้ป่วยวางเงินมัดจำและลงนามรับผิดชอบเอง", "is_correct": false, "explanation": "เงินมัดจำหรือการลงนามรับผิดชอบไม่ทดแทนคำสั่งแพทย์และเกณฑ์ของโปรแกรม"}], "key_takeaway": "Methadone ในโปรแกรมบำบัดจ่ายตามคำสั่งแพทย์และเกณฑ์ของโปรแกรมเท่านั้น เภสัชกรเพิ่มยากลับบ้านเองตามคำขอไม่ได้"}'::jsonb, 'hard', 'law-day1 • Methadone ในการบำบัดรักษาผู้ติดยา'),
('0ef93129a8fdeed07320c2ebeb4be4bf', 59, 'เภสัชกรผู้มีหน้าที่ปฏิบัติการของร้านขายยาแผนปัจจุบันพบว่า ในช่วงที่ตนไม่อยู่ร้าน พนักงานขายได้ขาย tramadol ให้วัยรุ่นหลายรายโดยไม่มีการคัดกรอง และไม่มีการบันทึกการขาย ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ไม่ผิด เพราะ tramadol ไม่ใช่ยาเสพติดตามประมวลกฎหมายยาเสพติด"}, {"label": "B", "text": "ผิดเฉพาะพนักงานขาย เภสัชกรไม่ต้องรับผิดชอบเพราะไม่อยู่ในร้านขณะนั้น"}, {"label": "C", "text": "ไม่ถูกต้อง เพราะยาควบคุมพิเศษต้องขายโดยเภสัชกรผู้มีหน้าที่ปฏิบัติการและบันทึกตามที่กำหนด เภสัชกรมีหน้าที่ควบคุมให้เป็นไปตามกฎหมาย"}, {"label": "D", "text": "ทำได้ หากพนักงานขายผ่านการอบรมจากบริษัทยาเรื่อง tramadol"}, {"label": "E", "text": "ทำได้ หากขายไม่เกินคนละหนึ่งแผงและเก็บเงินสด"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ไม่ถูกต้อง เพราะยาควบคุมพิเศษต้องขายโดยเภสัชกรผู้มีหน้าที่ปฏิบัติการและบันทึกตามที่กำหนด เภสัชกรมีหน้าที่ควบคุมให้เป็นไปตามกฎหมาย — ยาควบคุมพิเศษเช่น tramadol ต้องขายโดยเภสัชกรผู้มีหน้าที่ปฏิบัติการและบันทึกตามที่กำหนด", "reason": "Tramadol เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา การขายในร้านขายยาแผนปัจจุบันต้องกระทำโดยเภสัชกรผู้มีหน้าที่ปฏิบัติการ และต้องจัดทำบัญชีการขายตามที่กฎหมายกำหนด พนักงานที่ไม่ใช่เภสัชกรไม่มีสิทธิ์ขายยาควบคุมพิเศษ\n\nเภสัชกรผู้มีหน้าที่ปฏิบัติการมีหน้าที่ตามกฎหมายในการควบคุมการขายยาในร้าน และต้องอยู่ประจำตลอดเวลาที่เปิดทำการ การที่เภสัชกรไม่อยู่จึงไม่ได้ทำให้พ้นความรับผิดชอบ และอาจถูกดำเนินการทั้งตามกฎหมายยาและทางจรรยาบรรณวิชาชีพ", "choices": [{"label": "A", "text": "ไม่ผิด เพราะ tramadol ไม่ใช่ยาเสพติดตามประมวลกฎหมายยาเสพติด", "is_correct": false, "explanation": "แม้ไม่ใช่ยาเสพติด tramadol เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา ซึ่งมีข้อกำหนดการขาย"}, {"label": "B", "text": "ผิดเฉพาะพนักงานขาย เภสัชกรไม่ต้องรับผิดชอบเพราะไม่อยู่ในร้านขณะนั้น", "is_correct": false, "explanation": "เภสัชกรผู้มีหน้าที่ปฏิบัติการมีหน้าที่ควบคุมการขายและต้องอยู่ประจำร้าน จึงไม่พ้นความรับผิดชอบ"}, {"label": "C", "text": "ไม่ถูกต้อง เพราะยาควบคุมพิเศษต้องขายโดยเภสัชกรผู้มีหน้าที่ปฏิบัติการและบันทึกตามที่กำหนด เภสัชกรมีหน้าที่ควบคุมให้เป็นไปตามกฎหมาย", "is_correct": true, "explanation": "ถูกต้อง ยาควบคุมพิเศษต้องขายโดยเภสัชกรและบันทึกตามที่กำหนด เภสัชกรมีหน้าที่ควบคุม"}, {"label": "D", "text": "ทำได้ หากพนักงานขายผ่านการอบรมจากบริษัทยาเรื่อง tramadol", "is_correct": false, "explanation": "การอบรมจากบริษัทยาไม่ได้ให้สิทธิ์พนักงานขายยาควบคุมพิเศษ"}, {"label": "E", "text": "ทำได้ หากขายไม่เกินคนละหนึ่งแผงและเก็บเงินสด", "is_correct": false, "explanation": "การจำกัดจำนวนหรือวิธีชำระเงินไม่ทดแทนเงื่อนไขว่าต้องขายโดยเภสัชกร"}], "key_takeaway": "ยาควบคุมพิเศษเช่น tramadol ต้องขายโดยเภสัชกรผู้มีหน้าที่ปฏิบัติการพร้อมบันทึก และเภสัชกรต้องรับผิดชอบการขายในร้าน"}'::jsonb, 'medium', 'law-day1 • Tramadol: ความรับผิดชอบของเภสัชกรในร้านยา'),
('69d6a6b7b4df199a545bd3eb8daf9629', 60, 'สถานะทางกฎหมายของพืชกระท่อมในปัจจุบันคือข้อใด', '[{"label": "A", "text": "ยังเป็นยาเสพติดให้โทษประเภท 5 การปลูกต้องได้รับอนุญาตทุกกรณี"}, {"label": "B", "text": "ไม่เป็นยาเสพติดให้โทษแล้ว อยู่ภายใต้ พ.ร.บ.พืชกระท่อม พ.ศ. 2565 และการนำเข้าหรือส่งออกต้องได้รับอนุญาต"}, {"label": "C", "text": "เป็นวัตถุออกฤทธิ์ประเภท 4 จำหน่ายได้ในร้านขายยาที่มีใบอนุญาตเท่านั้น"}, {"label": "D", "text": "เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา ต้องมีใบสั่งยาจากแพทย์"}, {"label": "E", "text": "เป็นยาเสพติดให้โทษประเภท 1 เพราะมีสาร mitragynine"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ไม่เป็นยาเสพติดให้โทษแล้ว อยู่ภายใต้ พ.ร.บ.พืชกระท่อม พ.ศ. 2565 และการนำเข้าหรือส่งออกต้องได้รับอนุญาต — พืชกระท่อมไม่เป็นยาเสพติดให้โทษแล้ว และถูกควบคุมตาม พ.ร.บ.พืชกระท่อม พ.ศ. 2565", "reason": "พืชกระท่อมถูกถอนออกจากบัญชียาเสพติดให้โทษประเภท 5 ใน พ.ศ. 2564 และต่อมามี พ.ร.บ.พืชกระท่อม พ.ศ. 2565 เป็นกฎหมายเฉพาะสำหรับควบคุม ประชาชนสามารถปลูก ครอบครอง และขายใบกระท่อมภายในประเทศได้ภายใต้ข้อจำกัดของกฎหมาย ส่วนการนำเข้าหรือส่งออกต้องได้รับอนุญาต\n\nกฎหมายยังมีมาตรการคุ้มครอง เช่น ห้ามขายแก่กลุ่มเปราะบาง และห้ามนำใบกระท่อมไปผสมกับยาเสพติดหรือวัตถุอื่นเพื่อบริโภคในลักษณะที่เป็นอันตราย", "choices": [{"label": "A", "text": "ยังเป็นยาเสพติดให้โทษประเภท 5 การปลูกต้องได้รับอนุญาตทุกกรณี", "is_correct": false, "explanation": "พืชกระท่อมถูกถอนออกจากยาเสพติดให้โทษประเภท 5 แล้ว และการปลูกไม่ต้องขออนุญาต"}, {"label": "B", "text": "ไม่เป็นยาเสพติดให้โทษแล้ว อยู่ภายใต้ พ.ร.บ.พืชกระท่อม พ.ศ. 2565 และการนำเข้าหรือส่งออกต้องได้รับอนุญาต", "is_correct": true, "explanation": "ถูกต้อง พืชกระท่อมไม่เป็นยาเสพติดแล้ว อยู่ภายใต้ พ.ร.บ.พืชกระท่อม และการนำเข้า/ส่งออกต้องได้รับอนุญาต"}, {"label": "C", "text": "เป็นวัตถุออกฤทธิ์ประเภท 4 จำหน่ายได้ในร้านขายยาที่มีใบอนุญาตเท่านั้น", "is_correct": false, "explanation": "พืชกระท่อมไม่ได้จัดเป็นวัตถุออกฤทธิ์"}, {"label": "D", "text": "เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา ต้องมีใบสั่งยาจากแพทย์", "is_correct": false, "explanation": "พืชกระท่อมไม่ได้ควบคุมเป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา"}, {"label": "E", "text": "เป็นยาเสพติดให้โทษประเภท 1 เพราะมีสาร mitragynine", "is_correct": false, "explanation": "พืชกระท่อมไม่ได้จัดเป็นยาเสพติดให้โทษประเภท 1"}], "key_takeaway": "พืชกระท่อมไม่เป็นยาเสพติดแล้ว ควบคุมด้วย พ.ร.บ.พืชกระท่อม พ.ศ. 2565 และการนำเข้า/ส่งออกต้องได้รับอนุญาต"}'::jsonb, 'easy', 'law-day1 • พืชกระท่อม: สถานะทางกฎหมาย'),
('61b7bc2c0fec1aff141aa99df1eae201', 61, 'ข้อใดไม่ใช่วัตถุประสงค์ของสภาเภสัชกรรมตามพระราชบัญญัติวิชาชีพเภสัชกรรม พ.ศ. 2537', '[{"label": "A", "text": "ควบคุมการประกอบวิชาชีพเภสัชกรรมให้ถูกต้องตามจรรยาบรรณแห่งวิชาชีพ"}, {"label": "B", "text": "ส่งเสริมการศึกษา การวิจัย และการประกอบวิชาชีพในด้านเภสัชกรรม"}, {"label": "C", "text": "ออกใบอนุญาตขายยาแผนปัจจุบันให้แก่ผู้ประกอบกิจการร้านขายยา"}, {"label": "D", "text": "ให้คำปรึกษาหรือข้อเสนอแนะต่อรัฐบาลเกี่ยวกับปัญหาการสาธารณสุขและเภสัชกรรม"}, {"label": "E", "text": "ช่วยเหลือ แนะนำ เผยแพร่ และให้การศึกษาแก่ประชาชนในเรื่องที่เกี่ยวกับเภสัชกรรม"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ออกใบอนุญาตขายยาแผนปัจจุบันให้แก่ผู้ประกอบกิจการร้านขายยา — ใบอนุญาตขายยาออกโดยผู้อนุญาตตามกฎหมายว่าด้วยยา (สำนักงานคณะกรรมการอาหารและยา/สำนักงานสาธารณสุขจังหวัด) ไม่ใช่สภาเภสัชกรรม", "reason": "พ.ร.บ.วิชาชีพเภสัชกรรม พ.ศ. 2537 กำหนดให้สภาเภสัชกรรมเป็นนิติบุคคล มีวัตถุประสงค์ เช่น ควบคุมการประกอบวิชาชีพให้ถูกต้องตามจรรยาบรรณ ส่งเสริมการศึกษา การวิจัยและการประกอบวิชาชีพ ส่งเสริมความสามัคคีและผดุงเกียรติของสมาชิก ช่วยเหลือแนะนำและให้การศึกษาแก่ประชาชน ให้คำปรึกษาหรือข้อเสนอแนะต่อรัฐบาล และเป็นตัวแทนของผู้ประกอบวิชาชีพเภสัชกรรมในประเทศไทย\n\nสิ่งที่สภาเภสัชกรรมออกคือ \"ใบอนุญาตเป็นผู้ประกอบวิชาชีพเภสัชกรรม\" ซึ่งเป็นใบอนุญาตตัวบุคคล ส่วน \"ใบอนุญาตขายยา\" เป็นใบอนุญาตสถานประกอบการตามพระราชบัญญัติยา พ.ศ. 2510 ซึ่งออกโดยผู้อนุญาตภายใต้กระทรวงสาธารณสุข สองระบบนี้แยกจากกัน", "choices": [{"label": "A", "text": "ควบคุมการประกอบวิชาชีพเภสัชกรรมให้ถูกต้องตามจรรยาบรรณแห่งวิชาชีพ", "is_correct": false, "explanation": "เป็นวัตถุประสงค์หลักข้อแรกของสภาเภสัชกรรม"}, {"label": "B", "text": "ส่งเสริมการศึกษา การวิจัย และการประกอบวิชาชีพในด้านเภสัชกรรม", "is_correct": false, "explanation": "เป็นวัตถุประสงค์ของสภาเภสัชกรรมตามกฎหมาย"}, {"label": "C", "text": "ออกใบอนุญาตขายยาแผนปัจจุบันให้แก่ผู้ประกอบกิจการร้านขายยา", "is_correct": true, "explanation": "ถูกต้อง: ใบอนุญาตขายยาออกโดยผู้อนุญาตตามกฎหมายว่าด้วยยา (สำนักงานคณะกรรมการอาหารและยา/สำนักงานสาธารณสุขจังหวัด) ไม่ใช่สภาเภสัชกรรม"}, {"label": "D", "text": "ให้คำปรึกษาหรือข้อเสนอแนะต่อรัฐบาลเกี่ยวกับปัญหาการสาธารณสุขและเภสัชกรรม", "is_correct": false, "explanation": "เป็นวัตถุประสงค์ของสภาเภสัชกรรมตามกฎหมาย"}, {"label": "E", "text": "ช่วยเหลือ แนะนำ เผยแพร่ และให้การศึกษาแก่ประชาชนในเรื่องที่เกี่ยวกับเภสัชกรรม", "is_correct": false, "explanation": "เป็นวัตถุประสงค์ของสภาเภสัชกรรมตามกฎหมาย"}], "key_takeaway": "สภาเภสัชกรรมออกใบอนุญาตประกอบวิชาชีพ (ตัวบุคคล) ส่วนใบอนุญาตขายยา (สถานที่) ออกตามกฎหมายว่าด้วยยา"}'::jsonb, 'easy', 'law-day1 • สภาเภสัชกรรม: วัตถุประสงค์'),
('35dfecdf91c1c29d17e2da3301455fe0', 62, 'บุคคลที่สำเร็จการศึกษาปริญญาเภสัชศาสตรบัณฑิต และประสงค์จะประกอบวิชาชีพเภสัชกรรมโดยชอบด้วยกฎหมาย ต้องมีคุณสมบัติตามข้อใด', '[{"label": "A", "text": "เป็นสมาชิกสามัญของสภาเภสัชกรรม และได้ขึ้นทะเบียนรับใบอนุญาตจากสภาเภสัชกรรม"}, {"label": "B", "text": "เมื่อได้รับปริญญาเภสัชศาสตรบัณฑิตแล้วสามารถประกอบวิชาชีพได้ทันทีโดยไม่ต้องขึ้นทะเบียนใด ๆ"}, {"label": "C", "text": "ได้รับใบอนุญาตประกอบวิชาชีพจากสำนักงานคณะกรรมการอาหารและยา"}, {"label": "D", "text": "ขึ้นทะเบียนเป็นผู้ประกอบวิชาชีพกับมหาวิทยาลัยที่ตนสำเร็จการศึกษา"}, {"label": "E", "text": "เป็นสมาชิกวิสามัญหรือสมาชิกกิตติมศักดิ์ของสภาเภสัชกรรมก็เพียงพอต่อการรับใบอนุญาต"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. เป็นสมาชิกสามัญของสภาเภสัชกรรม และได้ขึ้นทะเบียนรับใบอนุญาตจากสภาเภสัชกรรม — ผู้ประกอบวิชาชีพเภสัชกรรมคือผู้ที่ได้ขึ้นทะเบียนและรับใบอนุญาตจากสภาเภสัชกรรม ซึ่งต้องเป็นสมาชิกสามัญ", "reason": "ตาม พ.ร.บ.วิชาชีพเภสัชกรรม พ.ศ. 2537 \"ผู้ประกอบวิชาชีพเภสัชกรรม\" หมายถึงบุคคลซึ่งได้ขึ้นทะเบียนและรับใบอนุญาตเป็นผู้ประกอบวิชาชีพเภสัชกรรมจากสภาเภสัชกรรม และผู้ขอขึ้นทะเบียนต้องเป็นสมาชิกสามัญของสภาเภสัชกรรม (ซึ่งมีคุณสมบัติด้านความรู้ในวิชาชีพตามที่สภากำหนด เช่น ผ่านการสอบความรู้)\n\nสมาชิกภาพกับใบอนุญาตจึงเกี่ยวเนื่องกัน การสำเร็จการศึกษาเพียงอย่างเดียวยังไม่ทำให้มีสิทธิประกอบวิชาชีพ", "choices": [{"label": "A", "text": "เป็นสมาชิกสามัญของสภาเภสัชกรรม และได้ขึ้นทะเบียนรับใบอนุญาตจากสภาเภสัชกรรม", "is_correct": true, "explanation": "ถูกต้อง: ผู้ประกอบวิชาชีพเภสัชกรรมคือผู้ที่ได้ขึ้นทะเบียนและรับใบอนุญาตจากสภาเภสัชกรรม ซึ่งต้องเป็นสมาชิกสามัญ"}, {"label": "B", "text": "เมื่อได้รับปริญญาเภสัชศาสตรบัณฑิตแล้วสามารถประกอบวิชาชีพได้ทันทีโดยไม่ต้องขึ้นทะเบียนใด ๆ", "is_correct": false, "explanation": "ปริญญาเป็นเพียงคุณวุฒิทางการศึกษา ยังต้องขึ้นทะเบียนและรับใบอนุญาตจากสภาเภสัชกรรมก่อน"}, {"label": "C", "text": "ได้รับใบอนุญาตประกอบวิชาชีพจากสำนักงานคณะกรรมการอาหารและยา", "is_correct": false, "explanation": "ผู้ออกใบอนุญาตประกอบวิชาชีพเภสัชกรรมคือสภาเภสัชกรรม ไม่ใช่ อย."}, {"label": "D", "text": "ขึ้นทะเบียนเป็นผู้ประกอบวิชาชีพกับมหาวิทยาลัยที่ตนสำเร็จการศึกษา", "is_correct": false, "explanation": "สถาบันการศึกษาไม่มีอำนาจออกใบอนุญาตประกอบวิชาชีพ"}, {"label": "E", "text": "เป็นสมาชิกวิสามัญหรือสมาชิกกิตติมศักดิ์ของสภาเภสัชกรรมก็เพียงพอต่อการรับใบอนุญาต", "is_correct": false, "explanation": "การขึ้นทะเบียนรับใบอนุญาตผูกกับสถานะสมาชิกสามัญ สมาชิกกิตติมศักดิ์เป็นตำแหน่งเกียรติยศ ไม่ใช่ช่องทางรับใบอนุญาต"}], "key_takeaway": "ประกอบวิชาชีพเภสัชกรรมได้ต้องเป็นสมาชิกสามัญและได้รับใบอนุญาตจากสภาเภสัชกรรม ไม่ใช่แค่มีปริญญา"}'::jsonb, 'easy', 'law-day1 • สภาเภสัชกรรม: สมาชิกและใบอนุญาต'),
('77235671887672db99e66605b2ba66e4', 63, 'นางสาวมะลิ นักศึกษาเภสัชศาสตร์ชั้นปีสุดท้าย ฝึกปฏิบัติงานวิชาชีพที่ร้านยาซึ่งเป็นแหล่งฝึกของมหาวิทยาลัย ระหว่างฝึกเธอซักประวัติและจ่ายยาอันตรายให้ผู้ป่วยโดยเภสัชกรประจำแหล่งฝึกตรวจสอบและควบคุมอยู่ด้วย ข้อใดถูกต้องที่สุดเกี่ยวกับการกระทำของนางสาวมะลิ', '[{"label": "A", "text": "ผิดกฎหมาย เพราะผู้ไม่มีใบอนุญาตประกอบวิชาชีพจะกระทำการใดที่เป็นวิชาชีพเภสัชกรรมไม่ได้ทุกกรณี"}, {"label": "B", "text": "ทำได้ เฉพาะเมื่อนักศึกษาสอบความรู้ผ่านแล้วบางส่วนและได้รับใบอนุญาตชั่วคราว"}, {"label": "C", "text": "ทำได้ หากผู้ป่วยแต่ละรายให้ความยินยอมเป็นลายลักษณ์อักษร"}, {"label": "D", "text": "ทำได้ตามลำพังแม้ไม่มีเภสัชกรควบคุม เพราะเป็นนักศึกษาชั้นปีสุดท้ายในหลักสูตรแล้ว"}, {"label": "E", "text": "ทำได้ เพราะเป็นการฝึกหัดตามหลักสูตรภายใต้การควบคุมของเภสัชกรผู้มีใบอนุญาต"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ทำได้ เพราะเป็นการฝึกหัดตามหลักสูตรภายใต้การควบคุมของเภสัชกรผู้มีใบอนุญาต — นักศึกษาที่ฝึกปฏิบัติตามหลักสูตรภายใต้การควบคุมของผู้ประกอบวิชาชีพเป็นข้อยกเว้นของการห้ามประกอบวิชาชีพโดยไม่มีใบอนุญาต", "reason": "พ.ร.บ.วิชาชีพเภสัชกรรมห้ามผู้ที่มิใช่ผู้ประกอบวิชาชีพเภสัชกรรมกระทำการประกอบวิชาชีพเภสัชกรรม หรือแสดงด้วยวิธีใด ๆ ให้ผู้อื่นเข้าใจว่าตนพร้อมจะประกอบวิชาชีพ แต่มีข้อยกเว้น เช่น การประกอบวิชาชีพแก่ตนเอง การช่วยเหลือตามหน้าที่มนุษยธรรมโดยไม่รับประโยชน์ตอบแทน และกรณีนักศึกษาหรือผู้รับการฝึกอบรมที่ฝึกหัดในวิชาชีพภายใต้การควบคุมของผู้ให้การศึกษาหรือฝึกอบรมซึ่งเป็นผู้ประกอบวิชาชีพเภสัชกรรม\n\nสาระสำคัญของข้อยกเว้นคือ \"อยู่ภายใต้การควบคุม\" ของเภสัชกร หากนักศึกษาปฏิบัติตามลำพังย่อมไม่อยู่ในข้อยกเว้น และเภสัชกรแหล่งฝึกยังต้องรับผิดชอบในการควบคุมดูแล", "choices": [{"label": "A", "text": "ผิดกฎหมาย เพราะผู้ไม่มีใบอนุญาตประกอบวิชาชีพจะกระทำการใดที่เป็นวิชาชีพเภสัชกรรมไม่ได้ทุกกรณี", "is_correct": false, "explanation": "กฎหมายมีข้อยกเว้นสำหรับนักศึกษาที่ฝึกภายใต้การควบคุมของผู้ประกอบวิชาชีพ จึงไม่ใช่ห้ามทุกกรณี"}, {"label": "B", "text": "ทำได้ เฉพาะเมื่อนักศึกษาสอบความรู้ผ่านแล้วบางส่วนและได้รับใบอนุญาตชั่วคราว", "is_correct": false, "explanation": "กฎหมายไม่ได้กำหนดระบบใบอนุญาตชั่วคราวสำหรับนักศึกษาฝึกงานเป็นเงื่อนไข"}, {"label": "C", "text": "ทำได้ หากผู้ป่วยแต่ละรายให้ความยินยอมเป็นลายลักษณ์อักษร", "is_correct": false, "explanation": "ความยินยอมของผู้ป่วยไม่ใช่ฐานที่ทำให้ผู้ไม่มีใบอนุญาตประกอบวิชาชีพได้"}, {"label": "D", "text": "ทำได้ตามลำพังแม้ไม่มีเภสัชกรควบคุม เพราะเป็นนักศึกษาชั้นปีสุดท้ายในหลักสูตรแล้ว", "is_correct": false, "explanation": "ข้อยกเว้นต้องเป็นการฝึกภายใต้การควบคุมของผู้ประกอบวิชาชีพเท่านั้น การปฏิบัติตามลำพังไม่ได้รับยกเว้น"}, {"label": "E", "text": "ทำได้ เพราะเป็นการฝึกหัดตามหลักสูตรภายใต้การควบคุมของเภสัชกรผู้มีใบอนุญาต", "is_correct": true, "explanation": "ถูกต้อง: นักศึกษาที่ฝึกปฏิบัติตามหลักสูตรภายใต้การควบคุมของผู้ประกอบวิชาชีพเป็นข้อยกเว้นของการห้ามประกอบวิชาชีพโดยไม่มีใบอนุญาต"}], "key_takeaway": "นักศึกษาฝึกงานทำงานวิชาชีพได้เฉพาะภายใต้การควบคุมของเภสัชกรผู้มีใบอนุญาตเท่านั้น"}'::jsonb, 'medium', 'law-day1 • การประกอบวิชาชีพโดยไม่มีใบอนุญาต: ข้อยกเว้น'),
('b2cd208347f62a3d52127cf48b2d86c5', 64, 'เภสัชกรสมชายสะสมหน่วยกิตการศึกษาต่อเนื่อง (CPE) ไม่ครบตามเกณฑ์จึงไม่ได้ยื่นต่ออายุใบอนุญาตประกอบวิชาชีพ จนใบอนุญาตสิ้นอายุไปแล้ว อย่างไรก็ตามเขายังคงปฏิบัติหน้าที่เป็นผู้มีหน้าที่ปฏิบัติการในร้านขายยาแผนปัจจุบันตามปกติ ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ทำได้ เพราะยังเป็นสมาชิกสภาเภสัชกรรมอยู่ การไม่ต่ออายุเป็นเพียงเรื่องทางธุรการ"}, {"label": "B", "text": "ถือเป็นการประกอบวิชาชีพเภสัชกรรมโดยไม่มีใบอนุญาต ซึ่งเป็นความผิดที่มีโทษทางอาญา"}, {"label": "C", "text": "ทำได้ ตราบใดที่ยังทยอยสะสมหน่วยกิต CPE ต่อไปจนครบในภายหลัง"}, {"label": "D", "text": "เป็นเพียงความผิดทางจรรยาบรรณ ซึ่งสภาเภสัชกรรมลงโทษได้สูงสุดเพียงว่ากล่าวตักเตือน"}, {"label": "E", "text": "ความรับผิดตกอยู่กับผู้รับอนุญาตขายยาแต่ฝ่ายเดียว ตัวเภสัชกรไม่มีความผิด"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ถือเป็นการประกอบวิชาชีพเภสัชกรรมโดยไม่มีใบอนุญาต ซึ่งเป็นความผิดที่มีโทษทางอาญา — เมื่อใบอนุญาตสิ้นอายุ ผู้นั้นไม่มีใบอนุญาตที่มีผล การปฏิบัติงานวิชาชีพต่อจึงเป็นการประกอบวิชาชีพโดยไม่มีใบอนุญาต", "reason": "ภายหลังการแก้ไขเพิ่มเติม พ.ร.บ.วิชาชีพเภสัชกรรม ใบอนุญาตประกอบวิชาชีพมีอายุและต้องต่ออายุตามหลักเกณฑ์ที่สภาเภสัชกรรมกำหนดในข้อบังคับ ซึ่งรวมถึงการศึกษาต่อเนื่องทางเภสัชศาสตร์ (CPE) ที่บริหารโดยศูนย์การศึกษาต่อเนื่องทางเภสัชศาสตร์ของสภาเภสัชกรรม\n\nเมื่อใบอนุญาตสิ้นอายุโดยไม่ได้ต่ออายุ บุคคลนั้นย่อมไม่มีใบอนุญาตที่ใช้ได้ การยังคงจ่ายยาหรือทำหน้าที่ผู้มีหน้าที่ปฏิบัติการในร้านขายยาจึงเป็นการประกอบวิชาชีพโดยไม่มีใบอนุญาตซึ่งมีโทษทางอาญา และร้านขายยายังขาดผู้มีหน้าที่ปฏิบัติการที่ถูกต้องตามกฎหมายว่าด้วยยาอีกด้วย", "choices": [{"label": "A", "text": "ทำได้ เพราะยังเป็นสมาชิกสภาเภสัชกรรมอยู่ การไม่ต่ออายุเป็นเพียงเรื่องทางธุรการ", "is_correct": false, "explanation": "สมาชิกภาพไม่ได้ทดแทนใบอนุญาต เมื่อใบอนุญาตสิ้นอายุย่อมไม่มีสิทธิประกอบวิชาชีพ"}, {"label": "B", "text": "ถือเป็นการประกอบวิชาชีพเภสัชกรรมโดยไม่มีใบอนุญาต ซึ่งเป็นความผิดที่มีโทษทางอาญา", "is_correct": true, "explanation": "ถูกต้อง: เมื่อใบอนุญาตสิ้นอายุ ผู้นั้นไม่มีใบอนุญาตที่มีผล การปฏิบัติงานวิชาชีพต่อจึงเป็นการประกอบวิชาชีพโดยไม่มีใบอนุญาต"}, {"label": "C", "text": "ทำได้ ตราบใดที่ยังทยอยสะสมหน่วยกิต CPE ต่อไปจนครบในภายหลัง", "is_correct": false, "explanation": "การสะสมหน่วยกิตภายหลังไม่ทำให้ใบอนุญาตที่สิ้นอายุแล้วกลับมีผล"}, {"label": "D", "text": "เป็นเพียงความผิดทางจรรยาบรรณ ซึ่งสภาเภสัชกรรมลงโทษได้สูงสุดเพียงว่ากล่าวตักเตือน", "is_correct": false, "explanation": "การประกอบวิชาชีพโดยไม่มีใบอนุญาตเป็นความผิดตามกฎหมายที่มีโทษทางอาญา ไม่ใช่แค่เรื่องจรรยาบรรณ"}, {"label": "E", "text": "ความรับผิดตกอยู่กับผู้รับอนุญาตขายยาแต่ฝ่ายเดียว ตัวเภสัชกรไม่มีความผิด", "is_correct": false, "explanation": "ผู้ที่ประกอบวิชาชีพโดยไม่มีใบอนุญาตมีความผิดโดยตรง ผู้รับอนุญาตอาจมีความรับผิดเพิ่มเติมได้แต่ไม่ทำให้เภสัชกรพ้นผิด"}], "key_takeaway": "ใบอนุญาตสิ้นอายุ = ไม่มีใบอนุญาต ต้องหยุดประกอบวิชาชีพจนกว่าจะได้รับใบอนุญาตที่มีผลใหม่"}'::jsonb, 'medium', 'law-day1 • ใบอนุญาต: การต่ออายุและ CPE'),
('5eb7a9c171de17b08701a025aeb313dd', 65, 'ข้อใดกล่าวถูกต้องเกี่ยวกับการยื่นเรื่องต่อสภาเภสัชกรรมเพื่อให้พิจารณาการประพฤติผิดจรรยาบรรณของผู้ประกอบวิชาชีพเภสัชกรรม', '[{"label": "A", "text": "เฉพาะผู้ได้รับความเสียหายโดยตรงเท่านั้นที่มีสิทธิยื่นเรื่องต่อสภาเภสัชกรรมเป็นหนังสือ"}, {"label": "B", "text": "ต้องร้องทุกข์ต่อพนักงานสอบสวนก่อน แล้วพนักงานสอบสวนจึงส่งเรื่องต่อสภาเภสัชกรรม"}, {"label": "C", "text": "ผู้เสียหายยื่นเรื่องเรียกว่า \"กล่าวโทษ\" ส่วนบุคคลอื่นยื่นเรื่องเรียกว่า \"กล่าวหา\""}, {"label": "D", "text": "ผู้เสียหายยื่นเรียกว่า \"กล่าวหา\" ส่วนบุคคลอื่นหรือคณะกรรมการสภายื่นเรียกว่า \"กล่าวโทษ\""}, {"label": "E", "text": "ต้องมีคำพิพากษาของศาลว่าเภสัชกรกระทำผิดก่อน จึงจะยื่นเรื่องต่อสภาเภสัชกรรมได้"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ผู้เสียหายยื่นเรียกว่า \"กล่าวหา\" ส่วนบุคคลอื่นหรือคณะกรรมการสภายื่นเรียกว่า \"กล่าวโทษ\" — ผู้เสียหายมีสิทธิ \"กล่าวหา\" ส่วนบุคคลอื่นรวมทั้งคณะกรรมการสภามีสิทธิ \"กล่าวโทษ\" ผู้ประกอบวิชาชีพที่ประพฤติผิดจรรยาบรรณ", "reason": "พ.ร.บ.วิชาชีพเภสัชกรรม พ.ศ. 2537 แยกผู้ยื่นเรื่องเป็นสองลักษณะ คือ บุคคลผู้ได้รับความเสียหายจากการประพฤติผิดจรรยาบรรณมีสิทธิกล่าวหา และบุคคลอื่นมีสิทธิกล่าวโทษ นอกจากนี้คณะกรรมการสภาเภสัชกรรมก็มีสิทธิกล่าวโทษได้เช่นกัน โดยยื่นเป็นหนังสือต่อสภาเภสัชกรรม\n\nกระบวนการทางจรรยาบรรณเป็นอิสระจากกระบวนการทางอาญาหรือแพ่ง จึงไม่ต้องผ่านพนักงานสอบสวนหรือรอคำพิพากษาของศาล ทั้งนี้สิทธิกล่าวหา/กล่าวโทษมีอายุความตามที่กฎหมายกำหนด", "choices": [{"label": "A", "text": "เฉพาะผู้ได้รับความเสียหายโดยตรงเท่านั้นที่มีสิทธิยื่นเรื่องต่อสภาเภสัชกรรมเป็นหนังสือ", "is_correct": false, "explanation": "บุคคลอื่นและคณะกรรมการสภาเภสัชกรรมก็มีสิทธิยื่นเรื่องได้ในรูปของการกล่าวโทษ"}, {"label": "B", "text": "ต้องร้องทุกข์ต่อพนักงานสอบสวนก่อน แล้วพนักงานสอบสวนจึงส่งเรื่องต่อสภาเภสัชกรรม", "is_correct": false, "explanation": "การกล่าวหาหรือกล่าวโทษยื่นต่อสภาเภสัชกรรมได้โดยตรง ไม่ต้องผ่านกระบวนการทางอาญา"}, {"label": "C", "text": "ผู้เสียหายยื่นเรื่องเรียกว่า \"กล่าวโทษ\" ส่วนบุคคลอื่นยื่นเรื่องเรียกว่า \"กล่าวหา\"", "is_correct": false, "explanation": "สลับกัน ผู้เสียหายเป็นผู้ \"กล่าวหา\" ส่วนบุคคลอื่นเป็นผู้ \"กล่าวโทษ\""}, {"label": "D", "text": "ผู้เสียหายยื่นเรียกว่า \"กล่าวหา\" ส่วนบุคคลอื่นหรือคณะกรรมการสภายื่นเรียกว่า \"กล่าวโทษ\"", "is_correct": true, "explanation": "ถูกต้อง: ผู้เสียหายมีสิทธิ \"กล่าวหา\" ส่วนบุคคลอื่นรวมทั้งคณะกรรมการสภามีสิทธิ \"กล่าวโทษ\" ผู้ประกอบวิชาชีพที่ประพฤติผิดจรรยาบรรณ"}, {"label": "E", "text": "ต้องมีคำพิพากษาของศาลว่าเภสัชกรกระทำผิดก่อน จึงจะยื่นเรื่องต่อสภาเภสัชกรรมได้", "is_correct": false, "explanation": "การพิจารณาจรรยาบรรณเป็นกระบวนการของสภาวิชาชีพที่แยกจากคดีในศาล ไม่ต้องรอคำพิพากษา"}], "key_takeaway": "กล่าวหา = ผู้เสียหายยื่น; กล่าวโทษ = บุคคลอื่นหรือคณะกรรมการสภายื่น"}'::jsonb, 'easy', 'law-day1 • การกล่าวหาและการกล่าวโทษ'),
('8529a0e8f5d54f180336b786aeacd23b', 66, 'เมื่อคณะกรรมการสภาเภสัชกรรมวินิจฉัยว่าผู้ประกอบวิชาชีพประพฤติผิดจรรยาบรรณ ข้อใดเรียงลำดับโทษตามกฎหมายจากเบาไปหนักได้ถูกต้อง', '[{"label": "A", "text": "ว่ากล่าวตักเตือน → ภาคทัณฑ์ → พักใช้ใบอนุญาต → เพิกถอนใบอนุญาต"}, {"label": "B", "text": "ภาคทัณฑ์ → ว่ากล่าวตักเตือน → พักใช้ใบอนุญาต → เพิกถอนใบอนุญาต"}, {"label": "C", "text": "ว่ากล่าวตักเตือน → พักใช้ใบอนุญาต → ภาคทัณฑ์ → เพิกถอนใบอนุญาต"}, {"label": "D", "text": "ว่ากล่าวตักเตือน → ภาคทัณฑ์ → เพิกถอนใบอนุญาต → พักใช้ใบอนุญาต"}, {"label": "E", "text": "ภาคทัณฑ์ → พักใช้ใบอนุญาต → ว่ากล่าวตักเตือน → เพิกถอนใบอนุญาต"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ว่ากล่าวตักเตือน → ภาคทัณฑ์ → พักใช้ใบอนุญาต → เพิกถอนใบอนุญาต — โทษทางจรรยาบรรณเรียงจากเบาไปหนัก คือ ว่ากล่าวตักเตือน ภาคทัณฑ์ พักใช้ใบอนุญาต และเพิกถอนใบอนุญาต", "reason": "เมื่อสอบสวนแล้ว คณะกรรมการสภาเภสัชกรรมมีอำนาจวินิจฉัยชี้ขาดอย่างหนึ่งอย่างใด คือ ยกข้อกล่าวหาหรือข้อกล่าวโทษ (กรณีไม่มีมูลหรือไม่ผิด) ว่ากล่าวตักเตือน ภาคทัณฑ์ พักใช้ใบอนุญาตมีกำหนดเวลาตามที่เห็นสมควรภายในกรอบที่กฎหมายกำหนด หรือเพิกถอนใบอนุญาต\n\n\"ยกข้อกล่าวหา\" ไม่ใช่โทษ แต่เป็นผลการวินิจฉัย ส่วนโทษเรียงจากเบาไปหนักตามลำดับข้างต้น โดยพักใช้และเพิกถอนมีผลต่อสิทธิในการประกอบวิชาชีพโดยตรง", "choices": [{"label": "A", "text": "ว่ากล่าวตักเตือน → ภาคทัณฑ์ → พักใช้ใบอนุญาต → เพิกถอนใบอนุญาต", "is_correct": true, "explanation": "ถูกต้อง: โทษทางจรรยาบรรณเรียงจากเบาไปหนัก คือ ว่ากล่าวตักเตือน ภาคทัณฑ์ พักใช้ใบอนุญาต และเพิกถอนใบอนุญาต"}, {"label": "B", "text": "ภาคทัณฑ์ → ว่ากล่าวตักเตือน → พักใช้ใบอนุญาต → เพิกถอนใบอนุญาต", "is_correct": false, "explanation": "ภาคทัณฑ์หนักกว่าว่ากล่าวตักเตือน จึงเรียงสลับกัน"}, {"label": "C", "text": "ว่ากล่าวตักเตือน → พักใช้ใบอนุญาต → ภาคทัณฑ์ → เพิกถอนใบอนุญาต", "is_correct": false, "explanation": "พักใช้ใบอนุญาตมีผลห้ามประกอบวิชาชีพชั่วคราว จึงหนักกว่าภาคทัณฑ์"}, {"label": "D", "text": "ว่ากล่าวตักเตือน → ภาคทัณฑ์ → เพิกถอนใบอนุญาต → พักใช้ใบอนุญาต", "is_correct": false, "explanation": "เพิกถอนใบอนุญาตเป็นโทษสูงสุด หนักกว่าพักใช้ใบอนุญาต"}, {"label": "E", "text": "ภาคทัณฑ์ → พักใช้ใบอนุญาต → ว่ากล่าวตักเตือน → เพิกถอนใบอนุญาต", "is_correct": false, "explanation": "ว่ากล่าวตักเตือนเป็นโทษเบาที่สุด ไม่ได้อยู่ระหว่างพักใช้กับเพิกถอน"}], "key_takeaway": "ตักเตือน < ภาคทัณฑ์ < พักใช้ < เพิกถอน; ยกข้อกล่าวหาไม่ใช่โทษ"}'::jsonb, 'easy', 'law-day1 • โทษทางจรรยาบรรณ'),
('dde3fb685627924c70c4ef913bad4ed3', 67, 'นางสมศรียื่นกล่าวหาเภสัชกรร้านยาแห่งหนึ่งต่อสภาเภสัชกรรมว่าจ่ายยาผิดทำให้ตนได้รับอันตราย ต่อมาเภสัชกรขอโทษและชดใช้ค่ารักษาพยาบาล นางสมศรีจึงยื่นหนังสือขอถอนเรื่องกล่าวหา ข้อใดถูกต้อง', '[{"label": "A", "text": "เรื่องยุติทันที เพราะความผิดจรรยาบรรณเป็นความผิดอันยอมความได้"}, {"label": "B", "text": "การถอนเรื่องมีผลเฉพาะเมื่อเภสัชกรผู้ถูกกล่าวหาลงนามยินยอมด้วย"}, {"label": "C", "text": "การถอนเรื่องไม่เป็นเหตุให้ระงับการดำเนินการ สภายังพิจารณาต่อได้"}, {"label": "D", "text": "เรื่องจะถูกส่งต่อเป็นคดีอาญาโดยอัตโนมัติแทนการพิจารณาทางจรรยาบรรณ"}, {"label": "E", "text": "เภสัชกรจะได้รับการลดโทษลงหนึ่งระดับโดยอัตโนมัติเพราะได้เยียวยาแล้ว"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. การถอนเรื่องไม่เป็นเหตุให้ระงับการดำเนินการ สภายังพิจารณาต่อได้ — การถอนเรื่องกล่าวหาหรือกล่าวโทษที่ยื่นแล้วไม่ทำให้กระบวนการพิจารณาจรรยาบรรณของสภาระงับ", "reason": "พ.ร.บ.วิชาชีพเภสัชกรรมบัญญัติว่าการถอนเรื่องการกล่าวหาหรือการกล่าวโทษที่ได้ยื่นไว้แล้ว ไม่เป็นเหตุให้ระงับการดำเนินการตามพระราชบัญญัตินี้ เพราะการควบคุมจรรยาบรรณเป็นไปเพื่อประโยชน์สาธารณะและการรักษามาตรฐานวิชาชีพ ไม่ใช่เพียงข้อพิพาทส่วนตัวระหว่างผู้ป่วยกับเภสัชกร\n\nการที่เภสัชกรเยียวยาความเสียหายเป็นสิ่งดีและอาจถูกนำมาพิจารณาประกอบ แต่ไม่ทำให้เรื่องยุติหรือได้ลดโทษโดยอัตโนมัติ", "choices": [{"label": "A", "text": "เรื่องยุติทันที เพราะความผิดจรรยาบรรณเป็นความผิดอันยอมความได้", "is_correct": false, "explanation": "ความผิดจรรยาบรรณไม่ได้ใช้หลักความผิดอันยอมความได้แบบคดีอาญา"}, {"label": "B", "text": "การถอนเรื่องมีผลเฉพาะเมื่อเภสัชกรผู้ถูกกล่าวหาลงนามยินยอมด้วย", "is_correct": false, "explanation": "ไม่มีหลักว่าการถอนเรื่องต้องได้รับความยินยอมจากผู้ถูกกล่าวหา และการถอนก็ไม่ทำให้กระบวนการระงับอยู่แล้ว"}, {"label": "C", "text": "การถอนเรื่องไม่เป็นเหตุให้ระงับการดำเนินการ สภายังพิจารณาต่อได้", "is_correct": true, "explanation": "ถูกต้อง: การถอนเรื่องกล่าวหาหรือกล่าวโทษที่ยื่นแล้วไม่ทำให้กระบวนการพิจารณาจรรยาบรรณของสภาระงับ"}, {"label": "D", "text": "เรื่องจะถูกส่งต่อเป็นคดีอาญาโดยอัตโนมัติแทนการพิจารณาทางจรรยาบรรณ", "is_correct": false, "explanation": "การถอนเรื่องไม่ได้เปลี่ยนสภาพเป็นคดีอาญา ทั้งสองกระบวนการแยกจากกัน"}, {"label": "E", "text": "เภสัชกรจะได้รับการลดโทษลงหนึ่งระดับโดยอัตโนมัติเพราะได้เยียวยาแล้ว", "is_correct": false, "explanation": "กฎหมายไม่มีหลักลดโทษอัตโนมัติ การเยียวยาอาจเป็นเพียงข้อพิจารณาประกอบดุลพินิจ"}], "key_takeaway": "การควบคุมจรรยาบรรณเป็นประโยชน์สาธารณะ ผู้กล่าวหาถอนเรื่องแล้วสภาก็ยังพิจารณาต่อได้"}'::jsonb, 'medium', 'law-day1 • การกล่าวหา: การถอนเรื่อง'),
('119a2508478c8e126fecc07f83293c31', 68, 'เภสัชกรวิชัยถูกคณะกรรมการสภาเภสัชกรรมลงโทษพักใช้ใบอนุญาตประกอบวิชาชีพ ระหว่างนั้นเขาไปทำงานที่ร้านยาของญาติในอีกจังหวัดหนึ่ง โดยไม่ได้ลงชื่อเป็นผู้มีหน้าที่ปฏิบัติการ แต่ทำหน้าที่ซักประวัติ แนะนำและจ่ายยาให้ผู้มารับบริการ ข้อใดถูกต้อง', '[{"label": "A", "text": "ทำได้ เพราะผลของการพักใช้ใบอนุญาตจำกัดเฉพาะจังหวัดที่เกิดเหตุ"}, {"label": "B", "text": "ทำได้ หากเป็นการทำงานในโรงพยาบาลของรัฐแทนร้านยาเอกชน"}, {"label": "C", "text": "ทำได้ เพราะไม่ได้ลงชื่อเป็นผู้มีหน้าที่ปฏิบัติการของร้าน"}, {"label": "D", "text": "ทำได้ เพราะการพักใช้มีผลเฉพาะสิทธิในฐานะสมาชิก เช่น สิทธิเลือกตั้ง แต่ไม่กระทบใบอนุญาต"}, {"label": "E", "text": "ทำไม่ได้ เพราะระหว่างถูกพักใช้ถือว่าเป็นผู้ไม่ได้รับใบอนุญาตประกอบวิชาชีพ"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ทำไม่ได้ เพราะระหว่างถูกพักใช้ถือว่าเป็นผู้ไม่ได้รับใบอนุญาตประกอบวิชาชีพ — ระหว่างถูกพักใช้ใบอนุญาต ผู้นั้นถือเป็นผู้ไม่ได้รับใบอนุญาต การประกอบวิชาชีพในระหว่างนั้นจึงผิดกฎหมาย", "reason": "กฎหมายวิชาชีพกำหนดว่าผู้ถูกพักใช้ใบอนุญาตให้ถือว่าเป็นผู้ไม่ได้รับใบอนุญาตเป็นผู้ประกอบวิชาชีพเภสัชกรรมตลอดระยะเวลาที่ถูกพักใช้ การทำกิจกรรมที่เป็นวิชาชีพเภสัชกรรม เช่น ซักประวัติ ให้คำแนะนำด้านยา และจ่ายยา จึงเป็นการประกอบวิชาชีพโดยไม่มีใบอนุญาต ซึ่งมีโทษทางอาญา\n\nผลของการพักใช้ไม่จำกัดพื้นที่หรือประเภทสถานบริการ และไม่ขึ้นกับว่าตนลงชื่อเป็นผู้มีหน้าที่ปฏิบัติการหรือไม่ ผู้รับอนุญาตที่ยอมให้บุคคลดังกล่าวปฏิบัติงานก็อาจมีความรับผิดด้วย", "choices": [{"label": "A", "text": "ทำได้ เพราะผลของการพักใช้ใบอนุญาตจำกัดเฉพาะจังหวัดที่เกิดเหตุ", "is_correct": false, "explanation": "ใบอนุญาตประกอบวิชาชีพใช้ได้ทั่วประเทศ การพักใช้จึงมีผลทั่วประเทศเช่นกัน"}, {"label": "B", "text": "ทำได้ หากเป็นการทำงานในโรงพยาบาลของรัฐแทนร้านยาเอกชน", "is_correct": false, "explanation": "การพักใช้มีผลห้ามประกอบวิชาชีพในทุกสถานที่ ไม่ว่ารัฐหรือเอกชน"}, {"label": "C", "text": "ทำได้ เพราะไม่ได้ลงชื่อเป็นผู้มีหน้าที่ปฏิบัติการของร้าน", "is_correct": false, "explanation": "การซักประวัติ แนะนำและจ่ายยาเป็นการประกอบวิชาชีพแล้ว ไม่ขึ้นกับการลงชื่อเป็นผู้มีหน้าที่ปฏิบัติการ"}, {"label": "D", "text": "ทำได้ เพราะการพักใช้มีผลเฉพาะสิทธิในฐานะสมาชิก เช่น สิทธิเลือกตั้ง แต่ไม่กระทบใบอนุญาต", "is_correct": false, "explanation": "การพักใช้ใบอนุญาตมีผลต่อใบอนุญาตโดยตรง คือห้ามประกอบวิชาชีพในระหว่างนั้น"}, {"label": "E", "text": "ทำไม่ได้ เพราะระหว่างถูกพักใช้ถือว่าเป็นผู้ไม่ได้รับใบอนุญาตประกอบวิชาชีพ", "is_correct": true, "explanation": "ถูกต้อง: ระหว่างถูกพักใช้ใบอนุญาต ผู้นั้นถือเป็นผู้ไม่ได้รับใบอนุญาต การประกอบวิชาชีพในระหว่างนั้นจึงผิดกฎหมาย"}], "key_takeaway": "พักใช้ใบอนุญาต = ห้ามประกอบวิชาชีพทุกรูปแบบทุกที่ตลอดระยะเวลาที่ถูกพัก"}'::jsonb, 'medium', 'law-day1 • โทษทางจรรยาบรรณ: ผลของการพักใช้ใบอนุญาต'),
('08e01a8a192f4e7897b0a496ab5522cb', 69, 'เภสัชกรสุนทรรับเงินรายเดือนจากเจ้าของร้านขายยาแผนปัจจุบันเพื่อให้ร้านใช้ชื่อและใบอนุญาตของตนเป็นผู้มีหน้าที่ปฏิบัติการ แต่เขาทำงานประจำที่อื่นและแทบไม่เคยมาที่ร้าน โดยบอกพนักงานว่าหากมีปัญหาให้โทรศัพท์ปรึกษา ต่อมาพนักงานซึ่งไม่ใช่เภสัชกรขายยาอันตรายให้ลูกค้ารายหนึ่งจนเกิดอาการไม่พึงประสงค์รุนแรง ลูกค้าจึงร้องเรียน ข้อใดวิเคราะห์ได้ถูกต้องที่สุด', '[{"label": "A", "text": "เภสัชกรไม่มีความผิดใด เพราะข้อตกลงกับเจ้าของร้านเป็นสัญญาจ้างทางแพ่งที่ทั้งสองฝ่ายยินยอม"}, {"label": "B", "text": "ผู้ที่ต้องรับผิดมีเพียงเจ้าของร้านในฐานะผู้รับอนุญาตขายยา เพราะเป็นผู้ควบคุมดูแลพนักงานโดยตรง"}, {"label": "C", "text": "เภสัชกรผิดจรรยาบรรณเท่านั้น โดยไม่มีความรับผิดตามกฎหมายว่าด้วยยา"}, {"label": "D", "text": "เภสัชกรอาจถูกดำเนินการทั้งทางจรรยาบรรณและตามกฎหมายว่าด้วยยา และการที่พนักงานขายยาอันตรายเองไม่ชอบด้วยกฎหมาย"}, {"label": "E", "text": "เภสัชกรไม่ผิด หากพิสูจน์ได้ว่าพนักงานโทรศัพท์ปรึกษาตนทุกครั้งก่อนขายยาอันตราย"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. เภสัชกรอาจถูกดำเนินการทั้งทางจรรยาบรรณและตามกฎหมายว่าด้วยยา และการที่พนักงานขายยาอันตรายเองไม่ชอบด้วยกฎหมาย — การ \"แขวนป้าย\" มีผลทั้งทางจรรยาบรรณและทางกฎหมายว่าด้วยยา และการขายยาอันตรายโดยไม่มีเภสัชกรควบคุมไม่ชอบด้วยกฎหมาย", "reason": "ประเด็นที่ 1 จรรยาบรรณ: ข้อบังคับว่าด้วยจรรยาบรรณแห่งวิชาชีพเภสัชกรรมห้ามผู้ประกอบวิชาชีพยินยอมให้ผู้อื่นใช้ชื่อหรือใบอนุญาตของตนในสถานประกอบการที่ตนไม่ได้ปฏิบัติงานจริง และกำหนดให้ประกอบวิชาชีพโดยคำนึงถึงความปลอดภัยของผู้รับบริการ การรับเงินเพื่อ \"แขวนป้าย\" จึงเป็นการประพฤติผิดจรรยาบรรณที่ร้ายแรง\n\nประเด็นที่ 2 กฎหมายว่าด้วยยา: ร้านขายยาแผนปัจจุบันต้องมีเภสัชกรผู้มีหน้าที่ปฏิบัติการอยู่ประจำตลอดเวลาเปิดทำการ และควบคุมการขายยาอันตรายด้วยตนเอง การไม่อยู่ประจำจึงเป็นการไม่ปฏิบัติหน้าที่ตามกฎหมาย ส่วนผู้รับอนุญาตก็มีความรับผิดของตนแยกต่างหาก\n\nประเด็นที่ 3: พนักงานที่ไม่ใช่เภสัชกรส่งมอบยาอันตรายโดยไม่มีเภสัชกรควบคุมเป็นการไม่ชอบด้วยกฎหมาย และลูกค้าผู้เสียหายยังอาจเรียกร้องค่าเสียหายทางแพ่งได้อีกทางหนึ่ง", "choices": [{"label": "A", "text": "เภสัชกรไม่มีความผิดใด เพราะข้อตกลงกับเจ้าของร้านเป็นสัญญาจ้างทางแพ่งที่ทั้งสองฝ่ายยินยอม", "is_correct": false, "explanation": "ความยินยอมระหว่างคู่สัญญาไม่อาจยกเว้นหน้าที่ตามกฎหมายและจรรยาบรรณที่มีไว้คุ้มครองประชาชน"}, {"label": "B", "text": "ผู้ที่ต้องรับผิดมีเพียงเจ้าของร้านในฐานะผู้รับอนุญาตขายยา เพราะเป็นผู้ควบคุมดูแลพนักงานโดยตรง", "is_correct": false, "explanation": "เภสัชกรผู้มีหน้าที่ปฏิบัติการมีหน้าที่ของตนเองตามกฎหมายว่าด้วยยาและตามจรรยาบรรณ จึงต้องรับผิดด้วย"}, {"label": "C", "text": "เภสัชกรผิดจรรยาบรรณเท่านั้น โดยไม่มีความรับผิดตามกฎหมายว่าด้วยยา", "is_correct": false, "explanation": "ผู้มีหน้าที่ปฏิบัติการที่ไม่อยู่ประจำและไม่ควบคุมการขายยาอันตรายมีความรับผิดตามกฎหมายว่าด้วยยาได้ด้วย"}, {"label": "D", "text": "เภสัชกรอาจถูกดำเนินการทั้งทางจรรยาบรรณและตามกฎหมายว่าด้วยยา และการที่พนักงานขายยาอันตรายเองไม่ชอบด้วยกฎหมาย", "is_correct": true, "explanation": "ถูกต้อง: การ \"แขวนป้าย\" มีผลทั้งทางจรรยาบรรณและทางกฎหมายว่าด้วยยา และการขายยาอันตรายโดยไม่มีเภสัชกรควบคุมไม่ชอบด้วยกฎหมาย"}, {"label": "E", "text": "เภสัชกรไม่ผิด หากพิสูจน์ได้ว่าพนักงานโทรศัพท์ปรึกษาตนทุกครั้งก่อนขายยาอันตราย", "is_correct": false, "explanation": "การปรึกษาทางโทรศัพท์โดยพนักงานเป็นผู้ส่งมอบยาเองไม่ใช่การที่เภสัชกรอยู่ประจำและควบคุมการขายยาอันตรายตามที่กฎหมายกำหนด"}], "key_takeaway": "การให้เช่าชื่อ/แขวนป้ายผิดทั้งจรรยาบรรณและกฎหมายว่าด้วยยา ความรับผิดไม่ตกอยู่กับเจ้าของร้านฝ่ายเดียว"}'::jsonb, 'hard', 'law-day1 • จรรยาบรรณ: การให้ใช้ชื่อโดยไม่ปฏิบัติงานจริง (แขวนป้าย)'),
('389778064b46d5847eb3038db0cbcc33', 70, 'เภสัชกรนภาเปิดร้านยาใหม่และต้องการประชาสัมพันธ์ร้านผ่านป้ายหน้าร้านและเพจเฟซบุ๊ก ข้อความใดเหมาะสมและสอดคล้องกับข้อบังคับว่าด้วยจรรยาบรรณแห่งวิชาชีพเภสัชกรรมมากที่สุด', '[{"label": "A", "text": "\"เภสัชกรเก่งที่สุดในจังหวัด รับประกันอาการหายภายใน 3 วัน มิฉะนั้นคืนเงิน\""}, {"label": "B", "text": "แสดงชื่อ คุณวุฒิ เลขที่ใบอนุญาต และเวลาปฏิบัติการ อย่างสุภาพตามจริง"}, {"label": "C", "text": "โพสต์ภาพลูกค้าพร้อมข้อความรีวิวว่าหายจากโรคผิวหนังเรื้อรังหลังรับยาจากร้าน"}, {"label": "D", "text": "ระบุว่าตนเป็น \"ผู้เชี่ยวชาญด้านเภสัชบำบัดโรคมะเร็ง\" ทั้งที่ไม่มีวุฒิบัตรหรือหนังสืออนุมัติใดรับรอง"}, {"label": "E", "text": "จ้างผู้มีชื่อเสียงทำคลิปร่วมกับตน แนะนำว่ายาที่ร้านรักษาโรคเบาหวานให้หายขาดได้"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. แสดงชื่อ คุณวุฒิ เลขที่ใบอนุญาต และเวลาปฏิบัติการ อย่างสุภาพตามจริง — การแจ้งข้อมูลข้อเท็จจริงของผู้ประกอบวิชาชีพ เช่น ชื่อ คุณวุฒิ และเวลาปฏิบัติการ ในลักษณะสุภาพ เป็นสิ่งที่ทำได้", "reason": "ข้อบังคับสภาเภสัชกรรมว่าด้วยจรรยาบรรณแห่งวิชาชีพเภสัชกรรมห้ามผู้ประกอบวิชาชีพโฆษณา ใช้ จ้าง หรือยินยอมให้ผู้อื่นโฆษณาความรู้ความสามารถของตนในลักษณะโอ้อวดหรือเกินความจริง แต่อนุญาตให้แสดงข้อมูลที่จำเป็นต่อประชาชน เช่น ชื่อ คุณวุฒิ หรือความรู้ความชำนาญเฉพาะที่ได้รับการรับรอง สถานที่ และเวลาทำการ ในลักษณะที่สุภาพ\n\nการรับประกันผล การใช้รีวิวผลการรักษา การอ้างความเชี่ยวชาญที่ไม่มีการรับรอง และการกล่าวอ้างว่ารักษาโรคเรื้อรังให้หายขาด ล้วนเป็นการโฆษณาที่ไม่เหมาะสม และบางกรณียังขัดต่อกฎหมายว่าด้วยการโฆษณายาหรือผลิตภัณฑ์สุขภาพด้วย", "choices": [{"label": "A", "text": "\"เภสัชกรเก่งที่สุดในจังหวัด รับประกันอาการหายภายใน 3 วัน มิฉะนั้นคืนเงิน\"", "is_correct": false, "explanation": "เป็นการโฆษณาโอ้อวดความรู้ความสามารถและรับรองผลการรักษา ซึ่งขัดต่อจรรยาบรรณ"}, {"label": "B", "text": "แสดงชื่อ คุณวุฒิ เลขที่ใบอนุญาต และเวลาปฏิบัติการ อย่างสุภาพตามจริง", "is_correct": true, "explanation": "ถูกต้อง: การแจ้งข้อมูลข้อเท็จจริงของผู้ประกอบวิชาชีพ เช่น ชื่อ คุณวุฒิ และเวลาปฏิบัติการ ในลักษณะสุภาพ เป็นสิ่งที่ทำได้"}, {"label": "C", "text": "โพสต์ภาพลูกค้าพร้อมข้อความรีวิวว่าหายจากโรคผิวหนังเรื้อรังหลังรับยาจากร้าน", "is_correct": false, "explanation": "เป็นการโฆษณาชวนเชื่อโดยอาศัยผลการรักษา และอาจละเมิดความลับผู้ป่วย"}, {"label": "D", "text": "ระบุว่าตนเป็น \"ผู้เชี่ยวชาญด้านเภสัชบำบัดโรคมะเร็ง\" ทั้งที่ไม่มีวุฒิบัตรหรือหนังสืออนุมัติใดรับรอง", "is_correct": false, "explanation": "การอ้างความเชี่ยวชาญที่ไม่มีหลักฐานรับรองเป็นการแสดงข้อความเท็จและโอ้อวด"}, {"label": "E", "text": "จ้างผู้มีชื่อเสียงทำคลิปร่วมกับตน แนะนำว่ายาที่ร้านรักษาโรคเบาหวานให้หายขาดได้", "is_correct": false, "explanation": "เป็นการโฆษณาเกินจริงเรื่องสรรพคุณและใช้สถานะวิชาชีพโอ้อวด ขัดทั้งจรรยาบรรณและกฎหมายว่าด้วยการโฆษณา"}], "key_takeaway": "โฆษณาตนเองได้เฉพาะข้อมูลข้อเท็จจริงที่สุภาพ ห้ามโอ้อวด รับประกันผล หรืออ้างความเชี่ยวชาญที่ไม่ได้รับรอง"}'::jsonb, 'medium', 'law-day1 • จรรยาบรรณ: การโฆษณาตนเอง'),
('f3a718157e8a3504d380da7a02a1056b', 71, 'เจ้าหน้าที่ฝ่ายบุคคลของบริษัทแห่งหนึ่งโทรศัพท์มาที่ร้านยา แจ้งว่าบริษัทให้สวัสดิการค่ายาแก่พนักงาน และขอทราบว่าพนักงานชื่อ นาย ก. มาซื้อยาอะไรบ้างในเดือนที่ผ่านมา เพื่อประเมินว่าป่วยเป็นโรคเรื้อรังหรือไม่ ร้านไม่มีหลักฐานว่านาย ก. ยินยอม เภสัชกรควรปฏิบัติอย่างไร', '[{"label": "A", "text": "เปิดเผยได้ เพราะบริษัทเป็นผู้จ่ายค่ายาตามสวัสดิการจึงมีสิทธิทราบข้อมูลการใช้ยา"}, {"label": "B", "text": "เปิดเผยได้เฉพาะชื่อยาที่ซื้อ แต่ต้องไม่ระบุชื่อโรคหรือการวินิจฉัย"}, {"label": "C", "text": "เปิดเผยได้ หากฝ่ายบุคคลส่งหนังสือขอข้อมูลอย่างเป็นทางการของบริษัท"}, {"label": "D", "text": "เปิดเผยได้ หากฝ่ายบุคคลลงนามรับรองว่าจะเก็บรักษาข้อมูลเป็นความลับ"}, {"label": "E", "text": "ไม่เปิดเผย เว้นแต่นาย ก. ประสงค์โดยตรงหรือมีกฎหมายบัญญัติให้ต้องเปิดเผย"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ไม่เปิดเผย เว้นแต่นาย ก. ประสงค์โดยตรงหรือมีกฎหมายบัญญัติให้ต้องเปิดเผย — ข้อมูลการใช้ยาเป็นข้อมูลสุขภาพที่เป็นความลับ จะเปิดเผยแก่นายจ้างได้เมื่อเจ้าของข้อมูลประสงค์หรือมีกฎหมายบังคับเท่านั้น", "reason": "พ.ร.บ.สุขภาพแห่งชาติ พ.ศ. 2550 มาตรา 7 กำหนดว่าข้อมูลด้านสุขภาพของบุคคลเป็นความลับส่วนบุคคล ผู้ใดจะนำไปเปิดเผยในประการที่น่าจะทำให้บุคคลนั้นเสียหายไม่ได้ เว้นแต่เป็นไปตามความประสงค์ของบุคคลนั้นโดยตรง หรือมีกฎหมายเฉพาะบัญญัติให้ต้องเปิดเผย ข้อมูลว่าใครซื้อยาอะไรย่อมบ่งบอกภาวะสุขภาพและอาจกระทบการจ้างงานได้\n\nนอกจากนี้ข้อบังคับว่าด้วยจรรยาบรรณกำหนดให้เภสัชกรรักษาความลับของผู้ป่วย ประมวลกฎหมายอาญามีความผิดฐานเปิดเผยความลับที่ล่วงรู้เพราะประกอบอาชีพเภสัชกร และ พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคลถือว่าข้อมูลสุขภาพเป็นข้อมูลอ่อนไหว เภสัชกรจึงควรปฏิเสธอย่างสุภาพและแนะนำให้บริษัทติดต่อขอความยินยอมจากพนักงานเอง", "choices": [{"label": "A", "text": "เปิดเผยได้ เพราะบริษัทเป็นผู้จ่ายค่ายาตามสวัสดิการจึงมีสิทธิทราบข้อมูลการใช้ยา", "is_correct": false, "explanation": "การเป็นผู้จ่ายเงินไม่ได้ทำให้มีสิทธิในข้อมูลสุขภาพของพนักงาน"}, {"label": "B", "text": "เปิดเผยได้เฉพาะชื่อยาที่ซื้อ แต่ต้องไม่ระบุชื่อโรคหรือการวินิจฉัย", "is_correct": false, "explanation": "ชื่อยาก็บ่งบอกภาวะสุขภาพได้ จึงเป็นข้อมูลสุขภาพที่ต้องรักษาความลับเช่นกัน"}, {"label": "C", "text": "เปิดเผยได้ หากฝ่ายบุคคลส่งหนังสือขอข้อมูลอย่างเป็นทางการของบริษัท", "is_correct": false, "explanation": "หนังสือของบริษัทไม่ใช่ความยินยอมของเจ้าของข้อมูลและไม่ใช่กฎหมายที่บังคับให้เปิดเผย"}, {"label": "D", "text": "เปิดเผยได้ หากฝ่ายบุคคลลงนามรับรองว่าจะเก็บรักษาข้อมูลเป็นความลับ", "is_correct": false, "explanation": "การรับรองว่าจะเก็บเป็นความลับไม่ได้ทำให้การเปิดเผยโดยไม่มีฐานทางกฎหมายชอบด้วยกฎหมาย"}, {"label": "E", "text": "ไม่เปิดเผย เว้นแต่นาย ก. ประสงค์โดยตรงหรือมีกฎหมายบัญญัติให้ต้องเปิดเผย", "is_correct": true, "explanation": "ถูกต้อง: ข้อมูลการใช้ยาเป็นข้อมูลสุขภาพที่เป็นความลับ จะเปิดเผยแก่นายจ้างได้เมื่อเจ้าของข้อมูลประสงค์หรือมีกฎหมายบังคับเท่านั้น"}], "key_takeaway": "ผู้จ่ายเงินหรือนายจ้างไม่มีสิทธิในข้อมูลการใช้ยาของผู้ป่วย หากไม่มีความยินยอมของผู้ป่วยหรือกฎหมายบังคับ"}'::jsonb, 'medium', 'law-day1 • การรักษาความลับผู้ป่วย'),
('93c29c8cc74ce213b4bd34b79bc7bedd', 72, 'ตามพระราชบัญญัติสุขภาพแห่งชาติ พ.ศ. 2550 มาตรา 7 ข้อมูลด้านสุขภาพของบุคคลอาจถูกเปิดเผยในประการที่น่าจะทำให้บุคคลนั้นเสียหายได้ในกรณีใด', '[{"label": "A", "text": "เมื่อผู้บริหารสถานพยาบาลอนุมัติให้เปิดเผยเป็นลายลักษณ์อักษร"}, {"label": "B", "text": "เมื่อญาติสายตรงของผู้ป่วย เช่น บิดามารดาหรือบุตร ร้องขอเป็นลายลักษณ์อักษร"}, {"label": "C", "text": "เมื่อเป็นไปตามความประสงค์ของบุคคลนั้นโดยตรง หรือมีกฎหมายเฉพาะบัญญัติให้ต้องเปิดเผย"}, {"label": "D", "text": "เมื่อผู้ขอใช้สิทธิตามกฎหมายว่าด้วยข้อมูลข่าวสารของราชการขอข้อมูลของผู้อื่น"}, {"label": "E", "text": "เมื่อผู้ประกอบวิชาชีพเห็นว่าการเปิดเผยเป็นประโยชน์ต่อสังคมโดยรวม"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. เมื่อเป็นไปตามความประสงค์ของบุคคลนั้นโดยตรง หรือมีกฎหมายเฉพาะบัญญัติให้ต้องเปิดเผย — มาตรา 7 ยกเว้นให้เปิดเผยได้เฉพาะตามความประสงค์ของเจ้าของข้อมูลโดยตรง หรือมีกฎหมายเฉพาะบัญญัติให้ต้องเปิดเผย", "reason": "มาตรา 7 แห่ง พ.ร.บ.สุขภาพแห่งชาติ พ.ศ. 2550 วางหลักว่าข้อมูลด้านสุขภาพของบุคคลเป็นความลับส่วนบุคคล ห้ามเปิดเผยในประการที่น่าจะทำให้บุคคลนั้นเสียหาย เว้นแต่ (1) เป็นไปตามความประสงค์ของบุคคลนั้นโดยตรง หรือ (2) มีกฎหมายเฉพาะบัญญัติให้ต้องเปิดเผย\n\nและไม่ว่ากรณีใด ๆ ผู้ใดจะอาศัยอำนาจหรือสิทธิตามกฎหมายว่าด้วยข้อมูลข่าวสารของราชการหรือกฎหมายอื่นเพื่อขอเอกสารเกี่ยวกับข้อมูลด้านสุขภาพของบุคคลที่ไม่ใช่ของตนไม่ได้", "choices": [{"label": "A", "text": "เมื่อผู้บริหารสถานพยาบาลอนุมัติให้เปิดเผยเป็นลายลักษณ์อักษร", "is_correct": false, "explanation": "การอนุมัติของผู้บริหารไม่ใช่ข้อยกเว้นตามมาตรา 7"}, {"label": "B", "text": "เมื่อญาติสายตรงของผู้ป่วย เช่น บิดามารดาหรือบุตร ร้องขอเป็นลายลักษณ์อักษร", "is_correct": false, "explanation": "ความเป็นญาติไม่ใช่ข้อยกเว้นตามมาตรา 7 หากผู้ป่วยไม่ประสงค์หรือไม่มีกฎหมายบังคับ"}, {"label": "C", "text": "เมื่อเป็นไปตามความประสงค์ของบุคคลนั้นโดยตรง หรือมีกฎหมายเฉพาะบัญญัติให้ต้องเปิดเผย", "is_correct": true, "explanation": "ถูกต้อง: มาตรา 7 ยกเว้นให้เปิดเผยได้เฉพาะตามความประสงค์ของเจ้าของข้อมูลโดยตรง หรือมีกฎหมายเฉพาะบัญญัติให้ต้องเปิดเผย"}, {"label": "D", "text": "เมื่อผู้ขอใช้สิทธิตามกฎหมายว่าด้วยข้อมูลข่าวสารของราชการขอข้อมูลของผู้อื่น", "is_correct": false, "explanation": "มาตรา 7 ห้ามไว้ชัดว่าไม่ว่ากรณีใด จะอาศัยกฎหมายข้อมูลข่าวสารของราชการหรือกฎหมายอื่นขอข้อมูลสุขภาพของผู้อื่นไม่ได้"}, {"label": "E", "text": "เมื่อผู้ประกอบวิชาชีพเห็นว่าการเปิดเผยเป็นประโยชน์ต่อสังคมโดยรวม", "is_correct": false, "explanation": "ดุลพินิจส่วนตัวของผู้ประกอบวิชาชีพไม่ใช่ข้อยกเว้นตามมาตรา 7"}], "key_takeaway": "ม.7: เปิดเผยข้อมูลสุขภาพได้เมื่อเจ้าตัวประสงค์โดยตรง หรือมีกฎหมายเฉพาะบังคับเท่านั้น"}'::jsonb, 'easy', 'law-day1 • พ.ร.บ.สุขภาพแห่งชาติ มาตรา 7'),
('aa8ffc07e038fea3330dceddeac75448', 73, 'นายประเสริฐ ผู้ป่วยมะเร็งระยะสุดท้าย เคยทำหนังสือแสดงเจตนาตามมาตรา 12 แห่ง พ.ร.บ.สุขภาพแห่งชาติ ไว้ว่าไม่ประสงค์จะรับการใส่ท่อช่วยหายใจและการกู้ชีพในวาระสุดท้าย ขณะนี้ผู้ป่วยหมดสติและอาการทรุดลง บุตรชายขอให้ทีมสุขภาพ "ทำทุกอย่างเพื่อยื้อชีวิต" ข้อใดเป็นแนวทางที่ถูกต้องที่สุด', '[{"label": "A", "text": "เคารพเจตนาตามหนังสือ งดหัตถการที่เพียงยืดการตาย แต่ยังให้การดูแลแบบประคับประคอง"}, {"label": "B", "text": "ต้องทำตามความประสงค์ของบุตรชาย เพราะเมื่อผู้ป่วยหมดสติ สิทธิในการตัดสินใจตกเป็นของญาติทั้งหมด"}, {"label": "C", "text": "หนังสือแสดงเจตนาจะมีผลบังคับต่อเมื่อศาลมีคำสั่งรับรองความถูกต้องแล้วเท่านั้น"}, {"label": "D", "text": "หนังสือดังกล่าวเปิดทางให้ทีมสุขภาพให้ยาเพื่อเร่งการเสียชีวิตของผู้ป่วยได้"}, {"label": "E", "text": "ทีมสุขภาพต้องหยุดการรักษาทุกชนิด รวมทั้งยาบรรเทาปวดและการดูแลความสุขสบาย"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. เคารพเจตนาตามหนังสือ งดหัตถการที่เพียงยืดการตาย แต่ยังให้การดูแลแบบประคับประคอง — มาตรา 12 ให้สิทธิปฏิเสธบริการที่เป็นไปเพียงเพื่อยืดการตาย โดยผู้ป่วยยังได้รับการดูแลแบบประคับประคอง และผู้ปฏิบัติตามได้รับความคุ้มครอง", "reason": "มาตรา 12 แห่ง พ.ร.บ.สุขภาพแห่งชาติ พ.ศ. 2550 ให้บุคคลมีสิทธิทำหนังสือแสดงเจตนาไม่ประสงค์จะรับบริการสาธารณสุขที่เป็นไปเพียงเพื่อยืดการตายในวาระสุดท้ายของชีวิตตน หรือเพื่อยุติการทรมานจากการเจ็บป่วย และเมื่อผู้ประกอบวิชาชีพด้านสาธารณสุขได้ปฏิบัติตามเจตนาดังกล่าวแล้ว มิให้ถือว่าการกระทำนั้นเป็นความผิดและให้พ้นจากความรับผิดทั้งปวง\n\nหลักนี้สะท้อน autonomy ของผู้ป่วย แต่ไม่ใช่การุณยฆาต ทีมสุขภาพยังต้องดูแลแบบประคับประคอง (palliative care) และควรสื่อสารกับญาติให้เข้าใจเจตนาของผู้ป่วย", "choices": [{"label": "A", "text": "เคารพเจตนาตามหนังสือ งดหัตถการที่เพียงยืดการตาย แต่ยังให้การดูแลแบบประคับประคอง", "is_correct": true, "explanation": "ถูกต้อง: มาตรา 12 ให้สิทธิปฏิเสธบริการที่เป็นไปเพียงเพื่อยืดการตาย โดยผู้ป่วยยังได้รับการดูแลแบบประคับประคอง และผู้ปฏิบัติตามได้รับความคุ้มครอง"}, {"label": "B", "text": "ต้องทำตามความประสงค์ของบุตรชาย เพราะเมื่อผู้ป่วยหมดสติ สิทธิในการตัดสินใจตกเป็นของญาติทั้งหมด", "is_correct": false, "explanation": "หนังสือแสดงเจตนาที่ผู้ป่วยทำไว้ล่วงหน้ามีไว้สำหรับสถานการณ์ที่ผู้ป่วยตัดสินใจเองไม่ได้ ญาติไม่อาจลบล้างเจตนานั้น"}, {"label": "C", "text": "หนังสือแสดงเจตนาจะมีผลบังคับต่อเมื่อศาลมีคำสั่งรับรองความถูกต้องแล้วเท่านั้น", "is_correct": false, "explanation": "กฎหมายไม่ได้กำหนดให้ต้องมีคำสั่งศาลรับรองหนังสือแสดงเจตนา"}, {"label": "D", "text": "หนังสือดังกล่าวเปิดทางให้ทีมสุขภาพให้ยาเพื่อเร่งการเสียชีวิตของผู้ป่วยได้", "is_correct": false, "explanation": "มาตรา 12 เป็นการปฏิเสธบริการที่ยืดการตาย ไม่ใช่การอนุญาตให้เร่งการตายหรือการุณยฆาต"}, {"label": "E", "text": "ทีมสุขภาพต้องหยุดการรักษาทุกชนิด รวมทั้งยาบรรเทาปวดและการดูแลความสุขสบาย", "is_correct": false, "explanation": "ผู้ป่วยยังต้องได้รับการดูแลแบบประคับประคองเพื่อบรรเทาความทุกข์ทรมาน"}], "key_takeaway": "หนังสือแสดงเจตนาตาม ม.12 = ปฏิเสธการยื้อการตาย ไม่ใช่การเร่งการตาย และไม่ใช่การหยุดการดูแลบรรเทาอาการ"}'::jsonb, 'medium', 'law-day1 • พ.ร.บ.สุขภาพแห่งชาติ มาตรา 12'),
('e8fe799bc14aba7d1da3a06176ad357a', 74, 'ร้านยาเครือข่ายแห่งหนึ่งมีระบบสมาชิกที่บันทึกโรคประจำตัว ประวัติแพ้ยา และรายการยาที่ลูกค้าซื้อ เพื่อใช้ตรวจสอบความปลอดภัยในการจ่ายยา ต่อมาบริษัทยาเสนอค่าตอบแทนเพื่อขอรายชื่อและเบอร์โทรศัพท์ของลูกค้าที่ซื้อยาเบาหวาน เพื่อส่ง SMS โฆษณาผลิตภัณฑ์ใหม่ เภสัชกรผู้จัดการร้านควรพิจารณาอย่างไรจึงถูกต้องที่สุด', '[{"label": "A", "text": "ทำได้ เพราะเป็นประโยชน์อันชอบธรรมทางธุรกิจของร้านและไม่ได้ขายข้อมูลการรักษาโดยตรง"}, {"label": "B", "text": "ทำได้ หากร้านติดประกาศนโยบายความเป็นส่วนตัวไว้หน้าร้านและบนเว็บไซต์ของร้านแล้ว"}, {"label": "C", "text": "ทำได้ เพราะรายชื่อและเบอร์โทรศัพท์เป็นข้อมูลส่วนบุคคลทั่วไป ไม่ใช่ข้อมูลอ่อนไหว"}, {"label": "D", "text": "ไม่ควรทำ เพราะเป็นข้อมูลอ่อนไหวที่ใช้นอกวัตถุประสงค์เดิม ต้องได้รับความยินยอมโดยชัดแจ้งก่อน"}, {"label": "E", "text": "ทำได้ หากร้านไม่รับค่าตอบแทนใด ๆ จากบริษัทยาเป็นการแลกเปลี่ยน"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ไม่ควรทำ เพราะเป็นข้อมูลอ่อนไหวที่ใช้นอกวัตถุประสงค์เดิม ต้องได้รับความยินยอมโดยชัดแจ้งก่อน — การส่งข้อมูลผู้ใช้ยาให้บุคคลภายนอกเพื่อการตลาดเป็นการใช้ข้อมูลอ่อนไหวนอกวัตถุประสงค์เดิม ต้องได้รับความยินยอมโดยชัดแจ้ง และยังขัดต่อจรรยาบรรณ", "reason": "พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 จัดข้อมูลสุขภาพเป็นข้อมูลส่วนบุคคลที่มีความอ่อนไหว การเก็บรวบรวม ใช้ หรือเปิดเผยต้องได้รับความยินยอมโดยชัดแจ้ง เว้นแต่เข้าข้อยกเว้นเฉพาะที่กฎหมายกำหนด (เช่น เพื่อป้องกันอันตรายต่อชีวิต หรือเพื่อการวินิจฉัยและการให้บริการด้านสุขภาพภายใต้หน้าที่รักษาความลับของผู้ประกอบวิชาชีพ) นอกจากนี้ผู้ควบคุมข้อมูลต้องใช้ข้อมูลตามวัตถุประสงค์ที่แจ้งไว้ การนำไปใช้เพื่อวัตถุประสงค์ใหม่ เช่น การตลาดของบุคคลที่สาม ต้องแจ้งและได้รับความยินยอมใหม่\n\nฐาน \"ประโยชน์อันชอบธรรม\" ใช้ไม่ได้กับข้อมูลอ่อนไหว และประกาศหน้าร้านไม่ใช่ความยินยอมโดยชัดแจ้ง ในด้านจรรยาบรรณ การรับผลประโยชน์จากบริษัทยาโดยแลกกับข้อมูลผู้ป่วยขัดต่อหน้าที่รักษาความลับและการไม่รับประโยชน์ที่ขัดกับวิชาชีพ อีกทั้งขัดต่อ พ.ร.บ.สุขภาพแห่งชาติ มาตรา 7 ด้วย", "choices": [{"label": "A", "text": "ทำได้ เพราะเป็นประโยชน์อันชอบธรรมทางธุรกิจของร้านและไม่ได้ขายข้อมูลการรักษาโดยตรง", "is_correct": false, "explanation": "ประโยชน์อันชอบธรรมไม่ใช่ฐานที่ใช้ประมวลผลข้อมูลอ่อนไหว และการระบุว่าใครซื้อยาเบาหวานคือการเปิดเผยข้อมูลสุขภาพ"}, {"label": "B", "text": "ทำได้ หากร้านติดประกาศนโยบายความเป็นส่วนตัวไว้หน้าร้านและบนเว็บไซต์ของร้านแล้ว", "is_correct": false, "explanation": "การติดประกาศไม่ใช่ความยินยอมโดยชัดแจ้งของเจ้าของข้อมูลแต่ละราย"}, {"label": "C", "text": "ทำได้ เพราะรายชื่อและเบอร์โทรศัพท์เป็นข้อมูลส่วนบุคคลทั่วไป ไม่ใช่ข้อมูลอ่อนไหว", "is_correct": false, "explanation": "เมื่อรายชื่อถูกคัดแยกว่าเป็นผู้ใช้ยาเบาหวาน ข้อมูลนั้นบ่งบอกภาวะสุขภาพจึงเป็นข้อมูลอ่อนไหว"}, {"label": "D", "text": "ไม่ควรทำ เพราะเป็นข้อมูลอ่อนไหวที่ใช้นอกวัตถุประสงค์เดิม ต้องได้รับความยินยอมโดยชัดแจ้งก่อน", "is_correct": true, "explanation": "ถูกต้อง: การส่งข้อมูลผู้ใช้ยาให้บุคคลภายนอกเพื่อการตลาดเป็นการใช้ข้อมูลอ่อนไหวนอกวัตถุประสงค์เดิม ต้องได้รับความยินยอมโดยชัดแจ้ง และยังขัดต่อจรรยาบรรณ"}, {"label": "E", "text": "ทำได้ หากร้านไม่รับค่าตอบแทนใด ๆ จากบริษัทยาเป็นการแลกเปลี่ยน", "is_correct": false, "explanation": "การไม่รับค่าตอบแทนไม่ได้แก้ปัญหาการเปิดเผยข้อมูลอ่อนไหวโดยไม่มีความยินยอม"}], "key_takeaway": "ข้อมูลสุขภาพเป็นข้อมูลอ่อนไหว ใช้นอกวัตถุประสงค์การดูแลรักษาหรือส่งให้บุคคลภายนอกต้องได้รับความยินยอมโดยชัดแจ้ง"}'::jsonb, 'hard', 'law-day1 • พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคล: ข้อมูลอ่อนไหวและการเปิดเผย'),
('e78b231fcd6a75af7e9b11891159e09e', 75, 'ผู้ป่วยชายสูงอายุหมดสติถูกนำส่งห้องฉุกเฉิน ไม่มีญาติมาด้วย เภสัชกรโรงพยาบาลพบบัตรสมาชิกร้านยาในกระเป๋าผู้ป่วยจึงโทรศัพท์ไปขอรายการยาที่ผู้ป่วยรับประจำเพื่อประกอบการรักษา เภสัชกรร้านยาลังเลเพราะกังวลเรื่อง พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคล ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ต้องรอให้ผู้ป่วยรู้สึกตัวและให้ความยินยอมเป็นหนังสือก่อนจึงจะให้ข้อมูลได้"}, {"label": "B", "text": "ให้ข้อมูลเท่าที่จำเป็นได้ เพราะเป็นการป้องกันอันตรายต่อชีวิตของผู้ที่ให้ความยินยอมไม่ได้"}, {"label": "C", "text": "ต้องให้โรงพยาบาลยื่นขอคำสั่งศาลก่อน ร้านยาจึงจะเปิดเผยข้อมูลได้"}, {"label": "D", "text": "ให้ข้อมูลทั้งหมดที่ร้านมีได้ รวมทั้งข้อมูลการซื้อสินค้าอื่นที่ไม่เกี่ยวกับการรักษา เพราะเป็นกรณีฉุกเฉิน"}, {"label": "E", "text": "ต้องขออนุญาตจากคณะกรรมการคุ้มครองข้อมูลส่วนบุคคลก่อนทุกครั้ง"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ให้ข้อมูลเท่าที่จำเป็นได้ เพราะเป็นการป้องกันอันตรายต่อชีวิตของผู้ที่ให้ความยินยอมไม่ได้ — การเปิดเผยข้อมูลสุขภาพเท่าที่จำเป็นเพื่อป้องกันอันตรายต่อชีวิตของผู้ที่ให้ความยินยอมไม่ได้ เป็นข้อยกเว้นที่ PDPA รับรอง", "reason": "พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 แม้จะกำหนดให้ข้อมูลสุขภาพต้องได้รับความยินยอมโดยชัดแจ้ง แต่ยกเว้นกรณีที่เป็นการป้องกันหรือระงับอันตรายต่อชีวิต ร่างกาย หรือสุขภาพของบุคคล ซึ่งเจ้าของข้อมูลไม่สามารถให้ความยินยอมได้ไม่ว่าด้วยเหตุใด รวมถึงกรณีที่จำเป็นเพื่อการวินิจฉัยโรคและการให้บริการด้านสุขภาพ\n\nอย่างไรก็ตาม ผู้เปิดเผยยังต้องยึดหลักใช้ข้อมูลเท่าที่จำเป็น ยืนยันว่าผู้ขอเป็นผู้ให้การรักษาจริง และบันทึกการเปิดเผยไว้เป็นหลักฐาน ซึ่งสอดคล้องกับหลัก beneficence ต่อผู้ป่วย", "choices": [{"label": "A", "text": "ต้องรอให้ผู้ป่วยรู้สึกตัวและให้ความยินยอมเป็นหนังสือก่อนจึงจะให้ข้อมูลได้", "is_correct": false, "explanation": "การรอจนผู้ป่วยฟื้นอาจเป็นอันตรายต่อชีวิต กฎหมายมีข้อยกเว้นสำหรับกรณีนี้"}, {"label": "B", "text": "ให้ข้อมูลเท่าที่จำเป็นได้ เพราะเป็นการป้องกันอันตรายต่อชีวิตของผู้ที่ให้ความยินยอมไม่ได้", "is_correct": true, "explanation": "ถูกต้อง: การเปิดเผยข้อมูลสุขภาพเท่าที่จำเป็นเพื่อป้องกันอันตรายต่อชีวิตของผู้ที่ให้ความยินยอมไม่ได้ เป็นข้อยกเว้นที่ PDPA รับรอง"}, {"label": "C", "text": "ต้องให้โรงพยาบาลยื่นขอคำสั่งศาลก่อน ร้านยาจึงจะเปิดเผยข้อมูลได้", "is_correct": false, "explanation": "ไม่จำเป็นต้องมีคำสั่งศาล กรณีนี้เข้าข้อยกเว้นเรื่องอันตรายต่อชีวิตและการให้บริการด้านสุขภาพ"}, {"label": "D", "text": "ให้ข้อมูลทั้งหมดที่ร้านมีได้ รวมทั้งข้อมูลการซื้อสินค้าอื่นที่ไม่เกี่ยวกับการรักษา เพราะเป็นกรณีฉุกเฉิน", "is_correct": false, "explanation": "แม้เป็นกรณีฉุกเฉินก็ต้องเปิดเผยเท่าที่จำเป็นต่อวัตถุประสงค์ (data minimisation)"}, {"label": "E", "text": "ต้องขออนุญาตจากคณะกรรมการคุ้มครองข้อมูลส่วนบุคคลก่อนทุกครั้ง", "is_correct": false, "explanation": "กฎหมายไม่ได้กำหนดให้ต้องขออนุญาตคณะกรรมการเป็นรายกรณี"}], "key_takeaway": "PDPA ไม่ได้ขัดขวางการช่วยชีวิต: เปิดเผยข้อมูลสุขภาพได้เท่าที่จำเป็นเมื่อเจ้าของข้อมูลให้ความยินยอมไม่ได้และชีวิตตกอยู่ในอันตราย"}'::jsonb, 'medium', 'law-day1 • พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคล: ฐานการประมวลผลกรณีฉุกเฉิน'),
('e29d10705016329b6db214c0ff4abe77', 76, 'เภสัชกรพบว่าตนส่งมอบยาผิดความแรงให้ผู้ป่วยเมื่อวาน แม้ผู้ป่วยยังไม่มีอาการผิดปกติ เภสัชกรเลือกโทรศัพท์แจ้งผู้ป่วยตามความเป็นจริง ขอโทษ และนัดเปลี่ยนยาที่ถูกต้อง การตัดสินใจบอกความจริงนี้สอดคล้องกับหลักจริยศาสตร์ข้อใดโดยตรงมากที่สุด', '[{"label": "A", "text": "Fidelity (ความซื่อสัตย์ต่อพันธะและคำมั่นสัญญา)"}, {"label": "B", "text": "Veracity (การบอกความจริง)"}, {"label": "C", "text": "Justice (ความยุติธรรม)"}, {"label": "D", "text": "Beneficence (การทำประโยชน์)"}, {"label": "E", "text": "Confidentiality (การรักษาความลับ)"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. Veracity (การบอกความจริง) — การเปิดเผยความคลาดเคลื่อนทางยาแก่ผู้ป่วยตามความเป็นจริงคือหลัก veracity", "reason": "Veracity คือหน้าที่บอกความจริงและไม่หลอกลวงผู้ป่วย ซึ่งรวมถึงการเปิดเผยความคลาดเคลื่อนทางยา (error disclosure) อย่างตรงไปตรงมา การบอกความจริงยังเป็นพื้นฐานของ autonomy เพราะผู้ป่วยต้องได้ข้อมูลที่ถูกต้องเพื่อตัดสินใจ\n\nหลักอื่นอาจเกี่ยวข้องในทางอ้อม เช่น beneficence และ non-maleficence ในการแก้ไขยาให้ถูกต้อง แต่หลักที่ตรงกับการกระทำ \"บอกความจริง\" ที่สุดคือ veracity", "choices": [{"label": "A", "text": "Fidelity (ความซื่อสัตย์ต่อพันธะและคำมั่นสัญญา)", "is_correct": false, "explanation": "Fidelity เน้นการรักษาคำมั่นและความไว้วางใจในความสัมพันธ์ แต่หลักที่ว่าด้วยการบอกความจริงโดยตรงคือ veracity"}, {"label": "B", "text": "Veracity (การบอกความจริง)", "is_correct": true, "explanation": "ถูกต้อง: การเปิดเผยความคลาดเคลื่อนทางยาแก่ผู้ป่วยตามความเป็นจริงคือหลัก veracity"}, {"label": "C", "text": "Justice (ความยุติธรรม)", "is_correct": false, "explanation": "Justice เกี่ยวกับการกระจายทรัพยากรและการปฏิบัติอย่างเท่าเทียม ไม่ใช่การเปิดเผยความจริง"}, {"label": "D", "text": "Beneficence (การทำประโยชน์)", "is_correct": false, "explanation": "การแก้ไขยาเป็นประโยชน์ต่อผู้ป่วยก็จริง แต่ประเด็นการบอกความจริงเรื่องความผิดพลาดตรงกับ veracity มากกว่า"}, {"label": "E", "text": "Confidentiality (การรักษาความลับ)", "is_correct": false, "explanation": "สถานการณ์นี้ไม่เกี่ยวกับการเปิดเผยข้อมูลผู้ป่วยแก่บุคคลอื่น"}], "key_takeaway": "Veracity = บอกความจริง รวมถึงการเปิดเผยความคลาดเคลื่อนทางยาแก่ผู้ป่วย"}'::jsonb, 'easy', 'law-day1 • หลักจริยศาสตร์: veracity'),
('dfed7ce3b802d55afba2fa321f1ecb70', 77, 'ระหว่างที่ยาต้านไวรัสชนิดหนึ่งขาดแคลน โรงพยาบาลกำหนดเกณฑ์จ่ายยาตามความรุนแรงและความเสี่ยงของผู้ป่วย ต่อมาผู้บริหารขอให้เภสัชกรกันยาส่วนหนึ่งไว้ให้ญาติของผู้บริหารซึ่งมีอาการเล็กน้อยและไม่เข้าเกณฑ์ การทำตามคำขอนี้ขัดกับหลักจริยศาสตร์ข้อใดชัดเจนที่สุด', '[{"label": "A", "text": "Veracity"}, {"label": "B", "text": "Autonomy"}, {"label": "C", "text": "Fidelity"}, {"label": "D", "text": "Confidentiality"}, {"label": "E", "text": "Justice"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. Justice — การจัดสรรยาที่ขาดแคลนโดยเอื้อประโยชน์แก่คนใกล้ชิดผู้มีอำนาจแทนเกณฑ์ความจำเป็นทางการแพทย์ขัดกับหลัก justice", "reason": "Justice (distributive justice) คือการกระจายทรัพยากรสุขภาพอย่างเป็นธรรม ตามเกณฑ์ที่สมเหตุผลและโปร่งใส เช่น ความจำเป็นทางการแพทย์และความเสี่ยง ไม่ใช่ตามสถานะทางสังคมหรือความสัมพันธ์ส่วนตัว\n\nเภสัชกรควรยึดเกณฑ์ที่องค์กรกำหนดและปฏิเสธคำขอที่ทำให้ผู้ป่วยที่จำเป็นกว่าเสียโอกาส ซึ่งสอดคล้องกับสิทธิผู้ป่วยในการได้รับบริการโดยไม่ถูกเลือกปฏิบัติด้วย", "choices": [{"label": "A", "text": "Veracity", "is_correct": false, "explanation": "ประเด็นหลักไม่ใช่การบอกความจริงแก่ผู้ป่วย"}, {"label": "B", "text": "Autonomy", "is_correct": false, "explanation": "ไม่ใช่เรื่องการเคารพการตัดสินใจของผู้ป่วยเกี่ยวกับการรักษาของตนเอง"}, {"label": "C", "text": "Fidelity", "is_correct": false, "explanation": "แม้กระทบความไว้วางใจ แต่ประเด็นหลักคือการจัดสรรทรัพยากรอย่างไม่เป็นธรรม"}, {"label": "D", "text": "Confidentiality", "is_correct": false, "explanation": "สถานการณ์นี้ไม่เกี่ยวกับการเปิดเผยข้อมูลผู้ป่วย"}, {"label": "E", "text": "Justice", "is_correct": true, "explanation": "ถูกต้อง: การจัดสรรยาที่ขาดแคลนโดยเอื้อประโยชน์แก่คนใกล้ชิดผู้มีอำนาจแทนเกณฑ์ความจำเป็นทางการแพทย์ขัดกับหลัก justice"}], "key_takeaway": "Justice = จัดสรรยาและบริการตามความจำเป็นทางการแพทย์ ไม่ใช่ตามสถานะหรือเส้นสาย"}'::jsonb, 'easy', 'law-day1 • หลักจริยศาสตร์: justice'),
('50a8def8edaa11488e758808aa3ab462', 78, 'นายสุรชัย อายุ 55 ปี สติสัมปชัญญะสมบูรณ์ ได้รับคำแนะนำจากเภสัชกรเกี่ยวกับประโยชน์และความเสี่ยงของยาลดไขมันที่แพทย์สั่งอย่างครบถ้วนแล้ว แต่ยืนยันว่าจะไม่รับประทานยาเพราะต้องการลองปรับพฤติกรรมก่อน เภสัชกรควรปฏิบัติอย่างไรเหมาะสมที่สุด', '[{"label": "A", "text": "เคารพการตัดสินใจ บันทึกการปฏิเสธ และเปิดโอกาสให้กลับมาปรึกษาได้"}, {"label": "B", "text": "โทรศัพท์แจ้งภรรยาของผู้ป่วยให้ช่วยโน้มน้าวโดยไม่ต้องขออนุญาตผู้ป่วย"}, {"label": "C", "text": "บอกผู้ป่วยว่าเป็นวิตามินบำรุงเพื่อให้ผู้ป่วยยอมรับประทาน"}, {"label": "D", "text": "ปฏิเสธการให้บริการอื่นทั้งหมดแก่ผู้ป่วยจนกว่าจะยอมรับประทานยา"}, {"label": "E", "text": "แจ้งแพทย์ให้ออกคำสั่งบังคับให้ผู้ป่วยรับประทานยา"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. เคารพการตัดสินใจ บันทึกการปฏิเสธ และเปิดโอกาสให้กลับมาปรึกษาได้ — ผู้ป่วยที่มีความสามารถในการตัดสินใจและได้รับข้อมูลครบถ้วนมีสิทธิปฏิเสธการรักษา เภสัชกรต้องเคารพและบันทึกไว้", "reason": "หลัก autonomy และคำประกาศสิทธิและข้อพึงปฏิบัติของผู้ป่วยรับรองสิทธิของผู้ป่วยที่จะได้รับข้อมูลอย่างเพียงพอเพื่อเลือกตัดสินใจยินยอมหรือไม่ยินยอมรับการรักษา (เว้นแต่กรณีฉุกเฉินอันจำเป็นเร่งด่วน) เมื่อผู้ป่วยมีความสามารถในการตัดสินใจและเข้าใจข้อมูลแล้ว การปฏิเสธนั้นเรียกว่า informed refusal\n\nบทบาทของเภสัชกรคือให้ข้อมูลที่ถูกต้อง ตรวจสอบความเข้าใจ บันทึก และสื่อสารกับผู้สั่งใช้ยา โดยไม่หลอกลวง ไม่บังคับ และไม่เปิดเผยข้อมูลแก่บุคคลอื่นโดยไม่ได้รับความยินยอม", "choices": [{"label": "A", "text": "เคารพการตัดสินใจ บันทึกการปฏิเสธ และเปิดโอกาสให้กลับมาปรึกษาได้", "is_correct": true, "explanation": "ถูกต้อง: ผู้ป่วยที่มีความสามารถในการตัดสินใจและได้รับข้อมูลครบถ้วนมีสิทธิปฏิเสธการรักษา เภสัชกรต้องเคารพและบันทึกไว้"}, {"label": "B", "text": "โทรศัพท์แจ้งภรรยาของผู้ป่วยให้ช่วยโน้มน้าวโดยไม่ต้องขออนุญาตผู้ป่วย", "is_correct": false, "explanation": "เป็นการเปิดเผยข้อมูลสุขภาพโดยไม่ได้รับความยินยอม และไม่เคารพ autonomy"}, {"label": "C", "text": "บอกผู้ป่วยว่าเป็นวิตามินบำรุงเพื่อให้ผู้ป่วยยอมรับประทาน", "is_correct": false, "explanation": "เป็นการหลอกลวง ขัดหลัก veracity และ autonomy"}, {"label": "D", "text": "ปฏิเสธการให้บริการอื่นทั้งหมดแก่ผู้ป่วยจนกว่าจะยอมรับประทานยา", "is_correct": false, "explanation": "การลงโทษผู้ป่วยที่ใช้สิทธิปฏิเสธการรักษาขัดต่อจรรยาบรรณและสิทธิผู้ป่วย"}, {"label": "E", "text": "แจ้งแพทย์ให้ออกคำสั่งบังคับให้ผู้ป่วยรับประทานยา", "is_correct": false, "explanation": "ผู้ป่วยผู้ใหญ่ที่มีความสามารถในการตัดสินใจมีสิทธิปฏิเสธการรักษา แพทย์ไม่มีอำนาจบังคับในกรณีนี้"}], "key_takeaway": "เคารพ informed refusal ของผู้ป่วยที่มีความสามารถตัดสินใจ: ให้ข้อมูล บันทึก และเปิดทางให้กลับมาปรึกษา"}'::jsonb, 'medium', 'law-day1 • หลักจริยศาสตร์: autonomy และ informed refusal'),
('9073b2600cc467569b76e724d334fc69', 79, 'เภสัชกรหัวหน้ากลุ่มงานเภสัชกรรมซึ่งเป็นกรรมการในคณะกรรมการเภสัชกรรมและการบำบัดของโรงพยาบาล ได้รับข้อเสนอจากผู้แทนบริษัทยาให้เดินทางไปต่างประเทศพร้อมครอบครัวโดยบริษัทออกค่าใช้จ่ายทั้งหมด ในช่วงก่อนที่คณะกรรมการจะพิจารณานำยาของบริษัทเข้าบัญชียาโรงพยาบาล ข้อใดเป็นการปฏิบัติที่เหมาะสมที่สุด', '[{"label": "A", "text": "รับข้อเสนอได้ หากตนงดออกเสียงเฉพาะในวาระที่พิจารณายาของบริษัทนั้นในคณะกรรมการ"}, {"label": "B", "text": "รับข้อเสนอได้ หากเดินทางในช่วงวันลาพักผ่อนของตนเอง"}, {"label": "C", "text": "ปฏิเสธข้อเสนอ และเปิดเผยส่วนได้เสียที่มีต่อคณะกรรมการพร้อมไม่ร่วมพิจารณา"}, {"label": "D", "text": "รับข้อเสนอได้ หากโปรแกรมมีการบรรยายวิชาการแทรกครึ่งวัน"}, {"label": "E", "text": "รับข้อเสนอได้ หากรายงานให้ผู้อำนวยการทราบหลังเดินทางกลับ"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ปฏิเสธข้อเสนอ และเปิดเผยส่วนได้เสียที่มีต่อคณะกรรมการพร้อมไม่ร่วมพิจารณา — ผู้มีบทบาทตัดสินใจคัดเลือกยาไม่ควรรับประโยชน์ส่วนตัวจากบริษัทยา และต้องเปิดเผยส่วนได้เสียพร้อมถอนตัวจากการพิจารณา", "reason": "ข้อบังคับว่าด้วยจรรยาบรรณแห่งวิชาชีพเภสัชกรรมห้ามเภสัชกรเรียกร้องหรือรับผลประโยชน์ที่ขัดกับวิชาชีพหรือที่อาจมีผลต่อการใช้ดุลพินิจทางวิชาชีพ และเกณฑ์จริยธรรมว่าด้วยการส่งเสริมการขายยา รวมถึงระเบียบของกระทรวงสาธารณสุขสำหรับหน่วยงานรัฐ วางหลักว่าผู้ประกอบวิชาชีพและผู้มีหน้าที่จัดซื้อจัดหาไม่ควรรับของขวัญ การเดินทาง หรือประโยชน์ส่วนตัวจากบริษัทยา การสนับสนุนวิชาการ (ถ้ามี) ควรผ่านหน่วยงานอย่างโปร่งใส ไม่ระบุตัวบุคคลและไม่รวมครอบครัว\n\nหลักการจัดการ conflict of interest คือ หลีกเลี่ยงการรับประโยชน์ และเปิดเผยส่วนได้เสีย (disclosure) พร้อมไม่ร่วมพิจารณา (recusal) การรายงานภายหลังหรืองดออกเสียงเพียงอย่างเดียวไม่เพียงพอ", "choices": [{"label": "A", "text": "รับข้อเสนอได้ หากตนงดออกเสียงเฉพาะในวาระที่พิจารณายาของบริษัทนั้นในคณะกรรมการ", "is_correct": false, "explanation": "การรับประโยชน์ส่วนตัวก่อให้เกิดผลประโยชน์ทับซ้อนแล้ว แม้งดออกเสียงก็ยังมีอิทธิพลต่อการพิจารณาและภาพลักษณ์ความเป็นกลาง"}, {"label": "B", "text": "รับข้อเสนอได้ หากเดินทางในช่วงวันลาพักผ่อนของตนเอง", "is_correct": false, "explanation": "ช่วงเวลาเดินทางไม่ได้เปลี่ยนสาระว่าเป็นการรับประโยชน์ส่วนตัวจากบริษัทยา"}, {"label": "C", "text": "ปฏิเสธข้อเสนอ และเปิดเผยส่วนได้เสียที่มีต่อคณะกรรมการพร้อมไม่ร่วมพิจารณา", "is_correct": true, "explanation": "ถูกต้อง: ผู้มีบทบาทตัดสินใจคัดเลือกยาไม่ควรรับประโยชน์ส่วนตัวจากบริษัทยา และต้องเปิดเผยส่วนได้เสียพร้อมถอนตัวจากการพิจารณา"}, {"label": "D", "text": "รับข้อเสนอได้ หากโปรแกรมมีการบรรยายวิชาการแทรกครึ่งวัน", "is_correct": false, "explanation": "การแทรกกิจกรรมวิชาการเล็กน้อยไม่ได้ทำให้การรับประโยชน์ส่วนตัวรวมถึงครอบครัวเหมาะสม"}, {"label": "E", "text": "รับข้อเสนอได้ หากรายงานให้ผู้อำนวยการทราบหลังเดินทางกลับ", "is_correct": false, "explanation": "การรายงานภายหลังไม่ได้ขจัดผลประโยชน์ทับซ้อนที่เกิดขึ้นแล้ว"}], "key_takeaway": "ผู้คัดเลือกยาต้องไม่รับประโยชน์ส่วนตัวจากบริษัทยา และต้องเปิดเผยส่วนได้เสียพร้อมถอนตัวจากการพิจารณา"}'::jsonb, 'medium', 'law-day1 • ผลประโยชน์ทับซ้อนและการส่งเสริมการขายยา'),
('19bd5c0a87afceeac0e58bc2e9a42465', 80, 'เวลา 20.00 น. ผู้ป่วยนำใบสั่งยาจากคลินิกเอกชนมาที่ร้านยา ใบสั่งระบุ methotrexate 2.5 mg ครั้งละ 4 เม็ดวันละครั้งทุกวัน สำหรับโรคข้ออักเสบรูมาตอยด์ ซึ่งเภสัชกรเห็นว่าน่าจะเป็นความคลาดเคลื่อนในการสั่งใช้ยาที่อาจเป็นอันตรายร้ายแรง คลินิกปิดแล้วและติดต่อแพทย์ไม่ได้ ผู้ป่วยเร่งให้จ่ายยาเพราะยาเดิมหมด ข้อใดเป็นการปฏิบัติที่เหมาะสมที่สุดในทางวิชาชีพและจริยธรรม', '[{"label": "A", "text": "จ่ายยาตามใบสั่ง เพราะความรับผิดชอบต่อการสั่งใช้ยาเป็นของแพทย์ผู้สั่งแต่เพียงผู้เดียว"}, {"label": "B", "text": "แก้ไขวิธีใช้เป็นสัปดาห์ละครั้งด้วยตนเองแล้วจ่ายยา โดยไม่จำเป็นต้องแจ้งแพทย์"}, {"label": "C", "text": "ปฏิเสธการจ่ายยา และบอกผู้ป่วยว่าแพทย์คนนี้ไม่มีความรู้ ควรไปร้องเรียนแพทย์ทันที"}, {"label": "D", "text": "ไม่จ่ายตามขนาดที่น่าจะเป็นอันตราย อธิบายผู้ป่วย บันทึก และติดต่อผู้สั่งยาเพื่อยืนยัน"}, {"label": "E", "text": "จ่ายยาเพียงครึ่งหนึ่งของจำนวนในใบสั่งเพื่อลดความเสี่ยง แล้วให้ผู้ป่วยมารับส่วนที่เหลือภายหลัง"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ไม่จ่ายตามขนาดที่น่าจะเป็นอันตราย อธิบายผู้ป่วย บันทึก และติดต่อผู้สั่งยาเพื่อยืนยัน — เภสัชกรต้องไม่จ่ายยาที่น่าจะเป็นอันตราย ไม่แก้ไขใบสั่งโดยพลการ และต้องสื่อสารกับผู้สั่งและผู้ป่วยอย่างเป็นวิชาชีพ", "reason": "ประเด็นความปลอดภัย: หลัก non-maleficence และหน้าที่ทางวิชาชีพกำหนดให้เภสัชกรตรวจสอบใบสั่งยา (prescription screening) และไม่จ่ายยาที่มีเหตุอันควรเชื่อว่าจะเป็นอันตรายร้ายแรงต่อผู้ป่วย การ \"ทำตามคำสั่ง\" ไม่ทำให้เภสัชกรพ้นความรับผิดชอบทางวิชาชีพ\n\nประเด็นขอบเขตวิชาชีพ: การเปลี่ยนแปลงสาระสำคัญของใบสั่งยาควรทำโดยปรึกษาและได้รับความเห็นชอบจากผู้สั่งใช้ยา เภสัชกรจึงไม่ควรแก้ไขเองโดยพลการ แต่ต้องบันทึกปัญหาและติดต่อผู้สั่งยาเพื่อยืนยันเมื่อทำได้\n\nประเด็นความสัมพันธ์กับวิชาชีพอื่นและผู้ป่วย: ข้อบังคับว่าด้วยจรรยาบรรณกำหนดให้ให้เกียรติผู้ร่วมงานต่างวิชาชีพ ไม่ทำให้ผู้อื่นเสื่อมเสีย การอธิบายแก่ผู้ป่วยควรเน้นความปลอดภัยและข้อเท็จจริง พร้อมช่วยให้ผู้ป่วยเข้าถึงการรักษาที่ปลอดภัย (เช่น ติดต่อแพทย์ในวันถัดไปหรือสถานพยาบาลที่เปิดบริการ)", "choices": [{"label": "A", "text": "จ่ายยาตามใบสั่ง เพราะความรับผิดชอบต่อการสั่งใช้ยาเป็นของแพทย์ผู้สั่งแต่เพียงผู้เดียว", "is_correct": false, "explanation": "เภสัชกรมีหน้าที่ตรวจสอบความเหมาะสมของใบสั่งยาและมีความรับผิดชอบของตนเอง การจ่ายยาที่รู้ว่าน่าจะเป็นอันตรายขัดหลัก non-maleficence"}, {"label": "B", "text": "แก้ไขวิธีใช้เป็นสัปดาห์ละครั้งด้วยตนเองแล้วจ่ายยา โดยไม่จำเป็นต้องแจ้งแพทย์", "is_correct": false, "explanation": "เภสัชกรไม่ควรแก้ไขใบสั่งยาโดยพลการโดยไม่ได้ปรึกษาผู้สั่งใช้ยา และต้องสื่อสารให้ผู้สั่งทราบ"}, {"label": "C", "text": "ปฏิเสธการจ่ายยา และบอกผู้ป่วยว่าแพทย์คนนี้ไม่มีความรู้ ควรไปร้องเรียนแพทย์ทันที", "is_correct": false, "explanation": "การตำหนิหรือทำให้ผู้ร่วมวิชาชีพเสื่อมเสียต่อหน้าผู้ป่วยขัดต่อจรรยาบรรณ ควรสื่อสารกับผู้สั่งยาอย่างสร้างสรรค์"}, {"label": "D", "text": "ไม่จ่ายตามขนาดที่น่าจะเป็นอันตราย อธิบายผู้ป่วย บันทึก และติดต่อผู้สั่งยาเพื่อยืนยัน", "is_correct": true, "explanation": "ถูกต้อง: เภสัชกรต้องไม่จ่ายยาที่น่าจะเป็นอันตราย ไม่แก้ไขใบสั่งโดยพลการ และต้องสื่อสารกับผู้สั่งและผู้ป่วยอย่างเป็นวิชาชีพ"}, {"label": "E", "text": "จ่ายยาเพียงครึ่งหนึ่งของจำนวนในใบสั่งเพื่อลดความเสี่ยง แล้วให้ผู้ป่วยมารับส่วนที่เหลือภายหลัง", "is_correct": false, "explanation": "การจ่ายยาบางส่วนพร้อมวิธีใช้ที่น่าจะผิดยังทำให้ผู้ป่วยเสี่ยงอันตรายอยู่ ไม่ได้แก้ปัญหาที่ต้นเหตุ"}], "key_takeaway": "ใบสั่งยาที่ไม่ปลอดภัย: ไม่จ่าย ไม่แก้เอง ติดต่อผู้สั่ง บันทึก และสื่อสารกับผู้ป่วยโดยไม่ตำหนิแพทย์"}'::jsonb, 'hard', 'law-day1 • การทำงานร่วมกับวิชาชีพอื่น: การปฏิเสธจ่ายยาตามใบสั่งที่ไม่ปลอดภัย'),
('f2b6782f7b1acea6f23f673012afc3b4', 81, 'เภสัชกรวีระมีความเชื่อทางศาสนาที่ทำให้ไม่สบายใจที่จะจ่ายยาคุมกำเนิดฉุกเฉิน วันหนึ่งหญิงสาวมาขอซื้อยาดังกล่าวที่ร้านซึ่งเขาปฏิบัติงานอยู่ ตามหลักจริยศาสตร์เรื่องการคัดค้านโดยมโนธรรม (conscientious objection) ข้อใดเหมาะสมที่สุด', '[{"label": "A", "text": "ปฏิเสธการจ่ายยา และให้คำแนะนำทางศีลธรรมแก่ผู้รับบริการเกี่ยวกับพฤติกรรมทางเพศ"}, {"label": "B", "text": "ต้องจ่ายยาทุกกรณี เพราะเภสัชกรไม่มีสิทธินำความเชื่อส่วนตัวมาเกี่ยวข้องกับงานใด ๆ เลย"}, {"label": "C", "text": "ปฏิเสธการจ่ายยาได้ โดยไม่มีหน้าที่ต้องแจ้งว่าผู้รับบริการจะรับยาได้จากที่ใด"}, {"label": "D", "text": "งดจ่ายด้วยตนเองได้ แต่ต้องไม่ตำหนิ และส่งต่อให้ได้รับบริการอย่างทันท่วงที"}, {"label": "E", "text": "จ่ายยาหลอกแทนโดยไม่แจ้ง เพื่อหลีกเลี่ยงการขัดแย้งกับผู้รับบริการ"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. งดจ่ายด้วยตนเองได้ แต่ต้องไม่ตำหนิ และส่งต่อให้ได้รับบริการอย่างทันท่วงที — การคัดค้านโดยมโนธรรมทำได้เฉพาะระดับตัวบุคคล โดยต้องไม่ตัดสินผู้รับบริการและต้องส่งต่อให้ได้รับบริการทันเวลา", "reason": "หลักจริยศาสตร์ยอมรับว่าผู้ประกอบวิชาชีพอาจปฏิเสธการกระทำที่ขัดต่อมโนธรรมของตนได้ (conscientious objection) แต่สิทธินี้มีขอบเขต คือ ต้องไม่ขัดขวางการเข้าถึงบริการที่ชอบด้วยกฎหมาย ต้องไม่ตำหนิหรือเลือกปฏิบัติต่อผู้รับบริการ ต้องส่งต่อ (duty to refer) อย่างทันท่วงที และไม่ใช้สิทธินี้ในภาวะฉุกเฉินที่ไม่มีผู้อื่นให้บริการได้\n\nกรณียาคุมกำเนิดฉุกเฉินซึ่งประสิทธิผลขึ้นกับเวลา การส่งต่อที่ล่าช้าหรือไม่ส่งต่อเลยอาจก่อความเสียหายต่อผู้รับบริการ ส่วนการจ่ายยาหลอกหรือการตำหนิเป็นการละเมิด veracity และการเคารพศักดิ์ศรีของผู้รับบริการ", "choices": [{"label": "A", "text": "ปฏิเสธการจ่ายยา และให้คำแนะนำทางศีลธรรมแก่ผู้รับบริการเกี่ยวกับพฤติกรรมทางเพศ", "is_correct": false, "explanation": "การตำหนิหรือยัดเยียดค่านิยมส่วนตัวขัดต่อการเคารพผู้รับบริการและหลัก autonomy"}, {"label": "B", "text": "ต้องจ่ายยาทุกกรณี เพราะเภสัชกรไม่มีสิทธินำความเชื่อส่วนตัวมาเกี่ยวข้องกับงานใด ๆ เลย", "is_correct": false, "explanation": "หลักจริยศาสตร์ยอมรับ conscientious objection ในขอบเขตจำกัด โดยมีเงื่อนไขว่าต้องไม่ขัดขวางการเข้าถึงบริการของผู้ป่วย"}, {"label": "C", "text": "ปฏิเสธการจ่ายยาได้ โดยไม่มีหน้าที่ต้องแจ้งว่าผู้รับบริการจะรับยาได้จากที่ใด", "is_correct": false, "explanation": "การปฏิเสธโดยไม่ส่งต่อทำให้ผู้รับบริการเสียโอกาสโดยเฉพาะยาที่ต้องใช้ทันเวลา ขัดกับหน้าที่ส่งต่อ"}, {"label": "D", "text": "งดจ่ายด้วยตนเองได้ แต่ต้องไม่ตำหนิ และส่งต่อให้ได้รับบริการอย่างทันท่วงที", "is_correct": true, "explanation": "ถูกต้อง: การคัดค้านโดยมโนธรรมทำได้เฉพาะระดับตัวบุคคล โดยต้องไม่ตัดสินผู้รับบริการและต้องส่งต่อให้ได้รับบริการทันเวลา"}, {"label": "E", "text": "จ่ายยาหลอกแทนโดยไม่แจ้ง เพื่อหลีกเลี่ยงการขัดแย้งกับผู้รับบริการ", "is_correct": false, "explanation": "การหลอกลวงผู้ป่วยขัดหลัก veracity และ non-maleficence อย่างร้ายแรง"}], "key_takeaway": "Conscientious objection ต้องมาพร้อมหน้าที่ส่งต่อ ไม่ตัดสิน และไม่ทำให้ผู้รับบริการเสียโอกาส"}'::jsonb, 'medium', 'law-day1 • หลักจริยศาสตร์: conscientious objection และ duty to refer'),
('5df3f856ca9d3eca0830c9cb57e6ffa7', 82, 'ผู้เข้าร่วมโครงการวิจัยทางคลินิกรายหนึ่งแจ้งเภสัชกรผู้วิจัยว่าต้องการถอนตัวจากโครงการก่อนครบกำหนด ข้อใดถูกต้องตามหลักจริยธรรมการวิจัยในมนุษย์', '[{"label": "A", "text": "ถอนตัวได้ทุกเมื่อโดยไม่ต้องให้เหตุผล และไม่เสียสิทธิการรักษาตามปกติ"}, {"label": "B", "text": "ถอนตัวได้เฉพาะเมื่อสิ้นสุดระยะใดระยะหนึ่งของการวิจัยตามที่โครงร่างกำหนด"}, {"label": "C", "text": "ถอนตัวได้ แต่ต้องคืนค่าตอบแทนและค่าเดินทางที่ได้รับไปแล้วทั้งหมด"}, {"label": "D", "text": "ต้องได้รับอนุมัติจากคณะกรรมการจริยธรรมการวิจัยก่อนจึงจะถอนตัวได้"}, {"label": "E", "text": "ถอนตัวได้ แต่จะไม่ได้รับการรักษาตามปกติจากสถาบันนั้นอีก"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ถอนตัวได้ทุกเมื่อโดยไม่ต้องให้เหตุผล และไม่เสียสิทธิการรักษาตามปกติ — ความยินยอมในการวิจัยต้องเป็นไปโดยสมัครใจตลอดเวลา ผู้เข้าร่วมถอนตัวได้ทุกเมื่อโดยไม่เสียสิทธิใด", "reason": "หลักจริยธรรมการวิจัยในมนุษย์ (เช่น ปฏิญญาเฮลซิงกิ และหลัก respect for persons ใน Belmont Report) กำหนดว่าความยินยอมต้องได้รับโดยสมัครใจ หลังได้ข้อมูลครบถ้วน และผู้เข้าร่วมมีสิทธิถอนตัวได้ทุกเมื่อโดยไม่ต้องให้เหตุผลและไม่เสียประโยชน์ที่พึงได้รับ\n\nคำประกาศสิทธิและข้อพึงปฏิบัติของผู้ป่วยก็รับรองสิทธิของผู้ป่วยที่จะได้รับข้อมูลเพื่อตัดสินใจเข้าร่วมหรือถอนตัวจากการเป็นผู้ถูกทดลองในการวิจัย", "choices": [{"label": "A", "text": "ถอนตัวได้ทุกเมื่อโดยไม่ต้องให้เหตุผล และไม่เสียสิทธิการรักษาตามปกติ", "is_correct": true, "explanation": "ถูกต้อง: ความยินยอมในการวิจัยต้องเป็นไปโดยสมัครใจตลอดเวลา ผู้เข้าร่วมถอนตัวได้ทุกเมื่อโดยไม่เสียสิทธิใด"}, {"label": "B", "text": "ถอนตัวได้เฉพาะเมื่อสิ้นสุดระยะใดระยะหนึ่งของการวิจัยตามที่โครงร่างกำหนด", "is_correct": false, "explanation": "สิทธิถอนตัวมีได้ทุกเมื่อ ไม่ผูกกับระยะของการวิจัย"}, {"label": "C", "text": "ถอนตัวได้ แต่ต้องคืนค่าตอบแทนและค่าเดินทางที่ได้รับไปแล้วทั้งหมด", "is_correct": false, "explanation": "การเรียกคืนค่าตอบแทนเป็นการกดดันไม่ให้ถอนตัว ขัดหลักความสมัครใจ"}, {"label": "D", "text": "ต้องได้รับอนุมัติจากคณะกรรมการจริยธรรมการวิจัยก่อนจึงจะถอนตัวได้", "is_correct": false, "explanation": "การถอนตัวเป็นสิทธิของผู้เข้าร่วม ไม่ต้องขออนุมัติจาก EC"}, {"label": "E", "text": "ถอนตัวได้ แต่จะไม่ได้รับการรักษาตามปกติจากสถาบันนั้นอีก", "is_correct": false, "explanation": "การตัดสิทธิการรักษาเป็นการลงโทษผู้ถอนตัว ขัดหลักจริยธรรมการวิจัยและสิทธิผู้ป่วย"}], "key_takeaway": "ผู้เข้าร่วมวิจัยถอนตัวได้ทุกเมื่อ ไม่ต้องให้เหตุผล และไม่เสียสิทธิการรักษาตามปกติ"}'::jsonb, 'easy', 'law-day1 • การวิจัยในมนุษย์: informed consent และการถอนตัว'),
('85ddd9c626d36eb5cdfbc2c2be9a960e', 83, 'ผู้แทนบริษัทยานำ "ตัวอย่างยา" ซึ่งเป็นยาอันตรายจำนวนหลายสิบกล่องมามอบให้เภสัชกรเจ้าของร้านยา พร้อมบอกว่า "ขายได้เลย ไม่ต้องจ่ายเงิน ถือเป็นกำไรของร้าน" ข้อใดเป็นการปฏิบัติที่ถูกต้องตามหลักจริยธรรมว่าด้วยการส่งเสริมการขายยามากที่สุด', '[{"label": "A", "text": "รับไว้และนำออกขายได้ เพราะเมื่อรับมาแล้วถือเป็นกรรมสิทธิ์ของร้าน"}, {"label": "B", "text": "รับได้ไม่จำกัดจำนวน และนำไปแจกเป็นของแถมแก่ลูกค้าที่ซื้อสินค้าครบตามยอด"}, {"label": "C", "text": "รับได้และขายในราคาต่ำกว่าท้องตลาดเพื่อประโยชน์ของผู้บริโภค"}, {"label": "D", "text": "รับได้และขายได้ หากบันทึกรายรับลงบัญชีของร้านอย่างถูกต้อง"}, {"label": "E", "text": "ไม่รับตัวอย่างยาในปริมาณที่เป็นการจูงใจ และไม่นำตัวอย่างยาไปขาย"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ไม่รับตัวอย่างยาในปริมาณที่เป็นการจูงใจ และไม่นำตัวอย่างยาไปขาย — ตัวอย่างยามีไว้เพื่อให้ผู้ประกอบวิชาชีพทำความคุ้นเคยในปริมาณที่เหมาะสม ห้ามนำไปขาย และไม่ควรรับในลักษณะที่เป็นสิ่งจูงใจ", "reason": "เกณฑ์จริยธรรมว่าด้วยการส่งเสริมการขายยาของประเทศไทยวางหลักว่าตัวอย่างยาให้ได้ในปริมาณที่เหมาะสมเพื่อให้ผู้ประกอบวิชาชีพได้ทำความคุ้นเคยหรือเพื่อประโยชน์ของผู้ป่วย ไม่ใช่เพื่อการจำหน่าย และผู้ประกอบวิชาชีพไม่ควรรับสิ่งของหรือประโยชน์ที่มีลักษณะเป็นการจูงใจให้สั่งใช้หรือจ่ายยา\n\nการรับยาจำนวนมากโดยให้ร้านนำไปขายเป็นกำไร คือการให้ประโยชน์ทางการเงินแก่ผู้จ่ายยาเพื่อผลักดันยอดขาย ซึ่งขัดกับหลักจรรยาบรรณเรื่องการไม่รับผลประโยชน์ที่ขัดกับวิชาชีพด้วย", "choices": [{"label": "A", "text": "รับไว้และนำออกขายได้ เพราะเมื่อรับมาแล้วถือเป็นกรรมสิทธิ์ของร้าน", "is_correct": false, "explanation": "ตัวอย่างยามีวัตถุประสงค์เพื่อการทดลองใช้/ทำความคุ้นเคย ไม่ใช่เพื่อการค้า การนำไปขายจึงไม่เหมาะสม"}, {"label": "B", "text": "รับได้ไม่จำกัดจำนวน และนำไปแจกเป็นของแถมแก่ลูกค้าที่ซื้อสินค้าครบตามยอด", "is_correct": false, "explanation": "การแจกยาอันตรายเป็นของแถมโดยไม่ได้ประเมินผู้ป่วยไม่ปลอดภัย และเป็นการใช้ยาเพื่อส่งเสริมการขาย"}, {"label": "C", "text": "รับได้และขายในราคาต่ำกว่าท้องตลาดเพื่อประโยชน์ของผู้บริโภค", "is_correct": false, "explanation": "ราคาต่ำไม่ได้ทำให้การนำตัวอย่างยาไปขายเหมาะสม"}, {"label": "D", "text": "รับได้และขายได้ หากบันทึกรายรับลงบัญชีของร้านอย่างถูกต้อง", "is_correct": false, "explanation": "การทำบัญชีถูกต้องไม่ได้แก้ปัญหาว่าตัวอย่างยาไม่ควรถูกนำไปขาย"}, {"label": "E", "text": "ไม่รับตัวอย่างยาในปริมาณที่เป็นการจูงใจ และไม่นำตัวอย่างยาไปขาย", "is_correct": true, "explanation": "ถูกต้อง: ตัวอย่างยามีไว้เพื่อให้ผู้ประกอบวิชาชีพทำความคุ้นเคยในปริมาณที่เหมาะสม ห้ามนำไปขาย และไม่ควรรับในลักษณะที่เป็นสิ่งจูงใจ"}], "key_takeaway": "ตัวอย่างยา = เพื่อทำความคุ้นเคยในปริมาณเหมาะสม ไม่ใช่สินค้าหรือของกำนัลเพื่อนำไปขาย"}'::jsonb, 'medium', 'law-day1 • เกณฑ์จริยธรรมว่าด้วยการส่งเสริมการขายยา'),
('57faa4e6fa1a203a989161bac3dd6c71', 84, 'คลินิกเวชกรรมแห่งหนึ่งได้รับอนุญาตตาม พ.ร.บ.สถานพยาบาล พ.ศ. 2541 แพทย์ผู้ดำเนินการจ่ายยาให้ผู้ป่วยที่ตนตรวจรักษาตามปกติ ต่อมาคลินิกเริ่มตั้งตู้ขายยาอันตรายให้บุคคลทั่วไปที่เดินเข้ามาซื้อโดยไม่ได้ตรวจรักษา และขายผ่านเพจออนไลน์ของคลินิก โดยอ้างว่ามีใบอนุญาตสถานพยาบาลแล้ว ข้อใดวิเคราะห์ได้ถูกต้องที่สุด', '[{"label": "A", "text": "ทำได้ทั้งหมด เพราะใบอนุญาตสถานพยาบาลครอบคลุมกิจกรรมเกี่ยวกับยาทุกประเภทในคลินิก"}, {"label": "B", "text": "คลินิกจะจ่ายยาแม้ให้ผู้ป่วยของตนเองได้ก็ต่อเมื่อมีเภสัชกรประจำคลินิกเท่านั้น"}, {"label": "C", "text": "จ่ายยาให้ผู้ป่วยที่ตรวจรักษาได้ แต่ขายแก่บุคคลทั่วไปต้องได้รับอนุญาตขายยาแยกต่างหาก"}, {"label": "D", "text": "แพทย์ต้องเขียนใบสั่งยาให้ผู้ป่วยไปซื้อยาที่ร้านยาเท่านั้น ห้ามคลินิกจ่ายยาเองในทุกกรณี"}, {"label": "E", "text": "การขายผ่านเพจออนไลน์ทำได้ หากลูกค้าเคยเป็นผู้ป่วยของคลินิกมาก่อนในอดีต"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. จ่ายยาให้ผู้ป่วยที่ตรวจรักษาได้ แต่ขายแก่บุคคลทั่วไปต้องได้รับอนุญาตขายยาแยกต่างหาก — ข้อยกเว้นให้แพทย์จ่ายยาได้จำกัดเฉพาะผู้ป่วยของตน การขายยาแก่บุคคลทั่วไปต้องได้รับอนุญาตขายยาแยกต่างหาก", "reason": "พ.ร.บ.สถานพยาบาล พ.ศ. 2541 ควบคุมการประกอบกิจการและการดำเนินการสถานพยาบาล โดยผู้ดำเนินการต้องเป็นผู้ประกอบวิชาชีพที่รับผิดชอบการให้บริการในสถานพยาบาล แต่ใบอนุญาตสถานพยาบาลไม่ใช่ใบอนุญาตขายยา\n\nพ.ร.บ.ยา พ.ศ. 2510 ยกเว้นให้ผู้ประกอบวิชาชีพเวชกรรม (และผู้ประกอบวิชาชีพบางสาขาตามที่กฎหมายกำหนด) ขายยาเฉพาะสำหรับผู้ป่วยของตนได้โดยไม่ต้องขอใบอนุญาตขายยา ข้อยกเว้นนี้ผูกกับความสัมพันธ์การตรวจรักษา เมื่อคลินิกขายยาอันตรายให้บุคคลทั่วไปที่ไม่ได้ตรวจรักษา หรือขายผ่านช่องทางออนไลน์ ย่อมไม่อยู่ในข้อยกเว้น และเป็นการขายยาโดยไม่ได้รับอนุญาต ซึ่งยังเสี่ยงต่อความปลอดภัยของผู้บริโภคเพราะไม่มีการประเมินผู้ป่วย", "choices": [{"label": "A", "text": "ทำได้ทั้งหมด เพราะใบอนุญาตสถานพยาบาลครอบคลุมกิจกรรมเกี่ยวกับยาทุกประเภทในคลินิก", "is_correct": false, "explanation": "ใบอนุญาตสถานพยาบาลไม่ได้ทดแทนใบอนุญาตขายยาตามกฎหมายว่าด้วยยา"}, {"label": "B", "text": "คลินิกจะจ่ายยาแม้ให้ผู้ป่วยของตนเองได้ก็ต่อเมื่อมีเภสัชกรประจำคลินิกเท่านั้น", "is_correct": false, "explanation": "กฎหมายว่าด้วยยายกเว้นให้ผู้ประกอบวิชาชีพเวชกรรมขายยาเฉพาะสำหรับผู้ป่วยของตนได้โดยไม่ต้องมีใบอนุญาตขายยา"}, {"label": "C", "text": "จ่ายยาให้ผู้ป่วยที่ตรวจรักษาได้ แต่ขายแก่บุคคลทั่วไปต้องได้รับอนุญาตขายยาแยกต่างหาก", "is_correct": true, "explanation": "ถูกต้อง: ข้อยกเว้นให้แพทย์จ่ายยาได้จำกัดเฉพาะผู้ป่วยของตน การขายยาแก่บุคคลทั่วไปต้องได้รับอนุญาตขายยาแยกต่างหาก"}, {"label": "D", "text": "แพทย์ต้องเขียนใบสั่งยาให้ผู้ป่วยไปซื้อยาที่ร้านยาเท่านั้น ห้ามคลินิกจ่ายยาเองในทุกกรณี", "is_correct": false, "explanation": "ประเทศไทยยังไม่ได้แยกการสั่งใช้ยากับการจ่ายยาโดยเด็ดขาด คลินิกจ่ายยาให้ผู้ป่วยของตนได้"}, {"label": "E", "text": "การขายผ่านเพจออนไลน์ทำได้ หากลูกค้าเคยเป็นผู้ป่วยของคลินิกมาก่อนในอดีต", "is_correct": false, "explanation": "การขายยาให้บุคคลที่ไม่ได้ตรวจรักษาในครั้งนั้นผ่านช่องทางออนไลน์ไม่ใช่การจ่ายยาให้ผู้ป่วยของตนตามข้อยกเว้น"}], "key_takeaway": "ใบอนุญาตสถานพยาบาลไม่ใช่ใบอนุญาตขายยา แพทย์จ่ายยาได้เฉพาะผู้ป่วยที่ตนตรวจรักษา"}'::jsonb, 'hard', 'law-day1 • พ.ร.บ.สถานพยาบาล: คลินิกจ่ายยาให้ผู้ป่วยของตน'),
('ef8f8b3a69e933b0933077a038486dd5', 85, 'ผู้ป่วยโรคความดันโลหิตสูงนำซองยาและใบสรุปรายการยาจากโรงพยาบาลมาขอให้เภสัชกรร้านยาช่วยดูว่ายาเหมาะสมหรือไม่ เพราะต้องการ "ความเห็นที่สอง" ก่อนกลับไปพบแพทย์ เภสัชกรร้านยาลังเลว่าจะเป็นการก้าวล่วงผู้ประกอบวิชาชีพที่โรงพยาบาลหรือไม่ ข้อใดเหมาะสมที่สุด', '[{"label": "A", "text": "ปฏิเสธ เพราะการให้ความเห็นต่อยาที่ผู้อื่นสั่งเป็นการละเมิดมารยาทระหว่างวิชาชีพเสมอ"}, {"label": "B", "text": "ให้ความเห็นอย่างเป็นกลางได้ โดยไม่ตำหนิผู้รักษาเดิม และแนะนำให้กลับไปปรึกษาแพทย์"}, {"label": "C", "text": "ให้ความเห็นได้เฉพาะเมื่อแพทย์เจ้าของไข้อนุญาตเป็นลายลักษณ์อักษร"}, {"label": "D", "text": "ให้ความเห็นและแนะนำให้หยุดยาทั้งหมดทันที พร้อมบอกว่าโรงพยาบาลรักษาผิด"}, {"label": "E", "text": "แนะนำให้ผู้ป่วยฟ้องร้องโรงพยาบาลเดิม เพื่อให้ได้รับการชดเชย"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ให้ความเห็นอย่างเป็นกลางได้ โดยไม่ตำหนิผู้รักษาเดิม และแนะนำให้กลับไปปรึกษาแพทย์ — ผู้ป่วยมีสิทธิขอความเห็นจากผู้ประกอบวิชาชีพอื่น เภสัชกรให้ความเห็นได้อย่างเป็นกลางโดยให้เกียรติผู้ประกอบวิชาชีพเดิม", "reason": "คำประกาศสิทธิและข้อพึงปฏิบัติของผู้ป่วยรับรองสิทธิของผู้ป่วยในการขอความเห็นจากผู้ประกอบวิชาชีพด้านสุขภาพอื่นที่มิได้เป็นผู้ให้บริการแก่ตน และสิทธิในการขอเปลี่ยนผู้ให้บริการและสถานพยาบาล\n\nในขณะเดียวกัน ข้อบังคับว่าด้วยจรรยาบรรณกำหนดให้เภสัชกรให้เกียรติและไม่ทำให้ผู้ร่วมวิชาชีพหรือผู้ประกอบวิชาชีพอื่นเสื่อมเสีย ความเห็นจึงควรอิงหลักวิชาการ สื่อสารอย่างระมัดระวัง และส่งเสริมให้ผู้ป่วยกลับไปปรึกษาผู้รักษาเพื่อปรับแผนการรักษาร่วมกัน", "choices": [{"label": "A", "text": "ปฏิเสธ เพราะการให้ความเห็นต่อยาที่ผู้อื่นสั่งเป็นการละเมิดมารยาทระหว่างวิชาชีพเสมอ", "is_correct": false, "explanation": "ผู้ป่วยมีสิทธิขอความเห็นจากผู้ประกอบวิชาชีพอื่น การให้ความเห็นอย่างเป็นกลางไม่ใช่การละเมิดมารยาท"}, {"label": "B", "text": "ให้ความเห็นอย่างเป็นกลางได้ โดยไม่ตำหนิผู้รักษาเดิม และแนะนำให้กลับไปปรึกษาแพทย์", "is_correct": true, "explanation": "ถูกต้อง: ผู้ป่วยมีสิทธิขอความเห็นจากผู้ประกอบวิชาชีพอื่น เภสัชกรให้ความเห็นได้อย่างเป็นกลางโดยให้เกียรติผู้ประกอบวิชาชีพเดิม"}, {"label": "C", "text": "ให้ความเห็นได้เฉพาะเมื่อแพทย์เจ้าของไข้อนุญาตเป็นลายลักษณ์อักษร", "is_correct": false, "explanation": "สิทธิขอความเห็นที่สองเป็นสิทธิของผู้ป่วย ไม่ต้องได้รับอนุญาตจากแพทย์เจ้าของไข้"}, {"label": "D", "text": "ให้ความเห็นและแนะนำให้หยุดยาทั้งหมดทันที พร้อมบอกว่าโรงพยาบาลรักษาผิด", "is_correct": false, "explanation": "การแนะนำให้หยุดยาเองอาจเป็นอันตราย และการกล่าวร้ายผู้ประกอบวิชาชีพอื่นขัดต่อจรรยาบรรณ"}, {"label": "E", "text": "แนะนำให้ผู้ป่วยฟ้องร้องโรงพยาบาลเดิม เพื่อให้ได้รับการชดเชย", "is_correct": false, "explanation": "การชักจูงให้ฟ้องร้องโดยไม่มีข้อเท็จจริงสนับสนุนไม่เหมาะสมและไม่ใช่บทบาทของการให้ความเห็นทางวิชาชีพ"}], "key_takeaway": "Second opinion เป็นสิทธิผู้ป่วย: ให้ความเห็นได้อย่างเป็นกลาง ไม่ตำหนิผู้ประกอบวิชาชีพเดิม ไม่สั่งหยุดยาเอง"}'::jsonb, 'medium', 'law-day1 • สิทธิผู้ป่วย: ความเห็นที่สองและความสัมพันธ์ระหว่างวิชาชีพ'),
('0bc0b54edea2fd1862d7b9c00c6c8429', 86, 'ข้อใดเป็นสิทธิของผู้ป่วยตามคำประกาศสิทธิและข้อพึงปฏิบัติของผู้ป่วย', '[{"label": "A", "text": "ได้รับยาทุกชนิดที่ตนร้องขอ แม้ไม่มีข้อบ่งใช้ทางการแพทย์"}, {"label": "B", "text": "ได้รับบริการทางสุขภาพโดยไม่ต้องชำระค่าใช้จ่ายในทุกกรณี"}, {"label": "C", "text": "ขอทราบข้อมูลสุขภาพของผู้ป่วยรายอื่นที่ใช้ยาชนิดเดียวกันเพื่อนำมาเปรียบเทียบ"}, {"label": "D", "text": "ได้รับบริการก่อนผู้อื่นเสมอเมื่อมาถึงก่อน แม้มีผู้ป่วยฉุกเฉินวิกฤตเข้ามาภายหลัง"}, {"label": "E", "text": "ทราบชื่อ สกุล และประเภทของผู้ประกอบวิชาชีพด้านสุขภาพที่เป็นผู้ให้บริการแก่ตน"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ทราบชื่อ สกุล และประเภทของผู้ประกอบวิชาชีพด้านสุขภาพที่เป็นผู้ให้บริการแก่ตน — ผู้ป่วยมีสิทธิทราบชื่อ สกุล และประเภทของผู้ประกอบวิชาชีพที่ให้บริการแก่ตน", "reason": "คำประกาศสิทธิและข้อพึงปฏิบัติของผู้ป่วยที่สภาวิชาชีพด้านสุขภาพร่วมกันประกาศ รับรองสิทธิหลายประการ เช่น สิทธิพื้นฐานที่จะได้รับการรักษาตามมาตรฐานโดยไม่เลือกปฏิบัติ สิทธิได้รับข้อมูลเพื่อตัดสินใจยินยอมหรือไม่ยินยอมรับการรักษา สิทธิได้รับการช่วยเหลือทันทีเมื่ออยู่ในภาวะฉุกเฉิน สิทธิทราบชื่อ สกุล และประเภทของผู้ประกอบวิชาชีพที่ให้บริการ สิทธิขอความเห็นที่สองและเปลี่ยนผู้ให้บริการ สิทธิในการรักษาความลับ และสิทธิเกี่ยวกับการวิจัยและเวชระเบียนของตน\n\nขณะเดียวกันผู้ป่วยก็มีข้อพึงปฏิบัติ เช่น ให้ข้อมูลสุขภาพที่เป็นจริงและครบถ้วน และปฏิบัติตามคำแนะนำของผู้ประกอบวิชาชีพ สิทธิผู้ป่วยไม่ได้หมายถึงการได้ทุกอย่างที่ร้องขอ", "choices": [{"label": "A", "text": "ได้รับยาทุกชนิดที่ตนร้องขอ แม้ไม่มีข้อบ่งใช้ทางการแพทย์", "is_correct": false, "explanation": "สิทธิผู้ป่วยไม่ได้รวมถึงการได้รับยาที่ไม่มีข้อบ่งใช้ ซึ่งอาจเป็นอันตราย"}, {"label": "B", "text": "ได้รับบริการทางสุขภาพโดยไม่ต้องชำระค่าใช้จ่ายในทุกกรณี", "is_correct": false, "explanation": "ค่าใช้จ่ายเป็นไปตามระบบหลักประกันและสิทธิของแต่ละบุคคล คำประกาศไม่ได้รับรองบริการฟรีทุกกรณี"}, {"label": "C", "text": "ขอทราบข้อมูลสุขภาพของผู้ป่วยรายอื่นที่ใช้ยาชนิดเดียวกันเพื่อนำมาเปรียบเทียบ", "is_correct": false, "explanation": "ข้อมูลของผู้ป่วยรายอื่นเป็นความลับ ไม่ใช่สิทธิของผู้ป่วยที่จะขอดู"}, {"label": "D", "text": "ได้รับบริการก่อนผู้อื่นเสมอเมื่อมาถึงก่อน แม้มีผู้ป่วยฉุกเฉินวิกฤตเข้ามาภายหลัง", "is_correct": false, "explanation": "ผู้ป่วยฉุกเฉินวิกฤตมีสิทธิได้รับการช่วยเหลือโดยทันที การจัดลำดับตามความเร่งด่วนเป็นสิ่งชอบธรรม"}, {"label": "E", "text": "ทราบชื่อ สกุล และประเภทของผู้ประกอบวิชาชีพด้านสุขภาพที่เป็นผู้ให้บริการแก่ตน", "is_correct": true, "explanation": "ถูกต้อง: ผู้ป่วยมีสิทธิทราบชื่อ สกุล และประเภทของผู้ประกอบวิชาชีพที่ให้บริการแก่ตน"}], "key_takeaway": "ผู้ป่วยมีสิทธิรู้ว่าใครเป็นผู้ให้บริการ (ชื่อ สกุล ประเภทวิชาชีพ) — เภสัชกรควรแสดงตนให้ผู้ป่วยทราบ"}'::jsonb, 'easy', 'law-day1 • คำประกาศสิทธิและข้อพึงปฏิบัติของผู้ป่วย'),
('48cce3a205f4abdd75375f453a48824b', 87, 'นาย ก. อายุ 30 ปี รับยาต้านไวรัสเอชไอวีต่อเนื่องที่หน่วยบริการของโรงพยาบาล วันหนึ่งภรรยาของนาย ก. มาที่ห้องจ่ายยาและถามเภสัชกรว่า "สามีกินยาอะไรอยู่ ทำไมต้องมารับยาทุกเดือน" เภสัชกรทราบจากเวชระเบียนว่านาย ก. ยังไม่ได้เปิดเผยผลเลือดแก่ภรรยา และนาย ก. ไม่เคยให้ความยินยอมในการเปิดเผยข้อมูล ข้อใดเป็นแนวทางที่เหมาะสมที่สุดทั้งในทางกฎหมายและจริยธรรม', '[{"label": "A", "text": "บอกภรรยาตามจริงทันที เพราะคู่สมรสตามกฎหมายมีสิทธิทราบข้อมูลสุขภาพของอีกฝ่าย"}, {"label": "B", "text": "ปฏิเสธการให้ข้อมูลแก่ภรรยา แล้วถือว่าเรื่องจบโดยไม่ต้องดำเนินการใดกับนาย ก. อีก"}, {"label": "C", "text": "ไม่บอกตรง ๆ แต่ยื่นซองยาให้ภรรยาดูชื่อยาเพื่อให้เข้าใจเอง"}, {"label": "D", "text": "ไม่เปิดเผยแก่ภรรยา แต่ให้คำปรึกษานาย ก. ให้เปิดเผยเอง และเชิญภรรยารับการปรึกษาของตน"}, {"label": "E", "text": "เปิดเผยข้อมูลได้ หากภรรยาเป็นผู้ชำระค่าใช้จ่ายในการรักษาและค่ายาของสามีมาโดยตลอด"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ไม่เปิดเผยแก่ภรรยา แต่ให้คำปรึกษานาย ก. ให้เปิดเผยเอง และเชิญภรรยารับการปรึกษาของตน — รักษาความลับของผู้ป่วยตาม ม.7 และ PDPA ควบคู่กับการลดความเสี่ยงต่อคู่ผ่านการให้คำปรึกษาผู้ป่วยให้เปิดเผยเอง และดูแลภรรยาในฐานะผู้รับบริการ", "reason": "ประเด็นกฎหมาย: ข้อมูลการติดเชื้อเอชไอวีเป็นข้อมูลสุขภาพที่อ่อนไหวสูง พ.ร.บ.สุขภาพแห่งชาติ มาตรา 7 ห้ามเปิดเผยในประการที่น่าจะทำให้เจ้าของข้อมูลเสียหาย เว้นแต่เป็นความประสงค์ของเจ้าตัวโดยตรงหรือมีกฎหมายเฉพาะบังคับ ความเป็นคู่สมรสหรือผู้ชำระเงินไม่ใช่ข้อยกเว้น และ พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคลกำหนดให้ข้อมูลสุขภาพเป็นข้อมูลอ่อนไหว\n\nประเด็นจริยธรรม: มีการถ่วงดุลระหว่าง confidentiality กับ beneficence/non-maleficence ต่อบุคคลที่สามซึ่งอาจมีความเสี่ยง แนวทางที่เป็นที่ยอมรับคือไม่เปิดเผยโดยพลการ แต่ให้คำปรึกษาผู้ป่วยถึงความสำคัญของการเปิดเผยแก่คู่ (partner notification) ด้วยความสมัครใจ โดยทีมสุขภาพช่วยสนับสนุน และเปิดช่องทางให้คู่เข้ารับการปรึกษาและตรวจในฐานะผู้รับบริการ\n\nการปฏิเสธเฉย ๆ ถูกต้องในแง่ความลับแต่ไม่ครบถ้วนในแง่หน้าที่ดูแล ส่วนการเปิดเผยทางอ้อม เช่น ให้ดูซองยา ก็ถือเป็นการละเมิดเช่นกัน", "choices": [{"label": "A", "text": "บอกภรรยาตามจริงทันที เพราะคู่สมรสตามกฎหมายมีสิทธิทราบข้อมูลสุขภาพของอีกฝ่าย", "is_correct": false, "explanation": "การเป็นคู่สมรสไม่ใช่ข้อยกเว้นของการรักษาความลับ การเปิดเผยโดยไม่ได้รับความยินยอมขัดต่อ ม.7 และจรรยาบรรณ"}, {"label": "B", "text": "ปฏิเสธการให้ข้อมูลแก่ภรรยา แล้วถือว่าเรื่องจบโดยไม่ต้องดำเนินการใดกับนาย ก. อีก", "is_correct": false, "explanation": "รักษาความลับได้ถูกต้อง แต่ละเลยหน้าที่ดูแลความเสี่ยงต่อบุคคลที่สาม ซึ่งควรจัดการผ่านการให้คำปรึกษาผู้ป่วย"}, {"label": "C", "text": "ไม่บอกตรง ๆ แต่ยื่นซองยาให้ภรรยาดูชื่อยาเพื่อให้เข้าใจเอง", "is_correct": false, "explanation": "เป็นการเปิดเผยข้อมูลโดยอ้อมซึ่งก็ถือเป็นการละเมิดความลับเช่นเดียวกัน"}, {"label": "D", "text": "ไม่เปิดเผยแก่ภรรยา แต่ให้คำปรึกษานาย ก. ให้เปิดเผยเอง และเชิญภรรยารับการปรึกษาของตน", "is_correct": true, "explanation": "ถูกต้อง: รักษาความลับของผู้ป่วยตาม ม.7 และ PDPA ควบคู่กับการลดความเสี่ยงต่อคู่ผ่านการให้คำปรึกษาผู้ป่วยให้เปิดเผยเอง และดูแลภรรยาในฐานะผู้รับบริการ"}, {"label": "E", "text": "เปิดเผยข้อมูลได้ หากภรรยาเป็นผู้ชำระค่าใช้จ่ายในการรักษาและค่ายาของสามีมาโดยตลอด", "is_correct": false, "explanation": "การเป็นผู้ชำระเงินไม่ทำให้มีสิทธิในข้อมูลสุขภาพของผู้อื่น"}], "key_takeaway": "ข้อมูลเอชไอวีห้ามเปิดเผยแก่คู่โดยพลการ ทางออกคือให้คำปรึกษาผู้ป่วยให้เปิดเผยเองและดูแลคู่ในฐานะผู้รับบริการ"}'::jsonb, 'hard', 'law-day1 • การรักษาความลับ: ข้อมูลอ่อนไหวกับความเสี่ยงต่อบุคคลที่สาม'),
('1aea3f8904d5d23e4be30cc073d3f654', 88, 'เภสัชกรร้าน ก. พบว่าผู้ป่วยรายหนึ่งได้รับยาจากร้าน ข. ซึ่งอยู่ใกล้เคียง โดยฉลากระบุวิธีใช้ที่ไม่ถูกต้องจนอาจเกิดอันตราย ผู้ป่วยถามว่า "ร้านนั้นแย่มากใช่ไหม" ข้อใดเป็นการปฏิบัติที่เหมาะสมที่สุดตามจรรยาบรรณ', '[{"label": "A", "text": "โพสต์ภาพฉลากยาลงโซเชียลมีเดียเพื่อเตือนประชาชนเกี่ยวกับร้าน ข."}, {"label": "B", "text": "แก้ไขให้ผู้ป่วยใช้ยาปลอดภัย ตอบตามข้อเท็จจริงโดยไม่กล่าวร้าย และติดต่อร้าน ข. โดยตรง"}, {"label": "C", "text": "บอกผู้ป่วยว่าร้าน ข. ไม่มีเภสัชกรอยู่จริง แม้ตนเองไม่ทราบข้อเท็จจริง"}, {"label": "D", "text": "ไม่บอกอะไรเลยและปล่อยให้ผู้ป่วยใช้ยาตามฉลากเดิม เพื่อรักษามารยาทกับผู้ร่วมวิชาชีพ"}, {"label": "E", "text": "แก้ฉลากให้ผู้ป่วยแล้วเสนอส่วนลดพิเศษเพื่อให้ผู้ป่วยเปลี่ยนมาซื้อยาที่ร้านตนเองเป็นประจำ"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. แก้ไขให้ผู้ป่วยใช้ยาปลอดภัย ตอบตามข้อเท็จจริงโดยไม่กล่าวร้าย และติดต่อร้าน ข. โดยตรง — ความปลอดภัยของผู้ป่วยมาก่อน โดยสื่อสารตามข้อเท็จจริงและไม่ทำให้ผู้ร่วมวิชาชีพเสื่อมเสียหรือแย่งลูกค้า", "reason": "ข้อบังคับว่าด้วยจรรยาบรรณแห่งวิชาชีพเภสัชกรรมกำหนดให้ผู้ประกอบวิชาชีพให้เกียรติและไม่กล่าวร้าย ใส่ความ หรือทำให้ผู้ร่วมวิชาชีพเสื่อมเสีย และไม่แข่งขันในทางที่ไม่เหมาะสม แต่ทั้งนี้ไม่ได้หมายถึงการปิดบังปัญหาที่กระทบความปลอดภัยของผู้ป่วย\n\nแนวทางที่เหมาะสมคือแก้ไขให้ผู้ป่วยปลอดภัยก่อน ให้ข้อมูลตามข้อเท็จจริงโดยไม่ตัดสินบุคคล และสื่อสารกับผู้ร่วมวิชาชีพโดยตรงเพื่อป้องกันการเกิดซ้ำ หากเป็นปัญหาร้ายแรงหรือซ้ำซากจึงใช้กลไกที่เป็นทางการ เช่น การกล่าวโทษต่อสภาเภสัชกรรม", "choices": [{"label": "A", "text": "โพสต์ภาพฉลากยาลงโซเชียลมีเดียเพื่อเตือนประชาชนเกี่ยวกับร้าน ข.", "is_correct": false, "explanation": "การประจานผู้ร่วมวิชาชีพต่อสาธารณะไม่ใช่ช่องทางที่เหมาะสม และอาจเปิดเผยข้อมูลผู้ป่วยด้วย"}, {"label": "B", "text": "แก้ไขให้ผู้ป่วยใช้ยาปลอดภัย ตอบตามข้อเท็จจริงโดยไม่กล่าวร้าย และติดต่อร้าน ข. โดยตรง", "is_correct": true, "explanation": "ถูกต้อง: ความปลอดภัยของผู้ป่วยมาก่อน โดยสื่อสารตามข้อเท็จจริงและไม่ทำให้ผู้ร่วมวิชาชีพเสื่อมเสียหรือแย่งลูกค้า"}, {"label": "C", "text": "บอกผู้ป่วยว่าร้าน ข. ไม่มีเภสัชกรอยู่จริง แม้ตนเองไม่ทราบข้อเท็จจริง", "is_correct": false, "explanation": "เป็นการกล่าวข้อความที่ไม่มีมูลซึ่งทำให้ผู้ร่วมวิชาชีพเสื่อมเสีย ขัดจรรยาบรรณและ veracity"}, {"label": "D", "text": "ไม่บอกอะไรเลยและปล่อยให้ผู้ป่วยใช้ยาตามฉลากเดิม เพื่อรักษามารยาทกับผู้ร่วมวิชาชีพ", "is_correct": false, "explanation": "ความปลอดภัยของผู้ป่วยต้องมาก่อน การนิ่งเฉยทั้งที่รู้ว่าอาจเกิดอันตรายขัดหลัก non-maleficence"}, {"label": "E", "text": "แก้ฉลากให้ผู้ป่วยแล้วเสนอส่วนลดพิเศษเพื่อให้ผู้ป่วยเปลี่ยนมาซื้อยาที่ร้านตนเองเป็นประจำ", "is_correct": false, "explanation": "การใช้ความผิดพลาดของผู้อื่นเพื่อแย่งลูกค้าเป็นการแข่งขันที่ไม่เหมาะสมตามจรรยาบรรณ"}], "key_takeaway": "แก้ปัญหาให้ผู้ป่วยปลอดภัยและสื่อสารกับผู้ร่วมวิชาชีพโดยตรง ไม่ประจาน ไม่กล่าวร้าย ไม่ใช้เป็นโอกาสแย่งลูกค้า"}'::jsonb, 'medium', 'law-day1 • จรรยาบรรณ: ความสัมพันธ์กับผู้ร่วมวิชาชีพ'),
('a83f7ea853cf46609a0a97b84388a463', 89, 'เภสัชกรโรงพยาบาลต้องการศึกษาย้อนหลังจากเวชระเบียนเกี่ยวกับอุบัติการณ์อาการไม่พึงประสงค์จากยาชนิดหนึ่งในช่วง 3 ปีที่ผ่านมา เพื่อนำเสนอในที่ประชุมวิชาการและตีพิมพ์ในวารสาร ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ต้องได้รับการพิจารณาจากคณะกรรมการจริยธรรมการวิจัยในมนุษย์ก่อนเริ่มเก็บข้อมูล"}, {"label": "B", "text": "ไม่ต้องผ่านคณะกรรมการจริยธรรม เพราะเป็นการศึกษาย้อนหลังที่ไม่ได้ทำอะไรกับผู้ป่วยโดยตรง"}, {"label": "C", "text": "เก็บข้อมูลก่อนได้ แล้วจึงยื่นขออนุมัติจากคณะกรรมการจริยธรรมก่อนส่งตีพิมพ์"}, {"label": "D", "text": "ได้รับอนุญาตจากหัวหน้ากลุ่มงานเภสัชกรรมเพียงอย่างเดียวก็เพียงพอ"}, {"label": "E", "text": "ไม่ต้องผ่านคณะกรรมการจริยธรรม หากตัดชื่อผู้ป่วยออกในขั้นตอนเขียนรายงาน"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ต้องได้รับการพิจารณาจากคณะกรรมการจริยธรรมการวิจัยในมนุษย์ก่อนเริ่มเก็บข้อมูล — การวิจัยที่ใช้ข้อมูลจากเวชระเบียนต้องได้รับการพิจารณาจาก EC ก่อนเริ่ม และ EC เป็นผู้ตัดสินเรื่องการยกเว้นความยินยอม", "reason": "หลักจริยธรรมการวิจัยในมนุษย์ (ปฏิญญาเฮลซิงกิ และแนวทางจริยธรรมการทำวิจัยในคนในประเทศไทย) กำหนดให้โครงร่างการวิจัยที่เกี่ยวข้องกับมนุษย์ รวมถึงการใช้ข้อมูลหรือสิ่งส่งตรวจที่ระบุตัวบุคคลได้ ต้องผ่านการพิจารณาและรับรองจากคณะกรรมการจริยธรรมการวิจัยที่เป็นอิสระก่อนเริ่มดำเนินการ\n\nสำหรับการศึกษาย้อนหลังที่มีความเสี่ยงต่ำ EC อาจพิจารณาให้ยกเว้นการขอความยินยอมรายบุคคล (waiver of consent) หรือจัดเป็นประเภทพิจารณาแบบยกเว้น/เร่งรัดได้ แต่การตัดสินนั้นเป็นอำนาจของ EC ไม่ใช่ของผู้วิจัยเอง นอกจากนี้ผู้วิจัยต้องคุ้มครองข้อมูลส่วนบุคคลตามหลัก PDPA ด้วย", "choices": [{"label": "A", "text": "ต้องได้รับการพิจารณาจากคณะกรรมการจริยธรรมการวิจัยในมนุษย์ก่อนเริ่มเก็บข้อมูล", "is_correct": true, "explanation": "ถูกต้อง: การวิจัยที่ใช้ข้อมูลจากเวชระเบียนต้องได้รับการพิจารณาจาก EC ก่อนเริ่ม และ EC เป็นผู้ตัดสินเรื่องการยกเว้นความยินยอม"}, {"label": "B", "text": "ไม่ต้องผ่านคณะกรรมการจริยธรรม เพราะเป็นการศึกษาย้อนหลังที่ไม่ได้ทำอะไรกับผู้ป่วยโดยตรง", "is_correct": false, "explanation": "การวิจัยที่ใช้ข้อมูลส่วนบุคคลจากเวชระเบียนยังเป็นการวิจัยในมนุษย์ที่ต้องผ่านการพิจารณาของ EC"}, {"label": "C", "text": "เก็บข้อมูลก่อนได้ แล้วจึงยื่นขออนุมัติจากคณะกรรมการจริยธรรมก่อนส่งตีพิมพ์", "is_correct": false, "explanation": "การรับรองจาก EC ต้องได้ก่อนเริ่มดำเนินการวิจัย การขอย้อนหลังไม่เป็นที่ยอมรับ"}, {"label": "D", "text": "ได้รับอนุญาตจากหัวหน้ากลุ่มงานเภสัชกรรมเพียงอย่างเดียวก็เพียงพอ", "is_correct": false, "explanation": "การอนุญาตทางบริหารไม่ใช่การพิจารณาด้านจริยธรรมการวิจัยโดยคณะกรรมการที่เป็นอิสระ"}, {"label": "E", "text": "ไม่ต้องผ่านคณะกรรมการจริยธรรม หากตัดชื่อผู้ป่วยออกในขั้นตอนเขียนรายงาน", "is_correct": false, "explanation": "การเข้าถึงข้อมูลที่ระบุตัวตนเกิดขึ้นแล้วตั้งแต่การเก็บข้อมูล และผู้วิจัยไม่ควรตัดสินยกเว้นการพิจารณาจริยธรรมด้วยตนเอง"}], "key_takeaway": "ทุกการวิจัยในมนุษย์ รวมถึงการทบทวนเวชระเบียน ต้องผ่าน EC ก่อนเริ่ม ผู้วิจัยยกเว้นให้ตัวเองไม่ได้"}'::jsonb, 'medium', 'law-day1 • การวิจัยในมนุษย์: คณะกรรมการจริยธรรมการวิจัย (EC/IRB)'),
('be442bd9287b3ed5590dca6c86f8beab', 90, 'เภสัชกรมานพเปิดไลฟ์สดขายผลิตภัณฑ์เสริมอาหารผ่านเพจที่ระบุว่าตนเป็น "เภสัชกร" ระหว่างไลฟ์เขากล่าวว่าผลิตภัณฑ์ "ช่วยรักษาโรคไตเสื่อม ไม่ต้องฟอกไต" และแสดงภาพแคปหน้าจอแชทของลูกค้าซึ่งเห็นชื่อบัญชี รูปโปรไฟล์ และข้อความเล่าว่าตนเป็นโรคไตระยะใด เพื่อใช้เป็นรีวิว โดยไม่ได้ขออนุญาตลูกค้า ข้อใดวิเคราะห์ได้ถูกต้องที่สุด', '[{"label": "A", "text": "ไม่มีความผิด เพราะลูกค้าส่งข้อความมาเองโดยสมัครใจ ถือว่ายินยอมให้นำไปเผยแพร่แล้ว"}, {"label": "B", "text": "ผิดเฉพาะเรื่องการโฆษณาเกินจริง ส่วนการแสดงแชทไม่ผิดเพราะลูกค้าเป็นผู้เปิดเผยข้อมูลของตนเองก่อน"}, {"label": "C", "text": "ผิดทั้งการเผยแพร่ข้อมูลสุขภาพลูกค้าโดยไม่ได้รับความยินยอม และการโฆษณาอ้างสรรพคุณรักษาโรค"}, {"label": "D", "text": "ไม่ผิดจรรยาบรรณ เพราะผลิตภัณฑ์เสริมอาหารไม่ใช่ยา จึงอยู่นอกขอบเขตวิชาชีพเภสัชกรรม"}, {"label": "E", "text": "ผิดเฉพาะเรื่องการแสดงแชท หากเบลอชื่อบัญชีและรูปโปรไฟล์แล้ว การไลฟ์ทั้งหมดก็ไม่มีปัญหาใด"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ผิดทั้งการเผยแพร่ข้อมูลสุขภาพลูกค้าโดยไม่ได้รับความยินยอม และการโฆษณาอ้างสรรพคุณรักษาโรค — กรณีนี้ละเมิดทั้งความลับ/ข้อมูลอ่อนไหวของลูกค้า และเป็นการโฆษณาสรรพคุณรักษาโรคเกินจริงโดยอาศัยสถานะวิชาชีพ", "reason": "ประเด็นที่ 1 ความลับและข้อมูลส่วนบุคคล: ข้อมูลว่าลูกค้าเป็นโรคไตระยะใดเป็นข้อมูลสุขภาพ ซึ่งเป็นข้อมูลอ่อนไหวตาม พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคล และเป็นความลับตาม พ.ร.บ.สุขภาพแห่งชาติ มาตรา 7 รวมทั้งตามจรรยาบรรณ การนำไปเผยแพร่โดยระบุตัวตนได้และไม่มีความยินยอมโดยชัดแจ้งจึงเป็นการละเมิด การที่ลูกค้าส่งข้อความปรึกษาเภสัชกรเป็นการเฉพาะไม่ใช่การยินยอมให้เผยแพร่\n\nประเด็นที่ 2 การโฆษณา: การใช้ตำแหน่งเภสัชกรรับรองว่าผลิตภัณฑ์เสริมอาหาร \"รักษาโรคไต ไม่ต้องฟอกไต\" เป็นการโฆษณาโอ้อวดเกินจริงที่ขัดต่อจรรยาบรรณ และกฎหมายว่าด้วยอาหารไม่อนุญาตให้โฆษณาผลิตภัณฑ์เสริมอาหารว่ามีสรรพคุณบำบัดรักษาโรค อีกทั้งอาจทำให้ผู้ป่วยหยุดการรักษาที่จำเป็น ขัดหลัก non-maleficence\n\nจรรยาบรรณใช้กับพฤติกรรมของผู้ประกอบวิชาชีพที่แสดงตนเป็นเภสัชกร ไม่ได้จำกัดเฉพาะการจ่ายยา", "choices": [{"label": "A", "text": "ไม่มีความผิด เพราะลูกค้าส่งข้อความมาเองโดยสมัครใจ ถือว่ายินยอมให้นำไปเผยแพร่แล้ว", "is_correct": false, "explanation": "การส่งข้อความปรึกษาไม่ใช่ความยินยอมโดยชัดแจ้งให้นำข้อมูลสุขภาพไปเผยแพร่ต่อสาธารณะ"}, {"label": "B", "text": "ผิดเฉพาะเรื่องการโฆษณาเกินจริง ส่วนการแสดงแชทไม่ผิดเพราะลูกค้าเป็นผู้เปิดเผยข้อมูลของตนเองก่อน", "is_correct": false, "explanation": "ลูกค้าเปิดเผยแก่เภสัชกรเป็นการเฉพาะ ไม่ได้เปิดเผยต่อสาธารณะ การนำไปเผยแพร่จึงละเมิดความลับและข้อมูลอ่อนไหว"}, {"label": "C", "text": "ผิดทั้งการเผยแพร่ข้อมูลสุขภาพลูกค้าโดยไม่ได้รับความยินยอม และการโฆษณาอ้างสรรพคุณรักษาโรค", "is_correct": true, "explanation": "ถูกต้อง: กรณีนี้ละเมิดทั้งความลับ/ข้อมูลอ่อนไหวของลูกค้า และเป็นการโฆษณาสรรพคุณรักษาโรคเกินจริงโดยอาศัยสถานะวิชาชีพ"}, {"label": "D", "text": "ไม่ผิดจรรยาบรรณ เพราะผลิตภัณฑ์เสริมอาหารไม่ใช่ยา จึงอยู่นอกขอบเขตวิชาชีพเภสัชกรรม", "is_correct": false, "explanation": "เมื่อใช้สถานะเภสัชกรให้ข้อมูลสุขภาพแก่ประชาชน จรรยาบรรณวิชาชีพย่อมใช้บังคับ และกฎหมายอาหารก็ห้ามโฆษณาว่ามีสรรพคุณรักษาโรค"}, {"label": "E", "text": "ผิดเฉพาะเรื่องการแสดงแชท หากเบลอชื่อบัญชีและรูปโปรไฟล์แล้ว การไลฟ์ทั้งหมดก็ไม่มีปัญหาใด", "is_correct": false, "explanation": "แม้ปกปิดตัวตนแล้ว การกล่าวอ้างว่ารักษาโรคไตได้ยังเป็นการโฆษณาเกินจริงที่ขัดต่อจรรยาบรรณและกฎหมาย"}], "key_takeaway": "บนสื่อออนไลน์ เภสัชกรยังผูกพันจรรยาบรรณ: ห้ามเผยแพร่ข้อมูลสุขภาพลูกค้าโดยไม่ได้รับความยินยอม และห้ามอ้างสรรพคุณรักษาโรคเกินจริง"}'::jsonb, 'hard', 'law-day1 • จรรยาบรรณ: การโฆษณาผ่านสื่อออนไลน์และการรักษาความลับ'),
('1106d3e683a75d501ec5afb619b56c1e', 91, 'ตาม พ.ร.บ.คุ้มครองผู้บริโภค พ.ศ. 2522 (และที่แก้ไขเพิ่มเติม) ผู้บริโภคมีสิทธิได้รับความคุ้มครอง 5 ประการ ข้อใด “ไม่ใช่” สิทธิของผู้บริโภคตามกฎหมายนี้', '[{"label": "A", "text": "สิทธิที่จะได้รับข่าวสารรวมทั้งคำพรรณนาคุณภาพที่ถูกต้องและเพียงพอเกี่ยวกับสินค้าหรือบริการ"}, {"label": "B", "text": "สิทธิที่จะมีอิสระในการเลือกหาสินค้าหรือบริการ"}, {"label": "C", "text": "สิทธิที่จะได้ซื้อสินค้าหรือบริการทุกรายการในราคาที่รัฐเป็นผู้กำหนด"}, {"label": "D", "text": "สิทธิที่จะได้รับความปลอดภัยจากการใช้สินค้าหรือบริการ"}, {"label": "E", "text": "สิทธิที่จะได้รับการพิจารณาและชดเชยความเสียหาย"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. สิทธิที่จะได้ซื้อสินค้าหรือบริการทุกรายการในราคาที่รัฐเป็นผู้กำหนด — กฎหมายไม่ได้รับรองสิทธิให้ผู้บริโภคได้ซื้อสินค้าทุกรายการในราคาที่รัฐกำหนด การควบคุมราคาเป็นเรื่องของกฎหมายว่าด้วยราคาสินค้าและบริการซึ่งใช้เฉพาะสินค้าควบคุม จึงไม่ใช่หนึ่งในสิทธิผู้บริโภค 5 ประการ", "reason": "พ.ร.บ.คุ้มครองผู้บริโภค พ.ศ. 2522 (แก้ไขเพิ่มเติม พ.ศ. 2541) รับรองสิทธิผู้บริโภค 5 ประการ ได้แก่ (1) สิทธิที่จะได้รับข่าวสารรวมทั้งคำพรรณนาคุณภาพที่ถูกต้องและเพียงพอ (2) สิทธิที่จะมีอิสระในการเลือกหาสินค้าหรือบริการ (3) สิทธิที่จะได้รับความปลอดภัยจากการใช้สินค้าหรือบริการ (4) สิทธิที่จะได้รับความเป็นธรรมในการทำสัญญา และ (5) สิทธิที่จะได้รับการพิจารณาและชดเชยความเสียหาย\n\nการซื้อสินค้าในราคาที่รัฐกำหนดไม่ใช่สิทธิผู้บริโภคตามกฎหมายฉบับนี้ แม้รัฐอาจควบคุมราคาสินค้าบางรายการได้ตามกฎหมายอื่น", "choices": [{"label": "A", "text": "สิทธิที่จะได้รับข่าวสารรวมทั้งคำพรรณนาคุณภาพที่ถูกต้องและเพียงพอเกี่ยวกับสินค้าหรือบริการ", "is_correct": false, "explanation": "เป็นสิทธิผู้บริโภคประการแรกตามกฎหมาย ซึ่งเป็นฐานของการควบคุมฉลากและโฆษณา"}, {"label": "B", "text": "สิทธิที่จะมีอิสระในการเลือกหาสินค้าหรือบริการ", "is_correct": false, "explanation": "เป็นสิทธิผู้บริโภคตามกฎหมาย ผู้บริโภคต้องเลือกซื้อได้โดยไม่ถูกบังคับหรือชักจูงโดยไม่เป็นธรรม"}, {"label": "C", "text": "สิทธิที่จะได้ซื้อสินค้าหรือบริการทุกรายการในราคาที่รัฐเป็นผู้กำหนด", "is_correct": true, "explanation": "กฎหมายไม่ได้รับรองสิทธิให้ผู้บริโภคได้ซื้อสินค้าทุกรายการในราคาที่รัฐกำหนด การควบคุมราคาเป็นเรื่องของกฎหมายว่าด้วยราคาสินค้าและบริการซึ่งใช้เฉพาะสินค้าควบคุม จึงไม่ใช่หนึ่งในสิทธิผู้บริโภค 5 ประการ"}, {"label": "D", "text": "สิทธิที่จะได้รับความปลอดภัยจากการใช้สินค้าหรือบริการ", "is_correct": false, "explanation": "เป็นสิทธิผู้บริโภคตามกฎหมาย สินค้าต้องปลอดภัยเมื่อใช้ตามคำแนะนำหรือตามปกติ"}, {"label": "E", "text": "สิทธิที่จะได้รับการพิจารณาและชดเชยความเสียหาย", "is_correct": false, "explanation": "เป็นสิทธิผู้บริโภคตามกฎหมาย เมื่อถูกละเมิดสิทธิผู้บริโภคมีสิทธิได้รับการพิจารณาและชดเชย"}], "key_takeaway": "สิทธิผู้บริโภค 5 ประการ คือ ได้รับข่าวสารถูกต้อง, อิสระในการเลือก, ความปลอดภัย, ความเป็นธรรมในการทำสัญญา และการพิจารณาชดเชยความเสียหาย"}'::jsonb, 'easy', 'law-day1 • พ.ร.บ.คุ้มครองผู้บริโภค – สิทธิผู้บริโภค 5 ประการ'),
('8831fc45839fff7fa099ffd9d43ae441', 92, 'หลักการสำคัญของ พ.ร.บ.ความรับผิดต่อความเสียหายที่เกิดขึ้นจากสินค้าที่ไม่ปลอดภัย พ.ศ. 2551 ที่ทำให้ผู้เสียหายฟ้องได้ง่ายกว่าการฟ้องละเมิดทั่วไปตามประมวลกฎหมายแพ่งและพาณิชย์ คือข้อใด', '[{"label": "A", "text": "ผู้ประกอบการต้องรับผิดโดยผู้เสียหายไม่ต้องพิสูจน์ว่าเกิดจากความจงใจหรือประมาทเลินเล่อ"}, {"label": "B", "text": "ผู้เสียหายต้องพิสูจน์ให้ได้ว่าผู้ผลิตประมาทเลินเล่อในขั้นตอนการผลิต"}, {"label": "C", "text": "ผู้ประกอบการรับผิดเฉพาะเมื่อสินค้านั้นไม่ได้ขึ้นทะเบียนกับหน่วยงานรัฐ"}, {"label": "D", "text": "ใช้บังคับเฉพาะกรณีผู้เสียหายซื้อสินค้าโดยตรงจากผู้ผลิตเท่านั้น"}, {"label": "E", "text": "ผู้ขายปลีกทุกรายต้องรับผิดเป็นลำดับแรกก่อนผู้ผลิตเสมอ"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ผู้ประกอบการต้องรับผิดโดยผู้เสียหายไม่ต้องพิสูจน์ว่าเกิดจากความจงใจหรือประมาทเลินเล่อ — เป็นหลักความรับผิดโดยเคร่งครัด (strict liability) ผู้ประกอบการต้องร่วมกันรับผิดไม่ว่าความเสียหายจะเกิดจากการกระทำโดยจงใจหรือประมาทเลินเล่อหรือไม่", "reason": "พ.ร.บ.ความรับผิดต่อความเสียหายที่เกิดขึ้นจากสินค้าที่ไม่ปลอดภัย พ.ศ. 2551 วางหลักว่าผู้ประกอบการทุกคนต้องร่วมกันรับผิดต่อผู้เสียหายในความเสียหายที่เกิดจากสินค้าที่ไม่ปลอดภัยซึ่งได้ขายให้แก่ผู้บริโภคแล้ว ไม่ว่าความเสียหายนั้นจะเกิดจากการกระทำโดยจงใจหรือประมาทเลินเล่อหรือไม่ (strict liability)\n\nผู้เสียหายเพียงพิสูจน์ว่าได้รับความเสียหายจากสินค้าของผู้ประกอบการ และการใช้หรือเก็บรักษาสินค้าเป็นไปตามปกติธรรมดา โดยไม่ต้องพิสูจน์ว่าความเสียหายเกิดจากการกระทำของผู้ประกอบการคนใด ซึ่งช่วยลดภาระการพิสูจน์ของผู้บริโภคอย่างมาก", "choices": [{"label": "A", "text": "ผู้ประกอบการต้องรับผิดโดยผู้เสียหายไม่ต้องพิสูจน์ว่าเกิดจากความจงใจหรือประมาทเลินเล่อ", "is_correct": true, "explanation": "ถูกต้อง เป็นหลักความรับผิดโดยเคร่งครัด (strict liability) ผู้ประกอบการต้องร่วมกันรับผิดไม่ว่าความเสียหายจะเกิดจากการกระทำโดยจงใจหรือประมาทเลินเล่อหรือไม่"}, {"label": "B", "text": "ผู้เสียหายต้องพิสูจน์ให้ได้ว่าผู้ผลิตประมาทเลินเล่อในขั้นตอนการผลิต", "is_correct": false, "explanation": "เป็นภาระการพิสูจน์แบบละเมิดทั่วไป ซึ่งกฎหมายนี้ยกเลิกไปสำหรับความเสียหายจากสินค้าที่ไม่ปลอดภัย"}, {"label": "C", "text": "ผู้ประกอบการรับผิดเฉพาะเมื่อสินค้านั้นไม่ได้ขึ้นทะเบียนกับหน่วยงานรัฐ", "is_correct": false, "explanation": "การได้รับอนุญาตหรือขึ้นทะเบียนไม่ใช่เหตุยกเว้นความรับผิด สินค้าที่ขึ้นทะเบียนแล้วก็อาจเป็นสินค้าที่ไม่ปลอดภัยได้"}, {"label": "D", "text": "ใช้บังคับเฉพาะกรณีผู้เสียหายซื้อสินค้าโดยตรงจากผู้ผลิตเท่านั้น", "is_correct": false, "explanation": "กฎหมายไม่ต้องอาศัยความสัมพันธ์ทางสัญญา ผู้เสียหายอาจเป็นผู้ใช้หรือบุคคลอื่นที่ได้รับความเสียหายก็ได้"}, {"label": "E", "text": "ผู้ขายปลีกทุกรายต้องรับผิดเป็นลำดับแรกก่อนผู้ผลิตเสมอ", "is_correct": false, "explanation": "ผู้ขายเป็นผู้ประกอบการที่ต้องรับผิดเฉพาะกรณีไม่สามารถระบุตัวผู้ผลิต ผู้ว่าจ้างให้ผลิต หรือผู้นำเข้าได้ ไม่ใช่ลำดับแรกเสมอ"}], "key_takeaway": "ความรับผิดจากสินค้าที่ไม่ปลอดภัยเป็นความรับผิดโดยเคร่งครัด ผู้เสียหายไม่ต้องพิสูจน์ความจงใจหรือประมาทเลินเล่อของผู้ประกอบการ"}'::jsonb, 'easy', 'law-day1 • พ.ร.บ.ความรับผิดต่อความเสียหายจากสินค้าที่ไม่ปลอดภัย – หลักความรับผิดโดยเคร่งครัด'),
('c1c8ea01a856dfe253022bfeab7a9dc6', 93, 'ร้านยาแห่งหนึ่งจำหน่ายผลิตภัณฑ์เสริมอาหารที่ผลิตในต่างประเทศ ฉลากภาษาไทยระบุชื่อและที่ตั้งของบริษัทผู้นำเข้าในประเทศไทยไว้ชัดเจน ต่อมาพบว่าผลิตภัณฑ์รุ่นการผลิตหนึ่งปนเปื้อนโลหะหนักจากกระบวนการผลิตที่โรงงานต่างประเทศ ทำให้ผู้บริโภคซึ่งรับประทานตามวิธีใช้บนฉลากได้รับอันตราย ผู้บริโภคต้องการเรียกค่าเสียหายตาม พ.ร.บ.ความรับผิดต่อความเสียหายที่เกิดขึ้นจากสินค้าที่ไม่ปลอดภัย พ.ศ. 2551 ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ร้านยาต้องรับผิดแต่เพียงผู้เดียว เพราะเป็นผู้ขายสินค้าให้ผู้บริโภคโดยตรง"}, {"label": "B", "text": "ผู้บริโภคต้องพิสูจน์ก่อนว่าบริษัทผู้นำเข้าประมาทเลินเล่อในการตรวจสอบคุณภาพ จึงจะเรียกค่าเสียหายได้"}, {"label": "C", "text": "ไม่มีผู้ใดต้องรับผิด เพราะผลิตภัณฑ์ได้รับเลขสารบบอาหารจาก อย. แล้ว"}, {"label": "D", "text": "ผู้ผลิตในต่างประเทศเท่านั้นที่ต้องรับผิด เนื่องจากความบกพร่องเกิดขึ้นในขั้นตอนการผลิต"}, {"label": "E", "text": "ผู้ผลิตและบริษัทผู้นำเข้าต้องร่วมกันรับผิด ส่วนร้านยาไม่เป็นผู้ประกอบการที่ต้องรับผิดตามกฎหมายนี้เพราะระบุตัวผู้นำเข้าได้"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ผู้ผลิตและบริษัทผู้นำเข้าต้องร่วมกันรับผิด ส่วนร้านยาไม่เป็นผู้ประกอบการที่ต้องรับผิดตามกฎหมายนี้เพราะระบุตัวผู้นำเข้าได้ — ผู้ผลิตและผู้นำเข้าเป็นผู้ประกอบการตามกฎหมายนี้และต้องร่วมกันรับผิด ส่วนผู้ขายจะเป็นผู้ประกอบการที่ต้องรับผิดเฉพาะเมื่อไม่สามารถระบุตัวผู้ผลิต ผู้ว่าจ้างให้ผลิต หรือผู้นำเข้าได้", "reason": "พ.ร.บ.ความรับผิดต่อความเสียหายที่เกิดขึ้นจากสินค้าที่ไม่ปลอดภัย พ.ศ. 2551 นิยาม “ผู้ประกอบการ” ให้รวมถึงผู้ผลิตหรือผู้ว่าจ้างให้ผลิต ผู้นำเข้า ผู้ขายที่ไม่สามารถระบุตัวผู้ผลิต ผู้ว่าจ้างให้ผลิต หรือผู้นำเข้าได้ และผู้ซึ่งใช้ชื่อ ชื่อทางการค้า หรือเครื่องหมายใด ๆ อันทำให้เข้าใจว่าเป็นผู้ผลิต ผู้ประกอบการทุกคนต้องร่วมกันรับผิดต่อผู้เสียหายโดยไม่ต้องพิสูจน์ความผิด\n\nในกรณีนี้ฉลากระบุตัวผู้นำเข้าได้ชัดเจน ร้านยาจึงไม่ใช่ผู้ประกอบการที่ต้องรับผิดตามกฎหมายนี้ (แต่ยังอาจมีหน้าที่หรือความรับผิดตามกฎหมายอื่น เช่น งดจำหน่ายสินค้าที่ไม่ปลอดภัยเมื่อทราบ) ส่วนผู้ผลิตและผู้นำเข้าต้องร่วมกันรับผิด", "choices": [{"label": "A", "text": "ร้านยาต้องรับผิดแต่เพียงผู้เดียว เพราะเป็นผู้ขายสินค้าให้ผู้บริโภคโดยตรง", "is_correct": false, "explanation": "ผิด ผู้ขายที่ระบุตัวผู้นำเข้าได้ไม่อยู่ในนิยามผู้ประกอบการที่ต้องรับผิดตามกฎหมายนี้ และกฎหมายไม่ได้ให้ผู้ขายรับผิดแต่เพียงผู้เดียว"}, {"label": "B", "text": "ผู้บริโภคต้องพิสูจน์ก่อนว่าบริษัทผู้นำเข้าประมาทเลินเล่อในการตรวจสอบคุณภาพ จึงจะเรียกค่าเสียหายได้", "is_correct": false, "explanation": "ผิด กฎหมายนี้ใช้หลักความรับผิดโดยเคร่งครัด ผู้เสียหายไม่ต้องพิสูจน์ความประมาทเลินเล่อ"}, {"label": "C", "text": "ไม่มีผู้ใดต้องรับผิด เพราะผลิตภัณฑ์ได้รับเลขสารบบอาหารจาก อย. แล้ว", "is_correct": false, "explanation": "ผิด การได้รับอนุญาตจากหน่วยงานรัฐไม่ใช่เหตุยกเว้นความรับผิด สินค้าที่ปนเปื้อนจนก่ออันตรายยังเป็นสินค้าที่ไม่ปลอดภัย"}, {"label": "D", "text": "ผู้ผลิตในต่างประเทศเท่านั้นที่ต้องรับผิด เนื่องจากความบกพร่องเกิดขึ้นในขั้นตอนการผลิต", "is_correct": false, "explanation": "ผิด ผู้นำเข้าเป็นผู้ประกอบการที่ต้องร่วมรับผิดด้วย กฎหมายกำหนดเช่นนี้เพื่อให้ผู้เสียหายในประเทศเรียกร้องได้จริง"}, {"label": "E", "text": "ผู้ผลิตและบริษัทผู้นำเข้าต้องร่วมกันรับผิด ส่วนร้านยาไม่เป็นผู้ประกอบการที่ต้องรับผิดตามกฎหมายนี้เพราะระบุตัวผู้นำเข้าได้", "is_correct": true, "explanation": "ถูกต้อง ผู้ผลิตและผู้นำเข้าเป็นผู้ประกอบการตามกฎหมายนี้และต้องร่วมกันรับผิด ส่วนผู้ขายจะเป็นผู้ประกอบการที่ต้องรับผิดเฉพาะเมื่อไม่สามารถระบุตัวผู้ผลิต ผู้ว่าจ้างให้ผลิต หรือผู้นำเข้าได้"}], "key_takeaway": "ผู้ขายต้องรับผิดตาม พ.ร.บ.ความรับผิดฯ เฉพาะเมื่อระบุตัวผู้ผลิต ผู้ว่าจ้างให้ผลิต หรือผู้นำเข้าไม่ได้ ส่วนผู้ผลิตและผู้นำเข้าต้องร่วมกันรับผิดเสมอ"}'::jsonb, 'hard', 'law-day1 • พ.ร.บ.ความรับผิดต่อความเสียหายจากสินค้าที่ไม่ปลอดภัย – ผู้ประกอบการที่ต้องรับผิด'),
('0fc416079aa33113d2e9d7569908d305', 94, 'ตาม พ.ร.บ.อาหาร พ.ศ. 2522 ผลิตภัณฑ์ใดต่อไปนี้จัดเป็น “อาหารควบคุมเฉพาะ” ซึ่งต้องขึ้นทะเบียนตำรับอาหารก่อนผลิตหรือนำเข้าเพื่อจำหน่าย', '[{"label": "A", "text": "ข้าวสารบรรจุถุงที่จำหน่ายในซูเปอร์มาร์เก็ต"}, {"label": "B", "text": "นมดัดแปลงสำหรับทารกและนมดัดแปลงสูตรต่อเนื่องสำหรับทารกและเด็กเล็ก"}, {"label": "C", "text": "ขนมขบเคี้ยวประเภทมันฝรั่งทอดกรอบบรรจุซอง"}, {"label": "D", "text": "ผักและผลไม้สดที่จำหน่ายโดยไม่บรรจุในภาชนะ"}, {"label": "E", "text": "น้ำตาลทรายที่ตักแบ่งขายตามน้ำหนักในร้านค้าปลีก"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. นมดัดแปลงสำหรับทารกและนมดัดแปลงสูตรต่อเนื่องสำหรับทารกและเด็กเล็ก — อาหารสำหรับทารกกลุ่มนี้ถูกประกาศเป็นอาหารควบคุมเฉพาะ เนื่องจากผู้บริโภคเป็นกลุ่มเปราะบางและคุณภาพมีผลต่อสุขภาพโดยตรง", "reason": "พ.ร.บ.อาหาร พ.ศ. 2522 ให้รัฐมนตรีประกาศจำแนกอาหารเพื่อการควบคุมตามระดับความเสี่ยง เช่น อาหารควบคุมเฉพาะ อาหารที่กำหนดคุณภาพหรือมาตรฐาน อาหารที่ต้องมีฉลาก และอาหารทั่วไป โดยอาหารควบคุมเฉพาะเป็นกลุ่มที่ควบคุมเข้มงวดที่สุด ต้องขึ้นทะเบียนตำรับอาหารก่อนผลิตหรือนำเข้าเพื่อจำหน่าย\n\nนมดัดแปลงสำหรับทารกและนมดัดแปลงสูตรต่อเนื่องสำหรับทารกและเด็กเล็กเป็นตัวอย่างคลาสสิกของอาหารควบคุมเฉพาะ เนื่องจากเป็นแหล่งอาหารหลักของกลุ่มเปราะบาง จึงต้องควบคุมสูตรและคุณภาพอย่างเข้มงวด", "choices": [{"label": "A", "text": "ข้าวสารบรรจุถุงที่จำหน่ายในซูเปอร์มาร์เก็ต", "is_correct": false, "explanation": "ไม่ได้ถูกประกาศเป็นอาหารควบคุมเฉพาะ จึงไม่ต้องขึ้นทะเบียนตำรับอาหาร"}, {"label": "B", "text": "นมดัดแปลงสำหรับทารกและนมดัดแปลงสูตรต่อเนื่องสำหรับทารกและเด็กเล็ก", "is_correct": true, "explanation": "ถูกต้อง อาหารสำหรับทารกกลุ่มนี้ถูกประกาศเป็นอาหารควบคุมเฉพาะ เนื่องจากผู้บริโภคเป็นกลุ่มเปราะบางและคุณภาพมีผลต่อสุขภาพโดยตรง"}, {"label": "C", "text": "ขนมขบเคี้ยวประเภทมันฝรั่งทอดกรอบบรรจุซอง", "is_correct": false, "explanation": "ไม่ได้ถูกประกาศเป็นอาหารควบคุมเฉพาะ แม้ต้องปฏิบัติตามหลักเกณฑ์เรื่องฉลากและสถานที่ผลิต"}, {"label": "D", "text": "ผักและผลไม้สดที่จำหน่ายโดยไม่บรรจุในภาชนะ", "is_correct": false, "explanation": "เป็นอาหารสดทั่วไป ไม่ได้เป็นอาหารควบคุมเฉพาะ"}, {"label": "E", "text": "น้ำตาลทรายที่ตักแบ่งขายตามน้ำหนักในร้านค้าปลีก", "is_correct": false, "explanation": "ไม่ได้ถูกประกาศเป็นอาหารควบคุมเฉพาะ จึงไม่ต้องขึ้นทะเบียนตำรับอาหาร"}], "key_takeaway": "อาหารควบคุมเฉพาะ (เช่น นมดัดแปลงสำหรับทารก) เป็นกลุ่มที่ควบคุมเข้มที่สุดตาม พ.ร.บ.อาหาร ต้องขึ้นทะเบียนตำรับอาหารก่อนผลิตหรือนำเข้า"}'::jsonb, 'easy', 'law-day1 • พ.ร.บ.อาหาร – ประเภทอาหารควบคุมเฉพาะ'),
('5a07dbf37dd5c3c103e2e4a1d90c5c7e', 95, 'ลูกค้านำกล่องผลิตภัณฑ์เสริมอาหารที่มีเลข 13 หลักอยู่ในกรอบเครื่องหมาย อย. มาถามเภสัชกรว่า “มีเลข อย. แบบนี้ แปลว่า อย. รับรองแล้วใช่ไหมว่าช่วยรักษาเบาหวานได้จริงตามที่โฆษณา” เภสัชกรควรอธิบายความหมายของเลขดังกล่าวอย่างไรจึงถูกต้องที่สุด', '[{"label": "A", "text": "เลขสารบบอาหารแสดงว่า อย. ทดสอบประสิทธิผลทางคลินิกแล้ว จึงอ้างสรรพคุณรักษาเบาหวานได้"}, {"label": "B", "text": "เลข 13 หลักนี้คือเลขทะเบียนตำรับยา แสดงว่าผลิตภัณฑ์นี้เป็นยาที่ใช้รักษาโรคได้"}, {"label": "C", "text": "เลขสารบบอาหารเป็นเลขที่ผู้ประกอบการกำหนดขึ้นเอง จึงไม่มีความหมายทางกฎหมาย"}, {"label": "D", "text": "เลขสารบบอาหารแสดงว่าสถานที่และผลิตภัณฑ์ได้รับอนุญาตตาม พ.ร.บ.อาหาร แต่ไม่ได้รับรองสรรพคุณรักษาโรค และควรสืบค้นเลขกับฐานข้อมูล อย."}, {"label": "E", "text": "เลขสารบบอาหารรับรองว่าผลิตภัณฑ์ทุกรุ่นการผลิตปลอดภัย ผู้ขายจึงไม่ต้องตรวจสอบสิ่งใดเพิ่ม"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. เลขสารบบอาหารแสดงว่าสถานที่และผลิตภัณฑ์ได้รับอนุญาตตาม พ.ร.บ.อาหาร แต่ไม่ได้รับรองสรรพคุณรักษาโรค และควรสืบค้นเลขกับฐานข้อมูล อย. — เลขสารบบอาหารบ่งว่าผลิตภัณฑ์ผ่านการอนุญาตในฐานะอาหาร ไม่ได้เป็นการรับรองว่ารักษาโรคได้ และผู้บริโภคควรตรวจสอบว่าเลขตรงกับผลิตภัณฑ์จริง", "reason": "เลขสารบบอาหาร 13 หลักที่แสดงในกรอบเครื่องหมาย อย. เป็นเลขที่ได้จากการอนุญาตตาม พ.ร.บ.อาหาร พ.ศ. 2522 สะท้อนว่าสถานที่ผลิต/นำเข้าและผลิตภัณฑ์อาหารนั้นได้รับอนุญาตแล้ว ไม่ได้หมายความว่า อย. รับรองว่าผลิตภัณฑ์รักษาโรคได้ และผลิตภัณฑ์อาหารไม่สามารถแสดงสรรพคุณในการบำบัด บรรเทา หรือรักษาโรค\n\nเภสัชกรควรแนะนำให้ผู้บริโภคสืบค้นเลขผ่านระบบตรวจสอบผลิตภัณฑ์ของ อย. (เว็บไซต์หรือแอปพลิเคชัน) เพื่อดูว่าชื่อและรายละเอียดผลิตภัณฑ์ตรงกับเลขหรือไม่ เพราะมีกรณีนำเลขของผลิตภัณฑ์อื่นมาแอบอ้าง", "choices": [{"label": "A", "text": "เลขสารบบอาหารแสดงว่า อย. ทดสอบประสิทธิผลทางคลินิกแล้ว จึงอ้างสรรพคุณรักษาเบาหวานได้", "is_correct": false, "explanation": "ผิด การอนุญาตอาหารไม่ใช่การประเมินประสิทธิผลทางคลินิก และอาหารไม่สามารถอ้างสรรพคุณรักษาโรคได้"}, {"label": "B", "text": "เลข 13 หลักนี้คือเลขทะเบียนตำรับยา แสดงว่าผลิตภัณฑ์นี้เป็นยาที่ใช้รักษาโรคได้", "is_correct": false, "explanation": "ผิด เลข 13 หลักในกรอบ อย. เป็นเลขของอาหาร ไม่ใช่เลขทะเบียนตำรับยา (Reg. No.) ซึ่งมีรูปแบบต่างออกไป"}, {"label": "C", "text": "เลขสารบบอาหารเป็นเลขที่ผู้ประกอบการกำหนดขึ้นเอง จึงไม่มีความหมายทางกฎหมาย", "is_correct": false, "explanation": "ผิด เลขสารบบอาหารออกโดยผู้อนุญาต และสามารถสืบค้นข้อมูลได้จากระบบของ อย."}, {"label": "D", "text": "เลขสารบบอาหารแสดงว่าสถานที่และผลิตภัณฑ์ได้รับอนุญาตตาม พ.ร.บ.อาหาร แต่ไม่ได้รับรองสรรพคุณรักษาโรค และควรสืบค้นเลขกับฐานข้อมูล อย.", "is_correct": true, "explanation": "ถูกต้อง เลขสารบบอาหารบ่งว่าผลิตภัณฑ์ผ่านการอนุญาตในฐานะอาหาร ไม่ได้เป็นการรับรองว่ารักษาโรคได้ และผู้บริโภคควรตรวจสอบว่าเลขตรงกับผลิตภัณฑ์จริง"}, {"label": "E", "text": "เลขสารบบอาหารรับรองว่าผลิตภัณฑ์ทุกรุ่นการผลิตปลอดภัย ผู้ขายจึงไม่ต้องตรวจสอบสิ่งใดเพิ่ม", "is_correct": false, "explanation": "ผิด เลขสารบบอาหารไม่ได้รับประกันคุณภาพทุกรุ่นการผลิต และยังพบการแอบอ้างเลขของผลิตภัณฑ์อื่นได้"}], "key_takeaway": "เลขสารบบอาหารยืนยันการอนุญาตในฐานะอาหาร ไม่ใช่การรับรองสรรพคุณรักษาโรค และควรสืบค้นยืนยันกับฐานข้อมูล อย. เสมอ"}'::jsonb, 'medium', 'law-day1 • พ.ร.บ.อาหาร – เลขสารบบอาหาร 13 หลัก'),
('c520da659cace998f837be41dd37952e', 96, 'ผู้แทนบริษัทนำผลิตภัณฑ์เสริมอาหารสารสกัดจากมะระขี้นกที่มีเลขสารบบอาหารถูกต้องมาเสนอขายให้ร้านยา ฉลากและแผ่นพับระบุข้อความว่า “ลดน้ำตาลในเลือด รักษาเบาหวาน ใช้แทนยาได้” เภสัชกรผู้มีหน้าที่ปฏิบัติการควรพิจารณาประเด็นทางกฎหมายอย่างไรจึงถูกต้องที่สุด', '[{"label": "A", "text": "ผลิตภัณฑ์เสริมอาหารแสดงสรรพคุณป้องกัน บำบัด หรือรักษาโรคไม่ได้ ข้อความนี้จึงไม่ชอบด้วยกฎหมายแม้ผลิตภัณฑ์มีเลขสารบบอาหาร"}, {"label": "B", "text": "ข้อความใช้ได้ เพราะผลิตภัณฑ์ที่มีเลขสารบบอาหารแล้วแสดงสรรพคุณใดก็ได้"}, {"label": "C", "text": "ข้อความใช้ได้ หากร้านยามีเภสัชกรคอยให้คำแนะนำประกอบการขาย"}, {"label": "D", "text": "ผลิตภัณฑ์นี้กลายเป็นยาแผนปัจจุบันที่ขึ้นทะเบียนแล้วโดยอัตโนมัติ เพราะมีข้อความว่ารักษาโรค"}, {"label": "E", "text": "ข้อความผิดเฉพาะเมื่อนำไปโฆษณาทางโทรทัศน์ แต่แสดงบนฉลากและแผ่นพับได้"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ผลิตภัณฑ์เสริมอาหารแสดงสรรพคุณป้องกัน บำบัด หรือรักษาโรคไม่ได้ ข้อความนี้จึงไม่ชอบด้วยกฎหมายแม้ผลิตภัณฑ์มีเลขสารบบอาหาร — ผลิตภัณฑ์เสริมอาหารเป็นอาหาร การแสดงข้อความว่ารักษาโรคหรือใช้แทนยาได้เป็นการแสดงฉลาก/โฆษณาที่เป็นเท็จหรือทำให้เข้าใจผิด เลขสารบบอาหารไม่ได้ทำให้ข้อความนั้นชอบด้วยกฎหมาย", "reason": "ผลิตภัณฑ์เสริมอาหารเป็นอาหารตาม พ.ร.บ.อาหาร พ.ศ. 2522 วัตถุประสงค์คือรับประทานนอกเหนือจากอาหารหลักตามปกติ จึงแสดงสรรพคุณในการป้องกัน บำบัด บรรเทา หรือรักษาโรคไม่ได้ ข้อความ “รักษาเบาหวาน ใช้แทนยาได้” เป็นการแสดงฉลากหรือโฆษณาที่เป็นเท็จหรือทำให้เข้าใจผิดในสาระสำคัญ และยังเป็นอันตรายต่อผู้ป่วยที่อาจหยุดยารักษาโรคประจำตัว\n\nการมีเลขสารบบอาหารเพียงแสดงว่าผลิตภัณฑ์ได้รับอนุญาตในฐานะอาหาร ไม่ได้อนุญาตให้แสดงข้อความดังกล่าว เภสัชกรจึงไม่ควรรับมาจำหน่ายและอาจแจ้ง อย. เพื่อตรวจสอบ", "choices": [{"label": "A", "text": "ผลิตภัณฑ์เสริมอาหารแสดงสรรพคุณป้องกัน บำบัด หรือรักษาโรคไม่ได้ ข้อความนี้จึงไม่ชอบด้วยกฎหมายแม้ผลิตภัณฑ์มีเลขสารบบอาหาร", "is_correct": true, "explanation": "ถูกต้อง ผลิตภัณฑ์เสริมอาหารเป็นอาหาร การแสดงข้อความว่ารักษาโรคหรือใช้แทนยาได้เป็นการแสดงฉลาก/โฆษณาที่เป็นเท็จหรือทำให้เข้าใจผิด เลขสารบบอาหารไม่ได้ทำให้ข้อความนั้นชอบด้วยกฎหมาย"}, {"label": "B", "text": "ข้อความใช้ได้ เพราะผลิตภัณฑ์ที่มีเลขสารบบอาหารแล้วแสดงสรรพคุณใดก็ได้", "is_correct": false, "explanation": "ผิด การได้เลขสารบบอาหารไม่ได้อนุญาตให้อ้างสรรพคุณทางยา"}, {"label": "C", "text": "ข้อความใช้ได้ หากร้านยามีเภสัชกรคอยให้คำแนะนำประกอบการขาย", "is_correct": false, "explanation": "ผิด การมีเภสัชกรไม่ได้ทำให้ข้อความอ้างรักษาโรคบนอาหารชอบด้วยกฎหมาย"}, {"label": "D", "text": "ผลิตภัณฑ์นี้กลายเป็นยาแผนปัจจุบันที่ขึ้นทะเบียนแล้วโดยอัตโนมัติ เพราะมีข้อความว่ารักษาโรค", "is_correct": false, "explanation": "ผิด การอ้างสรรพคุณไม่ได้ทำให้ผลิตภัณฑ์ได้รับทะเบียนตำรับยา กลับทำให้ผลิตภัณฑ์ผิดกฎหมาย"}, {"label": "E", "text": "ข้อความผิดเฉพาะเมื่อนำไปโฆษณาทางโทรทัศน์ แต่แสดงบนฉลากและแผ่นพับได้", "is_correct": false, "explanation": "ผิด การควบคุมครอบคลุมทั้งฉลากและการโฆษณาทุกสื่อ รวมถึงแผ่นพับ"}], "key_takeaway": "ผลิตภัณฑ์เสริมอาหารห้ามแสดงสรรพคุณป้องกันหรือรักษาโรค แม้จะมีเลขสารบบอาหารถูกต้องก็ตาม"}'::jsonb, 'medium', 'law-day1 • พ.ร.บ.อาหาร – ผลิตภัณฑ์เสริมอาหารห้ามอ้างสรรพคุณรักษาโรค'),
('8f0b1495e7718edff25a61433db7e29c', 97, 'บริษัทผู้นำเข้าผลิตภัณฑ์เสริมอาหารวิตามินซีที่มีเลขสารบบอาหารถูกต้อง ต้องการทำคลิปโฆษณาเผยแพร่ทางสื่อสังคมออนไลน์ โดยมีข้อความกล่าวถึงคุณประโยชน์ของวิตามินซีต่อร่างกาย ตาม พ.ร.บ.อาหาร พ.ศ. 2522 ข้อใดถูกต้อง', '[{"label": "A", "text": "ไม่ต้องขออนุญาต เพราะเลขสารบบอาหารครอบคลุมการโฆษณาทุกสื่ออยู่แล้ว"}, {"label": "B", "text": "ต้องขออนุญาตเฉพาะการโฆษณาทางโทรทัศน์และวิทยุ ส่วนสื่อออนไลน์ไม่อยู่ในบังคับ"}, {"label": "C", "text": "ต้องนำข้อความ ภาพ และเสียงที่ใช้โฆษณาคุณประโยชน์ของอาหารไปให้ผู้อนุญาตพิจารณาอนุญาตก่อนเผยแพร่"}, {"label": "D", "text": "ต้องขออนุญาตจาก สคบ. แทน อย. เพราะเป็นการโฆษณาผ่านสื่อออนไลน์"}, {"label": "E", "text": "ไม่ต้องขออนุญาต หากข้อความเป็นความจริงทางวิทยาศาสตร์และมีเอกสารอ้างอิงประกอบ"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ต้องนำข้อความ ภาพ และเสียงที่ใช้โฆษณาคุณประโยชน์ของอาหารไปให้ผู้อนุญาตพิจารณาอนุญาตก่อนเผยแพร่ — การโฆษณาคุณประโยชน์ คุณภาพ หรือสรรพคุณของอาหารต้องได้รับอนุญาตก่อน และใช้กับการโฆษณาด้วยวิธีอื่นใดรวมถึงสื่อออนไลน์", "reason": "พ.ร.บ.อาหาร พ.ศ. 2522 ห้ามโฆษณาอาหารโดยเป็นเท็จหรือหลอกลวงให้เกิดความหลงเชื่อโดยไม่สมควร และกำหนดให้ผู้ที่ประสงค์จะโฆษณาคุณประโยชน์ คุณภาพ หรือสรรพคุณของอาหาร ทางวิทยุ โทรทัศน์ ภาพยนตร์ สิ่งพิมพ์ หรือด้วยวิธีอื่นใด ต้องนำเสียง ภาพ หรือข้อความนั้นไปให้ผู้อนุญาตตรวจพิจารณาก่อน เมื่อได้รับอนุญาตแล้วจึงจะโฆษณาได้\n\nเลขสารบบอาหารเป็นการอนุญาตตัวผลิตภัณฑ์ ไม่ใช่การอนุญาตโฆษณา และ “วิธีอื่นใด” ครอบคลุมสื่อสังคมออนไลน์ด้วย", "choices": [{"label": "A", "text": "ไม่ต้องขออนุญาต เพราะเลขสารบบอาหารครอบคลุมการโฆษณาทุกสื่ออยู่แล้ว", "is_correct": false, "explanation": "ผิด การอนุญาตผลิตภัณฑ์กับการอนุญาตโฆษณาเป็นคนละเรื่องกัน"}, {"label": "B", "text": "ต้องขออนุญาตเฉพาะการโฆษณาทางโทรทัศน์และวิทยุ ส่วนสื่อออนไลน์ไม่อยู่ในบังคับ", "is_correct": false, "explanation": "ผิด กฎหมายครอบคลุมการโฆษณาด้วยวิธีอื่นใด ซึ่งรวมสื่อออนไลน์"}, {"label": "C", "text": "ต้องนำข้อความ ภาพ และเสียงที่ใช้โฆษณาคุณประโยชน์ของอาหารไปให้ผู้อนุญาตพิจารณาอนุญาตก่อนเผยแพร่", "is_correct": true, "explanation": "ถูกต้อง การโฆษณาคุณประโยชน์ คุณภาพ หรือสรรพคุณของอาหารต้องได้รับอนุญาตก่อน และใช้กับการโฆษณาด้วยวิธีอื่นใดรวมถึงสื่อออนไลน์"}, {"label": "D", "text": "ต้องขออนุญาตจาก สคบ. แทน อย. เพราะเป็นการโฆษณาผ่านสื่อออนไลน์", "is_correct": false, "explanation": "ผิด การโฆษณาอาหารอยู่ภายใต้ พ.ร.บ.อาหาร ซึ่ง อย. เป็นผู้อนุญาต ไม่ได้เปลี่ยนตามช่องทางสื่อ"}, {"label": "E", "text": "ไม่ต้องขออนุญาต หากข้อความเป็นความจริงทางวิทยาศาสตร์และมีเอกสารอ้างอิงประกอบ", "is_correct": false, "explanation": "ผิด แม้ข้อความเป็นความจริงก็ยังต้องได้รับอนุญาตก่อนโฆษณาคุณประโยชน์ของอาหาร"}], "key_takeaway": "การโฆษณาคุณประโยชน์ คุณภาพ หรือสรรพคุณของอาหารทุกช่องทาง รวมถึงออนไลน์ ต้องได้รับอนุญาตจากผู้อนุญาตก่อนเผยแพร่"}'::jsonb, 'medium', 'law-day1 • พ.ร.บ.อาหาร – การโฆษณาอาหารต้องได้รับอนุญาต'),
('b2fb3385af5f50f1dba67c62d2e9f493', 98, 'หญิงอายุ 25 ปีมาที่ร้านยาด้วยอาการใจสั่น นอนไม่หลับ หลังรับประทาน “ผลิตภัณฑ์เสริมอาหารลดน้ำหนัก” ที่ซื้อทางออนไลน์ ฉลากมีเลข 13 หลักในกรอบ อย. เภสัชกรสืบค้นพบข่าวเตือนของ อย. ว่าผลิตภัณฑ์ชื่อและรูปลักษณ์เดียวกันตรวจพบไซบูทรามีน (sibutramine) และเลขที่แสดงบนฉลากเป็นของผลิตภัณฑ์อื่น นอกจากประเมินอาการและส่งต่อตามความเหมาะสมแล้ว การดำเนินการใดถูกต้องและครบถ้วนที่สุด', '[{"label": "A", "text": "แนะนำให้ใช้ต่อในขนาดครึ่งหนึ่ง เพราะผลิตภัณฑ์มีเลข อย. จึงถือว่าถูกกฎหมาย"}, {"label": "B", "text": "แนะนำให้หยุดใช้เท่านั้น ไม่ต้องรายงาน เพราะระบบเฝ้าระวังรับรายงานเฉพาะยาที่ขึ้นทะเบียน"}, {"label": "C", "text": "รับซื้อผลิตภัณฑ์ที่เหลือคืนไว้ขายต่อในร้าน เพราะผู้บริโภครายอื่นอาจไม่เกิดอาการ"}, {"label": "D", "text": "แนะนำให้ติดต่อผู้ขายออนไลน์เพื่อขอเงินคืนเพียงอย่างเดียว เพราะเป็นข้อพิพาททางแพ่ง"}, {"label": "E", "text": "แนะนำให้หยุดใช้ เก็บผลิตภัณฑ์และหลักฐานการซื้อ รายงานอาการไม่พึงประสงค์ไปยังระบบเฝ้าระวังของ อย. และแจ้งร้องเรียนต่อ อย. หรือ สสจ."}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. แนะนำให้หยุดใช้ เก็บผลิตภัณฑ์และหลักฐานการซื้อ รายงานอาการไม่พึงประสงค์ไปยังระบบเฝ้าระวังของ อย. และแจ้งร้องเรียนต่อ อย. หรือ สสจ. — ครอบคลุมทั้งความปลอดภัยของผู้ป่วย การรายงานเหตุการณ์ไม่พึงประสงค์จากผลิตภัณฑ์สุขภาพ และการร้องเรียนเพื่อให้หน่วยงานดำเนินการทางกฎหมายกับผลิตภัณฑ์ผิดกฎหมาย", "reason": "ไซบูทรามีนเป็นยาลดความอยากอาหารที่ถูกเพิกถอนทะเบียนตำรับยาเนื่องจากความเสี่ยงต่อระบบหัวใจและหลอดเลือด และเป็นสารที่ห้ามผสมในอาหาร ผลิตภัณฑ์ที่อ้างเป็นอาหารแต่ลักลอบผสมยาและแสดงเลขสารบบอาหารของผลิตภัณฑ์อื่นจึงเป็นผลิตภัณฑ์ผิดกฎหมาย (เช่น เข้าข่ายอาหารที่แสดงฉลากเพื่อลวงให้เข้าใจผิด) เลขที่ปรากฏบนฉลากไม่ได้ทำให้ถูกกฎหมาย\n\nบทบาทของเภสัชกร ได้แก่ (1) ความปลอดภัยของผู้ป่วย: หยุดใช้และส่งต่อตามความรุนแรง (2) เก็บผลิตภัณฑ์/หลักฐานไว้เป็นข้อมูลประกอบการตรวจสอบ (3) รายงานอาการไม่พึงประสงค์ไปยังศูนย์เฝ้าระวังความปลอดภัยด้านผลิตภัณฑ์สุขภาพของ อย. และ (4) ร้องเรียนต่อ อย. (เช่น สายด่วน 1556) หรือสำนักงานสาธารณสุขจังหวัด เพื่อให้มีการดำเนินคดีและเตือนภัยผู้บริโภค", "choices": [{"label": "A", "text": "แนะนำให้ใช้ต่อในขนาดครึ่งหนึ่ง เพราะผลิตภัณฑ์มีเลข อย. จึงถือว่าถูกกฎหมาย", "is_correct": false, "explanation": "ผิด เลขที่แสดงเป็นของผลิตภัณฑ์อื่นและผลิตภัณฑ์ผสมยาที่ห้ามใช้ในอาหาร จึงเป็นผลิตภัณฑ์ผิดกฎหมายและไม่ปลอดภัย"}, {"label": "B", "text": "แนะนำให้หยุดใช้เท่านั้น ไม่ต้องรายงาน เพราะระบบเฝ้าระวังรับรายงานเฉพาะยาที่ขึ้นทะเบียน", "is_correct": false, "explanation": "ผิด ระบบเฝ้าระวังความปลอดภัยของ อย. ครอบคลุมผลิตภัณฑ์สุขภาพ รวมถึงผลิตภัณฑ์เสริมอาหารและผลิตภัณฑ์ที่ลักลอบผสมยา"}, {"label": "C", "text": "รับซื้อผลิตภัณฑ์ที่เหลือคืนไว้ขายต่อในร้าน เพราะผู้บริโภครายอื่นอาจไม่เกิดอาการ", "is_correct": false, "explanation": "ผิด การจำหน่ายผลิตภัณฑ์อาหารที่ผสมยาและแสดงฉลากลวงเป็นความผิด และเป็นอันตรายต่อผู้บริโภค"}, {"label": "D", "text": "แนะนำให้ติดต่อผู้ขายออนไลน์เพื่อขอเงินคืนเพียงอย่างเดียว เพราะเป็นข้อพิพาททางแพ่ง", "is_correct": false, "explanation": "ผิด กรณีนี้เป็นปัญหาความปลอดภัยและการฝ่าฝืนกฎหมายผลิตภัณฑ์สุขภาพ ไม่ใช่แค่ข้อพิพาททางแพ่ง ต้องรายงานและร้องเรียน"}, {"label": "E", "text": "แนะนำให้หยุดใช้ เก็บผลิตภัณฑ์และหลักฐานการซื้อ รายงานอาการไม่พึงประสงค์ไปยังระบบเฝ้าระวังของ อย. และแจ้งร้องเรียนต่อ อย. หรือ สสจ.", "is_correct": true, "explanation": "ถูกต้อง ครอบคลุมทั้งความปลอดภัยของผู้ป่วย การรายงานเหตุการณ์ไม่พึงประสงค์จากผลิตภัณฑ์สุขภาพ และการร้องเรียนเพื่อให้หน่วยงานดำเนินการทางกฎหมายกับผลิตภัณฑ์ผิดกฎหมาย"}], "key_takeaway": "ผลิตภัณฑ์ “อาหาร” ที่ลักลอบผสมยาเป็นของผิดกฎหมายแม้มีเลข อย. บนฉลาก เภสัชกรควรให้หยุดใช้ รายงานอาการไม่พึงประสงค์ และร้องเรียนต่อหน่วยงานกำกับดูแล"}'::jsonb, 'hard', 'law-day1 • การแยกแยะผลิตภัณฑ์สุขภาพ – ผลิตภัณฑ์ลดน้ำหนักผสมยา/การร้องเรียนและรายงาน'),
('29cccfb6359bbf12cede2d667bc18f20', 99, 'ตาม พ.ร.บ.เครื่องสำอาง พ.ศ. 2558 ข้อใดถูกต้องเกี่ยวกับการควบคุมเครื่องสำอางก่อนออกสู่ตลาด', '[{"label": "A", "text": "เครื่องสำอางแบ่งเป็นควบคุมพิเศษ ควบคุม และทั่วไป โดยเฉพาะชนิดควบคุมพิเศษเท่านั้นที่ต้องขึ้นทะเบียน"}, {"label": "B", "text": "เครื่องสำอางทุกผลิตภัณฑ์ต้องจดแจ้งรายละเอียดต่อผู้รับจดแจ้งก่อนผลิตเพื่อขาย รับจ้างผลิต หรือนำเข้าเพื่อขาย"}, {"label": "C", "text": "เครื่องสำอางทุกชนิดต้องขึ้นทะเบียนตำรับและผ่านการประเมินประสิทธิผลทางคลินิกจาก อย. ก่อนจำหน่าย"}, {"label": "D", "text": "เครื่องสำอางนำเข้าได้รับยกเว้นการจดแจ้ง หากได้รับอนุญาตจากประเทศผู้ผลิตแล้ว"}, {"label": "E", "text": "ผู้ขายปลีกทุกรายต้องยื่นจดแจ้งเครื่องสำอางแต่ละรายการก่อนวางจำหน่ายในร้านของตน"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. เครื่องสำอางทุกผลิตภัณฑ์ต้องจดแจ้งรายละเอียดต่อผู้รับจดแจ้งก่อนผลิตเพื่อขาย รับจ้างผลิต หรือนำเข้าเพื่อขาย — กฎหมายฉบับปี 2558 ใช้ระบบจดแจ้งกับเครื่องสำอางทุกผลิตภัณฑ์ก่อนผลิตหรือนำเข้าเพื่อขาย", "reason": "พ.ร.บ.เครื่องสำอาง พ.ศ. 2558 ยกเลิกการแบ่งเครื่องสำอางเป็นควบคุมพิเศษ ควบคุม และทั่วไปตามกฎหมายเดิม และกำหนดให้ผู้ที่จะผลิตเพื่อขาย รับจ้างผลิต หรือนำเข้าเพื่อขายเครื่องสำอางต้องจดแจ้งรายละเอียดเครื่องสำอางต่อผู้รับจดแจ้งก่อน เมื่อจดแจ้งแล้วจะได้รับใบรับจดแจ้ง\n\nระบบจดแจ้งเป็นการแจ้งข้อมูลโดยผู้ประกอบการรับผิดชอบความปลอดภัยของผลิตภัณฑ์เอง และรัฐเน้นการตรวจสอบเฝ้าระวังหลังออกสู่ตลาด ไม่ใช่การประเมินประสิทธิผลทางคลินิกก่อนจำหน่ายแบบยา", "choices": [{"label": "A", "text": "เครื่องสำอางแบ่งเป็นควบคุมพิเศษ ควบคุม และทั่วไป โดยเฉพาะชนิดควบคุมพิเศษเท่านั้นที่ต้องขึ้นทะเบียน", "is_correct": false, "explanation": "ผิด เป็นระบบตามกฎหมายเครื่องสำอางฉบับเดิม (พ.ศ. 2535) ซึ่งถูกยกเลิกแล้ว"}, {"label": "B", "text": "เครื่องสำอางทุกผลิตภัณฑ์ต้องจดแจ้งรายละเอียดต่อผู้รับจดแจ้งก่อนผลิตเพื่อขาย รับจ้างผลิต หรือนำเข้าเพื่อขาย", "is_correct": true, "explanation": "ถูกต้อง กฎหมายฉบับปี 2558 ใช้ระบบจดแจ้งกับเครื่องสำอางทุกผลิตภัณฑ์ก่อนผลิตหรือนำเข้าเพื่อขาย"}, {"label": "C", "text": "เครื่องสำอางทุกชนิดต้องขึ้นทะเบียนตำรับและผ่านการประเมินประสิทธิผลทางคลินิกจาก อย. ก่อนจำหน่าย", "is_correct": false, "explanation": "ผิด เครื่องสำอางใช้ระบบจดแจ้ง ไม่ใช่การขึ้นทะเบียนตำรับพร้อมประเมินประสิทธิผลทางคลินิกแบบยา"}, {"label": "D", "text": "เครื่องสำอางนำเข้าได้รับยกเว้นการจดแจ้ง หากได้รับอนุญาตจากประเทศผู้ผลิตแล้ว", "is_correct": false, "explanation": "ผิด ผู้นำเข้าเพื่อขายต้องจดแจ้งในประเทศไทย การอนุญาตของต่างประเทศไม่ใช่เหตุยกเว้น"}, {"label": "E", "text": "ผู้ขายปลีกทุกรายต้องยื่นจดแจ้งเครื่องสำอางแต่ละรายการก่อนวางจำหน่ายในร้านของตน", "is_correct": false, "explanation": "ผิด หน้าที่จดแจ้งเป็นของผู้ผลิตเพื่อขาย ผู้รับจ้างผลิต และผู้นำเข้าเพื่อขาย ไม่ใช่ผู้ขายปลีก"}], "key_takeaway": "ภายใต้ พ.ร.บ.เครื่องสำอาง พ.ศ. 2558 เครื่องสำอางทุกผลิตภัณฑ์ต้องจดแจ้งก่อนผลิตหรือนำเข้าเพื่อขาย ไม่มีการแบ่งควบคุมพิเศษ/ควบคุม/ทั่วไปแบบเดิมแล้ว"}'::jsonb, 'easy', 'law-day1 • พ.ร.บ.เครื่องสำอาง – การจดแจ้ง'),
('e7a60663c7e91ca801a86d2e470dda6f', 100, 'เภสัชกรร้านยาได้รับข่าวเตือนจาก อย. ว่าครีมทาผิวขาวยี่ห้อหนึ่งตรวจพบสารประกอบของปรอท ทั้งที่ฉลากแสดงเลขที่ใบรับจดแจ้งซึ่งสืบค้นแล้วมีอยู่จริง ร้านยายังมีครีมดังกล่าวเหลืออยู่บนชั้นวาง ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ขายต่อได้จนหมดสต็อก เพราะใบรับจดแจ้งยังไม่ถูกเพิกถอน"}, {"label": "B", "text": "ขายต่อได้ หากติดป้ายเตือนผู้ซื้อว่ามีสารปรอทเป็นส่วนผสม"}, {"label": "C", "text": "ความรับผิดตกอยู่กับผู้ผลิตเท่านั้น ผู้ขายไม่มีหน้าที่ใดตามกฎหมายเครื่องสำอาง"}, {"label": "D", "text": "ต้องงดขายทันที เพราะการขายเครื่องสำอางที่มีสารห้ามใช้เป็นความผิด แม้ผลิตภัณฑ์จะได้รับใบรับจดแจ้งแล้วก็ตาม"}, {"label": "E", "text": "ขายต่อได้เฉพาะลูกค้าที่เคยใช้และไม่เคยเกิดอาการแพ้มาก่อน"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ต้องงดขายทันที เพราะการขายเครื่องสำอางที่มีสารห้ามใช้เป็นความผิด แม้ผลิตภัณฑ์จะได้รับใบรับจดแจ้งแล้วก็ตาม — กฎหมายห้ามทั้งการผลิต นำเข้า และขายเครื่องสำอางที่มีสารห้ามใช้ ใบรับจดแจ้งไม่ได้รับประกันว่าผลิตภัณฑ์จริงในท้องตลาดปลอดภัย", "reason": "สารประกอบของปรอทเป็นสารห้ามใช้ในเครื่องสำอาง พ.ร.บ.เครื่องสำอาง พ.ศ. 2558 ห้ามมิให้ผู้ใดผลิต นำเข้า หรือขายเครื่องสำอางที่ไม่ปลอดภัยในการใช้ ซึ่งรวมถึงเครื่องสำอางที่มีสารห้ามใช้เป็นส่วนผสม หน้าที่นี้จึงครอบคลุมถึงร้านยาในฐานะผู้ขาย\n\nใบรับจดแจ้งเป็นหลักฐานว่าผู้ประกอบการได้แจ้งข้อมูลต่อผู้รับจดแจ้งแล้ว ไม่ใช่การรับรองว่าผลิตภัณฑ์ทุกชิ้นในตลาดปลอดภัย การที่ผลิตภัณฑ์จริงตรวจพบสารห้ามใช้จึงทำให้การขายเป็นความผิด เภสัชกรควรงดขาย แยกเก็บสินค้า และติดต่อผู้จัดจำหน่าย/แจ้งหน่วยงานตามข่าวเตือน", "choices": [{"label": "A", "text": "ขายต่อได้จนหมดสต็อก เพราะใบรับจดแจ้งยังไม่ถูกเพิกถอน", "is_correct": false, "explanation": "ผิด ความผิดเกิดจากการขายเครื่องสำอางที่มีสารห้ามใช้ ไม่ขึ้นกับว่าใบรับจดแจ้งถูกเพิกถอนแล้วหรือยัง"}, {"label": "B", "text": "ขายต่อได้ หากติดป้ายเตือนผู้ซื้อว่ามีสารปรอทเป็นส่วนผสม", "is_correct": false, "explanation": "ผิด การแจ้งเตือนไม่ได้ทำให้การขายเครื่องสำอางที่มีสารห้ามใช้ชอบด้วยกฎหมาย"}, {"label": "C", "text": "ความรับผิดตกอยู่กับผู้ผลิตเท่านั้น ผู้ขายไม่มีหน้าที่ใดตามกฎหมายเครื่องสำอาง", "is_correct": false, "explanation": "ผิด กฎหมายเครื่องสำอางห้ามการขายด้วย ผู้ขายจึงมีความผิดหากยังขายต่อ"}, {"label": "D", "text": "ต้องงดขายทันที เพราะการขายเครื่องสำอางที่มีสารห้ามใช้เป็นความผิด แม้ผลิตภัณฑ์จะได้รับใบรับจดแจ้งแล้วก็ตาม", "is_correct": true, "explanation": "ถูกต้อง กฎหมายห้ามทั้งการผลิต นำเข้า และขายเครื่องสำอางที่มีสารห้ามใช้ ใบรับจดแจ้งไม่ได้รับประกันว่าผลิตภัณฑ์จริงในท้องตลาดปลอดภัย"}, {"label": "E", "text": "ขายต่อได้เฉพาะลูกค้าที่เคยใช้และไม่เคยเกิดอาการแพ้มาก่อน", "is_correct": false, "explanation": "ผิด ปรอทเป็นอันตรายสะสมแม้ไม่เกิดอาการแพ้ และเป็นสารห้ามใช้ในเครื่องสำอางโดยเด็ดขาด"}], "key_takeaway": "ใบรับจดแจ้งไม่ใช่ใบรับประกันความปลอดภัย ผู้ขายห้ามขายเครื่องสำอางที่ตรวจพบสารห้ามใช้ทุกกรณี"}'::jsonb, 'medium', 'law-day1 • พ.ร.บ.เครื่องสำอาง – เครื่องสำอางที่มีสารห้ามใช้/หน้าที่ผู้ขาย'),
('7102926b28a74cf3f196e24ce2edf0b4', 101, 'สารใดต่อไปนี้ “ไม่ได้” เป็นสารห้ามใช้ในเครื่องสำอางตามกฎหมายเครื่องสำอางของประเทศไทย', '[{"label": "A", "text": "สารประกอบของปรอท (mercury compounds)"}, {"label": "B", "text": "ไฮโดรควิโนน (hydroquinone)"}, {"label": "C", "text": "กรดเรทิโนอิก (tretinoin)"}, {"label": "D", "text": "ยากลุ่มคอร์ติโคสเตียรอยด์ เช่น clobetasol propionate"}, {"label": "E", "text": "ไนอะซินาไมด์ (niacinamide)"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ไนอะซินาไมด์ (niacinamide) — ไนอะซินาไมด์เป็นสารที่ใช้ได้ในเครื่องสำอาง ไม่ใช่สารห้ามใช้", "reason": "ประกาศกระทรวงสาธารณสุขภายใต้กฎหมายเครื่องสำอางกำหนดรายชื่อสารห้ามใช้ในเครื่องสำอาง ซึ่งรวมถึงสารประกอบของปรอท ไฮโดรควิโนน กรดเรทิโนอิก และยากลุ่มคอร์ติโคสเตียรอยด์ สารเหล่านี้พบบ่อยในการลักลอบผสมในครีมทาผิวขาว/ครีมหน้าใสที่ผิดกฎหมาย\n\nไฮโดรควิโนน เทรทิโนอิน และสเตียรอยด์เป็นสารที่มีฤทธิ์ทางยา จึงต้องใช้ในรูปผลิตภัณฑ์ยาที่ขึ้นทะเบียนเท่านั้น ส่วนไนอะซินาไมด์เป็นสารที่อนุญาตให้ใช้ในเครื่องสำอางได้", "choices": [{"label": "A", "text": "สารประกอบของปรอท (mercury compounds)", "is_correct": false, "explanation": "เป็นสารห้ามใช้ในเครื่องสำอาง พบลักลอบใส่ในครีมทาผิวขาว ก่อพิษต่อไตและระบบประสาท"}, {"label": "B", "text": "ไฮโดรควิโนน (hydroquinone)", "is_correct": false, "explanation": "เป็นสารห้ามใช้ในเครื่องสำอางของไทย การใช้รักษาฝ้าต้องอยู่ในรูปยา"}, {"label": "C", "text": "กรดเรทิโนอิก (tretinoin)", "is_correct": false, "explanation": "เป็นสารห้ามใช้ในเครื่องสำอาง ใช้ได้เฉพาะในรูปยา"}, {"label": "D", "text": "ยากลุ่มคอร์ติโคสเตียรอยด์ เช่น clobetasol propionate", "is_correct": false, "explanation": "เป็นสารห้ามใช้ในเครื่องสำอาง เพราะเป็นยาที่ก่อผลไม่พึงประสงค์ เช่น ผิวบาง สิวสเตียรอยด์"}, {"label": "E", "text": "ไนอะซินาไมด์ (niacinamide)", "is_correct": true, "explanation": "ถูกต้อง ไนอะซินาไมด์เป็นสารที่ใช้ได้ในเครื่องสำอาง ไม่ใช่สารห้ามใช้"}], "key_takeaway": "ปรอท ไฮโดรควิโนน กรดเรทิโนอิก และสเตียรอยด์ เป็นสารห้ามใช้ในเครื่องสำอาง พบบ่อยในครีมผิวขาวผิดกฎหมาย"}'::jsonb, 'easy', 'law-day1 • พ.ร.บ.เครื่องสำอาง – สารห้ามใช้ในเครื่องสำอาง'),
('e6f531ccd5f5a46fa052effab2a2a377', 102, 'ผู้ประกอบการรายหนึ่งต้องการจดแจ้งครีมทาหน้าเป็นเครื่องสำอาง และต้องการระบุบนฉลากว่า “รักษาฝ้า รักษาสิวอักเสบ ฆ่าเชื้อแบคทีเรียที่เป็นสาเหตุของสิว” ข้อใดถูกต้องที่สุดตามหลักการจำแนกผลิตภัณฑ์สุขภาพ', '[{"label": "A", "text": "แสดงข้อความได้ เพราะเครื่องสำอางอ้างสรรพคุณรักษาโรคผิวหนังได้ทุกชนิด"}, {"label": "B", "text": "แสดงข้อความได้ หากผู้ประกอบการเป็นแพทย์ผิวหนังหรือเภสัชกร"}, {"label": "C", "text": "ข้อความเป็นการอ้างสรรพคุณบำบัดหรือรักษาโรค ซึ่งเข้าข่ายนิยามของยา จึงแสดงในฐานะเครื่องสำอางไม่ได้"}, {"label": "D", "text": "ผลิตภัณฑ์ต้องเปลี่ยนไปขออนุญาตเป็นผลิตภัณฑ์เสริมอาหารแทน เพราะมีสรรพคุณต่อสุขภาพผิว"}, {"label": "E", "text": "แสดงข้อความได้ หากเขียนเป็นภาษาอังกฤษแทนภาษาไทย"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ข้อความเป็นการอ้างสรรพคุณบำบัดหรือรักษาโรค ซึ่งเข้าข่ายนิยามของยา จึงแสดงในฐานะเครื่องสำอางไม่ได้ — เครื่องสำอางมุ่งเพื่อความสะอาด ความสวยงาม หรือส่งเสริมความสวยงาม ส่วนการอ้างรักษาโรคเป็นวัตถุประสงค์ของยา", "reason": "นิยามเครื่องสำอางมุ่งถึงวัตถุที่ใช้ภายนอกร่างกายเพื่อความสะอาด ความสวยงาม หรือเปลี่ยนแปลงลักษณะที่ปรากฏ ขณะที่ยาตาม พ.ร.บ.ยา หมายรวมถึงวัตถุที่มุ่งหมายสำหรับวินิจฉัย บำบัด บรรเทา รักษา หรือป้องกันโรค การจำแนกจึงขึ้นกับวัตถุประสงค์การใช้และสรรพคุณที่กล่าวอ้าง\n\nข้อความ “รักษาฝ้า รักษาสิวอักเสบ ฆ่าเชื้อที่เป็นสาเหตุของสิว” เป็นการอ้างรักษาโรค ผลิตภัณฑ์ที่ต้องการอ้างเช่นนี้ต้องผ่านการขึ้นทะเบียนตำรับยา หากจะเป็นเครื่องสำอางต้องใช้ข้อความระดับความสวยงาม เช่น ช่วยให้ผิวดูเรียบเนียนกระจ่างใส", "choices": [{"label": "A", "text": "แสดงข้อความได้ เพราะเครื่องสำอางอ้างสรรพคุณรักษาโรคผิวหนังได้ทุกชนิด", "is_correct": false, "explanation": "ผิด เครื่องสำอางไม่สามารถอ้างสรรพคุณรักษาโรค"}, {"label": "B", "text": "แสดงข้อความได้ หากผู้ประกอบการเป็นแพทย์ผิวหนังหรือเภสัชกร", "is_correct": false, "explanation": "ผิด การจำแนกผลิตภัณฑ์ขึ้นกับวัตถุประสงค์การใช้และสรรพคุณที่อ้าง ไม่ใช่วิชาชีพของผู้ประกอบการ"}, {"label": "C", "text": "ข้อความเป็นการอ้างสรรพคุณบำบัดหรือรักษาโรค ซึ่งเข้าข่ายนิยามของยา จึงแสดงในฐานะเครื่องสำอางไม่ได้", "is_correct": true, "explanation": "ถูกต้อง เครื่องสำอางมุ่งเพื่อความสะอาด ความสวยงาม หรือส่งเสริมความสวยงาม ส่วนการอ้างรักษาโรคเป็นวัตถุประสงค์ของยา"}, {"label": "D", "text": "ผลิตภัณฑ์ต้องเปลี่ยนไปขออนุญาตเป็นผลิตภัณฑ์เสริมอาหารแทน เพราะมีสรรพคุณต่อสุขภาพผิว", "is_correct": false, "explanation": "ผิด ผลิตภัณฑ์ทาภายนอกไม่ใช่อาหาร และผลิตภัณฑ์เสริมอาหารก็อ้างรักษาโรคไม่ได้เช่นกัน"}, {"label": "E", "text": "แสดงข้อความได้ หากเขียนเป็นภาษาอังกฤษแทนภาษาไทย", "is_correct": false, "explanation": "ผิด การเปลี่ยนภาษาไม่เปลี่ยนสาระของการอ้างสรรพคุณ"}], "key_takeaway": "การอ้างสรรพคุณรักษาโรคทำให้ผลิตภัณฑ์เข้าข่ายยา เครื่องสำอางอ้างได้เพียงเรื่องความสะอาดและความสวยงาม"}'::jsonb, 'medium', 'law-day1 • การแยกแยะผลิตภัณฑ์สุขภาพ – เครื่องสำอางกับยา'),
('796a66bd60ecd69e0f24ea720c669285', 103, 'ร้านยาแห่งหนึ่งรับเซรั่มบำรุงผิวนำเข้าจากญี่ปุ่นผ่านผู้หิ้วรายย่อยมาวางขาย ผลิตภัณฑ์มีเฉพาะฉลากภาษาญี่ปุ่นและอังกฤษ ไม่มีฉลากภาษาไทย ไม่ระบุผู้นำเข้า และไม่พบเลขที่ใบรับจดแจ้ง เภสัชกรควรพิจารณาอย่างไร', '[{"label": "A", "text": "ไม่ควรวางขาย เพราะเครื่องสำอางที่ขายในไทยต้องจดแจ้งและมีฉลากภาษาไทย เช่น ชื่อผู้ผลิต/ผู้นำเข้าและเลขที่ใบรับจดแจ้ง"}, {"label": "B", "text": "วางขายได้ เพราะเป็นสินค้าจากประเทศที่มีมาตรฐานการควบคุมสูงกว่าไทย"}, {"label": "C", "text": "วางขายได้ หากเภสัชกรอธิบายวิธีใช้เป็นภาษาไทยให้ลูกค้าด้วยวาจา"}, {"label": "D", "text": "วางขายได้ เพราะกฎหมายบังคับฉลากภาษาไทยเฉพาะเครื่องสำอางที่ผลิตในประเทศ"}, {"label": "E", "text": "วางขายได้ หากผลิตภัณฑ์ยังไม่หมดอายุและบรรจุภัณฑ์ไม่ชำรุด"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ไม่ควรวางขาย เพราะเครื่องสำอางที่ขายในไทยต้องจดแจ้งและมีฉลากภาษาไทย เช่น ชื่อผู้ผลิต/ผู้นำเข้าและเลขที่ใบรับจดแจ้ง — ผลิตภัณฑ์นี้ไม่มีหลักฐานการจดแจ้งและฉลากไม่เป็นไปตามกฎหมาย การนำมาขายจึงเสี่ยงต่อการฝ่าฝืนกฎหมายเครื่องสำอาง", "reason": "ตาม พ.ร.บ.เครื่องสำอาง พ.ศ. 2558 เครื่องสำอางที่ผลิตหรือนำเข้าเพื่อขายต้องจดแจ้งก่อน และต้องมีฉลากเป็นภาษาไทยแสดงข้อความตามที่กำหนด เช่น ชื่อเครื่องสำอาง ชนิด ส่วนประกอบ วิธีใช้ ชื่อและที่ตั้งผู้ผลิต/ผู้นำเข้า ปริมาณสุทธิ เลขที่แสดงครั้งที่ผลิต วันเดือนปีที่ผลิต/หมดอายุ คำเตือน (ถ้ามี) และเลขที่ใบรับจดแจ้ง\n\nสินค้าหิ้วที่ไม่มีผู้นำเข้าในไทยรับผิดชอบ ไม่มีการจดแจ้ง และไม่มีฉลากไทย ไม่สามารถตรวจสอบย้อนกลับได้ เภสัชกรจึงไม่ควรรับมาจำหน่าย", "choices": [{"label": "A", "text": "ไม่ควรวางขาย เพราะเครื่องสำอางที่ขายในไทยต้องจดแจ้งและมีฉลากภาษาไทย เช่น ชื่อผู้ผลิต/ผู้นำเข้าและเลขที่ใบรับจดแจ้ง", "is_correct": true, "explanation": "ถูกต้อง ผลิตภัณฑ์นี้ไม่มีหลักฐานการจดแจ้งและฉลากไม่เป็นไปตามกฎหมาย การนำมาขายจึงเสี่ยงต่อการฝ่าฝืนกฎหมายเครื่องสำอาง"}, {"label": "B", "text": "วางขายได้ เพราะเป็นสินค้าจากประเทศที่มีมาตรฐานการควบคุมสูงกว่าไทย", "is_correct": false, "explanation": "ผิด มาตรฐานของประเทศต้นทางไม่ทดแทนการจดแจ้งและฉลากตามกฎหมายไทย"}, {"label": "C", "text": "วางขายได้ หากเภสัชกรอธิบายวิธีใช้เป็นภาษาไทยให้ลูกค้าด้วยวาจา", "is_correct": false, "explanation": "ผิด การอธิบายด้วยวาจาไม่ทดแทนฉลากภาษาไทยที่กฎหมายกำหนด"}, {"label": "D", "text": "วางขายได้ เพราะกฎหมายบังคับฉลากภาษาไทยเฉพาะเครื่องสำอางที่ผลิตในประเทศ", "is_correct": false, "explanation": "ผิด เครื่องสำอางนำเข้าเพื่อขายต้องมีฉลากภาษาไทยเช่นกัน"}, {"label": "E", "text": "วางขายได้ หากผลิตภัณฑ์ยังไม่หมดอายุและบรรจุภัณฑ์ไม่ชำรุด", "is_correct": false, "explanation": "ผิด สภาพบรรจุภัณฑ์และวันหมดอายุไม่ทดแทนการจดแจ้งและฉลากที่ถูกต้อง"}], "key_takeaway": "เครื่องสำอางที่ขายในไทย รวมถึงสินค้านำเข้า ต้องจดแจ้งและมีฉลากภาษาไทยครบตามกฎหมาย"}'::jsonb, 'medium', 'law-day1 • พ.ร.บ.เครื่องสำอาง – ฉลากเครื่องสำอาง'),
('8fde15b46ad91b95a4b592b061cbbb8c', 104, 'คลินิกเสริมความงามแห่งหนึ่งผลิต “ครีมหน้าใสสูตรเฉพาะ” บรรจุตลับไม่มีฉลาก จำหน่ายทั้งหน้าคลินิกและทางออนไลน์ให้บุคคลทั่วไป โดยโฆษณาว่าเป็นเครื่องสำอางปลอดภัย 100% ลูกค้ารายหนึ่งทาทุกวันตามที่แนะนำเป็นเวลา 6 เดือน แล้วเกิดผิวบาง เส้นเลือดฝอยขยาย และสิวสเตียรอยด์ ผลตรวจวิเคราะห์พบ clobetasol propionate ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ไม่ผิดกฎหมาย เพราะคลินิกมีแพทย์ประจำ จึงผสมยาในเครื่องสำอางเพื่อขายให้บุคคลทั่วไปได้"}, {"label": "B", "text": "เป็นเพียงข้อพิพาทเรื่องคุณภาพสินค้า ผู้เสียหายต้องพิสูจน์ว่าคลินิกจงใจใส่สเตียรอยด์จึงจะเรียกค่าเสียหายได้"}, {"label": "C", "text": "ไม่ผิดกฎหมายเครื่องสำอาง เพราะผลิตภัณฑ์ไม่มีฉลาก จึงไม่ถือเป็นเครื่องสำอางตามกฎหมาย"}, {"label": "D", "text": "การผสมสเตียรอยด์ในผลิตภัณฑ์ที่ขายเป็นเครื่องสำอางคือการใช้สารห้ามใช้ และผู้ผลิตต้องรับผิดต่อความเสียหายจากสินค้าที่ไม่ปลอดภัยโดยไม่ต้องพิสูจน์ความประมาท"}, {"label": "E", "text": "ผู้เสียหายใช้ต่อเนื่องนานเกินไปเอง ผู้ผลิตจึงหลุดพ้นความรับผิดทุกกรณี"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. การผสมสเตียรอยด์ในผลิตภัณฑ์ที่ขายเป็นเครื่องสำอางคือการใช้สารห้ามใช้ และผู้ผลิตต้องรับผิดต่อความเสียหายจากสินค้าที่ไม่ปลอดภัยโดยไม่ต้องพิสูจน์ความประมาท — ประเด็นแรกคือสเตียรอยด์เป็นสารห้ามใช้ในเครื่องสำอาง ประเด็นที่สองคือคลินิกในฐานะผู้ผลิตต้องรับผิดตามหลักความรับผิดโดยเคร่งครัด", "reason": "ประเด็นที่ 1 (กฎหมายเครื่องสำอาง): ยากลุ่มคอร์ติโคสเตียรอยด์เป็นสารห้ามใช้ในเครื่องสำอาง ผลิตภัณฑ์ที่ขายเป็นเครื่องสำอางแต่ผสม clobetasol จึงเป็นเครื่องสำอางที่ไม่ปลอดภัยในการใช้ ห้ามผลิตและขาย นอกจากนี้ยังไม่มีการจดแจ้งและไม่มีฉลาก การมีแพทย์ประจำคลินิกไม่ได้ยกเว้นความผิด เพราะเป็นการผลิตเพื่อขายให้บุคคลทั่วไป ไม่ใช่การสั่งใช้ยาแก่ผู้ป่วยเฉพาะราย\n\nประเด็นที่ 2 (พ.ร.บ.ความรับผิดต่อความเสียหายที่เกิดขึ้นจากสินค้าที่ไม่ปลอดภัย พ.ศ. 2551): คลินิกเป็นผู้ผลิตและผู้ขายสินค้า จึงเป็นผู้ประกอบการที่ต้องรับผิดโดยเคร่งครัด ผู้เสียหายเพียงพิสูจน์ว่าได้รับความเสียหายจากสินค้าและใช้ตามปกติ ซึ่งการทาทุกวันตามคำแนะนำของผู้ขายถือเป็นการใช้ตามปกติ", "choices": [{"label": "A", "text": "ไม่ผิดกฎหมาย เพราะคลินิกมีแพทย์ประจำ จึงผสมยาในเครื่องสำอางเพื่อขายให้บุคคลทั่วไปได้", "is_correct": false, "explanation": "ผิด การมีแพทย์ไม่ได้ทำให้ผสมสารห้ามใช้ในผลิตภัณฑ์ที่ขายเป็นเครื่องสำอางได้"}, {"label": "B", "text": "เป็นเพียงข้อพิพาทเรื่องคุณภาพสินค้า ผู้เสียหายต้องพิสูจน์ว่าคลินิกจงใจใส่สเตียรอยด์จึงจะเรียกค่าเสียหายได้", "is_correct": false, "explanation": "ผิด ตาม พ.ร.บ.ความรับผิดฯ ผู้เสียหายไม่ต้องพิสูจน์ความจงใจหรือประมาทเลินเล่อ"}, {"label": "C", "text": "ไม่ผิดกฎหมายเครื่องสำอาง เพราะผลิตภัณฑ์ไม่มีฉลาก จึงไม่ถือเป็นเครื่องสำอางตามกฎหมาย", "is_correct": false, "explanation": "ผิด การไม่มีฉลากเป็นความผิดเพิ่มอีกประเด็น ไม่ได้ทำให้ผลิตภัณฑ์หลุดจากการควบคุม"}, {"label": "D", "text": "การผสมสเตียรอยด์ในผลิตภัณฑ์ที่ขายเป็นเครื่องสำอางคือการใช้สารห้ามใช้ และผู้ผลิตต้องรับผิดต่อความเสียหายจากสินค้าที่ไม่ปลอดภัยโดยไม่ต้องพิสูจน์ความประมาท", "is_correct": true, "explanation": "ถูกต้อง ประเด็นแรกคือสเตียรอยด์เป็นสารห้ามใช้ในเครื่องสำอาง ประเด็นที่สองคือคลินิกในฐานะผู้ผลิตต้องรับผิดตามหลักความรับผิดโดยเคร่งครัด"}, {"label": "E", "text": "ผู้เสียหายใช้ต่อเนื่องนานเกินไปเอง ผู้ผลิตจึงหลุดพ้นความรับผิดทุกกรณี", "is_correct": false, "explanation": "ผิด ผู้เสียหายใช้ตามที่ผู้ขายแนะนำซึ่งเป็นการใช้ตามปกติของเครื่องสำอาง และผลิตภัณฑ์ไม่มีฉลากคำเตือนใด ๆ"}], "key_takeaway": "สเตียรอยด์ในเครื่องสำอางเป็นสารห้ามใช้ และผู้ผลิตสินค้าที่ไม่ปลอดภัยต้องรับผิดโดยผู้เสียหายไม่ต้องพิสูจน์ความประมาท"}'::jsonb, 'hard', 'law-day1 • พ.ร.บ.เครื่องสำอาง + พ.ร.บ.ความรับผิดฯ – สเตียรอยด์ในครีมคลินิก'),
('df7a8052821b0fd859a4650169682826', 105, 'ภายหลัง พ.ร.บ.เครื่องมือแพทย์ (ฉบับที่ 2) พ.ศ. 2562 และประกาศที่เกี่ยวข้อง การกำกับดูแลเครื่องมือแพทย์ก่อนออกสู่ตลาดในประเทศไทยยึดหลักการใดเป็นสำคัญ', '[{"label": "A", "text": "ควบคุมตามราคาจำหน่าย เครื่องมือแพทย์ราคาสูงต้องขออนุญาต ส่วนราคาต่ำไม่ต้องควบคุม"}, {"label": "B", "text": "จำแนกตามระดับความเสี่ยง โดยความเสี่ยงสูงควบคุมเข้มงวดกว่า (เช่น ต้องได้รับใบอนุญาต) และความเสี่ยงต่ำใช้การจดแจ้ง"}, {"label": "C", "text": "ควบคุมเฉพาะเครื่องมือแพทย์ที่ใช้ไฟฟ้า ส่วนชนิดที่ไม่ใช้ไฟฟ้าไม่อยู่ในบังคับกฎหมาย"}, {"label": "D", "text": "เครื่องมือแพทย์ทุกชนิดต้องขออนุญาตในระดับเดียวกันโดยไม่คำนึงถึงความเสี่ยง"}, {"label": "E", "text": "ควบคุมตามประเทศผู้ผลิต โดยเครื่องมือแพทย์ที่ผลิตในประเทศได้รับยกเว้นการควบคุม"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. จำแนกตามระดับความเสี่ยง โดยความเสี่ยงสูงควบคุมเข้มงวดกว่า (เช่น ต้องได้รับใบอนุญาต) และความเสี่ยงต่ำใช้การจดแจ้ง — ระบบปัจจุบันจำแนกเครื่องมือแพทย์ตามระดับความเสี่ยงต่อผู้ใช้ และกำหนดความเข้มงวดของการกำกับดูแลให้สอดคล้อง", "reason": "การแก้ไข พ.ร.บ.เครื่องมือแพทย์ใน พ.ศ. 2562 ปรับระบบการกำกับดูแลให้สอดคล้องกับแนวทางสากล (เช่น ASEAN Medical Device Directive) โดยจำแนกเครื่องมือแพทย์ตามระดับความเสี่ยงเป็นหลายประเภท ตั้งแต่ความเสี่ยงต่ำไปจนถึงความเสี่ยงสูง\n\nโดยหลักการ เครื่องมือแพทย์ความเสี่ยงสูงต้องได้รับใบอนุญาตซึ่งมีการประเมินเอกสารเข้มงวด กลุ่มความเสี่ยงปานกลางใช้การแจ้งรายการละเอียด และกลุ่มความเสี่ยงต่ำใช้การจดแจ้ง ทำให้ทรัพยากรการกำกับดูแลมุ่งไปที่ผลิตภัณฑ์ที่มีความเสี่ยงต่อผู้ใช้มากที่สุด", "choices": [{"label": "A", "text": "ควบคุมตามราคาจำหน่าย เครื่องมือแพทย์ราคาสูงต้องขออนุญาต ส่วนราคาต่ำไม่ต้องควบคุม", "is_correct": false, "explanation": "ผิด ราคาไม่ใช่เกณฑ์การจำแนกเพื่อกำกับดูแล"}, {"label": "B", "text": "จำแนกตามระดับความเสี่ยง โดยความเสี่ยงสูงควบคุมเข้มงวดกว่า (เช่น ต้องได้รับใบอนุญาต) และความเสี่ยงต่ำใช้การจดแจ้ง", "is_correct": true, "explanation": "ถูกต้อง ระบบปัจจุบันจำแนกเครื่องมือแพทย์ตามระดับความเสี่ยงต่อผู้ใช้ และกำหนดความเข้มงวดของการกำกับดูแลให้สอดคล้อง"}, {"label": "C", "text": "ควบคุมเฉพาะเครื่องมือแพทย์ที่ใช้ไฟฟ้า ส่วนชนิดที่ไม่ใช้ไฟฟ้าไม่อยู่ในบังคับกฎหมาย", "is_correct": false, "explanation": "ผิด เครื่องมือแพทย์ที่ไม่ใช้ไฟฟ้า เช่น ถุงยางอนามัย หรือกระบอกฉีดยา ก็อยู่ในบังคับกฎหมาย"}, {"label": "D", "text": "เครื่องมือแพทย์ทุกชนิดต้องขออนุญาตในระดับเดียวกันโดยไม่คำนึงถึงความเสี่ยง", "is_correct": false, "explanation": "ผิด ระบบปัจจุบันปรับความเข้มงวดตามความเสี่ยง ไม่ใช่ระดับเดียวกันทั้งหมด"}, {"label": "E", "text": "ควบคุมตามประเทศผู้ผลิต โดยเครื่องมือแพทย์ที่ผลิตในประเทศได้รับยกเว้นการควบคุม", "is_correct": false, "explanation": "ผิด ทั้งผู้ผลิตในประเทศและผู้นำเข้าต้องอยู่ภายใต้การกำกับดูแลเช่นเดียวกัน"}], "key_takeaway": "เครื่องมือแพทย์ในไทยกำกับดูแลตามระดับความเสี่ยง ยิ่งเสี่ยงสูงยิ่งควบคุมเข้ม (อนุญาต > แจ้งรายการละเอียด > จดแจ้ง)"}'::jsonb, 'medium', 'law-day1 • พ.ร.บ.เครื่องมือแพทย์ – การจำแนกตามความเสี่ยง'),
('57a873f7a9d6c820355399de3e24edd5', 106, 'ร้านขายยาแผนปัจจุบัน (ขย.1) ที่มีเภสัชกรปฏิบัติการตลอดเวลาทำการ ต้องการเริ่มจำหน่ายเครื่องมือแพทย์ชนิดหนึ่งซึ่งรัฐมนตรีว่าการกระทรวงสาธารณสุขประกาศกำหนดให้ผู้ขายต้องได้รับใบอนุญาตขายเครื่องมือแพทย์ ข้อใดถูกต้อง', '[{"label": "A", "text": "ขายได้ทันที เพราะใบอนุญาตขายยาแผนปัจจุบันครอบคลุมผลิตภัณฑ์สุขภาพทุกประเภท"}, {"label": "B", "text": "ต้องได้รับใบอนุญาตขายเครื่องมือแพทย์ตาม พ.ร.บ.เครื่องมือแพทย์ก่อน เพราะใบอนุญาตขายยาเป็นใบอนุญาตตามกฎหมายคนละฉบับ"}, {"label": "C", "text": "ขายได้ทันที เพราะมีเภสัชกรประจำร้าน ซึ่งกฎหมายยกเว้นการขออนุญาตให้ทุกกรณี"}, {"label": "D", "text": "ร้านยาต้องขึ้นทะเบียนเครื่องมือแพทย์ชนิดนั้นใหม่ในนามของร้านก่อนจำหน่าย"}, {"label": "E", "text": "ไม่มีเครื่องมือแพทย์ชนิดใดต้องมีใบอนุญาตขาย เพราะกฎหมายควบคุมเฉพาะผู้ผลิตและผู้นำเข้า"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ต้องได้รับใบอนุญาตขายเครื่องมือแพทย์ตาม พ.ร.บ.เครื่องมือแพทย์ก่อน เพราะใบอนุญาตขายยาเป็นใบอนุญาตตามกฎหมายคนละฉบับ — ใบอนุญาตขายยาออกตาม พ.ร.บ.ยา ไม่ครอบคลุมการขายเครื่องมือแพทย์ที่กฎหมายเครื่องมือแพทย์กำหนดให้ต้องมีใบอนุญาตขาย", "reason": "พ.ร.บ.เครื่องมือแพทย์ พ.ศ. 2551 และที่แก้ไขเพิ่มเติม พ.ศ. 2562 กำหนดให้การขายเครื่องมือแพทย์บางชนิดตามที่รัฐมนตรีประกาศกำหนดต้องได้รับใบอนุญาตขายเครื่องมือแพทย์ ไม่ใช่เครื่องมือแพทย์ทุกชนิด\n\nใบอนุญาตขายยาแผนปัจจุบันออกตาม พ.ร.บ.ยา พ.ศ. 2510 ซึ่งเป็นกฎหมายคนละฉบับ จึงไม่ครอบคลุมการขายเครื่องมือแพทย์ที่ต้องมีใบอนุญาตขาย ร้านยาที่ต้องการขายเครื่องมือแพทย์กลุ่มนี้จึงต้องยื่นขอใบอนุญาตขายเครื่องมือแพทย์และปฏิบัติตามเงื่อนไขของกฎหมายเครื่องมือแพทย์", "choices": [{"label": "A", "text": "ขายได้ทันที เพราะใบอนุญาตขายยาแผนปัจจุบันครอบคลุมผลิตภัณฑ์สุขภาพทุกประเภท", "is_correct": false, "explanation": "ผิด ใบอนุญาตตามกฎหมายแต่ละฉบับครอบคลุมเฉพาะผลิตภัณฑ์ตามกฎหมายนั้น"}, {"label": "B", "text": "ต้องได้รับใบอนุญาตขายเครื่องมือแพทย์ตาม พ.ร.บ.เครื่องมือแพทย์ก่อน เพราะใบอนุญาตขายยาเป็นใบอนุญาตตามกฎหมายคนละฉบับ", "is_correct": true, "explanation": "ถูกต้อง ใบอนุญาตขายยาออกตาม พ.ร.บ.ยา ไม่ครอบคลุมการขายเครื่องมือแพทย์ที่กฎหมายเครื่องมือแพทย์กำหนดให้ต้องมีใบอนุญาตขาย"}, {"label": "C", "text": "ขายได้ทันที เพราะมีเภสัชกรประจำร้าน ซึ่งกฎหมายยกเว้นการขออนุญาตให้ทุกกรณี", "is_correct": false, "explanation": "ผิด ไม่มีบทยกเว้นแบบครอบคลุมทุกกรณีเพียงเพราะมีเภสัชกรประจำร้าน"}, {"label": "D", "text": "ร้านยาต้องขึ้นทะเบียนเครื่องมือแพทย์ชนิดนั้นใหม่ในนามของร้านก่อนจำหน่าย", "is_correct": false, "explanation": "ผิด การอนุญาต/จดแจ้งตัวผลิตภัณฑ์เป็นหน้าที่ของผู้ผลิตหรือผู้นำเข้า ผู้ขายมีหน้าที่เรื่องใบอนุญาตขาย"}, {"label": "E", "text": "ไม่มีเครื่องมือแพทย์ชนิดใดต้องมีใบอนุญาตขาย เพราะกฎหมายควบคุมเฉพาะผู้ผลิตและผู้นำเข้า", "is_correct": false, "explanation": "ผิด กฎหมายเปิดให้รัฐมนตรีประกาศกำหนดเครื่องมือแพทย์ที่ผู้ขายต้องได้รับใบอนุญาตขาย"}], "key_takeaway": "ใบอนุญาตขายยาไม่ครอบคลุมเครื่องมือแพทย์ที่ประกาศให้ต้องมีใบอนุญาตขาย ต้องขอใบอนุญาตตาม พ.ร.บ.เครื่องมือแพทย์แยกต่างหาก"}'::jsonb, 'medium', 'law-day1 • พ.ร.บ.เครื่องมือแพทย์ – ใบอนุญาตขายเครื่องมือแพทย์'),
('11350be866edfbac86b31330a700a266', 107, 'นักศึกษาเภสัชศาสตร์ฝึกงานที่ร้านยาได้รับมอบหมายให้จัดหมวดหมู่สินค้าในร้านตามกฎหมายที่กำกับดูแลในประเทศไทย ข้อใดจับคู่ผลิตภัณฑ์กับประเภทตามกฎหมายได้ถูกต้อง', '[{"label": "A", "text": "ครีมกันแดดสำหรับทาผิวทั่วไป – ยาแผนปัจจุบัน"}, {"label": "B", "text": "แชมพูขจัดรังแคที่มี ketoconazole 2% – เครื่องสำอาง"}, {"label": "C", "text": "นมดัดแปลงสำหรับทารก – อาหารทั่วไป"}, {"label": "D", "text": "ยาหอมตำรับแผนไทย – ยาแผนปัจจุบันตาม พ.ร.บ.ยา"}, {"label": "E", "text": "ชุดตรวจการตั้งครรภ์จากปัสสาวะ – เครื่องมือแพทย์"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ชุดตรวจการตั้งครรภ์จากปัสสาวะ – เครื่องมือแพทย์ — ชุดตรวจการตั้งครรภ์เป็นผลิตภัณฑ์ที่ใช้เพื่อการวินิจฉัย จัดเป็นเครื่องมือแพทย์ (กลุ่มเครื่องมือแพทย์สำหรับการวินิจฉัยภายนอกร่างกาย)", "reason": "การจำแนกผลิตภัณฑ์สุขภาพพิจารณาจากวัตถุประสงค์การใช้ ส่วนประกอบ และสรรพคุณที่อ้าง ชุดตรวจการตั้งครรภ์ใช้เพื่อวินิจฉัยภาวะของร่างกายจากสิ่งส่งตรวจ จึงเป็นเครื่องมือแพทย์ตาม พ.ร.บ.เครื่องมือแพทย์\n\nตัวอย่างอื่น: ครีมกันแดดเป็นเครื่องสำอาง, แชมพูที่มี ketoconazole เป็นยา, นมดัดแปลงสำหรับทารกเป็นอาหารควบคุมเฉพาะ และยาแผนไทยเป็นผลิตภัณฑ์สมุนไพรตาม พ.ร.บ.ผลิตภัณฑ์สมุนไพร พ.ศ. 2562 การจำแนกถูกต้องสำคัญเพราะกำหนดว่าต้องใช้ใบอนุญาต ฉลาก และการโฆษณาตามกฎหมายฉบับใด", "choices": [{"label": "A", "text": "ครีมกันแดดสำหรับทาผิวทั่วไป – ยาแผนปัจจุบัน", "is_correct": false, "explanation": "ผิด ครีมกันแดดในประเทศไทยจัดเป็นเครื่องสำอาง"}, {"label": "B", "text": "แชมพูขจัดรังแคที่มี ketoconazole 2% – เครื่องสำอาง", "is_correct": false, "explanation": "ผิด ketoconazole เป็นยาต้านเชื้อรา แชมพูที่มีตัวยานี้ขึ้นทะเบียนเป็นยา"}, {"label": "C", "text": "นมดัดแปลงสำหรับทารก – อาหารทั่วไป", "is_correct": false, "explanation": "ผิด นมดัดแปลงสำหรับทารกเป็นอาหารควบคุมเฉพาะ"}, {"label": "D", "text": "ยาหอมตำรับแผนไทย – ยาแผนปัจจุบันตาม พ.ร.บ.ยา", "is_correct": false, "explanation": "ผิด ยาแผนไทยอยู่ภายใต้ พ.ร.บ.ผลิตภัณฑ์สมุนไพร พ.ศ. 2562"}, {"label": "E", "text": "ชุดตรวจการตั้งครรภ์จากปัสสาวะ – เครื่องมือแพทย์", "is_correct": true, "explanation": "ถูกต้อง ชุดตรวจการตั้งครรภ์เป็นผลิตภัณฑ์ที่ใช้เพื่อการวินิจฉัย จัดเป็นเครื่องมือแพทย์ (กลุ่มเครื่องมือแพทย์สำหรับการวินิจฉัยภายนอกร่างกาย)"}], "key_takeaway": "จำแนกผลิตภัณฑ์สุขภาพจากวัตถุประสงค์และสรรพคุณ: ชุดตรวจวินิจฉัยเป็นเครื่องมือแพทย์ ครีมกันแดดเป็นเครื่องสำอาง และแชมพูที่มีตัวยาเป็นยา"}'::jsonb, 'medium', 'law-day1 • การแยกแยะผลิตภัณฑ์สุขภาพ – ยา/อาหาร/เครื่องสำอาง/เครื่องมือแพทย์/สมุนไพร'),
('1a161fdb808f6fe2dee20a8442b623e5', 108, 'ภายหลัง พ.ร.บ.ผลิตภัณฑ์สมุนไพร พ.ศ. 2562 มีผลใช้บังคับ ยาแผนไทย (ซึ่งเดิมกำกับดูแลภายใต้ พ.ร.บ.ยา ในฐานะ “ยาแผนโบราณ”) อยู่ภายใต้การกำกับดูแลของกฎหมายฉบับใดเป็นหลัก', '[{"label": "A", "text": "พ.ร.บ.ผลิตภัณฑ์สมุนไพร พ.ศ. 2562 โดยจัดเป็นยาจากสมุนไพรซึ่งเป็นส่วนหนึ่งของผลิตภัณฑ์สมุนไพร"}, {"label": "B", "text": "พ.ร.บ.ยา พ.ศ. 2510 ในฐานะยาแผนโบราณเช่นเดิมทุกประการ"}, {"label": "C", "text": "พ.ร.บ.อาหาร พ.ศ. 2522 ในฐานะอาหารควบคุมเฉพาะ"}, {"label": "D", "text": "พ.ร.บ.วิชาชีพการแพทย์แผนไทย พ.ศ. 2556 แต่เพียงฉบับเดียว"}, {"label": "E", "text": "พ.ร.บ.คุ้มครองผู้บริโภค พ.ศ. 2522 ในฐานะสินค้าควบคุมฉลาก"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. พ.ร.บ.ผลิตภัณฑ์สมุนไพร พ.ศ. 2562 โดยจัดเป็นยาจากสมุนไพรซึ่งเป็นส่วนหนึ่งของผลิตภัณฑ์สมุนไพร — กฎหมายนี้รวมการกำกับดูแลผลิตภัณฑ์สมุนไพร รวมถึงยาแผนไทยและยาจากสมุนไพร ไว้ในกฎหมายฉบับเดียว", "reason": "พ.ร.บ.ผลิตภัณฑ์สมุนไพร พ.ศ. 2562 รวมการกำกับดูแลผลิตภัณฑ์สมุนไพรไว้ในกฎหมายเฉพาะ โดย “ผลิตภัณฑ์สมุนไพร” ครอบคลุมยาจากสมุนไพร (เช่น ยาแผนไทย ยาพัฒนาจากสมุนไพร) และผลิตภัณฑ์สมุนไพรเพื่อสุขภาพ\n\nยาแผนไทยซึ่งเดิมขึ้นทะเบียนเป็นยาแผนโบราณตาม พ.ร.บ.ยา จึงย้ายมาอยู่ภายใต้กฎหมายนี้ โดยมีบทเฉพาะกาลรองรับใบอนุญาตและทะเบียนเดิม ส่วนการกำกับวิชาชีพผู้ประกอบการแพทย์แผนไทยยังเป็นเรื่องของกฎหมายวิชาชีพแยกต่างหาก", "choices": [{"label": "A", "text": "พ.ร.บ.ผลิตภัณฑ์สมุนไพร พ.ศ. 2562 โดยจัดเป็นยาจากสมุนไพรซึ่งเป็นส่วนหนึ่งของผลิตภัณฑ์สมุนไพร", "is_correct": true, "explanation": "ถูกต้อง กฎหมายนี้รวมการกำกับดูแลผลิตภัณฑ์สมุนไพร รวมถึงยาแผนไทยและยาจากสมุนไพร ไว้ในกฎหมายฉบับเดียว"}, {"label": "B", "text": "พ.ร.บ.ยา พ.ศ. 2510 ในฐานะยาแผนโบราณเช่นเดิมทุกประการ", "is_correct": false, "explanation": "ผิด การกำกับดูแลยาแผนไทยย้ายมาอยู่ภายใต้ พ.ร.บ.ผลิตภัณฑ์สมุนไพรแล้ว"}, {"label": "C", "text": "พ.ร.บ.อาหาร พ.ศ. 2522 ในฐานะอาหารควบคุมเฉพาะ", "is_correct": false, "explanation": "ผิด ยาแผนไทยไม่ใช่อาหาร"}, {"label": "D", "text": "พ.ร.บ.วิชาชีพการแพทย์แผนไทย พ.ศ. 2556 แต่เพียงฉบับเดียว", "is_correct": false, "explanation": "ผิด กฎหมายวิชาชีพกำกับผู้ประกอบวิชาชีพ ไม่ได้กำกับตัวผลิตภัณฑ์"}, {"label": "E", "text": "พ.ร.บ.คุ้มครองผู้บริโภค พ.ศ. 2522 ในฐานะสินค้าควบคุมฉลาก", "is_correct": false, "explanation": "ผิด กฎหมายคุ้มครองผู้บริโภคเป็นกฎหมายทั่วไป ไม่ใช่กฎหมายหลักที่กำกับยาแผนไทย"}], "key_takeaway": "ยาแผนไทยปัจจุบันอยู่ภายใต้ พ.ร.บ.ผลิตภัณฑ์สมุนไพร พ.ศ. 2562 ในฐานะยาจากสมุนไพร ไม่ใช่ยาแผนโบราณตาม พ.ร.บ.ยาอีกต่อไป"}'::jsonb, 'easy', 'law-day1 • พ.ร.บ.ผลิตภัณฑ์สมุนไพร – ขอบเขตครอบคลุมยาแผนไทย'),
('5678161b37e59e7892fcfd75777f7aeb', 109, 'วิสาหกิจชุมชนแห่งหนึ่งต้องการผลิตผลิตภัณฑ์จากสมุนไพรเพื่อจำหน่ายทั่วประเทศ จึงสอบถามเภสัชกรประจำ รพ.สต. เกี่ยวกับการอนุญาตผลิตภัณฑ์ตาม พ.ร.บ.ผลิตภัณฑ์สมุนไพร พ.ศ. 2562 ข้อใดอธิบายหลักการได้ถูกต้องที่สุด', '[{"label": "A", "text": "ผลิตภัณฑ์จากสมุนไพรไทยได้รับยกเว้นการควบคุมทั้งหมด เพราะเป็นภูมิปัญญาพื้นบ้าน"}, {"label": "B", "text": "ทุกผลิตภัณฑ์ต้องขึ้นทะเบียนตำรับยาแผนปัจจุบันตาม พ.ร.บ.ยา และผ่านการศึกษาทางคลินิกระยะที่ 3"}, {"label": "C", "text": "ผลิตภัณฑ์สมุนไพรต้องขึ้นทะเบียน แจ้งรายละเอียด หรือจดแจ้ง ตามประเภทที่กฎหมายกำหนด ก่อนผลิตหรือนำเข้าเพื่อขาย"}, {"label": "D", "text": "ให้ยื่นจดแจ้งเป็นเครื่องสำอางทุกกรณี ไม่ว่าผลิตภัณฑ์จะใช้ภายนอกหรือรับประทาน"}, {"label": "E", "text": "ต้องขออนุญาตเฉพาะสถานที่ผลิต ส่วนตัวผลิตภัณฑ์ไม่ต้องดำเนินการใด ๆ กับ อย."}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ผลิตภัณฑ์สมุนไพรต้องขึ้นทะเบียน แจ้งรายละเอียด หรือจดแจ้ง ตามประเภทที่กฎหมายกำหนด ก่อนผลิตหรือนำเข้าเพื่อขาย — กฎหมายกำหนดช่องทางการอนุญาตผลิตภัณฑ์ 3 ระดับ ตามประเภทและความเสี่ยงของผลิตภัณฑ์", "reason": "พ.ร.บ.ผลิตภัณฑ์สมุนไพร พ.ศ. 2562 กำหนดให้ผู้รับอนุญาตผลิตหรือนำเข้าผลิตภัณฑ์สมุนไพรต้องนำผลิตภัณฑ์มาดำเนินการก่อนผลิตหรือนำเข้า โดยแบ่งเป็น 3 ช่องทาง ได้แก่ การขึ้นทะเบียน การแจ้งรายละเอียด และการจดแจ้ง ตามประเภทผลิตภัณฑ์ที่รัฐมนตรีประกาศกำหนด ซึ่งสะท้อนระดับความเสี่ยงและความเข้มงวดในการพิจารณาที่แตกต่างกัน\n\nนอกจากตัวผลิตภัณฑ์แล้ว สถานที่ผลิตหรือนำเข้าก็ต้องได้รับอนุญาตด้วย การเป็นภูมิปัญญาพื้นบ้านไม่ได้ยกเว้นการผลิตเพื่อขาย", "choices": [{"label": "A", "text": "ผลิตภัณฑ์จากสมุนไพรไทยได้รับยกเว้นการควบคุมทั้งหมด เพราะเป็นภูมิปัญญาพื้นบ้าน", "is_correct": false, "explanation": "ผิด การผลิตเพื่อขายต้องอยู่ภายใต้การกำกับดูแลตามกฎหมาย"}, {"label": "B", "text": "ทุกผลิตภัณฑ์ต้องขึ้นทะเบียนตำรับยาแผนปัจจุบันตาม พ.ร.บ.ยา และผ่านการศึกษาทางคลินิกระยะที่ 3", "is_correct": false, "explanation": "ผิด ผลิตภัณฑ์สมุนไพรอยู่ภายใต้กฎหมายเฉพาะ และไม่ได้กำหนดให้ทุกผลิตภัณฑ์ต้องผ่านการศึกษาระยะที่ 3"}, {"label": "C", "text": "ผลิตภัณฑ์สมุนไพรต้องขึ้นทะเบียน แจ้งรายละเอียด หรือจดแจ้ง ตามประเภทที่กฎหมายกำหนด ก่อนผลิตหรือนำเข้าเพื่อขาย", "is_correct": true, "explanation": "ถูกต้อง กฎหมายกำหนดช่องทางการอนุญาตผลิตภัณฑ์ 3 ระดับ ตามประเภทและความเสี่ยงของผลิตภัณฑ์"}, {"label": "D", "text": "ให้ยื่นจดแจ้งเป็นเครื่องสำอางทุกกรณี ไม่ว่าผลิตภัณฑ์จะใช้ภายนอกหรือรับประทาน", "is_correct": false, "explanation": "ผิด ผลิตภัณฑ์สำหรับรับประทานไม่ใช่เครื่องสำอาง และผลิตภัณฑ์สมุนไพรมีช่องทางของตนเอง"}, {"label": "E", "text": "ต้องขออนุญาตเฉพาะสถานที่ผลิต ส่วนตัวผลิตภัณฑ์ไม่ต้องดำเนินการใด ๆ กับ อย.", "is_correct": false, "explanation": "ผิด ทั้งสถานที่และตัวผลิตภัณฑ์ต้องได้รับอนุญาตหรือดำเนินการตามที่กฎหมายกำหนด"}], "key_takeaway": "ผลิตภัณฑ์สมุนไพรเข้าสู่ตลาดผ่าน 3 ช่องทาง คือ ขึ้นทะเบียน แจ้งรายละเอียด หรือจดแจ้ง ตามประเภทและความเสี่ยงของผลิตภัณฑ์"}'::jsonb, 'medium', 'law-day1 • พ.ร.บ.ผลิตภัณฑ์สมุนไพร – ขึ้นทะเบียน/แจ้งรายละเอียด/จดแจ้ง'),
('ed7d2d9a4503d4694d85157eef8d74d3', 110, 'ร้านขายยาแห่งหนึ่งโพสต์ทางเพจของร้านว่า “ยาแก้ปวดข้อตัวนี้ หายขาด 100% ไม่มีผลข้างเคียง” โดยไม่ได้ขออนุญาตโฆษณา ผู้บริโภคร้องเรียนไปยัง สคบ. และ อย. เจ้าหน้าที่ต้องพิจารณาว่าจะใช้กฎหมายฉบับใด ข้อใดอธิบายความสัมพันธ์ระหว่าง พ.ร.บ.คุ้มครองผู้บริโภค พ.ศ. 2522 กับกฎหมายเฉพาะ เช่น พ.ร.บ.ยา ได้ถูกต้องที่สุด', '[{"label": "A", "text": "พ.ร.บ.คุ้มครองผู้บริโภคมีลำดับศักดิ์สูงกว่า จึงใช้บังคับแทน พ.ร.บ.ยาในทุกเรื่องที่เกี่ยวกับโฆษณา"}, {"label": "B", "text": "เมื่อเป็นการโฆษณายา พ.ร.บ.คุ้มครองผู้บริโภคไม่สามารถนำมาใช้ได้เลยในทุกกรณี"}, {"label": "C", "text": "การโพสต์ทางเพจของร้านไม่ถือเป็นการโฆษณาตามกฎหมายใด เพราะไม่ได้ใช้สื่อโทรทัศน์หรือวิทยุ"}, {"label": "D", "text": "เรื่องที่กฎหมายเฉพาะบัญญัติไว้แล้วให้บังคับตามกฎหมายนั้น ส่วน พ.ร.บ.คุ้มครองผู้บริโภคใช้ได้เท่าที่ไม่ซ้ำหรือขัดกับกฎหมายเฉพาะ"}, {"label": "E", "text": "ผู้บริโภคร้องเรียนได้เพียงหน่วยงานเดียว และหน่วยงานนั้นใช้ได้เฉพาะกฎหมายของตนเองเท่านั้น"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. เรื่องที่กฎหมายเฉพาะบัญญัติไว้แล้วให้บังคับตามกฎหมายนั้น ส่วน พ.ร.บ.คุ้มครองผู้บริโภคใช้ได้เท่าที่ไม่ซ้ำหรือขัดกับกฎหมายเฉพาะ — พ.ร.บ.คุ้มครองผู้บริโภคเป็นกฎหมายกลาง ใช้เสริมในส่วนที่กฎหมายเฉพาะไม่ได้บัญญัติไว้หรือไม่ซ้ำ/ขัดกัน", "reason": "พ.ร.บ.คุ้มครองผู้บริโภค พ.ศ. 2522 มีบทบัญญัติว่า ในกรณีที่มีกฎหมายว่าด้วยการใดบัญญัติเรื่องใดไว้โดยเฉพาะแล้ว ให้บังคับตามกฎหมายนั้น และให้นำบทบัญญัติของ พ.ร.บ.คุ้มครองผู้บริโภคไปใช้บังคับได้เท่าที่ไม่ซ้ำหรือขัดกับกฎหมายนั้น\n\nในกรณีนี้ การโฆษณายาโดยไม่ได้รับอนุญาตและโอ้อวดสรรพคุณว่า “หายขาด” เป็นเรื่องที่ พ.ร.บ.ยา ควบคุมไว้โดยเฉพาะ จึงบังคับตาม พ.ร.บ.ยา เป็นหลัก ส่วนหลักทั่วไปเรื่องการโฆษณาที่เป็นเท็จหรือเกินความจริงตามกฎหมายคุ้มครองผู้บริโภคใช้เสริมได้ในส่วนที่ไม่ซ้ำหรือขัด", "choices": [{"label": "A", "text": "พ.ร.บ.คุ้มครองผู้บริโภคมีลำดับศักดิ์สูงกว่า จึงใช้บังคับแทน พ.ร.บ.ยาในทุกเรื่องที่เกี่ยวกับโฆษณา", "is_correct": false, "explanation": "ผิด ทั้งสองฉบับเป็นพระราชบัญญัติลำดับเดียวกัน และกฎหมายคุ้มครองผู้บริโภคเองกำหนดให้กฎหมายเฉพาะใช้ก่อน"}, {"label": "B", "text": "เมื่อเป็นการโฆษณายา พ.ร.บ.คุ้มครองผู้บริโภคไม่สามารถนำมาใช้ได้เลยในทุกกรณี", "is_correct": false, "explanation": "ผิด กฎหมายคุ้มครองผู้บริโภคยังใช้ได้ในส่วนที่ไม่ซ้ำหรือขัดกับกฎหมายเฉพาะ"}, {"label": "C", "text": "การโพสต์ทางเพจของร้านไม่ถือเป็นการโฆษณาตามกฎหมายใด เพราะไม่ได้ใช้สื่อโทรทัศน์หรือวิทยุ", "is_correct": false, "explanation": "ผิด การเผยแพร่ข้อความเพื่อประโยชน์ทางการค้าผ่านสื่อออนไลน์ถือเป็นการโฆษณา"}, {"label": "D", "text": "เรื่องที่กฎหมายเฉพาะบัญญัติไว้แล้วให้บังคับตามกฎหมายนั้น ส่วน พ.ร.บ.คุ้มครองผู้บริโภคใช้ได้เท่าที่ไม่ซ้ำหรือขัดกับกฎหมายเฉพาะ", "is_correct": true, "explanation": "ถูกต้อง พ.ร.บ.คุ้มครองผู้บริโภคเป็นกฎหมายกลาง ใช้เสริมในส่วนที่กฎหมายเฉพาะไม่ได้บัญญัติไว้หรือไม่ซ้ำ/ขัดกัน"}, {"label": "E", "text": "ผู้บริโภคร้องเรียนได้เพียงหน่วยงานเดียว และหน่วยงานนั้นใช้ได้เฉพาะกฎหมายของตนเองเท่านั้น", "is_correct": false, "explanation": "ผิด ผู้บริโภคร้องเรียนได้หลายช่องทาง และหน่วยงานประสานส่งต่อเรื่องตามอำนาจหน้าที่ได้"}], "key_takeaway": "กฎหมายเฉพาะ (เช่น พ.ร.บ.ยา อาหาร เครื่องสำอาง) ใช้บังคับก่อน พ.ร.บ.คุ้มครองผู้บริโภคใช้เสริมเท่าที่ไม่ซ้ำหรือขัด"}'::jsonb, 'hard', 'law-day1 • พ.ร.บ.คุ้มครองผู้บริโภค – ความสัมพันธ์กับกฎหมายเฉพาะ/การโฆษณาเกินจริง'),
('2202a9296176e6aea199e5181ffcc259', 111, 'ข้อใดอธิบายบทบาทของศูนย์เฝ้าระวังความปลอดภัยด้านผลิตภัณฑ์สุขภาพ (Health Product Vigilance Center; HPVC) ของสำนักงานคณะกรรมการอาหารและยาได้ถูกต้องที่สุด', '[{"label": "A", "text": "รวบรวมและประเมินรายงานอาการไม่พึงประสงค์จากผลิตภัณฑ์สุขภาพทั่วประเทศ เพื่อค้นหาสัญญาณความเสี่ยง และแลกเปลี่ยนข้อมูลกับเครือข่ายขององค์การอนามัยโลก"}, {"label": "B", "text": "ตัดสินคดีและกำหนดค่าชดเชยให้ผู้ป่วยที่เกิดอาการไม่พึงประสงค์จากยาทุกราย"}, {"label": "C", "text": "ออกใบอนุญาตขายยาและตรวจประเมินร้านยาตามหลักวิธีปฏิบัติที่ดีทางเภสัชกรรม"}, {"label": "D", "text": "รับรายงานเฉพาะอาการไม่พึงประสงค์จากยาที่ทำให้ผู้ป่วยเสียชีวิตเท่านั้น"}, {"label": "E", "text": "ทดสอบประสิทธิผลทางคลินิกของยาใหม่ก่อนการขึ้นทะเบียนตำรับยา"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. รวบรวมและประเมินรายงานอาการไม่พึงประสงค์จากผลิตภัณฑ์สุขภาพทั่วประเทศ เพื่อค้นหาสัญญาณความเสี่ยง และแลกเปลี่ยนข้อมูลกับเครือข่ายขององค์การอนามัยโลก — HPVC เป็นศูนย์กลางระดับชาติของระบบเฝ้าระวังความปลอดภัย และประเทศไทยเป็นสมาชิกโครงการติดตามความปลอดภัยด้านยาระหว่างประเทศของ WHO", "reason": "ศูนย์เฝ้าระวังความปลอดภัยด้านผลิตภัณฑ์สุขภาพ (HPVC) สังกัดสำนักงานคณะกรรมการอาหารและยา ทำหน้าที่เป็นศูนย์กลางระบบเฝ้าระวังความปลอดภัยหลังออกสู่ตลาดของประเทศ รับรายงานอาการไม่พึงประสงค์จากบุคลากรทางการแพทย์ ผู้รับอนุญาต และแหล่งอื่น ๆ วิเคราะห์หาสัญญาณความเสี่ยง (signal detection) และเผยแพร่ข้อมูลความปลอดภัยเพื่อนำไปสู่มาตรการทางกฎหมาย เช่น การแก้ไขฉลาก หรือการทบทวนทะเบียน\n\nประเทศไทยเป็นสมาชิกโครงการ WHO Programme for International Drug Monitoring จึงมีการส่งข้อมูลไปยังฐานข้อมูลระดับโลกที่ Uppsala Monitoring Centre", "choices": [{"label": "A", "text": "รวบรวมและประเมินรายงานอาการไม่พึงประสงค์จากผลิตภัณฑ์สุขภาพทั่วประเทศ เพื่อค้นหาสัญญาณความเสี่ยง และแลกเปลี่ยนข้อมูลกับเครือข่ายขององค์การอนามัยโลก", "is_correct": true, "explanation": "ถูกต้อง HPVC เป็นศูนย์กลางระดับชาติของระบบเฝ้าระวังความปลอดภัย และประเทศไทยเป็นสมาชิกโครงการติดตามความปลอดภัยด้านยาระหว่างประเทศของ WHO"}, {"label": "B", "text": "ตัดสินคดีและกำหนดค่าชดเชยให้ผู้ป่วยที่เกิดอาการไม่พึงประสงค์จากยาทุกราย", "is_correct": false, "explanation": "ผิด HPVC ไม่ใช่องค์กรตัดสินคดีหรือกำหนดค่าชดเชย"}, {"label": "C", "text": "ออกใบอนุญาตขายยาและตรวจประเมินร้านยาตามหลักวิธีปฏิบัติที่ดีทางเภสัชกรรม", "is_correct": false, "explanation": "ผิด เป็นงานด้านการอนุญาตและตรวจสถานประกอบการ ไม่ใช่บทบาทหลักของศูนย์เฝ้าระวัง"}, {"label": "D", "text": "รับรายงานเฉพาะอาการไม่พึงประสงค์จากยาที่ทำให้ผู้ป่วยเสียชีวิตเท่านั้น", "is_correct": false, "explanation": "ผิด ระบบรับรายงานอาการไม่พึงประสงค์ทุกระดับความรุนแรง และครอบคลุมผลิตภัณฑ์สุขภาพหลายประเภท"}, {"label": "E", "text": "ทดสอบประสิทธิผลทางคลินิกของยาใหม่ก่อนการขึ้นทะเบียนตำรับยา", "is_correct": false, "explanation": "ผิด การศึกษาทางคลินิกก่อนขึ้นทะเบียนเป็นหน้าที่ของผู้วิจัย/ผู้ยื่นขอ ไม่ใช่ HPVC"}], "key_takeaway": "HPVC เป็นศูนย์กลางระดับชาติในการรวบรวม วิเคราะห์ และเผยแพร่ข้อมูลความปลอดภัยของผลิตภัณฑ์สุขภาพ และเชื่อมกับเครือข่ายของ WHO"}'::jsonb, 'easy', 'law-day1 • Pharmacovigilance – บทบาทศูนย์ HPVC'),
('c9848175b3076e347f7bce08653af114', 112, 'เภสัชกรโรงพยาบาลชุมชนพบผู้ป่วยมีผื่นผิวหนังลอกและแผลในปากหลังเริ่มใช้ยาใหม่หลายรายการพร้อมกัน แพทย์ยังสรุปไม่ได้ว่าเกิดจากยาตัวใด เภสัชกรลังเลว่าจะรายงานอาการไม่พึงประสงค์ไปยังระบบเฝ้าระวังระดับชาติหรือไม่ ข้อใดถูกต้องตามหลักการเฝ้าระวังความปลอดภัยด้านยา', '[{"label": "A", "text": "ห้ามรายงานจนกว่าจะทำ rechallenge เพื่อยืนยันว่าเกิดจากยาตัวใด"}, {"label": "B", "text": "ไม่ต้องรายงาน เพราะการรายงานโดยสมัครใจใช้เฉพาะยาใหม่ในโครงการ SMP เท่านั้น"}, {"label": "C", "text": "ควรรายงานเฉพาะเมื่อผู้ป่วยหรือญาติประสงค์จะฟ้องร้องผู้ผลิต"}, {"label": "D", "text": "ควรรายงานเมื่อสงสัยว่าเป็นอาการไม่พึงประสงค์จากยา โดยไม่ต้องรอพิสูจน์ความสัมพันธ์เชิงสาเหตุให้แน่ชัด และระบุยาที่สงสัยทุกรายการ"}, {"label": "E", "text": "ไม่ต้องรายงาน เพราะรายงานอาจถูกนำไปใช้เป็นหลักฐานลงโทษแพทย์ผู้สั่งใช้ยา"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ควรรายงานเมื่อสงสัยว่าเป็นอาการไม่พึงประสงค์จากยา โดยไม่ต้องรอพิสูจน์ความสัมพันธ์เชิงสาเหตุให้แน่ชัด และระบุยาที่สงสัยทุกรายการ — ระบบ spontaneous reporting ต้องการรายงานจากความสงสัย การประเมินความสัมพันธ์เชิงสาเหตุทำต่อในระดับศูนย์", "reason": "ระบบรายงานอาการไม่พึงประสงค์โดยสมัครใจ (spontaneous reporting) เป็นหัวใจของการเฝ้าระวังความปลอดภัยหลังออกสู่ตลาด บุคลากรทางการแพทย์ควรรายงานเมื่อ “สงสัย” ว่าอาการเกิดจากผลิตภัณฑ์สุขภาพ โดยไม่ต้องพิสูจน์ความสัมพันธ์เชิงสาเหตุให้แน่ชัดก่อน หากมียาหลายรายการให้ระบุยาที่สงสัยทั้งหมดพร้อมข้อมูลช่วงเวลาที่ใช้\n\nอาการผื่นผิวหนังลอกร่วมกับแผลในเยื่อบุเป็นอาการรุนแรงที่ควรรายงานโดยเร็ว ข้อมูลจากหลายรายงานรวมกันช่วยให้ศูนย์ระดับชาติตรวจพบสัญญาณความเสี่ยงและนำไปสู่มาตรการกำกับดูแลได้", "choices": [{"label": "A", "text": "ห้ามรายงานจนกว่าจะทำ rechallenge เพื่อยืนยันว่าเกิดจากยาตัวใด", "is_correct": false, "explanation": "ผิด ไม่จำเป็นต้องยืนยันก่อนรายงาน และการ rechallenge ในอาการรุนแรงเช่นนี้เป็นอันตราย"}, {"label": "B", "text": "ไม่ต้องรายงาน เพราะการรายงานโดยสมัครใจใช้เฉพาะยาใหม่ในโครงการ SMP เท่านั้น", "is_correct": false, "explanation": "ผิด การรายงานโดยสมัครใจครอบคลุมยาทุกรายการ ไม่จำกัดเฉพาะยาใน SMP"}, {"label": "C", "text": "ควรรายงานเฉพาะเมื่อผู้ป่วยหรือญาติประสงค์จะฟ้องร้องผู้ผลิต", "is_correct": false, "explanation": "ผิด การรายงานมีวัตถุประสงค์เพื่อความปลอดภัยของสาธารณะ ไม่ได้ผูกกับการฟ้องร้อง"}, {"label": "D", "text": "ควรรายงานเมื่อสงสัยว่าเป็นอาการไม่พึงประสงค์จากยา โดยไม่ต้องรอพิสูจน์ความสัมพันธ์เชิงสาเหตุให้แน่ชัด และระบุยาที่สงสัยทุกรายการ", "is_correct": true, "explanation": "ถูกต้อง ระบบ spontaneous reporting ต้องการรายงานจากความสงสัย การประเมินความสัมพันธ์เชิงสาเหตุทำต่อในระดับศูนย์"}, {"label": "E", "text": "ไม่ต้องรายงาน เพราะรายงานอาจถูกนำไปใช้เป็นหลักฐานลงโทษแพทย์ผู้สั่งใช้ยา", "is_correct": false, "explanation": "ผิด ระบบเฝ้าระวังมีวัตถุประสงค์เพื่อเรียนรู้และป้องกัน ไม่ใช่เพื่อหาผู้กระทำผิด"}], "key_takeaway": "รายงาน ADR เมื่อสงสัย ไม่ต้องรอพิสูจน์ความสัมพันธ์เชิงสาเหตุ โดยเฉพาะอาการรุนแรง"}'::jsonb, 'medium', 'law-day1 • Pharmacovigilance – การรายงาน ADR โดยสมัครใจ'),
('76a96a21bc204e41fdedfafc386eb0b4', 113, 'ในการรายงานอาการไม่พึงประสงค์จากยา (ADR) เหตุการณ์ใดต่อไปนี้ “ไม่เข้า” เกณฑ์ ADR ร้ายแรง (serious ADR) ตามนิยามสากลที่ใช้ในระบบเฝ้าระวังของประเทศไทย', '[{"label": "A", "text": "อาการที่ทำให้ผู้ป่วยเสียชีวิต"}, {"label": "B", "text": "อาการที่เป็นอันตรายถึงชีวิตในขณะที่เกิดเหตุการณ์"}, {"label": "C", "text": "อาการที่ทำให้ต้องเข้ารักษาในโรงพยาบาลหรือต้องอยู่โรงพยาบาลนานขึ้น"}, {"label": "D", "text": "อาการที่ทำให้เกิดความพิการถาวร หรือทารกที่คลอดมีความพิการแต่กำเนิด"}, {"label": "E", "text": "อาการที่ไม่ได้ระบุไว้ในเอกสารกำกับยา แต่รุนแรงเพียงเล็กน้อยและหายได้เองโดยไม่ต้องรักษา"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. อาการที่ไม่ได้ระบุไว้ในเอกสารกำกับยา แต่รุนแรงเพียงเล็กน้อยและหายได้เองโดยไม่ต้องรักษา — เป็น ADR ที่ “ไม่คาดคิด” (unexpected) แต่ไม่ใช่ “ร้ายแรง” (serious) เพราะไม่เข้าเกณฑ์ผลลัพธ์รุนแรงใด", "reason": "ADR ร้ายแรง (serious) ตามนิยามสากล หมายถึงอาการไม่พึงประสงค์ที่ส่งผลให้ เสียชีวิต อันตรายถึงชีวิต ต้องเข้ารักษาตัวในโรงพยาบาลหรือนอนโรงพยาบาลนานขึ้น เกิดความพิการหรือไร้ความสามารถอย่างถาวรหรือมีนัยสำคัญ ทารกพิการแต่กำเนิด หรือเหตุการณ์สำคัญทางการแพทย์อื่น ๆ\n\nความ “ร้ายแรง” (seriousness) ต่างจากความ “ไม่คาดคิด” (unexpectedness) ซึ่งหมายถึงอาการที่ไม่สอดคล้องกับข้อมูลในเอกสารกำกับยา อาการที่ไม่คาดคิดแต่เล็กน้อยจึงไม่ใช่ ADR ร้ายแรง แม้ยังควรรายงานเพราะมีคุณค่าในการค้นหาสัญญาณใหม่", "choices": [{"label": "A", "text": "อาการที่ทำให้ผู้ป่วยเสียชีวิต", "is_correct": false, "explanation": "เข้าเกณฑ์ร้ายแรง"}, {"label": "B", "text": "อาการที่เป็นอันตรายถึงชีวิตในขณะที่เกิดเหตุการณ์", "is_correct": false, "explanation": "เข้าเกณฑ์ร้ายแรง"}, {"label": "C", "text": "อาการที่ทำให้ต้องเข้ารักษาในโรงพยาบาลหรือต้องอยู่โรงพยาบาลนานขึ้น", "is_correct": false, "explanation": "เข้าเกณฑ์ร้ายแรง"}, {"label": "D", "text": "อาการที่ทำให้เกิดความพิการถาวร หรือทารกที่คลอดมีความพิการแต่กำเนิด", "is_correct": false, "explanation": "เข้าเกณฑ์ร้ายแรง"}, {"label": "E", "text": "อาการที่ไม่ได้ระบุไว้ในเอกสารกำกับยา แต่รุนแรงเพียงเล็กน้อยและหายได้เองโดยไม่ต้องรักษา", "is_correct": true, "explanation": "ถูกต้อง เป็น ADR ที่ “ไม่คาดคิด” (unexpected) แต่ไม่ใช่ “ร้ายแรง” (serious) เพราะไม่เข้าเกณฑ์ผลลัพธ์รุนแรงใด"}], "key_takeaway": "ADR ร้ายแรงพิจารณาจากผลลัพธ์ (เสียชีวิต อันตรายถึงชีวิต นอนโรงพยาบาล พิการ ทารกพิการแต่กำเนิด) ไม่ใช่จากการที่อาการไม่อยู่ในเอกสารกำกับยา"}'::jsonb, 'medium', 'law-day1 • Pharmacovigilance – เกณฑ์ ADR ร้ายแรง'),
('d4ad1242979538209ffc2900259295de', 114, 'ผู้ป่วยถือใบสั่งยาจากแพทย์คลินิกมาขอซื้อยาใหม่รายการหนึ่งที่ร้านยา เภสัชกรตรวจสอบพบว่ายานี้ได้รับทะเบียนตำรับยาแบบมีเงื่อนไขและอยู่ระหว่างโครงการติดตามความปลอดภัยของยาใหม่ (Safety Monitoring Program; SMP) ข้อใดถูกต้อง', '[{"label": "A", "text": "จำหน่ายได้ เพราะมีใบสั่งยาจากแพทย์ และเภสัชกรเป็นผู้ส่งมอบยาด้วยตนเอง"}, {"label": "B", "text": "จำหน่ายได้ หากผู้ป่วยลงนามยินยอมรับความเสี่ยงจากการใช้ยาใหม่"}, {"label": "C", "text": "ยาที่อยู่ระหว่าง SMP มีเงื่อนไขให้จำหน่ายและใช้เฉพาะในสถานพยาบาลภายใต้การดูแลของแพทย์ ร้านยาจึงจำหน่ายไม่ได้แม้มีใบสั่งยา"}, {"label": "D", "text": "จำหน่ายได้ เฉพาะร้านยาที่ผ่านการรับรองมาตรฐานร้านยาคุณภาพ"}, {"label": "E", "text": "จำหน่ายได้ โดยไม่ต้องรายงานอาการไม่พึงประสงค์ เพราะเป็นหน้าที่ของบริษัทยาแต่ผู้เดียว"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ยาที่อยู่ระหว่าง SMP มีเงื่อนไขให้จำหน่ายและใช้เฉพาะในสถานพยาบาลภายใต้การดูแลของแพทย์ ร้านยาจึงจำหน่ายไม่ได้แม้มีใบสั่งยา — เงื่อนไขของทะเบียนตำรับยาแบบมีเงื่อนไขจำกัดการใช้ในโรงพยาบาลและคลินิก เพื่อให้ติดตามความปลอดภัยของผู้ป่วยได้", "reason": "ยาใหม่ที่ได้รับทะเบียนตำรับยาแบบมีเงื่อนไขต้องเข้าสู่ระบบติดตามความปลอดภัย (SMP) ในช่วงแรกหลังออกสู่ตลาด เพราะข้อมูลจากการศึกษาทางคลินิกก่อนขึ้นทะเบียนยังมีจำนวนผู้ป่วยจำกัด อาจไม่พบอาการไม่พึงประสงค์ที่เกิดน้อยหรือในประชากรไทย\n\nเงื่อนไขสำคัญคือให้ใช้ยาเฉพาะในสถานพยาบาล (โรงพยาบาลและคลินิก) ภายใต้การดูแลของแพทย์ เพื่อให้ติดตามผู้ป่วยและรายงานอาการไม่พึงประสงค์ได้อย่างเป็นระบบ ร้านยาจึงไม่สามารถจำหน่ายยาที่อยู่ระหว่าง SMP ได้", "choices": [{"label": "A", "text": "จำหน่ายได้ เพราะมีใบสั่งยาจากแพทย์ และเภสัชกรเป็นผู้ส่งมอบยาด้วยตนเอง", "is_correct": false, "explanation": "ผิด เงื่อนไขทะเบียนจำกัดสถานที่ใช้ยา การมีใบสั่งยาไม่ได้ยกเว้นเงื่อนไขนี้"}, {"label": "B", "text": "จำหน่ายได้ หากผู้ป่วยลงนามยินยอมรับความเสี่ยงจากการใช้ยาใหม่", "is_correct": false, "explanation": "ผิด การยินยอมของผู้ป่วยไม่เปลี่ยนเงื่อนไขของทะเบียนตำรับยา"}, {"label": "C", "text": "ยาที่อยู่ระหว่าง SMP มีเงื่อนไขให้จำหน่ายและใช้เฉพาะในสถานพยาบาลภายใต้การดูแลของแพทย์ ร้านยาจึงจำหน่ายไม่ได้แม้มีใบสั่งยา", "is_correct": true, "explanation": "ถูกต้อง เงื่อนไขของทะเบียนตำรับยาแบบมีเงื่อนไขจำกัดการใช้ในโรงพยาบาลและคลินิก เพื่อให้ติดตามความปลอดภัยของผู้ป่วยได้"}, {"label": "D", "text": "จำหน่ายได้ เฉพาะร้านยาที่ผ่านการรับรองมาตรฐานร้านยาคุณภาพ", "is_correct": false, "explanation": "ผิด การรับรองร้านยาคุณภาพไม่ได้ให้สิทธิจำหน่ายยาที่จำกัดเฉพาะสถานพยาบาล"}, {"label": "E", "text": "จำหน่ายได้ โดยไม่ต้องรายงานอาการไม่พึงประสงค์ เพราะเป็นหน้าที่ของบริษัทยาแต่ผู้เดียว", "is_correct": false, "explanation": "ผิด ทั้งการจำหน่ายในร้านยาไม่ถูกต้อง และบุคลากรควรรายงานอาการไม่พึงประสงค์ของยาใหม่ด้วย"}], "key_takeaway": "ยาใน SMP (ทะเบียนแบบมีเงื่อนไข) ใช้ได้เฉพาะในสถานพยาบาลภายใต้การดูแลของแพทย์ ร้านยาจำหน่ายไม่ได้แม้มีใบสั่งยา"}'::jsonb, 'medium', 'law-day1 • Pharmacovigilance – ยาใน Safety Monitoring Program (SMP)'),
('e7c52c7aaab71d3a8f8fb2511a11ca3c', 115, 'บริษัทยาได้รับทะเบียนตำรับยาแบบมีเงื่อนไขสำหรับยาที่มีสารออกฤทธิ์ใหม่ โรงพยาบาลจังหวัดนำยานี้เข้าบัญชียาโรงพยาบาล และฝ่ายเภสัชกรรมวางระบบติดตามผู้ป่วยทุกรายที่ได้รับยา ข้อใดอธิบายระบบ SMP และหน้าที่ของผู้เกี่ยวข้องได้ถูกต้องที่สุด', '[{"label": "A", "text": "SMP มีวัตถุประสงค์เพื่อเปรียบเทียบประสิทธิผลกับยาหลอกในผู้ป่วยไทย ซึ่งต้องทำให้เสร็จก่อนได้รับทะเบียนแบบมีเงื่อนไข"}, {"label": "B", "text": "ผู้รับอนุญาตต้องติดตามความปลอดภัยตามเงื่อนไขและส่งรายงานต่อ อย. เมื่อข้อมูลเพียงพอจึงอาจได้รับการพิจารณาเปลี่ยนเป็นทะเบียนแบบไม่มีเงื่อนไข ส่วนบุคลากรควรรายงาน ADR ที่พบ"}, {"label": "C", "text": "ยาใน SMP ถือว่าปลอดภัยโดยสมบูรณ์แล้ว จึงจำหน่ายได้ทุกช่องทาง รวมทั้งร้านยาและการขายออนไลน์"}, {"label": "D", "text": "ทะเบียนแบบมีเงื่อนไขเปลี่ยนเป็นทะเบียนแบบไม่มีเงื่อนไขโดยอัตโนมัติเมื่อครบกำหนดเวลา โดยไม่ต้องส่งข้อมูลความปลอดภัย"}, {"label": "E", "text": "โรงพยาบาลต้องรับผิดชอบติดตามและรายงานแทนบริษัทยาทั้งหมด ผู้รับอนุญาตไม่มีหน้าที่ติดตามความปลอดภัย"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ผู้รับอนุญาตต้องติดตามความปลอดภัยตามเงื่อนไขและส่งรายงานต่อ อย. เมื่อข้อมูลเพียงพอจึงอาจได้รับการพิจารณาเปลี่ยนเป็นทะเบียนแบบไม่มีเงื่อนไข ส่วนบุคลากรควรรายงาน ADR ที่พบ — สะท้อนทั้งหน้าที่ของผู้รับอนุญาต กลไกการเปลี่ยนสถานะทะเบียนซึ่งต้องพิจารณาจากข้อมูลความปลอดภัย และบทบาทของบุคลากรในสถานพยาบาล", "reason": "ระบบ SMP เป็นกลไกการกำกับดูแลยาใหม่หลังออกสู่ตลาด ผู้รับอนุญาตที่ได้ทะเบียนตำรับยาแบบมีเงื่อนไขมีหน้าที่ติดตามความปลอดภัยของยาในช่วงเวลาที่กำหนดและส่งรายงานความปลอดภัยต่อ อย. ตามเงื่อนไข เมื่อครบกำหนดและข้อมูลแสดงว่ายามีความปลอดภัยเพียงพอ จึงยื่นขอและได้รับการพิจารณาเปลี่ยนเป็นทะเบียนตำรับยาแบบไม่มีเงื่อนไข หากพบปัญหาความปลอดภัย อย. อาจคงเงื่อนไข เพิ่มคำเตือน หรือพิจารณามาตรการอื่น\n\nในช่วง SMP ยาจะใช้ในสถานพยาบาลภายใต้การดูแลของแพทย์ บุคลากรในสถานพยาบาล เช่น เภสัชกร มีบทบาทติดตามผู้ป่วยและรายงานอาการไม่พึงประสงค์ที่พบ ข้อมูลเหล่านี้เป็นฐานของการตัดสินใจทางทะเบียน", "choices": [{"label": "A", "text": "SMP มีวัตถุประสงค์เพื่อเปรียบเทียบประสิทธิผลกับยาหลอกในผู้ป่วยไทย ซึ่งต้องทำให้เสร็จก่อนได้รับทะเบียนแบบมีเงื่อนไข", "is_correct": false, "explanation": "ผิด SMP เป็นการเฝ้าระวังความปลอดภัยหลังได้รับทะเบียน ไม่ใช่การศึกษาประสิทธิผลเทียบยาหลอกก่อนขึ้นทะเบียน"}, {"label": "B", "text": "ผู้รับอนุญาตต้องติดตามความปลอดภัยตามเงื่อนไขและส่งรายงานต่อ อย. เมื่อข้อมูลเพียงพอจึงอาจได้รับการพิจารณาเปลี่ยนเป็นทะเบียนแบบไม่มีเงื่อนไข ส่วนบุคลากรควรรายงาน ADR ที่พบ", "is_correct": true, "explanation": "ถูกต้อง สะท้อนทั้งหน้าที่ของผู้รับอนุญาต กลไกการเปลี่ยนสถานะทะเบียนซึ่งต้องพิจารณาจากข้อมูลความปลอดภัย และบทบาทของบุคลากรในสถานพยาบาล"}, {"label": "C", "text": "ยาใน SMP ถือว่าปลอดภัยโดยสมบูรณ์แล้ว จึงจำหน่ายได้ทุกช่องทาง รวมทั้งร้านยาและการขายออนไลน์", "is_correct": false, "explanation": "ผิด ยาใน SMP ยังมีข้อมูลความปลอดภัยจำกัด และถูกจำกัดให้ใช้ในสถานพยาบาล"}, {"label": "D", "text": "ทะเบียนแบบมีเงื่อนไขเปลี่ยนเป็นทะเบียนแบบไม่มีเงื่อนไขโดยอัตโนมัติเมื่อครบกำหนดเวลา โดยไม่ต้องส่งข้อมูลความปลอดภัย", "is_correct": false, "explanation": "ผิด การเปลี่ยนสถานะต้องอาศัยการพิจารณาข้อมูลความปลอดภัยที่ผู้รับอนุญาตส่ง ไม่ได้เกิดขึ้นอัตโนมัติ"}, {"label": "E", "text": "โรงพยาบาลต้องรับผิดชอบติดตามและรายงานแทนบริษัทยาทั้งหมด ผู้รับอนุญาตไม่มีหน้าที่ติดตามความปลอดภัย", "is_correct": false, "explanation": "ผิด ผู้รับอนุญาตเป็นผู้มีหน้าที่หลักตามเงื่อนไขทะเบียน โรงพยาบาลเป็นแหล่งข้อมูลและผู้รายงาน"}], "key_takeaway": "SMP คือการติดตามความปลอดภัยยาใหม่หลังได้ทะเบียนแบบมีเงื่อนไข การเปลี่ยนเป็นทะเบียนไม่มีเงื่อนไขต้องพิจารณาจากข้อมูลความปลอดภัย ไม่ใช่อัตโนมัติ"}'::jsonb, 'hard', 'law-day1 • Pharmacovigilance – วงจรของ SMP และหน้าที่ของผู้เกี่ยวข้อง'),
('a941648d13fae51f17355ca7c439ac8a', 116, 'ข้อใดอธิบายบทบาทของบัญชียาหลักแห่งชาติในฐานะเครื่องมือเชิงนโยบายของระบบยาไทยได้ถูกต้องที่สุด', '[{"label": "A", "text": "เป็นรายชื่อยาที่ได้รับอนุญาตให้ขึ้นทะเบียนในไทย ยาที่ไม่อยู่ในบัญชีจะจำหน่ายในประเทศไม่ได้"}, {"label": "B", "text": "เป็นรายการยาที่ร้านยาทุกแห่งต้องมีไว้จำหน่ายครบทุกรายการตามเงื่อนไขใบอนุญาต"}, {"label": "C", "text": "เป็นบัญชีที่กำหนดราคาขายปลีกสูงสุดของยาทุกรายการในตลาดเอกชน"}, {"label": "D", "text": "เป็นบัญชีรายชื่อยาที่ห้ามแพทย์สั่งใช้ในโรงพยาบาลเอกชน"}, {"label": "E", "text": "เป็นรายการยาที่จำเป็น คุ้มค่า และเหมาะสม ใช้อ้างอิงสิทธิประโยชน์ด้านยาของระบบหลักประกันสุขภาพภาครัฐและการจัดหายาของหน่วยงานรัฐ"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. เป็นรายการยาที่จำเป็น คุ้มค่า และเหมาะสม ใช้อ้างอิงสิทธิประโยชน์ด้านยาของระบบหลักประกันสุขภาพภาครัฐและการจัดหายาของหน่วยงานรัฐ — บัญชียาหลักแห่งชาติเป็นเครื่องมือกำหนดรายการยาจำเป็นที่ใช้เชื่อมโยงกับสิทธิประโยชน์และการจัดซื้อยาภาครัฐ", "reason": "บัญชียาหลักแห่งชาติเป็นรายการยาที่คัดเลือกโดยพิจารณาความจำเป็นด้านสาธารณสุข ประสิทธิผล ความปลอดภัย และความคุ้มค่า จัดทำภายใต้คณะกรรมการพัฒนาระบบยาแห่งชาติ ทำหน้าที่เป็นเครื่องมือเชิงนโยบายสำคัญ เช่น เป็นกรอบสิทธิประโยชน์ด้านยาของระบบหลักประกันสุขภาพภาครัฐ (บัตรทอง ประกันสังคม สวัสดิการรักษาพยาบาลข้าราชการ) และเป็นแนวทางการจัดหายาของหน่วยงานรัฐ เพื่อส่งเสริมการเข้าถึงยาจำเป็นและการใช้ยาอย่างสมเหตุผล\n\nบัญชียาหลักไม่ใช่ทะเบียนตำรับยา ยาที่ไม่อยู่ในบัญชียังขึ้นทะเบียนและจำหน่ายได้ตาม พ.ร.บ.ยา", "choices": [{"label": "A", "text": "เป็นรายชื่อยาที่ได้รับอนุญาตให้ขึ้นทะเบียนในไทย ยาที่ไม่อยู่ในบัญชีจะจำหน่ายในประเทศไม่ได้", "is_correct": false, "explanation": "ผิด การขึ้นทะเบียนตำรับยาเป็นเรื่องของ พ.ร.บ.ยา ยาที่ไม่อยู่ในบัญชียาหลักยังขึ้นทะเบียนและจำหน่ายได้"}, {"label": "B", "text": "เป็นรายการยาที่ร้านยาทุกแห่งต้องมีไว้จำหน่ายครบทุกรายการตามเงื่อนไขใบอนุญาต", "is_correct": false, "explanation": "ผิด ไม่มีข้อกำหนดให้ร้านยาต้องมียาครบตามบัญชียาหลักแห่งชาติ"}, {"label": "C", "text": "เป็นบัญชีที่กำหนดราคาขายปลีกสูงสุดของยาทุกรายการในตลาดเอกชน", "is_correct": false, "explanation": "ผิด บัญชียาหลักไม่ได้เป็นกลไกกำหนดราคาขายปลีกสูงสุดในตลาดเอกชน"}, {"label": "D", "text": "เป็นบัญชีรายชื่อยาที่ห้ามแพทย์สั่งใช้ในโรงพยาบาลเอกชน", "is_correct": false, "explanation": "ผิด บัญชียาหลักไม่ได้ห้ามการสั่งใช้ยาในภาคเอกชน"}, {"label": "E", "text": "เป็นรายการยาที่จำเป็น คุ้มค่า และเหมาะสม ใช้อ้างอิงสิทธิประโยชน์ด้านยาของระบบหลักประกันสุขภาพภาครัฐและการจัดหายาของหน่วยงานรัฐ", "is_correct": true, "explanation": "ถูกต้อง บัญชียาหลักแห่งชาติเป็นเครื่องมือกำหนดรายการยาจำเป็นที่ใช้เชื่อมโยงกับสิทธิประโยชน์และการจัดซื้อยาภาครัฐ"}], "key_takeaway": "บัญชียาหลักแห่งชาติเป็นเครื่องมือนโยบายกำหนดยาจำเป็นที่คุ้มค่าเพื่อสิทธิประโยชน์และการจัดหาภาครัฐ ไม่ใช่ทะเบียนที่ห้ามจำหน่ายยานอกบัญชี"}'::jsonb, 'easy', 'law-day1 • บัญชียาหลักแห่งชาติ – เครื่องมือเชิงนโยบาย'),
('65e850c2f61179931a0351b8d311b37a', 117, 'อย. ตรวจพบเครื่องดื่มสมุนไพรชนิดผงที่แสดงฉลากว่า “ผลิตในประเทศญี่ปุ่น” และ “มีโสมสกัด 50%” แต่การตรวจสอบพบว่าผลิตในประเทศไทยและตรวจไม่พบส่วนประกอบของโสมเลย ตาม พ.ร.บ.อาหาร พ.ศ. 2522 ผลิตภัณฑ์นี้เข้าข่ายข้อใดมากที่สุด', '[{"label": "A", "text": "อาหารไม่บริสุทธิ์ เพราะมีเชื้อโรคหรือสารพิษเจือปนในระดับที่เป็นอันตราย"}, {"label": "B", "text": "อาหารปลอม เพราะแสดงฉลากเพื่อลวงให้ผู้ซื้อเข้าใจผิดในเรื่องคุณภาพ ส่วนประกอบ และประเทศที่ผลิต"}, {"label": "C", "text": "อาหารผิดมาตรฐานเพียงเล็กน้อย จึงไม่มีความผิดตามกฎหมาย"}, {"label": "D", "text": "ถูกต้องตามกฎหมาย เพราะผู้ผลิตระบุประเทศที่ผลิตตามแหล่งวัตถุดิบหลักได้"}, {"label": "E", "text": "เป็นเพียงปัญหาการโฆษณา ซึ่งอยู่นอกขอบเขตของ พ.ร.บ.อาหาร"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. อาหารปลอม เพราะแสดงฉลากเพื่อลวงให้ผู้ซื้อเข้าใจผิดในเรื่องคุณภาพ ส่วนประกอบ และประเทศที่ผลิต — การแสดงฉลากเพื่อลวงหรือพยายามลวงให้เข้าใจผิดในเรื่องคุณภาพ ประโยชน์ หรือสถานที่และประเทศที่ผลิต เป็นลักษณะหนึ่งของอาหารปลอม", "reason": "พ.ร.บ.อาหาร พ.ศ. 2522 ห้ามผลิต นำเข้า หรือจำหน่ายอาหารไม่บริสุทธิ์ อาหารปลอม อาหารผิดมาตรฐาน และอาหารอื่นที่รัฐมนตรีกำหนด โดย “อาหารปลอม” ครอบคลุมหลายลักษณะ เช่น อาหารที่ใช้วัตถุอื่นแทนทั้งหมดหรือบางส่วน และอาหารที่แสดงฉลากเพื่อลวงหรือพยายามลวงผู้ซื้อให้เข้าใจผิดในเรื่องคุณภาพ ปริมาณ ประโยชน์ หรือลักษณะพิเศษอย่างอื่น หรือในเรื่องสถานที่และประเทศที่ผลิต\n\nผลิตภัณฑ์นี้อ้างว่าผลิตในญี่ปุ่นและมีโสม 50% แต่ความจริงผลิตในไทยและไม่มีโสม จึงเข้าข่ายอาหารปลอม ส่วนอาหารไม่บริสุทธิ์มุ่งถึงการปนเปื้อนสิ่งที่เป็นอันตราย และอาหารผิดมาตรฐานคืออาหารที่คุณภาพไม่ถึงมาตรฐานที่กำหนดแต่ไม่ถึงขั้นอาหารปลอม", "choices": [{"label": "A", "text": "อาหารไม่บริสุทธิ์ เพราะมีเชื้อโรคหรือสารพิษเจือปนในระดับที่เป็นอันตราย", "is_correct": false, "explanation": "ผิด โจทย์ไม่ได้ระบุการปนเปื้อนเชื้อโรคหรือสารพิษ ประเด็นคือฉลากลวงให้เข้าใจผิด"}, {"label": "B", "text": "อาหารปลอม เพราะแสดงฉลากเพื่อลวงให้ผู้ซื้อเข้าใจผิดในเรื่องคุณภาพ ส่วนประกอบ และประเทศที่ผลิต", "is_correct": true, "explanation": "ถูกต้อง การแสดงฉลากเพื่อลวงหรือพยายามลวงให้เข้าใจผิดในเรื่องคุณภาพ ประโยชน์ หรือสถานที่และประเทศที่ผลิต เป็นลักษณะหนึ่งของอาหารปลอม"}, {"label": "C", "text": "อาหารผิดมาตรฐานเพียงเล็กน้อย จึงไม่มีความผิดตามกฎหมาย", "is_correct": false, "explanation": "ผิด การลวงเรื่องประเทศที่ผลิตและส่วนประกอบหลักเป็นอาหารปลอม และอาหารผิดมาตรฐานเองก็มีความผิด"}, {"label": "D", "text": "ถูกต้องตามกฎหมาย เพราะผู้ผลิตระบุประเทศที่ผลิตตามแหล่งวัตถุดิบหลักได้", "is_correct": false, "explanation": "ผิด ไม่พบโสมเลย และสถานที่ผลิตจริงอยู่ในประเทศไทย ฉลากจึงไม่ตรงความจริง"}, {"label": "E", "text": "เป็นเพียงปัญหาการโฆษณา ซึ่งอยู่นอกขอบเขตของ พ.ร.บ.อาหาร", "is_correct": false, "explanation": "ผิด ฉลากอาหารอยู่ภายใต้ พ.ร.บ.อาหารโดยตรง และการโฆษณาอาหารก็อยู่ในกฎหมายนี้ด้วย"}], "key_takeaway": "ฉลากที่ลวงให้เข้าใจผิดเรื่องคุณภาพ ส่วนประกอบ หรือประเทศที่ผลิต ทำให้ผลิตภัณฑ์เป็นอาหารปลอมตาม พ.ร.บ.อาหาร"}'::jsonb, 'medium', 'law-day1 • พ.ร.บ.อาหาร – อาหารปลอม'),
('b2ce73f87193a2dfdb631f06bd6b1439', 118, 'โครงการส่งเสริมการใช้ยาปฏิชีวนะอย่างสมเหตุผล (Antibiotics Smart Use; ASU) ซึ่งเป็นรากฐานหนึ่งของนโยบายการใช้ยาอย่างสมเหตุผล (RDU) ของประเทศไทย มุ่งลดการใช้ยาปฏิชีวนะที่ไม่จำเป็นในกลุ่มโรค/ภาวะใดเป็นหลัก', '[{"label": "A", "text": "วัณโรคปอด ปอดอักเสบ และการติดเชื้อในกระแสเลือด"}, {"label": "B", "text": "โรคติดต่อทางเพศสัมพันธ์ทุกชนิด"}, {"label": "C", "text": "การติดเชื้อทางเดินปัสสาวะที่มีภาวะแทรกซ้อน และเยื่อหุ้มสมองอักเสบ"}, {"label": "D", "text": "โรคติดเชื้อทางเดินหายใจส่วนบน (หวัด เจ็บคอ) ท้องร่วงเฉียบพลัน และบาดแผลสดจากอุบัติเหตุ"}, {"label": "E", "text": "การติดเชื้อดื้อยาหลายขนานในหอผู้ป่วยวิกฤต"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. โรคติดเชื้อทางเดินหายใจส่วนบน (หวัด เจ็บคอ) ท้องร่วงเฉียบพลัน และบาดแผลสดจากอุบัติเหตุ — ทั้งสามภาวะเป็นเป้าหมายหลักของ ASU เพราะส่วนใหญ่ไม่จำเป็นต้องใช้ยาปฏิชีวนะแต่มีการใช้เกินจำเป็นมาก", "reason": "ASU เป็นโครงการที่เริ่มจากความร่วมมือของ อย. และภาคีเครือข่าย มุ่งปรับพฤติกรรมการสั่งใช้และการใช้ยาปฏิชีวนะในสามภาวะที่พบบ่อยและมักไม่จำเป็นต้องใช้ยาปฏิชีวนะ ได้แก่ โรคติดเชื้อทางเดินหายใจส่วนบน (หวัด เจ็บคอ) ท้องร่วงเฉียบพลัน และบาดแผลสดจากอุบัติเหตุ แนวคิดนี้ต่อยอดเป็นตัวชี้วัดในนโยบายโรงพยาบาลส่งเสริมการใช้ยาอย่างสมเหตุผล (RDU Hospital) และการขยายสู่ชุมชนและร้านยา\n\nสำหรับเภสัชกรร้านยา นโยบายนี้สะท้อนบทบาทในการคัดกรองและไม่จ่ายยาปฏิชีวนะโดยไม่จำเป็น ซึ่งสอดคล้องกับยุทธศาสตร์การจัดการการดื้อยาต้านจุลชีพของประเทศ", "choices": [{"label": "A", "text": "วัณโรคปอด ปอดอักเสบ และการติดเชื้อในกระแสเลือด", "is_correct": false, "explanation": "ผิด เป็นโรคติดเชื้อที่จำเป็นต้องได้รับยาต้านจุลชีพ ไม่ใช่เป้าหมายการลดใช้ของ ASU"}, {"label": "B", "text": "โรคติดต่อทางเพศสัมพันธ์ทุกชนิด", "is_correct": false, "explanation": "ผิด ไม่ใช่กลุ่มเป้าหมายหลักของ ASU"}, {"label": "C", "text": "การติดเชื้อทางเดินปัสสาวะที่มีภาวะแทรกซ้อน และเยื่อหุ้มสมองอักเสบ", "is_correct": false, "explanation": "ผิด เป็นภาวะที่ต้องรักษาด้วยยาต้านจุลชีพ ไม่ใช่เป้าหมายการลดใช้"}, {"label": "D", "text": "โรคติดเชื้อทางเดินหายใจส่วนบน (หวัด เจ็บคอ) ท้องร่วงเฉียบพลัน และบาดแผลสดจากอุบัติเหตุ", "is_correct": true, "explanation": "ถูกต้อง ทั้งสามภาวะเป็นเป้าหมายหลักของ ASU เพราะส่วนใหญ่ไม่จำเป็นต้องใช้ยาปฏิชีวนะแต่มีการใช้เกินจำเป็นมาก"}, {"label": "E", "text": "การติดเชื้อดื้อยาหลายขนานในหอผู้ป่วยวิกฤต", "is_correct": false, "explanation": "ผิด เป็นประเด็นการควบคุมเชื้อดื้อยาในโรงพยาบาล ไม่ใช่กลุ่มโรคเป้าหมายของ ASU"}], "key_takeaway": "ASU มุ่งลดยาปฏิชีวนะใน 3 ภาวะ: หวัด/เจ็บคอ ท้องร่วงเฉียบพลัน และแผลสด"}'::jsonb, 'medium', 'law-day1 • Rational Drug Use – Antibiotics Smart Use (ASU)'),
('66492e58f8215181e94cd39dd38fae0d', 119, 'ร้านยาแห่งหนึ่งจำหน่ายผลิตภัณฑ์เสริมอาหารกลูตาไธโอนชนิดแคปซูลที่มีเลขสารบบอาหารถูกต้อง เจ้าของร้านโพสต์ภาพ “ก่อน–หลัง” ทางเพจของร้านพร้อมข้อความ “กินแล้วผิวขาวใสใน 7 วัน ลดฝ้า กระ” ลูกค้ารายหนึ่งถามว่าผลิตภัณฑ์นี้เป็นเครื่องสำอางใช่หรือไม่ และโฆษณาแบบนี้ทำได้หรือไม่ ข้อใดวิเคราะห์ได้ถูกต้องที่สุด', '[{"label": "A", "text": "เป็นอาหาร ไม่ใช่เครื่องสำอางเพราะใช้รับประทาน การอ้างทำให้ผิวขาวและลดฝ้าเป็นการโฆษณาอาหารที่ไม่ชอบด้วยกฎหมาย และผู้โฆษณาก็มีความผิดแม้เป็นผู้ขาย"}, {"label": "B", "text": "เป็นเครื่องสำอาง เพราะมีวัตถุประสงค์เพื่อความสวยงาม จึงโฆษณาได้โดยไม่ต้องขออนุญาต"}, {"label": "C", "text": "โฆษณาได้ เพราะผลิตภัณฑ์มีเลขสารบบอาหาร และภาพก่อน–หลังเป็นประสบการณ์จริงของลูกค้า"}, {"label": "D", "text": "เป็นยาแผนปัจจุบันโดยอัตโนมัติ ร้านยาจึงโฆษณาได้เพราะมีเภสัชกรประจำร้าน"}, {"label": "E", "text": "ร้านยาไม่มีความรับผิด เพราะเป็นเพียงผู้ขาย ความรับผิดเรื่องโฆษณาตกอยู่กับผู้ผลิตเท่านั้น"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. เป็นอาหาร ไม่ใช่เครื่องสำอางเพราะใช้รับประทาน การอ้างทำให้ผิวขาวและลดฝ้าเป็นการโฆษณาอาหารที่ไม่ชอบด้วยกฎหมาย และผู้โฆษณาก็มีความผิดแม้เป็นผู้ขาย — ผลิตภัณฑ์รับประทานไม่เข้านิยามเครื่องสำอางซึ่งใช้ภายนอก อาหารอ้างสรรพคุณทำให้ผิวขาว/ลดฝ้าไม่ได้ และผู้ใดที่โฆษณาโดยฝ่าฝืนกฎหมายต้องรับผิด", "reason": "ประเด็นที่ 1 (การจำแนก): เครื่องสำอางเป็นผลิตภัณฑ์ที่ใช้ภายนอกร่างกาย ผลิตภัณฑ์ที่รับประทานซึ่งมีเลขสารบบอาหารจึงเป็นอาหาร (ผลิตภัณฑ์เสริมอาหาร) อยู่ภายใต้ พ.ร.บ.อาหาร พ.ศ. 2522\n\nประเด็นที่ 2 (การโฆษณา): ผลิตภัณฑ์เสริมอาหารไม่สามารถอ้างสรรพคุณทำให้ผิวขาว หรือลดฝ้า กระ ซึ่งเป็นการอ้างสรรพคุณเกินกว่าอาหาร การใช้ภาพก่อน–หลังและระบุระยะเวลาเห็นผลเป็นการโฆษณาที่ทำให้เข้าใจผิด นอกจากนี้การโฆษณาคุณประโยชน์ของอาหารต้องได้รับอนุญาตก่อน กฎหมายใช้บังคับกับผู้ใดก็ตามที่โฆษณา ร้านยาที่โพสต์เองจึงมีความผิดได้แม้ไม่ใช่ผู้ผลิต", "choices": [{"label": "A", "text": "เป็นอาหาร ไม่ใช่เครื่องสำอางเพราะใช้รับประทาน การอ้างทำให้ผิวขาวและลดฝ้าเป็นการโฆษณาอาหารที่ไม่ชอบด้วยกฎหมาย และผู้โฆษณาก็มีความผิดแม้เป็นผู้ขาย", "is_correct": true, "explanation": "ถูกต้อง ผลิตภัณฑ์รับประทานไม่เข้านิยามเครื่องสำอางซึ่งใช้ภายนอก อาหารอ้างสรรพคุณทำให้ผิวขาว/ลดฝ้าไม่ได้ และผู้ใดที่โฆษณาโดยฝ่าฝืนกฎหมายต้องรับผิด"}, {"label": "B", "text": "เป็นเครื่องสำอาง เพราะมีวัตถุประสงค์เพื่อความสวยงาม จึงโฆษณาได้โดยไม่ต้องขออนุญาต", "is_correct": false, "explanation": "ผิด เครื่องสำอางคือผลิตภัณฑ์ที่ใช้ภายนอกร่างกาย ผลิตภัณฑ์รับประทานจึงไม่ใช่เครื่องสำอาง"}, {"label": "C", "text": "โฆษณาได้ เพราะผลิตภัณฑ์มีเลขสารบบอาหาร และภาพก่อน–หลังเป็นประสบการณ์จริงของลูกค้า", "is_correct": false, "explanation": "ผิด เลขสารบบอาหารไม่ได้อนุญาตให้อ้างสรรพคุณ และภาพก่อน–หลังเป็นการโฆษณาที่ทำให้เข้าใจผิด"}, {"label": "D", "text": "เป็นยาแผนปัจจุบันโดยอัตโนมัติ ร้านยาจึงโฆษณาได้เพราะมีเภสัชกรประจำร้าน", "is_correct": false, "explanation": "ผิด การอ้างสรรพคุณไม่ได้เปลี่ยนสถานะเป็นยาที่ขึ้นทะเบียน และการมีเภสัชกรไม่ได้อนุญาตให้โฆษณา"}, {"label": "E", "text": "ร้านยาไม่มีความรับผิด เพราะเป็นเพียงผู้ขาย ความรับผิดเรื่องโฆษณาตกอยู่กับผู้ผลิตเท่านั้น", "is_correct": false, "explanation": "ผิด กฎหมายควบคุม “ผู้ใด” ที่โฆษณา ผู้ขายที่โพสต์โฆษณาเองจึงมีความผิดได้"}], "key_takeaway": "ผลิตภัณฑ์รับประทานเพื่อความงามเป็นอาหาร ไม่ใช่เครื่องสำอาง และห้ามอ้างทำให้ผิวขาวหรือลดฝ้า ผู้ขายที่โฆษณาเองก็มีความผิดได้"}'::jsonb, 'hard', 'law-day1 • การแยกแยะผลิตภัณฑ์สุขภาพ – ผลิตภัณฑ์รับประทานอ้างผิวขาว'),
('3a7b3c34e0b90db0212069c171b099e2', 120, 'ผู้บริโภครายหนึ่งซื้อโลชั่นบำรุงผิวทางออนไลน์ ใช้แล้วเกิดผื่นแดงคัน จึงมาปรึกษาเภสัชกรว่าจะตรวจสอบได้อย่างไรว่าผลิตภัณฑ์จดแจ้งถูกต้อง และควรร้องเรียนที่ใด ข้อใดเป็นคำแนะนำที่เหมาะสมที่สุด', '[{"label": "A", "text": "ตรวจสอบได้ทางเดียว คือส่งผลิตภัณฑ์ไปตรวจวิเคราะห์ที่ห้องปฏิบัติการเอกชนด้วยตนเอง"}, {"label": "B", "text": "ร้องเรียนได้เฉพาะที่สถานีตำรวจ เพราะ อย. ไม่รับเรื่องร้องเรียนจากประชาชนทั่วไป"}, {"label": "C", "text": "สืบค้นเลขที่ใบรับจดแจ้งผ่านระบบของ อย. หรือแอปพลิเคชัน Oryor Smart แล้วร้องเรียนผ่านสายด่วน อย. 1556 หรือ สสจ. พร้อมเก็บผลิตภัณฑ์และหลักฐานการซื้อ"}, {"label": "D", "text": "ดูรีวิวของผู้ใช้รายอื่นบนแพลตฟอร์ม หากรีวิวดีถือว่าผลิตภัณฑ์จดแจ้งถูกต้อง"}, {"label": "E", "text": "ดูว่าฉลากมีเลข 13 หลักในกรอบเครื่องหมาย อย. หรือไม่ ซึ่งเป็นรูปแบบเลขของเครื่องสำอาง"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. สืบค้นเลขที่ใบรับจดแจ้งผ่านระบบของ อย. หรือแอปพลิเคชัน Oryor Smart แล้วร้องเรียนผ่านสายด่วน อย. 1556 หรือ สสจ. พร้อมเก็บผลิตภัณฑ์และหลักฐานการซื้อ — เป็นช่องทางตรวจสอบและร้องเรียนผลิตภัณฑ์สุขภาพที่ถูกต้อง และการเก็บหลักฐานช่วยให้หน่วยงานตรวจสอบย้อนกลับได้", "reason": "เครื่องสำอางที่ถูกต้องตาม พ.ร.บ.เครื่องสำอาง พ.ศ. 2558 ต้องแสดงเลขที่ใบรับจดแจ้ง ซึ่งเป็นรูปแบบต่างจากเลขสารบบอาหาร 13 หลักในกรอบเครื่องหมาย อย. ผู้บริโภคสามารถสืบค้นเลขและชื่อผลิตภัณฑ์ได้จากระบบตรวจสอบผลิตภัณฑ์ของ อย. ทั้งทางเว็บไซต์และแอปพลิเคชัน Oryor Smart เพื่อดูว่าข้อมูลตรงกับผลิตภัณฑ์จริงหรือไม่\n\nหากได้รับอันตรายหรือพบผลิตภัณฑ์ผิดกฎหมาย สามารถร้องเรียนผ่านสายด่วน อย. 1556 ช่องทางออนไลน์ของ อย. หรือสำนักงานสาธารณสุขจังหวัด ควรเก็บผลิตภัณฑ์ บรรจุภัณฑ์ และหลักฐานการซื้อไว้ ส่วนปัญหาด้านสัญญาหรือการให้บริการทั่วไปอาจร้องเรียนต่อ สคบ. (1166) ได้เพิ่มเติม", "choices": [{"label": "A", "text": "ตรวจสอบได้ทางเดียว คือส่งผลิตภัณฑ์ไปตรวจวิเคราะห์ที่ห้องปฏิบัติการเอกชนด้วยตนเอง", "is_correct": false, "explanation": "ผิด ผู้บริโภคสืบค้นข้อมูลการจดแจ้งได้เองจากฐานข้อมูลของ อย. โดยไม่ต้องตรวจวิเคราะห์"}, {"label": "B", "text": "ร้องเรียนได้เฉพาะที่สถานีตำรวจ เพราะ อย. ไม่รับเรื่องร้องเรียนจากประชาชนทั่วไป", "is_correct": false, "explanation": "ผิด อย. และ สสจ. รับเรื่องร้องเรียนผลิตภัณฑ์สุขภาพจากประชาชน"}, {"label": "C", "text": "สืบค้นเลขที่ใบรับจดแจ้งผ่านระบบของ อย. หรือแอปพลิเคชัน Oryor Smart แล้วร้องเรียนผ่านสายด่วน อย. 1556 หรือ สสจ. พร้อมเก็บผลิตภัณฑ์และหลักฐานการซื้อ", "is_correct": true, "explanation": "ถูกต้อง เป็นช่องทางตรวจสอบและร้องเรียนผลิตภัณฑ์สุขภาพที่ถูกต้อง และการเก็บหลักฐานช่วยให้หน่วยงานตรวจสอบย้อนกลับได้"}, {"label": "D", "text": "ดูรีวิวของผู้ใช้รายอื่นบนแพลตฟอร์ม หากรีวิวดีถือว่าผลิตภัณฑ์จดแจ้งถูกต้อง", "is_correct": false, "explanation": "ผิด รีวิวไม่ใช่หลักฐานทางกฎหมาย และอาจเป็นรีวิวที่จัดทำขึ้น"}, {"label": "E", "text": "ดูว่าฉลากมีเลข 13 หลักในกรอบเครื่องหมาย อย. หรือไม่ ซึ่งเป็นรูปแบบเลขของเครื่องสำอาง", "is_correct": false, "explanation": "ผิด เลข 13 หลักในกรอบ อย. เป็นเลขสารบบอาหาร เครื่องสำอางใช้เลขที่ใบรับจดแจ้งซึ่งไม่อยู่ในกรอบดังกล่าว"}], "key_takeaway": "ตรวจสอบเลขผลิตภัณฑ์สุขภาพผ่านระบบของ อย./Oryor Smart และร้องเรียนผ่าน อย. 1556 หรือ สสจ. โดยเก็บผลิตภัณฑ์และหลักฐานไว้"}'::jsonb, 'medium', 'law-day1 • การตรวจสอบเลขผลิตภัณฑ์และการร้องเรียน')
) AS v(id, qn, scenario, choices, correct_answer, detailed_explanation, difficulty, ai_notes)
CROSS JOIN (SELECT id FROM public.mcq_subjects WHERE name = 'PharmacyLaw') s
ON CONFLICT (id) DO NOTHING;
